INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11743a07-f862-4834-bb51-8be0600458e0', '', '', '8c5d508d-2dd0-42b7-aa06-85706b3c2795', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 王勔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52f6e867-ec26-466c-b2d8-1e8bf3714236', '山名', '山名', '8c5d508d-2dd0-42b7-aa06-85706b3c2795', '唐', '["麗景斜中嶠，晴華泛晚春。","琴聲抽楚雪，歌曲下梁塵。","傾蓋彫炎遠，班荆密契新。","方承綺□暮，烟上洛橋□。","（見影印本《新編纂圖書類要事林廣記》卷七。","）。"]', '["丽景斜中嶠，晴华泛晚春。","琴声抽楚雪，歌曲下梁塵。","傾蓋彫炎远，班荆密契新。","方承綺□暮，烟上洛橋□。","（见影印本《新編纂圖书類要事林廣記》卷七。","）。"]', '诗', 'shi', '', NULL, '山名 王勔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db8234e7-2306-4a20-b88f-4f46ca797d55', '太平興龍寺（題擬）', '太平兴龙寺（題擬）', 'fee52be3-9dbf-49b0-811a-7fa71985b765', '唐', '["昨度[匡]（厈）山下，春鶯曉弄稀。","今來[湓]（盆）水曲，秋鴈晚行飛。","國有文皇召，人慙謫傳歸。","迴行過梵塔，歷覽遍吳畿。","杏樹栽時久，蓮花刻處微。","南溪雨颯颯，東峴日輝輝。","瀑溜天童捧，香爐法衆圍。","煙雲隨道路，鶯鶴遠驂騑。","遠上靈儀肅，生公談柄揮。","一兹觀佛影，暫欲罷朝衣。","（此詩見《永樂大典》卷六六九九「十八陽」「江」字〖七函、六十四冊〗。","）（按《永樂大典》卷六六九九「九江府」十一「寺院」引《江州志》。","「太平興龍寺在虎溪，本晉東林寺。","太元九年桓伊置，法師慧遠道場也。","」又引《元一統志》：「東林禪寺，《舊志》載在州境，晉武帝太和十年建，唐號太平興龍寺，最爲廬山之古剎，寺有慧遠袈裟。","」《江州志》又謂寺有劉孝綽、孟浩然、李白、崔融、錢起、裴休、皇甫冉、杜荀鶴及樂天之詩。","此詩即自所引錄出。","〖1〗《吉石庵叢書》影印日本藏古鈔陳舜俞《廬山記》卷四收此詩，題作《遊東林寺》。","首句作「昨度匡山下」，第三句作「今來湓水曲」，均可訂《大典》之誤，兹據改。","第十五句作「煙霞隨道路」。","又詩後附跋云：「元和十三年二月二十九日，曾孫朝散大夫使持節江州諸軍事江州刺史上柱國清河縣開國男賜紫金魚袋能再刊勒。","」）。"]', '["昨度[匡]（厈）山下，春鶯晓弄稀。","今来[湓]（盆）水曲，秋鴈晚行飞。","国有文皇召，人慙謫傳归。","迴行過梵塔，歷覽遍吳畿。","杏樹栽时久，蓮花刻处微。","南溪雨颯颯，东峴日輝輝。","瀑溜天童捧，香爐法衆圍。","煙云隨道路，鶯鹤远驂騑。","远上靈儀肅，生公談柄揮。","一兹观佛影，暫欲罷朝衣。","（此诗见《永乐大典》卷六六九九「十八陽」「江」字〖七函、六十四冊〗。","）（按《永乐大典》卷六六九九「九江府」十一「寺院」引《江州志》。","「太平兴龙寺在虎溪，本晉东林寺。","太元九年桓伊置，法師慧远道場也。","」又引《元一統志》：「东林禪寺，《旧志》載在州境，晉武帝太和十年建，唐號太平兴龙寺，最爲廬山之古剎，寺有慧远袈裟。","」《江州志》又謂寺有劉孝綽、孟浩然、李白、崔融、錢起、裴休、皇甫冉、杜荀鹤及乐天之诗。","此诗即自所引錄出。","〖1〗《吉石庵叢书》影印日本藏古鈔陳舜俞《廬山記》卷四收此诗，題作《游东林寺》。","首句作「昨度匡山下」，第三句作「今来湓水曲」，均可訂《大典》之誤，兹據改。","第十五句作「煙霞隨道路」。","又诗後附跋云：「元和十三年二月二十九日，曾孫朝散大夫使持節江州諸軍事江州刺史上柱国清河縣开国男賜紫金鱼袋能再刊勒。","」）。"]', '诗', 'shi', '', NULL, '太平興龍寺（題擬） 崔融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('619a48e1-e086-431c-87c0-b9c4d3e17c89', '寶名', '寶名', 'fee52be3-9dbf-49b0-811a-7fa71985b765', '唐', '["□城煙雨霽，□苑物華滋。","池連金水白，人契玉山時。","珠浦荷如蓋，銅街樹似帷。","琴歌待明月，丹石有深期。","（此詩見影印本《新編纂圖增類羣書類要事林廣記》卷七。","本詩所缺二字，原本較模糊。","首句缺字似爲「鼎」字，次句缺字，右邊爲「圭」形，左邊已難辨認，疑應爲「桂」字。","）。"]', '["□城煙雨霽，□苑物华滋。","池連金水白，人契玉山时。","珠浦荷如蓋，銅街樹似帷。","琴歌待明月，丹石有深期。","（此诗见影印本《新編纂圖增類羣书類要事林廣記》卷七。","本诗所缺二字，原本較模糊。","首句缺字似爲「鼎」字，次句缺字，右邊爲「圭」形，左邊已难辨認，疑應爲「桂」字。","）。"]', '诗', 'shi', '', NULL, '寶名 崔融 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e329eb4-5f0b-47f5-a355-682521e875be', '五言夏日游神泉詩（幷序）', '五言夏日游神泉诗（幷序）', '61028b68-b3eb-4974-9272-fad7b49945e8', '唐', '["聞有濠梁地，駕言幷四美。","契冥邀異迹，勝會不延晷。","澗響若琴中，泉華疑鏡裏。","形隨員月正，制逐規虹起。","澡流瑩丹心，跂石涼玉趾。","近焉將安適？行當潤濛氾。","（此詩見《金石萃編》卷六十一。","）（按詩題下原署「美原縣尉韋元旦字烜」，碑刻文字係尹元凱所書。","）。"]', '["闻有濠梁地，駕言幷四美。","契冥邀異迹，勝會不延晷。","澗响若琴中，泉华疑镜裏。","形隨員月正，制逐規虹起。","澡流瑩丹心，跂石涼玉趾。","近焉將安適？行當潤濛氾。","（此诗见《金石萃編》卷六十一。","）（按诗題下原署「美原縣尉韋元旦字烜」，碑刻文字係尹元凱所书。","）。"]', '诗', 'shi', '', NULL, '五言夏日游神泉詩（幷序） 韋元旦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('818bcd6f-872a-4749-b0f7-5a2f8d1b8500', '五言夏日游神泉詩', '五言夏日游神泉诗', '2d621e6b-bf33-48aa-8ef8-5f01cee56ed7', '唐', '["詞人擁高節，狎異尋幽賞。","𧯆險洞深澗，皦鏡鯀無象。","形隨澡魄員，氣逐非烟上。","徙谷縈新溜，分谿疏舊壤。","冥功兆□□，効奇靈既往。","共漱□□清，超然□□想。","（見《金石萃編》卷六十一。","〖此詩又見孫星衍《續古文苑》卷四，第五句作「形隨隨滿魄鼎」；第九句所缺二字，下一字作「即」；第十一句缺二字之上一字，《金石萃編》存左半邊，作「馬」形，《續古文苑》作「鳴」。","〗）（按是刻次韋元旦詩後，原署「主簿賈言淑」，書者體會爲尹元凱。","）。"]', '["词人擁高節，狎異尋幽賞。","𧯆險洞深澗，皦镜鯀無象。","形隨澡魄員，氣逐非烟上。","徙谷縈新溜，分谿疏旧壤。","冥功兆□□，効奇靈既往。","共漱□□清，超然□□想。","（见《金石萃編》卷六十一。","〖此诗又见孫星衍《續古文苑》卷四，第五句作「形隨隨满魄鼎」；第九句所缺二字，下一字作「即」；第十一句缺二字之上一字，《金石萃編》存左半邊，作「马」形，《續古文苑》作「鳴」。","〗）（按是刻次韋元旦诗後，原署「主簿賈言淑」，书者體會爲尹元凱。","）。"]', '诗', 'shi', '', NULL, '五言夏日游神泉詩 賈言淑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eb2d4cd-882a-49c7-9be1-42964c6e2928', '', '', 'c999688f-d2dd-4b21-8b42-0c5e13b69689', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 尹元凱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2baee7ee-6fee-4aea-8702-ccf2b34f4cad', '五言同韋子斿神泉詩（幷序）', '五言同韋子斿神泉诗（幷序）', 'c999688f-d2dd-4b21-8b42-0c5e13b69689', '唐', '["桐坂疏抱𦉥，崐丘落縣米。","豈如中輔邑，迸泉毓爲醴。","氣高靈洮作，潤洽沖務啟。","月潭信玲瓏，霞溜幾清泚？","湝湝上善用，的的煩慮洗。","君子懷淡交，相從澗之底。","（見《金石萃編》卷六十一。","序中原缺一字，據《續古文苑》卷四補。","）（按此詩快乐序在韋元旦、賈言淑詩刻之碑陰，詩前署書者之名曰「大唐裕明子書」，題下署詩序作者之名曰「雲陽主簿明臺子徐彥伯字光」，詩後署詩作者之名曰「裕明子河間尹元凱字戫」。","望又按史稱徐彦伯名洪，以字顯，據碑，知實名彦伯而字光也。","彦伯於武后垂拱間爲雲間主簿，屢遷給事中，預修《三教珠英》，歷修文館學士、工部侍郎、太子賓客而卒。","）。"]', '["桐坂疏抱𦉥，崐丘落縣米。","豈如中輔邑，迸泉毓爲醴。","氣高靈洮作，潤洽沖務啟。","月潭信玲瓏，霞溜幾清泚？","湝湝上善用，的的煩慮洗。","君子懷淡交，相從澗之底。","（见《金石萃編》卷六十一。","序中原缺一字，據《續古文苑》卷四補。","）（按此诗快乐序在韋元旦、賈言淑诗刻之碑陰，诗前署书者之名曰「大唐裕明子书」，題下署诗序作者之名曰「云陽主簿明台子徐彥伯字光」，诗後署诗作者之名曰「裕明子河间尹元凱字戫」。","望又按史稱徐彦伯名洪，以字显，據碑，知實名彦伯而字光也。","彦伯於武后垂拱间爲云间主簿，屢遷給事中，預修《三教珠英》，歷修文館学士、工部侍郎、太子賓客而卒。","）。"]', '诗', 'shi', '', NULL, '五言同韋子斿神泉詩（幷序） 尹元凱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('683e6c19-0951-4e06-abc9-2d55a4c4a098', '', '', '4f6592e6-cca4-446b-8690-3cc6db0c9bf6', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 溫翁念 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c57b3077-3cd6-4896-81cf-0c646bbd0369', '五言同韋子斿神泉詩', '五言同韋子斿神泉诗', '4f6592e6-cca4-446b-8690-3cc6db0c9bf6', '唐', '["聞君泉壑幽，俯裂頻陽趾。","及我性情狎，遥輕武陵涘。","欿窞明月制，沮𣹤涼風起。","朋來想辟雝，日去疑濛汜。","列坐殊滿腹，揚清非洗耳。","髣髴參石斿，淡焉適真理。","（見《金石萃編》卷六十一。","）（〖1〗此詩列尹元凱詩刻之後，署作者之名曰「左司郎中溫翁念字敬祖」，書者亦爲尹元凱。","據《新唐書》卷七十二中《宰相世系表》載翁念爲彦博之孫，官大僕少卿。","此碑署銜左司郎中，蓋武后垂拱間仕歷也。","）。"]', '["闻君泉壑幽，俯裂頻陽趾。","及我性情狎，遥轻武陵涘。","欿窞明月制，沮𣹤涼风起。","朋来想辟雝，日去疑濛汜。","列坐殊满腹，揚清非洗耳。","髣髴參石斿，淡焉適真理。","（见《金石萃編》卷六十一。","）（〖1〗此诗列尹元凱诗刻之後，署作者之名曰「左司郎中溫翁念字敬祖」，书者亦爲尹元凱。","據《新唐书》卷七十二中《宰相世系表》載翁念爲彦博之孫，官大僕少卿。","此碑署銜左司郎中，蓋武后垂拱间仕歷也。","）。"]', '诗', 'shi', '', NULL, '五言同韋子斿神泉詩 溫翁念 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d058f5d-afe7-4ecf-9ec1-c289c659fc03', '五言同韋子斿神泉詩', '五言同韋子斿神泉诗', '5877f379-1105-4b05-ba47-bf20c56d5817', '唐', '["昔日鳴絃地，今聞生澗水。","靈潛敝政餘，潤發彫文始。","滴滴流珠散，渟渟明月止。","善香懷若人，淡交挹君子。","鏡澈無纖翳，天清滌煩滓。","虛忝神僊臺，何由弄風晷？","（見《金石萃編》卷六十一。","）（〖1〗詩刻次溫翁念一詩後，署作者之名曰「天官員外郎李鵬字至遠」，亦尹元凱所書。","碑末紀年曰「垂拱四年龍集戊子四月戊□」，蓋公元六八八年也。","）。"]', '["昔日鳴絃地，今闻生澗水。","靈潛敝政餘，潤發彫文始。","滴滴流珠散，渟渟明月止。","善香懷若人，淡交挹君子。","镜澈無纖翳，天清滌煩滓。","虛忝神僊台，何由弄风晷？","（见《金石萃編》卷六十一。","）（〖1〗诗刻次溫翁念一诗後，署作者之名曰「天官員外郎李鵬字至远」，亦尹元凱所书。","碑末紀年曰「垂拱四年龙集戊子四月戊□」，蓋公元六八八年也。","）。"]', '诗', 'shi', '', NULL, '五言同韋子斿神泉詩 李鵬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22598cfc-4428-49de-9e31-c574d8c1343f', '', '', 'd11a37c1-35f4-455b-b6ce-e3a2f71532d4', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 光溫古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a130d14d-b078-4490-a783-1366b9fc2af8', '句', '句', 'd11a37c1-35f4-455b-b6ce-e3a2f71532d4', '唐', '["錦色陽川后，絲雨降桐鄉。","（〖1〗句見《金石萃編》卷六十五「唐二十五」。","按此詩句幷下趙不爲、王鉉、成公簡、李大寶諸人詩句均刻在《衛州共城縣百門陂碑銘》之碑陰，或乞雨，或喜晴，皆摘取兩句，不得見其全爲可惜耳。","又此詩句前有記事，略謂長安二年〖公元七○二年〗夏五月，州符下縣祈雨。","六月一日先祈社稷，遍祈山川，其時西北山頂，有雲團團而上，雷起巖突，電發𡓜蕃，須臾之間，降雨一境。","父老光溫古上詩賀公曰〖句不重錄〗云云。","望按記事中所稱上詩賀公，公，蓋指靈源公，爲當地民間所祠神名。","）。"]', '["錦色陽川后，絲雨降桐乡。","（〖1〗句见《金石萃編》卷六十五「唐二十五」。","按此诗句幷下趙不爲、王鉉、成公簡、李大寶諸人诗句均刻在《衛州共城縣百门陂碑銘》之碑陰，或乞雨，或喜晴，皆摘取兩句，不得见其全爲可惜耳。","又此诗句前有記事，略謂长安二年〖公元七○二年〗夏五月，州符下縣祈雨。","六月一日先祈社稷，遍祈山川，其时西北山頂，有云團團而上，雷起巖突，電發𡓜蕃，須臾之间，降雨一境。","父老光溫古上诗賀公曰〖句不重錄〗云云。","望按記事中所稱上诗賀公，公，蓋指靈源公，爲當地民间所祠神名。","）。"]', '诗', 'shi', '', NULL, '句 光溫古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6876048a-5d9b-4830-a028-f724d279ce5f', '句', '句', 'ba983b54-d755-45f8-ae43-597df184f9b1', '唐', '["調弦敷廣西惠，濟物被深仁。","（〖1〗句列光溫古祈雨詩句後。","曰「五𠥱〖月〗十〖乙〗〖日〗，前南岳齋郎趙不爲詩曰。","〖句不重錄〗」望按：《全唐文》爲四○一有趙不爲文。","）。"]', '["調弦敷廣西惠，濟物被深仁。","（〖1〗句列光溫古祈雨诗句後。","曰「五𠥱〖月〗十〖乙〗〖日〗，前南岳斋郎趙不爲诗曰。","〖句不重錄〗」望按：《全唐文》爲四○一有趙不爲文。","）。"]', '诗', 'shi', '', NULL, '句 趙不爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('397d6b7b-d0ca-4cb2-b563-bbc325560ec6', '又句', '又句', 'ba983b54-d755-45f8-ae43-597df184f9b1', '唐', '["晴暉疑兆夢，甘液類隨車。","（〖1〗句列於此碑碑陰之末，曰：「趙不爲《喜晴》詩曰〖句不重錄〗云云。」","）。"]', '["晴暉疑兆梦，甘液類隨车。","（〖1〗句列於此碑碑陰之末，曰：「趙不爲《喜晴》诗曰〖句不重錄〗云云。」","）。"]', '诗', 'shi', '', NULL, '又句 趙不爲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9baadb3f-e119-46d2-986f-983d1849750f', '句', '句', 'fa655455-959d-47d7-8c51-b508d59de7ee', '唐', '["良宰多憂憫，虔誠謁庶神。","（〖1〗句次趙不爲祈雨詩句後，曰「七𠥱〖月〗廿三〖乙〗〖日〗，文林郎王堅詩曰〖句不重錄〗」云云。","）。"]', '["良宰多憂憫，虔誠謁庶神。","（〖1〗句次趙不爲祈雨诗句後，曰「七𠥱〖月〗廿三〖乙〗〖日〗，文林郎王堅诗曰〖句不重錄〗」云云。","）。"]', '诗', 'shi', '', NULL, '句 王堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97f46ccc-c62a-4af5-8bf3-157a4b8896f2', '句', '句', '47eb9a4f-d973-4d89-bc92-22f5da14c0a4', '唐', '["雨似隨車至，雲疑逐蓋飛。","（〖1〗句次王堅詩句後，曰「文林郎王鉉詩曰〖句不重錄〗」云云。","按唐有兩王鉉，《全唐文》卷七九一收王鉉文二篇，乃大中時處士，此則長安間人。","）。"]', '["雨似隨车至，云疑逐蓋飞。","（〖1〗句次王堅诗句後，曰「文林郎王鉉诗曰〖句不重錄〗」云云。","按唐有兩王鉉，《全唐文》卷七九一收王鉉文二篇，乃大中时处士，此則长安间人。","）。"]', '诗', 'shi', '', NULL, '句 王鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ece754f-de76-4987-abf1-f4a70a622b7c', '句', '句', '727c6a66-9a6e-4400-923e-33cc281defe7', '唐', '["隨軒感仁惠，應日（原作〖乙〗）灑甘滋。","（〖1〗句次王鉉詩句後，曰「武聖〖原作●〗縣尉成公簡詩曰〖句不重錄〗云云。」","）。"]', '["隨軒感仁惠，應日（原作〖乙〗）灑甘滋。","（〖1〗句次王鉉诗句後，曰「武聖〖原作●〗縣尉成公簡诗曰〖句不重錄〗云云。」","）。"]', '诗', 'shi', '', NULL, '句 成公簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a462f86f-45d3-4634-af5d-7f006601ccae', '句', '句', '5bf63746-1b73-4f18-8c11-bf381d75539c', '唐', '["陽耀求便灑，陰霖請復晴。","（〖1〗句次成公簡詩句後，曰「成均進士李大寶《賀晴詩》曰〖句不重錄〗云云。」","）。"]', '["陽耀求便灑，陰霖請复晴。","（〖1〗句次成公簡诗句後，曰「成均進士李大寶《賀晴诗》曰〖句不重錄〗云云。」","）。"]', '诗', 'shi', '', NULL, '句 李大寶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea9cef18-11ef-4324-aa73-8fd1e686630c', '', '', '1411d253-2c05-4ed5-a894-164767ba90cc', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 馬友鹿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca01291e-9d6b-492c-be41-f744fc09f9fc', '早春陪敕麻先生（慈力）祭岳（久視二年。見《山左金石志》卷十二，亦見《金石萃編》卷五十三。此詩《全唐詩》卷八百八十七補遺卷載之，作者馬令，注曰」失名「。今按《山左金石志》署作者曰「行博城縣令馬友鹿」，則其名固未失也。詩同，不重出，校其異文如下：第三句「鞭撻造神鬼」，「造」《全唐詩》作「走」。五句「忽下元洲使」，「元洲」，《全唐詩》作「袁州」。六句「來赴紫洞前」，「赴」，《全唐詩》作「遊」。八句「白鶴怪時還」，「怪」，《全唐詩》闕；「還」，作「年」。十一句「巖風半山水」，「巖」，《全唐詩》闕。十二句', '早春陪敕麻先生（慈力）祭岳（久視二年。见《山左金石志》卷十二，亦见《金石萃編》卷五十三。此诗《全唐诗》卷八百八十七補遺卷載之，作者马令，注曰」失名「。今按《山左金石志》署作者曰「行博城縣令马友鹿」，則其名固未失也。诗同，不重出，校其異文如下：第三句「鞭撻造神鬼」，「造」《全唐诗》作「走」。五句「忽下元洲使」，「元洲」，《全唐诗》作「袁州」。六句「来赴紫洞前」，「赴」，《全唐诗》作「游」。八句「白鹤怪时還」，「怪」，《全唐诗》闕；「還」，作「年」。十一句「巖风半山水」，「巖」，《全唐诗》闕。十二句', '1411d253-2c05-4ed5-a894-164767ba90cc', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '早春陪敕麻先生（慈力）祭岳（久視二年。見《山左金石志》卷十二，亦見《金石萃編》卷五十三。此詩《全唐詩》卷八百八十七補遺卷載之，作者馬令，注曰」失名「。今按《山左金石志》署作者曰「行博城縣令馬友鹿」，則其名固未失也。詩同，不重出，校其異文如下：第三句「鞭撻造神鬼」，「造」《全唐詩》作「走」。五句「忽下元洲使」，「元洲」，《全唐詩》作「袁州」。六句「來赴紫洞前」，「赴」，《全唐詩》作「遊」。八句「白鶴怪時還」，「怪」，《全唐詩》闕；「還」，作「年」。十一句「巖風半山水」，「巖」，《全唐詩》闕。十二句 馬友鹿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87f9821c-2768-4544-b296-123d746550b4', '贈崔十娘', '贈崔十娘', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["自隱多姿則，欺他獨自眠。","故故將纖手，時時弄小絃。","耳聞猶氣絕，眼見若爲憐。","從渠痛不肯，人更別求天。"]', '["自隐多姿則，欺他独自眠。","故故將纖手，时时弄小絃。","耳闻猶氣絕，眼见若爲怜。","從渠痛不肯，人更別求天。"]', '诗', 'shi', '', NULL, '贈崔十娘 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c4b8756-8e5c-4bdc-b90f-a8b4fcc5fd1a', '詩一首', '诗一首', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["歛笑偷殘靨，含羞露半脣。","一眉猶叵耐，雙眼定傷人。"]', '["歛笑偷殘靨，含羞露半脣。","一眉猶叵耐，雙眼定傷人。"]', '诗', 'shi', '', NULL, '詩一首 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e3f42c0-6165-4212-88a2-f0bca754e1be', '又一首', '又一首', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["夢中疑是實，覺後忽非真。","誠知腸欲繼，窮鬼故調人。"]', '["梦中疑是實，覺後忽非真。","誠知腸欲繼，窮鬼故調人。"]', '诗', 'shi', '', NULL, '又一首 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e09e26f-7b2b-4731-94a6-d41f9403b3f2', '又一首', '又一首', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["未必由詩得，將詩故表憐。","聞渠擲入火，定是欲相然。","。"]', '["未必由诗得，將诗故表怜。","闻渠擲入火，定是欲相然。","。"]', '诗', 'shi', '', NULL, '又一首 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67baefa1-b8cb-4691-9280-5cfdad7e951a', '又一首', '又一首', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["心虛不可測，眼細强關情。","迴身已入抱，不見有嬌聲。"]', '["心虛不可測，眼細强关情。","迴身已入抱，不见有嬌声。"]', '诗', 'shi', '', NULL, '又一首 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c13df77-886a-4ed9-a1c2-01b61924c9fe', '詠𡱈', '詠𡱈', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["眼似星初轉，眉如月欲渭。","先須捺後脚，然後勒前腰。"]', '["眼似星初轉，眉如月欲渭。","先須捺後脚，然後勒前腰。"]', '诗', 'shi', '', NULL, '詠𡱈 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32ce7f3d-4314-4899-829e-044ebbed7bba', '詩一首', '诗一首', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["忽然心裏愛，不覺眼中憐。","未關雙眼曲，直是寸心偏。"]', '["忽然心裏愛，不覺眼中怜。","未关雙眼曲，直是寸心偏。"]', '诗', 'shi', '', NULL, '詩一首 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53e6130a-bb17-41e2-83ef-443a099a79c5', '又一首', '又一首', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["舊來心使眼，心思眼剩（《唐人小說》本作即。","）傳。","由心使眼見，眼亦共心憐。"]', '["旧来心使眼，心思眼剩（《唐人小说》本作即。","）傳。","由心使眼见，眼亦共心怜。"]', '诗', 'shi', '', NULL, '又一首 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16c79884-993e-4671-a9ef-70ad3782cea4', '詠刀子', '詠刀子', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["自憐膠漆重，相思意不窮。","不惜尖頭物，終日在皮中。"]', '["自怜膠漆重，相思意不窮。","不惜尖头物，終日在皮中。"]', '诗', 'shi', '', NULL, '詠刀子 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a39a3828-ed2b-4fda-bc19-3646b5c53c4c', '詩一首', '诗一首', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["向來知道徑，生平不忍欺。","但令守行跡，何用數圍碁。"]', '["向来知道徑，生平不忍欺。","但令守行跡，何用數圍碁。"]', '诗', 'shi', '', NULL, '詩一首 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5af90233-e556-4a0d-9f96-314df6b978bd', '又一首', '又一首', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["千金此處有，一笑待渠爲。","不望全露齒，請爲暫嚬眉。"]', '["千金此处有，一笑待渠爲。","不望全露齒，請爲暫嚬眉。"]', '诗', 'shi', '', NULL, '又一首 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef313415-5ab5-4c67-8765-f9a58a80aa87', '詠破銅熨斗', '詠破銅熨斗', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["若冷頭面在，生平不熨空。","即今雖冷惡，人自覓殘銅。","。"]', '["若冷头面在，生平不熨空。","即今雖冷惡，人自覓殘銅。","。"]', '诗', 'shi', '', NULL, '詠破銅熨斗 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc0744ac-5717-4451-9199-065c755f5432', '舞詞', '舞词', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["從來巡遶四邊，忽逢兩箇神仙。","眉上冬天出柳，頰中旱地生蓮。","千看千處嫵媚，萬看萬處㛹妍。","今宵若其不得，剩命過與黃泉。"]', '["從来巡遶四邊，忽逢兩箇神仙。","眉上冬天出柳，頰中旱地生蓮。","千看千处嫵媚，万看万处㛹妍。","今宵若其不得，剩命過與黄泉。"]', '诗', 'shi', '', NULL, '舞詞 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d51cce1-03bf-4560-9088-4edbdb978d97', '詠筆硯', '詠笔硯', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["摧毛任便點，愛色轉須磨。","所以研難竟，良由水太多。"]', '["摧毛任便点，愛色轉須磨。","所以研难竟，良由水太多。"]', '诗', 'shi', '', NULL, '詠筆硯 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a87a41e-f397-4d8a-9fb8-908e33a55780', '詠雙燕子', '詠雙燕子', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["雙燕子，聯聯翩翩幾萬迴。","（《唐人小說》本作聯翩幾萬迴。","）强知人是客，方便惱他來。"]', '["雙燕子，聯聯翩翩幾万迴。","（《唐人小说》本作聯翩幾万迴。","）强知人是客，方便惱他来。"]', '诗', 'shi', '', NULL, '詠雙燕子 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34c091d6-580c-465e-b56e-629f09c12f3e', '詠酒杓子', '詠酒杓子', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["尾動惟須急，頭低則不平。","渠今合把爵，深淺任君情。"]', '["尾动惟須急，头低則不平。","渠今合把爵，深淺任君情。"]', '诗', 'shi', '', NULL, '詠酒杓子 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4e3d658-5ce8-4e5a-a9de-00f5d77dbed4', '詠李', '詠李', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["問李樹，如何意不同？應來主毛裏，翻入客懷中。"]', '["问李樹，如何意不同？應来主毛裏，翻入客懷中。"]', '诗', 'shi', '', NULL, '詠李 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6fad4cc-fc7e-4396-9636-16c04e66338e', '答十娘射雉', '答十娘射雉', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["心緒恰相當，誰能護短長。","一床無兩好，半醜亦何妨。"]', '["心緒恰相當，誰能護短长。","一床無兩好，半醜亦何妨。"]', '诗', 'shi', '', NULL, '答十娘射雉 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bf1b256-d73b-4f68-b9ce-eb7abec1cf00', '答十娘詠弓', '答十娘詠弓', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["縮幹全不到，抬頭則大過。","若令臍下入，百放故籌多。","。"]', '["縮幹全不到，抬头則大過。","若令臍下入，百放故籌多。","。"]', '诗', 'shi', '', NULL, '答十娘詠弓 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94ef3f28-cd3b-4cd7-9e66-4e53c0d712ac', '詩一首', '诗一首', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["千看千意密，一見一憐深。","但當把手子，寸斬亦甘心。"]', '["千看千意密，一见一怜深。","但當把手子，寸斬亦甘心。"]', '诗', 'shi', '', NULL, '詩一首 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('deb80130-92c5-41b6-a595-f1e3a964d2c8', '又一首', '又一首', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["千思千腸熱，一念一心焦。","若爲求守得，暫借可憐腰。"]', '["千思千腸熱，一念一心焦。","若爲求守得，暫借可怜腰。"]', '诗', 'shi', '', NULL, '又一首 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('834d1306-b786-4c8f-aeb8-77c22819aac8', '又一首', '又一首', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["腰支一遇勒，心中百處傷。","但若得口子，餘事不承望。"]', '["腰支一遇勒，心中百处傷。","但若得口子，餘事不承望。"]', '诗', 'shi', '', NULL, '又一首 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('236b624c-139a-4c9b-8e2a-7e369b39aeb5', '又一首', '又一首', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["藥草俱嘗遍，並悉不相宜。","惟須一箇物，不道自應知。"]', '["藥草俱嘗遍，並悉不相宜。","惟須一箇物，不道自應知。"]', '诗', 'shi', '', NULL, '又一首 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('263cda28-bb6d-46cb-a91e-c4360f56c247', '又一首', '又一首', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["積愁腸已斵，懸望眼應穿。","今宵莫閉戶，夢裏向渠邊。"]', '["積愁腸已斵，懸望眼應穿。","今宵莫閉戶，梦裏向渠邊。"]', '诗', 'shi', '', NULL, '又一首 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c3c4216-0f16-4aae-8eff-9384942765cb', '別崔瓊英', '別崔瓊英', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["卞和山未斵，羊雍地不耕。"]', '["卞和山未斵，羊雍地不耕。"]', '诗', 'shi', '', NULL, '別崔瓊英 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a17c525b-d498-4ee1-8a0e-b36e37ef8f24', '相思枕留贈十娘', '相思枕留贈十娘', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["南國傳椰子，東家賦石榴。","聊將代左腕，長夜枕渠頭。"]', '["南国傳椰子，东家賦石榴。","聊將代左腕，长夜枕渠头。"]', '诗', 'shi', '', NULL, '相思枕留贈十娘 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a74e22c9-ab33-401e-b186-dbffb250e862', '益州新樣錦留贈五嫂', '益州新樣錦留贈五嫂', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["今留片子信，可以贈佳期。","裁爲八幅被，時復一相思。","。"]', '["今留片子信，可以贈佳期。","裁爲八幅被，时复一相思。","。"]', '诗', 'shi', '', NULL, '益州新樣錦留贈五嫂 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c92dba26-eb50-46d1-9a8c-df167168ba33', '答張文成', '答張文成', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["（案以下各詩，《遊仙窟》雖謂崔十娘所作，要皆張文成戲墨耳。","）面非他舍面，心是自家心。","何處關天事，辛苦漫追尋。"]', '["（案以下各诗，《游仙窟》雖謂崔十娘所作，要皆張文成戲墨耳。","）面非他舍面，心是自家心。","何处关天事，辛苦漫追尋。"]', '诗', 'shi', '', NULL, '答張文成 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('890dfc95-2998-4fed-a6a9-33b36cc74ea5', '又', '又', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["好是他家好，人非着意人。","何須漫相弄，幾許費精神。"]', '["好是他家好，人非着意人。","何須漫相弄，幾許費精神。"]', '诗', 'shi', '', NULL, '又 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('823af34b-0473-484f-959d-7a73908d8f75', '詩一首', '诗一首', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["憐腸忽欲繼，憶眼己先開。"]', '["怜腸忽欲繼，憶眼己先开。"]', '诗', 'shi', '', NULL, '詩一首 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('defef83c-5b14-4e45-8b6c-826e74143c3c', '詠尺八', '詠尺八', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["眼多本自令渠愛，口少元來每被侵。","天事風聲徹他耳，教人氣滿自填心。"]', '["眼多本自令渠愛，口少元来每被侵。","天事风声徹他耳，教人氣满自填心。"]', '诗', 'shi', '', NULL, '詠尺八 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('617b8954-16d6-40fb-9373-2608f127af6a', '詠𡱈', '詠𡱈', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["勒腰須巧快，捺脚更風流。","但令細眼合，人自分輪籌。"]', '["勒腰須巧快，捺脚更风流。","但令細眼合，人自分輪籌。"]', '诗', 'shi', '', NULL, '詠𡱈 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e840e2fe-07c2-46eb-97d4-3c97728f9e56', '詩一首', '诗一首', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["眼心非一處，心眼舊分離。","直令渠眼見，誰遣報心知。"]', '["眼心非一处，心眼旧分離。","直令渠眼见，誰遣報心知。"]', '诗', 'shi', '', NULL, '詩一首 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7694dc89-12d8-4878-8a50-f597c55140fd', '又一首', '又一首', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["眼心俱憶念，心眼共追尋。","誰家解事眼，副著可憐心。","。"]', '["眼心俱憶念，心眼共追尋。","誰家解事眼，副著可怜心。","。"]', '诗', 'shi', '', NULL, '又一首 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f5efe34-843b-45db-8e70-7b035c2013b8', '詠鞘', '詠鞘', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["數捺皮應緩，頻磨快轉多。","渠今拔出後，空鞘欲如何。"]', '["數捺皮應緩，頻磨快轉多。","渠今拔出後，空鞘欲如何。"]', '诗', 'shi', '', NULL, '詠鞘 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f00122e7-c43e-44df-91cf-bfb805c01365', '詩一首', '诗一首', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["雙眉碎客膽，兩眼判君心。","誰能用一笑，賤價買千金。"]', '["雙眉碎客膽，兩眼判君心。","誰能用一笑，賤價買千金。"]', '诗', 'shi', '', NULL, '詩一首 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d35ea59b-af8f-499d-9e96-425a6b97a25c', '詠破銅熨斗', '詠破銅熨斗', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["舊來心肚熱，無端強熨他。","即今形勢冷，誰肯重（重字原缺，據《唐人小說》本補。","）相磨。"]', '["旧来心肚熱，無端強熨他。","即今形勢冷，誰肯重（重字原缺，據《唐人小说》本補。","）相磨。"]', '诗', 'shi', '', NULL, '詠破銅熨斗 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ad82c7c-4b3e-4517-85cf-28972a821dcf', '詩一首', '诗一首', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["得意似鴛鴦，情乖若吳越。","不向君邊盡，更知何處歇。"]', '["得意似鴛鴦，情乖若吳越。","不向君邊尽，更知何处歇。"]', '诗', 'shi', '', NULL, '詩一首 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('619285c7-3ab7-463a-bfaf-670918fb69d6', '詠鴨頭鐺子', '詠鴨头鐺子', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["觜長非爲嗍，項曲不由攀。","但令脚直上，他自眼雙翻。"]', '["觜长非爲嗍，項曲不由攀。","但令脚直上，他自眼雙翻。"]', '诗', 'shi', '', NULL, '詠鴨頭鐺子 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a115df3-cd5c-462a-b752-e56072db3cb8', '詠雙燕子', '詠雙燕子', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["雙燕子，可可事風流。","即令人得伴，更亦不相求。"]', '["雙燕子，可可事风流。","即令人得伴，更亦不相求。"]', '诗', 'shi', '', NULL, '詠雙燕子 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4357e781-0b49-44e1-8613-39b08cb6655d', '詠盞', '詠盞', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["發初先向口，欲竟漸伸頭。","從君中道歇，到底郎（《唐人小說》本作即。","）須休。"]', '["發初先向口，欲竟漸伸头。","從君中道歇，到底郎（《唐人小说》本作即。","）須休。"]', '诗', 'shi', '', NULL, '詠盞 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6923d79-bdbc-4580-9836-fea572b5a970', '詠蜂子', '詠蜂子', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["問蜂子，蜂子太無情。","飛來蹈人面，欲似意相輕。","。"]', '["问蜂子，蜂子太無情。","飞来蹈人面，欲似意相轻。","。"]', '诗', 'shi', '', NULL, '詠蜂子 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('807d47ea-8259-473e-a2b6-8de018e4dfad', '詠射雉', '詠射雉', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["大夫巡麥隴，處子習桑間。","若非由一箭，誰能爲解顏。"]', '["大夫巡麦隴，处子習桑间。","若非由一箭，誰能爲解顏。"]', '诗', 'shi', '', NULL, '詠射雉 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3263485b-bd52-4fe0-869e-030d32d0f5fb', '詠弓', '詠弓', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["平生好須弩，得挽則低頭。","聞君把提快，再乞五三籌。"]', '["平生好須弩，得挽則低头。","闻君把提快，再乞五三籌。"]', '诗', 'shi', '', NULL, '詠弓 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b42a643d-767d-4286-8f24-96e129374e50', '詩一首', '诗一首', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["手子從君把，腰支亦任迴。","人家不中物，漸漸逼他來。"]', '["手子從君把，腰支亦任迴。","人家不中物，漸漸逼他来。"]', '诗', 'shi', '', NULL, '詩一首 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5544e25a-6fdd-4190-9e3b-e8a9b1f553ca', '答文成', '答文成', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["素手曾經捉，纖腰又被將。","即今輸口子，餘事可平章。"]', '["素手曾經捉，纖腰又被將。","即今輸口子，餘事可平章。"]', '诗', 'shi', '', NULL, '答文成 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b1e453c-b38c-48d1-8b6e-08e5c0fb0f23', '詩一首', '诗一首', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["元來不相識，判自繼知聞。","天公強多事，今遣若爲分。"]', '["元来不相識，判自繼知闻。","天公強多事，今遣若爲分。"]', '诗', 'shi', '', NULL, '詩一首 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7aec7ad0-6289-4f01-bf38-fd04a08bebcf', '答文成贈別', '答文成贈別', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["鳯錦行須贈，龍梭久絕互。"]', '["鳯錦行須贈，龙梭久絕互。"]', '诗', 'shi', '', NULL, '答文成贈別 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f80bb68-bc2a-4f2e-bf25-8cf0abe4c73e', '報文成雙履', '報文成雙履', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["雙鳥作失伴，兩燕還相屬。","聊以當兒心，竟日承君足。"]', '["雙鸟作失伴，兩燕還相屬。","聊以當兒心，竟日承君足。"]', '诗', 'shi', '', NULL, '報文成雙履 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aabb133b-4f9e-460d-8645-2ef77b6b3c03', '報文成', '報文成', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["他道愁勝死，兒言死勝愁。","愁來百處痛，死去一時休。","。"]', '["他道愁勝死，兒言死勝愁。","愁来百处痛，死去一时休。","。"]', '诗', 'shi', '', NULL, '報文成 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b7fce5f-35ff-4f2c-af35-c310917eb151', '報文成', '報文成', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["他道愁勝死，兒言死勝愁。","日夜懸心憶，知隔幾年秋。"]', '["他道愁勝死，兒言死勝愁。","日夜懸心憶，知隔幾年秋。"]', '诗', 'shi', '', NULL, '報文成 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9250e27b-88b6-46ea-9cb3-1c83bb71d690', '詠筝', '詠筝', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["（案以下各詩，《遊仙窟》雖謂崔五嫂所作，要亦張文成戲墨而已。","）天生素面能留客，發意關情並（《唐人小說》本作併。","）在渠。","莫怪向者頻聲戰，良由得伴乍心虛。"]', '["（案以下各诗，《游仙窟》雖謂崔五嫂所作，要亦張文成戲墨而已。","）天生素面能留客，發意关情並（《唐人小说》本作併。","）在渠。","莫怪向者頻声戰，良由得伴乍心虛。"]', '诗', 'shi', '', NULL, '詠筝 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('313e64d8-6711-4045-adbd-a4d5e8673927', '詩一首', '诗一首', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["娘子爲性好圍碁，逢人劇戲不尋思。","氣欲繼絕先挑眼，既得速罷即須遲。"]', '["娘子爲性好圍碁，逢人劇戲不尋思。","氣欲繼絕先挑眼，既得速罷即須遲。"]', '诗', 'shi', '', NULL, '詩一首 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3023a38a-6841-4909-95e2-5f261c1f02e9', '詠李', '詠李', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["李樹子，元來不是偏。","巧知娘子意，擲果到渠邊。"]', '["李樹子，元来不是偏。","巧知娘子意，擲果到渠邊。"]', '诗', 'shi', '', NULL, '詠李 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14d56d1b-64be-4875-a200-e1feba2e1748', '詩一首', '诗一首', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["他家解事在，未肯輒相瞋。","徑須剛捉著，遮莫造精神。"]', '["他家解事在，未肯輒相瞋。","徑須剛捉著，遮莫造精神。"]', '诗', 'shi', '', NULL, '詩一首 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('524d3e10-aae9-47f6-aa02-eaa43e9dabf1', '又一首', '又一首', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["巧將衣障口，能用被遮身。","定知心肯在，方便故邀人。"]', '["巧將衣障口，能用被遮身。","定知心肯在，方便故邀人。"]', '诗', 'shi', '', NULL, '又一首 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04d1c3e6-c831-4f2d-b983-a8d77c34b794', '又一首', '又一首', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["自隱風流到，人前法用多。","計時應拒得，佯作不禁他。"]', '["自隐风流到，人前法用多。","計时應拒得，佯作不禁他。"]', '诗', 'shi', '', NULL, '又一首 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a1d7f89-b3f8-4f6f-920e-4c22ca48f4fa', '報文成金釵', '報文成金釵', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["兒今贈君別，情知復會難。","莫言釵意小，可以掛渠冠。","（〖1〗《日本圖經》卷二十二《藝文志》：「《遊仙窟》一卷，唐張文成。","昌平學舊寫八行本、容安書院舊寫九行本、尾張真福寺舊寫六行本刊本，卷首題《遊仙窟》，寧州襄樂縣尉張文成作，小說家言也。","寧州，注云屬關內道，在去京三百里西北也。","日本人言是書作嵯峨天皇時，果爾，則唐元和間也。","陳氏矩得刊本。","」〖2〗汪辟疆《唐人小說》：「按張文成《遊仙窟》一卷，唐時流傳日本。","書凡數刻，中土向無傳本。","河世寧曾據之駿補《全唐詩》，楊守敬始著錄於，日本訪書志。","治唐稗者，始稍稍稱焉。","余舊藏鈔本，卷首有『平等閣』及『忠州李士棻隨身書卷』二印記。","卷尾有『壬午三月借遵義黎氏影寫本重校』小字一行，乃知此本爲芋仙舊藏。","芋仙與蒓齋有縞紵之雅。","黎氏在日本刻《古逸叢書》，嘗以初印本寄李，李累索之，不以爲貪。","則此本原鈔，或即出諸黎氏，未可知也。","原鈔卷首題『寧州襄樂縣詩張文成作』。","世因定爲唐張鷟所撰。","鷟字文成，深州陸澤人。","兩《唐書》並附見《張薦傳》。","鷟兒時夢紫文鸑鷟，其祖謂是兒當以文章瑞朝廷，因以爲名字。","調露初，登進士第，授岐王府參軍。","八舉皆登甲科，大有文譽。","調長安尉，遷鴻臚丞。","凡四參選，判策爲銓府之最。","員半千謂人曰：『張子之文，如青錢萬選萬中。","』時目爲青錢學士。","然性褊躁，不持士行。","姚崇甚薄之。","開元初，御史李全交劾鷟訕短提政，貶嶺南。","旋得內徙，入爲司門員外郎。","卒。","鷟下筆敏速，言頗詼諧，大行於時，後進莫不傳記。","新羅、日本東夷諸番，尤重其文。","每遣使入朝，必出重金貝以購其文。","惟浮豔少理致，論著亦率詆誚蕪穢。","〖以上摘兩《唐書》有本傳〗《大唐新語》亦稱鷟後轉洛陽尉，故有《詠燕詩》。","其末章云：『變石身猶重，銜泥力尚微。","從來赴甲第，兩起一雙飛。","』時人無不諷詠云云。","今鷟書之傳於今者，有《龍筋鳯髓判》及《朝野僉載》，而《遊仙窟》一卷無傳，其目亦不見史志及諸家著錄。","然據兩《唐書》即稱日本、新羅争傳其文，而《新語》《詠燕》與《龍筋鳯髓》之作，浮豔鄙倍，與此篇辭旨正復相同。","據此，則《遊仙窟》之出於張鷟，當非僞造也。","」「又按《遊仙窟》不傳於中國，至日本人推重其書，則自唐以來，迄今弗衰，故文學蒙其影響。","其流傳日本之年歲可考者，據慶安五年〖清順治九年〗刻本，前有文保三年〖元延祐六年〗文章生英房序，有『嵯峨天生書卷之中撰得《遊仙窟》』之語。","日本嵯峨天皇當唐元和、長慶間，則是中唐時此書已流傳日本矣。","惟日本最古之《萬葉集》卷四有大伴家持《贈坂上大纕歌》十五首，辭意多與此書相同，後人評論，如契沖阿闍梨，遂繼爲出於《遊仙窟》。","前乎此者，尚在山上憶良《沈疴自哀文》亦引《遊仙窟》云：『九泉下人，一錢不值。","』山上在聖武天皇天平之世，此文爲山上末年之作，正當唐開元二十一年。","是此書於刊載元張鷟尚在之時，即已傳至日本，又早於嵯峨天皇八十餘年。","此徵諸《萬葉集》可信者也。","竊意張氏此書，當爲早年一時興到之作。","當時有無寓意，今不可知。","惟日本當趙宋南渡之時，有西行法師傳鈔之《唐物語》一書，其第九章述及《遊仙窟》本事，定爲張文成愛慕武則天而作。","平康賴《寶物集》卷四亦：『則天皇后，高宗之后也。","遇好色者張文成，得《遊仙窟》之文，所謂「可憎病鵲，夜半驚人」，即指當時之事也』云云。","日人幸田露伴著《蝸牛庵夜談》，頗疑此爲蓮花六郎之傳訛。","因易之、昌宗姓張，而二人之父爲張行成，〖按易之、昌宗爲張行成之族孫，非其父也。","易之父名希臧，見兩《唐書》。","〗文成恰有《遊仙窟》之文，遂牽合而有此一段傳說，固不足深信者也。","至其書辭旨淺鄙，文氣卑下，了無足取。","惟唐人口語，尚賴此略存。","」）。"]', '["兒今贈君別，情知复會难。","莫言釵意小，可以掛渠冠。","（〖1〗《日本圖經》卷二十二《藝文志》：「《游仙窟》一卷，唐張文成。","昌平学旧寫八行本、容安书院旧寫九行本、尾張真福寺旧寫六行本刊本，卷首題《游仙窟》，寧州襄乐縣尉張文成作，小说家言也。","寧州，注云屬关內道，在去京三百里西北也。","日本人言是书作嵯峨天皇时，果爾，則唐元和间也。","陳氏矩得刊本。","」〖2〗汪辟疆《唐人小说》：「按張文成《游仙窟》一卷，唐时流傳日本。","书凡數刻，中土向無傳本。","河世寧曾據之駿補《全唐诗》，楊守敬始著錄於，日本訪书志。","治唐稗者，始稍稍稱焉。","余旧藏鈔本，卷首有『平等閣』及『忠州李士棻隨身书卷』二印記。","卷尾有『壬午三月借遵義黎氏影寫本重校』小字一行，乃知此本爲芋仙旧藏。","芋仙與蒓斋有縞紵之雅。","黎氏在日本刻《古逸叢书》，嘗以初印本寄李，李累索之，不以爲貪。","則此本原鈔，或即出諸黎氏，未可知也。","原鈔卷首題『寧州襄乐縣诗張文成作』。","世因定爲唐張鷟所撰。","鷟字文成，深州陸澤人。","兩《唐书》並附见《張薦傳》。","鷟兒时梦紫文鸑鷟，其祖謂是兒當以文章瑞朝廷，因以爲名字。","調露初，登進士第，授岐王府參軍。","八舉皆登甲科，大有文譽。","調长安尉，遷鴻臚丞。","凡四參選，判策爲銓府之最。","員半千謂人曰：『張子之文，如青錢万選万中。","』时目爲青錢学士。","然性褊躁，不持士行。","姚崇甚薄之。","开元初，御史李全交劾鷟訕短提政，貶嶺南。","旋得內徙，入爲司门員外郎。","卒。","鷟下笔敏速，言頗詼諧，大行於时，後進莫不傳記。","新羅、日本东夷諸番，尤重其文。","每遣使入朝，必出重金貝以購其文。","惟浮豔少理致，論著亦率詆誚蕪穢。","〖以上摘兩《唐书》有本傳〗《大唐新語》亦稱鷟後轉洛陽尉，故有《詠燕诗》。","其末章云：『变石身猶重，銜泥力尚微。","從来赴甲第，兩起一雙飞。","』时人無不諷詠云云。","今鷟书之傳於今者，有《龙筋鳯髓判》及《朝野僉載》，而《游仙窟》一卷無傳，其目亦不见史志及諸家著錄。","然據兩《唐书》即稱日本、新羅争傳其文，而《新語》《詠燕》與《龙筋鳯髓》之作，浮豔鄙倍，與此篇辞旨正复相同。","據此，則《游仙窟》之出於張鷟，當非僞造也。","」「又按《游仙窟》不傳於中国，至日本人推重其书，則自唐以来，迄今弗衰，故文学蒙其影响。","其流傳日本之年歲可考者，據慶安五年〖清順治九年〗刻本，前有文保三年〖元延祐六年〗文章生英房序，有『嵯峨天生书卷之中撰得《游仙窟》』之語。","日本嵯峨天皇當唐元和、长慶间，則是中唐时此书已流傳日本矣。","惟日本最古之《万葉集》卷四有大伴家持《贈坂上大纕歌》十五首，辞意多與此书相同，後人評論，如契沖阿闍梨，遂繼爲出於《游仙窟》。","前乎此者，尚在山上憶良《沈疴自哀文》亦引《游仙窟》云：『九泉下人，一錢不值。","』山上在聖武天皇天平之世，此文爲山上末年之作，正當唐开元二十一年。","是此书於刊載元張鷟尚在之时，即已傳至日本，又早於嵯峨天皇八十餘年。","此徵諸《万葉集》可信者也。","竊意張氏此书，當爲早年一时兴到之作。","當时有無寓意，今不可知。","惟日本當趙宋南渡之时，有西行法師傳鈔之《唐物語》一书，其第九章述及《游仙窟》本事，定爲張文成愛慕武則天而作。","平康賴《寶物集》卷四亦：『則天皇后，高宗之后也。","遇好色者張文成，得《游仙窟》之文，所謂「可憎病鵲，夜半驚人」，即指當时之事也』云云。","日人幸田露伴著《蝸牛庵夜談》，頗疑此爲蓮花六郎之傳訛。","因易之、昌宗姓張，而二人之父爲張行成，〖按易之、昌宗爲張行成之族孫，非其父也。","易之父名希臧，见兩《唐书》。","〗文成恰有《游仙窟》之文，遂牽合而有此一段傳说，固不足深信者也。","至其书辞旨淺鄙，文氣卑下，了無足取。","惟唐人口語，尚賴此略存。","」）。"]', '诗', 'shi', '', NULL, '報文成金釵 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3b0ea52-f270-4c9d-b546-2e523536951b', '酒名', '酒名', '036fa87c-42c8-4bb1-b325-6b9a50c4ccc7', '唐', '["帝鄉從事隙，薄暮中山開。","地域荆南記，人事豫北□。","蘭英{身虎}虹上。","竹葉清風來。","雲物上可惜，落日顧霞杯。","（見影印本《新編纂圖增類要事林廣記》卷七。","）。"]', '["帝乡從事隙，薄暮中山开。","地域荆南記，人事豫北□。","蘭英{身虎}虹上。","竹葉清风来。","云物上可惜，落日顧霞杯。","（见影印本《新編纂圖增類要事林廣記》卷七。","）。"]', '诗', 'shi', '', NULL, '酒名 員半千 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d66bf97-bf62-4fb1-bf24-f219a9fb5232', '風名', '风名', '89552f74-306f-447b-bcb4-ef7e30581023', '唐', '["玉階王道泰，金門詞藻多。","文雄自指引，美景相經過。","野氣連空谷，春色滿長河。","方從君子會，終宴且當歌。","（見影印本《新編纂圖增類羣書類要事林廣記》卷七。","）。"]', '["玉階王道泰，金门词藻多。","文雄自指引，美景相經過。","野氣連空谷，春色满长河。","方從君子會，終宴且當歌。","（见影印本《新編纂圖增類羣书類要事林廣記》卷七。","）。"]', '诗', 'shi', '', NULL, '風名 閭丘均 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cb2ab25-f434-4c5c-afaf-4424c77fad40', '董孝子黯復讎', '董孝子黯复讎', '3379ae1d-ad39-42f1-aa77-0a168f065885', '唐', '["十年心事苦，惟爲復恩仇。","兩意既已盡，碧山吾白頭。","（見鄞縣張壽鏞刻《四明叢書》第一集中《賀祕監集》。","）。"]', '["十年心事苦，惟爲复恩仇。","兩意既已尽，碧山吾白头。","（见鄞縣張壽鏞刻《四明叢书》第一集中《賀祕監集》。","）。"]', '诗', 'shi', '', NULL, '董孝子黯復讎 賀知章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebd1e332-db9d-4471-aeb8-93fc880ce178', '石橋詠', '石橋詠', '50a58740-7564-4b14-8c53-a62c6ab812b6', '唐', '["巨川橫廣路，□涉吟艱危。","巧思侔神□，經途變險戲。","石梁全架□，鐵鏁竟何□。","昔有黿鼉異，今看結構奇。","□□□□補，似迫□龍移。","跨水鼇峯見，凌虛鵬翼垂。","寧勞浮柱設，詎假造舟爲。","代久堤維固，年深砌不隳。","□虹常偃蹇，雲鴈□差池。","□物三方會，傳名四海□。","□鐫起花葉，模寫躍蛟螭。","□矗平踰砥，下穹圓甚規。","□如丹洞出，窓類白巖窺。","□鶴臨華表，詞人訪古碑。","□燕□□□，郢越亘南馳。","□□無濡足，千秋長□□。","（見《文物參攷資料》一九五七年第三期俞同奎作《安濟橋補充文獻》所附詩刻拓片。","）（〖1〗按石刻詩題下原署「趙州長史崔恂」。","《新唐書》卷七十二下《宰相世系表》鄭州崔氏房有崔恂，杭州刺史清河男。","其從叔崔元綜，相武后朝，則恂當是中宗、玄宗時人。","又此詩刻後有魏州司功參軍劉義□《詶崔長史》詩一首，惜已漫漶不可得辨矣。","〖2〗俞同奎文謂此詩見趙縣安濟橋下所得石刻，同時另出一石，與詩石大小相同，後味殘文尚可辨認，錄如次：「□元八年九月□□□□□□李」於時□□□□□崔恂「任深州□史□□□還此橋過喜其壯麗命」舊詩云□志並七年春俞文考定「□元八年」應爲「經營元八年」，所出詩石爲崔恂開元七年在趙州時作，次年由深州重經此橋，序而刻石。","）。"]', '["巨川橫廣路，□涉吟艱危。","巧思侔神□，經途变險戲。","石梁全架□，鐵鏁竟何□。","昔有黿鼉異，今看結構奇。","□□□□補，似迫□龙移。","跨水鼇峯见，凌虛鵬翼垂。","寧勞浮柱設，詎假造舟爲。","代久堤維固，年深砌不隳。","□虹常偃蹇，云鴈□差池。","□物三方會，傳名四海□。","□鐫起花葉，模寫躍蛟螭。","□矗平踰砥，下穹圓甚規。","□如丹洞出，窓類白巖窺。","□鹤臨华表，词人訪古碑。","□燕□□□，郢越亘南驰。","□□無濡足，千秋长□□。","（见《文物參攷資料》一九五七年第三期俞同奎作《安濟橋補充文獻》所附诗刻拓片。","）（〖1〗按石刻诗題下原署「趙州长史崔恂」。","《新唐书》卷七十二下《宰相世系表》鄭州崔氏房有崔恂，杭州刺史清河男。","其從叔崔元綜，相武后朝，則恂當是中宗、玄宗时人。","又此诗刻後有魏州司功參軍劉義□《詶崔长史》诗一首，惜已漫漶不可得辨矣。","〖2〗俞同奎文謂此诗见趙縣安濟橋下所得石刻，同时另出一石，與诗石大小相同，後味殘文尚可辨認，錄如次：「□元八年九月□□□□□□李」於时□□□□□崔恂「任深州□史□□□還此橋過喜其壯丽命」旧诗云□志並七年春俞文考定「□元八年」應爲「經營元八年」，所出诗石爲崔恂开元七年在趙州时作，次年由深州重經此橋，序而刻石。","）。"]', '诗', 'shi', '', NULL, '石橋詠 崔恂 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('133c1491-05bc-4e5b-ab72-502771f95dc1', '遊石門洞（題擬）', '游石门洞（題擬）', '0bc29f7a-6a76-43da-a22d-9ff1b3325156', '唐', '["溪竹亂花鳥，是月春將暮。","登棧過崖畔，空間瞻瀑布。","千齡無斷絕，百尺恒奔注。","高巖迸似珠，半壁灑如霧。","澹艷水澄澈，欹傾石回護。","藥房森自閑，苔徑窅誰遇。","天翠落深沼，雲華生輕樹。","班輪齊効功，嚴馬何能喻？","勝蹟蓋爲寡，花錢遊誠可屢。","謝公鐫舊詞，安得寢章句？","（見《永樂大典》卷一三○七四「一送」「洞」字「石門洞」條〖十四函一百三十四冊〗。","）。"]', '["溪竹亂花鸟，是月春將暮。","登棧過崖畔，空间瞻瀑布。","千齡無斷絕，百尺恒奔注。","高巖迸似珠，半壁灑如霧。","澹艷水澄澈，欹傾石回護。","藥房森自闲，苔徑窅誰遇。","天翠落深沼，云华生轻樹。","班輪齊効功，嚴马何能喻？","勝蹟蓋爲寡，花錢游誠可屢。","謝公鐫旧词，安得寢章句？","（见《永乐大典》卷一三○七四「一送」「洞」字「石门洞」條〖十四函一百三十四冊〗。","）。"]', '诗', 'shi', '', NULL, '遊石門洞（題擬） 裴士淹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e73617b-54b7-45c0-8ba8-6ed995a4852c', '', '', 'c0fc0ba5-25d0-46b1-90b4-9cad06d7d721', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 王英 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7cdcdef-7ad2-41c3-9ff3-be8e1b6bd497', '感石浮圖', '感石浮圖', 'c0fc0ba5-25d0-46b1-90b4-9cad06d7d721', '唐', '["樹福金巖頂，粧巖琢石成。","真容繪美素，圖鏤萬年榮。"]', '["樹福金巖頂，粧巖琢石成。","真容繪美素，圖鏤万年榮。"]', '诗', 'shi', '', NULL, '感石浮圖 王英 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2aeb3eb4-c2a2-4568-83ac-b75664367517', '又一首', '又一首', 'c0fc0ba5-25d0-46b1-90b4-9cad06d7d721', '唐', '["琉𭸻彫瑩美，圖真琢玉成。","神功呈百福，含聚曰光明。","輪寶□霄壯，珠瓔鏤石晶。","感□嚴父志，謁力爲先靈。","（以上二詩見陸增祥輯《八瓊室金石補正》卷五十八。","）（〖1〗《八瓊室金石補正》謂「二詩不著撰人名，當是英輩所作。","」按二詩附於石經山中臺浮圖諸刻之後，是刻先列《王晉造石浮圖記》，標明天寶十二載鶘廿五日建，次列《感怨文》，爲王晉子王英所撰，次刊《感石浮圖》詩二首，末列安禄山題名，曰「御史大夫安禄山供養」，惟「安禄山」三字後人惡其名而鑿之，然尚可辨識。","）。"]', '["琉𭸻彫瑩美，圖真琢玉成。","神功呈百福，含聚曰光明。","輪寶□霄壯，珠瓔鏤石晶。","感□嚴父志，謁力爲先靈。","（以上二诗见陸增祥輯《八瓊室金石補正》卷五十八。","）（〖1〗《八瓊室金石補正》謂「二诗不著撰人名，當是英輩所作。","」按二诗附於石經山中台浮圖諸刻之後，是刻先列《王晉造石浮圖記》，標明天寶十二載鶘廿五日建，次列《感怨文》，爲王晉子王英所撰，次刊《感石浮圖》诗二首，末列安禄山題名，曰「御史大夫安禄山供養」，惟「安禄山」三字後人惡其名而鑿之，然尚可辨識。","）。"]', '诗', 'shi', '', NULL, '又一首 王英 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffeb988c-1852-43e6-986b-6070c48c8fb4', '千秋亭詠（並序）', '千秋亭詠（並序）', 'b33117e8-e883-4ef5-b2b5-b53c28a600c8', '唐', '["飲餞憑何地，依巖闢此亭。","玉江摽勝託，石壁效題銘。","秋染藤宜紫，春圖柳愛青。","樽來是離酌，皆爲送歸情。","（見石刻拓片。","亦見《金石苑》。","）（望按：此詩與《石亭記千秋亭記》合刻一石，記在前，係開元十八年前飛鳥縣主簿趙演撰文，詩居後，題曰「《千秋亭詠》並序」，下署「朝散郎行梓州銅瞐縣詩博陵崔文邕」，詩後有「開元十九年歲次辛未五月五日」一行，當是刻詩年月。","碑在四川中江縣，友人寧鄉程千帆〖會昌〗以所藏拓片見贈，其末並有近人張巽中跋文一段，畧謂「此碑出吾蜀中江縣{身犬}子店，昔何蝯叟督學來川，曾拓數十紙驗歸，祕而不宣。","康長素亦手藏一搨，不以示人。","細玩字裏行間，於晉魏六朝之外，獨具婀娜風致，宜爲道州、南海所寶也」云云。","今細讀斯記，祇稱「石亭」，不及「千秋」之名，而附詩詩題，則明標「千秋」，以是頗疑崔氏始構此亭。","原稱「石亭」，其後乃更名其後乃更名「千秋亭」耳。","然則文題作《石亭記千秋亭記》，其「千秋亭記」四字系開元十九年崔氏刻詩時所後加，不然，安有一文而兼勒二題之理耶。","又此詩亦見劉喜海《金石苑》，惟「玉江」爲異。","劉氏曰：「詩內玉誤王，記誤託，未知是否。","」今按石碑作玉作託，當以拓片爲準。","）。"]', '["饮餞憑何地，依巖闢此亭。","玉江摽勝託，石壁效題銘。","秋染藤宜紫，春圖柳愛青。","樽来是離酌，皆爲送归情。","（见石刻拓片。","亦见《金石苑》。","）（望按：此诗與《石亭記千秋亭記》合刻一石，記在前，係开元十八年前飞鸟縣主簿趙演撰文，诗居後，題曰「《千秋亭詠》並序」，下署「朝散郎行梓州銅瞐縣诗博陵崔文邕」，诗後有「开元十九年歲次辛未五月五日」一行，當是刻诗年月。","碑在四川中江縣，友人寧乡程千帆〖會昌〗以所藏拓片见贈，其末並有近人張巽中跋文一段，畧謂「此碑出吾蜀中江縣{身犬}子店，昔何蝯叟督学来川，曾拓數十紙驗归，祕而不宣。","康长素亦手藏一搨，不以示人。","細玩字裏行间，於晉魏六朝之外，独具婀娜风致，宜爲道州、南海所寶也」云云。","今細读斯記，祇稱「石亭」，不及「千秋」之名，而附诗诗題，則明標「千秋」，以是頗疑崔氏始構此亭。","原稱「石亭」，其後乃更名其後乃更名「千秋亭」耳。","然則文題作《石亭記千秋亭記》，其「千秋亭記」四字系开元十九年崔氏刻诗时所後加，不然，安有一文而兼勒二題之理耶。","又此诗亦见劉喜海《金石苑》，惟「玉江」爲異。","劉氏曰：「诗內玉誤王，記誤託，未知是否。","」今按石碑作玉作託，當以拓片爲準。","）。"]', '诗', 'shi', '', NULL, '千秋亭詠（並序） 崔文邕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9c87c43-3ca4-49c9-bbf4-cbf7c7fb5985', '永嘉懷古（題一作《石門山》）', '永嘉懷古（題一作《石门山》）', '91f16551-a8e2-4297-bca2-00dbfc6fe8b3', '唐', '["永嘉東南盡，□袒《青田志》（作「倚棹」。","）皆可究。","帆引滄海風，舟□（《青田志》作「沿」。","）縉雲溜。","羣瞐何隱磷，萬□（《青田志》作「物」。","）更森秀。","地氣冬轉暄（一作「暝」）瞑（一作暄。","）氛陰改晝。","緬懅謝康樂，□（《青田志》作「伊」，一作「夙」。","）昔兹爲壽（《青田志》作「守」。","）逸興滿雲林，清詞（一作「詩」。","）冠宇宙。","嘗遊石門裏，□□（《青田志》作「勝踐」。","）宛如舊。","峭壁苔蘚濃，懸崖（一作「巖」。","）風雨驟。","巖隈□（《青田志》作「餘」。","）灌莽，□□（《青田志》作「壁畔」。","）空泉甃。","物是人已非，瑶潭淒□□（《青田志》作「懷獨漱」。","）（〖1〗案石刻詩前原署「諸暨縣令郭密之」七字。","〖2〗附《□使永嘉經謝公石門山作》一首〖《全唐詩》題作《永嘉經謝公石門山作》〗：「絕境〖《全唐詩》作「綿境」〗經耳目，未曾〖《全唐詩》、《青田志》並作「嘗」〗曠躋登。","一窺石門險，載〖《全唐詩》作再〗滌心神懵。","洞壑閟金澗，𢽽崖{股/皿}〖《全唐詩》、《青田志》並作「盤」〗石楞。","陰潭下羃羃，秀嶺上層層。","千丈瀑流𠹟〖《全唐詩》、《青田志》並作「蹇」〗，半溪風雨恆〖《全唐詩》作「絙」〗。","興餘志每愜，心遠道自弘〖《青田志》作「宏」〗。","乘軺廣儲佳〖《全唐詩》作「峙」，《青田志》作「偫」〗，祇命愧才能。","輟棹〖《全唐詩》作「櫂」〗周氣象，捫條歷騫崩。","忽如生羽翼，怳若將超〖《全唐詩》作「起」〗騰。","謝客今已矣，我來誰與朋？","」按詩前署「者暨縣令郭密之」七字。","詩末紀「時天寶八載冬仲月勒」九字。","《全唐詩》不記年月。","〖3〗阮元《兩浙金石志》：「右詩刻二種，在青田縣石門洞磨崖。","一《題石門山》，詩及前後題款年月凡十一行：一《永嘉懷古》，詩及題款凡八行，俱正書，徑寸。","嘉慶元年二月，臨海令華氏瑞潢過此摉出之。","按二詩《全唐詩》未載〖望按：《永嘉懷古》《全唐詩》未載，餘一首載在《補遺》卷，阮氏蓋未見耳〗邑志云：郭密之於天寶中令諸暨，建義津橋，築放生湖，溉田二千餘頃，民便之。","舊志止載後《懷古》詩，題作」石門山，而無前詩，未見石刻也。","〖4〗錢大昕《十駕齋養新錄》：「郭密之五言詩二篇，皆刻於青田之石門洞崖壁，前人錄金石者皆未之及。","今芸臺中丞《兩浙金石記》始著之。","詩古淡近選體。","石門尚有徐嶠、張愿詩刻，皆開元天寶間人。","崖石鑱損，唯姓名僅存，詩句莫能辨識矣。","」〖5〗王尚賡雲舫跋：「右石門山唐郭密之詩刻拓本，乃余友芝庭以贈嘉興李金瀾先生者，先生最爲珍秘。","如阮宮保《兩浙金石志》亦載此詩刻。","其《永嘉懷古》詩計缺一十有一字，此拓僅缺二字。","又前詩「偫」，《兩浙金石志》作「仕」，後詩「棹」作「袒」、「守」作「壽」、「宛」作「定」，又《郡志》「伊」作「夙」、「詞」作「詩」、「崖」作「巖」，此拓一一明顯，俱爲核正，可不謂善本乎？","」）（〖6〗雷銑《重修青田縣志》：案前詩八行，行十三字，末行九字。","同治壬戌兵燹後石角斜泐，廑存八十四之。","第二行「𢽽」字。","《金石志》誤作「歌」。","後詩六行，行十七字，末行十五字，尚完好。","〖7〗贊寧《宋高僧傳》卷十七《唐越州焦山大曆寺神邕傳》：「天寶中，本邑郭密之請居法樂寺西坊」云云。","〖8〗馮煦《三修諸暨縣志》：「義津橋，在縣南二里。","放生湖，在安俗鄉，縣東北二里。","」）。"]', '["永嘉东南尽，□袒《青田志》（作「倚棹」。","）皆可究。","帆引滄海风，舟□（《青田志》作「沿」。","）縉云溜。","羣瞐何隐磷，万□（《青田志》作「物」。","）更森秀。","地氣冬轉暄（一作「暝」）瞑（一作暄。","）氛陰改晝。","緬懅謝康乐，□（《青田志》作「伊」，一作「夙」。","）昔兹爲壽（《青田志》作「守」。","）逸兴满云林，清词（一作「诗」。","）冠宇宙。","嘗游石门裏，□□（《青田志》作「勝踐」。","）宛如旧。","峭壁苔蘚濃，懸崖（一作「巖」。","）风雨驟。","巖隈□（《青田志》作「餘」。","）灌莽，□□（《青田志》作「壁畔」。","）空泉甃。","物是人已非，瑶潭淒□□（《青田志》作「懷独漱」。","）（〖1〗案石刻诗前原署「諸暨縣令郭密之」七字。","〖2〗附《□使永嘉經謝公石门山作》一首〖《全唐诗》題作《永嘉經謝公石门山作》〗：「絕境〖《全唐诗》作「綿境」〗經耳目，未曾〖《全唐诗》、《青田志》並作「嘗」〗曠躋登。","一窺石门險，載〖《全唐诗》作再〗滌心神懵。","洞壑閟金澗，𢽽崖{股/皿}〖《全唐诗》、《青田志》並作「盤」〗石楞。","陰潭下羃羃，秀嶺上層層。","千丈瀑流𠹟〖《全唐诗》、《青田志》並作「蹇」〗，半溪风雨恆〖《全唐诗》作「絙」〗。","兴餘志每愜，心远道自弘〖《青田志》作「宏」〗。","乘軺廣儲佳〖《全唐诗》作「峙」，《青田志》作「偫」〗，祇命愧才能。","輟棹〖《全唐诗》作「櫂」〗周氣象，捫條歷騫崩。","忽如生羽翼，怳若將超〖《全唐诗》作「起」〗腾。","謝客今已矣，我来誰與朋？","」按诗前署「者暨縣令郭密之」七字。","诗末紀「时天寶八載冬仲月勒」九字。","《全唐诗》不記年月。","〖3〗阮元《兩浙金石志》：「右诗刻二種，在青田縣石门洞磨崖。","一《題石门山》，诗及前後題款年月凡十一行：一《永嘉懷古》，诗及題款凡八行，俱正书，徑寸。","嘉慶元年二月，臨海令华氏瑞潢過此摉出之。","按二诗《全唐诗》未載〖望按：《永嘉懷古》《全唐诗》未載，餘一首載在《補遺》卷，阮氏蓋未见耳〗邑志云：郭密之於天寶中令諸暨，建義津橋，築放生湖，溉田二千餘頃，民便之。","旧志止載後《懷古》诗，題作」石门山，而無前诗，未见石刻也。","〖4〗錢大昕《十駕斋養新錄》：「郭密之五言诗二篇，皆刻於青田之石门洞崖壁，前人錄金石者皆未之及。","今芸台中丞《兩浙金石記》始著之。","诗古淡近選體。","石门尚有徐嶠、張愿诗刻，皆开元天寶间人。","崖石鑱損，唯姓名僅存，诗句莫能辨識矣。","」〖5〗王尚賡云舫跋：「右石门山唐郭密之诗刻拓本，乃余友芝庭以贈嘉兴李金瀾先生者，先生最爲珍秘。","如阮宮保《兩浙金石志》亦載此诗刻。","其《永嘉懷古》诗計缺一十有一字，此拓僅缺二字。","又前诗「偫」，《兩浙金石志》作「仕」，後诗「棹」作「袒」、「守」作「壽」、「宛」作「定」，又《郡志》「伊」作「夙」、「词」作「诗」、「崖」作「巖」，此拓一一明显，俱爲核正，可不謂善本乎？","」）（〖6〗雷銑《重修青田縣志》：案前诗八行，行十三字，末行九字。","同治壬戌兵燹後石角斜泐，廑存八十四之。","第二行「𢽽」字。","《金石志》誤作「歌」。","後诗六行，行十七字，末行十五字，尚完好。","〖7〗贊寧《宋高僧傳》卷十七《唐越州焦山大曆寺神邕傳》：「天寶中，本邑郭密之請居法乐寺西坊」云云。","〖8〗馮煦《三修諸暨縣志》：「義津橋，在縣南二里。","放生湖，在安俗乡，縣东北二里。","」）。"]', '诗', 'shi', '', NULL, '永嘉懷古（題一作《石門山》） 郭密之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aea3e0e4-2daa-4b09-8766-96509bdb9e27', '琵琶泓石壁詩刻（按《山西通志》《山右金石記》卷九著錄《》，謂「詩七古一首，見《鳯臺縣志》。」檢《全唐詩》無考卷有權澈五言《題沈黎城》一首。此七古《琵琶泓詩》，蓋未收。）', '琵琶泓石壁诗刻（按《山西通志》《山右金石記》卷九著錄《》，謂「诗七古一首，见《鳯台縣志》。」檢《全唐诗》無考卷有權澈五言《題沈黎城》一首。此七古《琵琶泓诗》，蓋未收。）', '98fca7bd-cf69-47d5-90c2-a84a05927a45', '唐', '["咨予白髪年，始佐丹水曲。","夙願解塵組，幸兹洗煩欲。","琵琶翠泓湛且清，屏風畫壁勢相迎。","檉柏颼飀雜風雨，龜龍睗睒游虛明。","北行七里有靈跡，潭中聖字看歷歷。","一符君德應明時，一契吾真誓幽適。","由來此泓□□傳，今夕覩之信可憐。","夷猶頓使宦積薄，日暮濯纓心浩然。","（見乾隆四十八年官刊本《鳯臺縣志》卷十七）（此詩又見胡聘之《山右石刻叢編》卷七，詩題作《琵琶泓作幷序》。","詩前有序，錄如次：「予頃嘗秉憲，負譴而遷，才散數奇，屢移邦國。","爰初至止，即聞有兹勝，迨今一游，果覯殊絕。","澄灣納溜，激射成雷，峭壁迴景，周流如畫，嘉木潛鱗，又不可名也。","北去七里復有石潭焉，潭中有聖字，了了可覩，峰巒相屬，宛似屏障。","閒行其中，潛洞幽窟，信爲靈異。","予超然有獨往之意，而賦是詩。","」詩中有二處稍異。","第六句「相迎」作「相適」，疑誤。","第十五句琵琶泓石壁詩刻「宦積」作「宣清」，疑原應作「宦情」。","）（〖1〗《鳯臺縣志》〖姚學甲等纂修〗卷十九《輯錄部》謂：「唐清九壁詩序石刻在琵琶泓，朝議大夫高平郡別駕權澈詞，錢塘縣尉瑯琊王紓書，天寶五載夏五月二十日。","從末行逆讀自序，其秉憲被譴，來佐丹曲，訪兹勝遊，詩字俱佳。","考天寶五載、元宗丙戌。","權澈名，新舊《唐書》俱不載。","權氏，《宰相世系表》及姓族諸書並無其人，或非天水一族也。","郡人王紓，想以瑯琊地望而係之。","」）。"]', '["咨予白髪年，始佐丹水曲。","夙願解塵組，幸兹洗煩欲。","琵琶翠泓湛且清，屏风畫壁勢相迎。","檉柏颼飀杂风雨，龟龙睗睒游虛明。","北行七里有靈跡，潭中聖字看歷歷。","一符君德應明时，一契吾真誓幽適。","由来此泓□□傳，今夕覩之信可怜。","夷猶頓使宦積薄，日暮濯纓心浩然。","（见乾隆四十八年官刊本《鳯台縣志》卷十七）（此诗又见胡聘之《山右石刻叢編》卷七，诗題作《琵琶泓作幷序》。","诗前有序，錄如次：「予頃嘗秉憲，負譴而遷，才散數奇，屢移邦国。","爰初至止，即闻有兹勝，迨今一游，果覯殊絕。","澄灣納溜，激射成雷，峭壁迴景，周流如畫，嘉木潛鱗，又不可名也。","北去七里复有石潭焉，潭中有聖字，了了可覩，峰巒相屬，宛似屏障。","閒行其中，潛洞幽窟，信爲靈異。","予超然有独往之意，而賦是诗。","」诗中有二处稍異。","第六句「相迎」作「相適」，疑誤。","第十五句琵琶泓石壁诗刻「宦積」作「宣清」，疑原應作「宦情」。","）（〖1〗《鳯台縣志》〖姚学甲等纂修〗卷十九《輯錄部》謂：「唐清九壁诗序石刻在琵琶泓，朝議大夫高平郡別駕權澈词，錢塘縣尉瑯琊王紓书，天寶五載夏五月二十日。","從末行逆读自序，其秉憲被譴，来佐丹曲，訪兹勝游，诗字俱佳。","考天寶五載、元宗丙戌。","權澈名，新旧《唐书》俱不載。","權氏，《宰相世系表》及姓族諸书並無其人，或非天水一族也。","郡人王紓，想以瑯琊地望而係之。","」）。"]', '诗', 'shi', '', NULL, '琵琶泓石壁詩刻（按《山西通志》《山右金石記》卷九著錄《》，謂「詩七古一首，見《鳯臺縣志》。」檢《全唐詩》無考卷有權澈五言《題沈黎城》一首。此七古《琵琶泓詩》，蓋未收。） 權澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2303e027-2b90-49cf-93db-7b28999081d6', '送張舍人往江東（此詩見韋莊《又玄集》卷上。案《全唐詩》卷一七五作李白詩，題曰《關張舍人之江東》，詩同，不重錄。惟第二句「正在秋風時」，《全唐詩》「在」字作「值」，三句「天晴一雁遠」，「晴」字作「清」爲異耳。〖《文苑英華》卷二六九、《唐文粹》卷十五、影宋本《李太白文集》卷十四皆收此詩爲李白作。〗）', '送張舍人往江东（此诗见韋莊《又玄集》卷上。案《全唐诗》卷一七五作李白诗，題曰《关張舍人之江东》，诗同，不重錄。惟第二句「正在秋风时」，《全唐诗》「在」字作「值」，三句「天晴一雁远」，「晴」字作「清」爲異耳。〖《文苑英华》卷二六九、《唐文粹》卷十五、影宋本《李太白文集》卷十四皆收此诗爲李白作。〗）', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '送張舍人往江東（此詩見韋莊《又玄集》卷上。案《全唐詩》卷一七五作李白詩，題曰《關張舍人之江東》，詩同，不重錄。惟第二句「正在秋風時」，《全唐詩》「在」字作「值」，三句「天晴一雁遠」，「晴」字作「清」爲異耳。〖《文苑英華》卷二六九、《唐文粹》卷十五、影宋本《李太白文集》卷十四皆收此詩爲李白作。〗） 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eb5f180-8d6c-40cc-a05c-2c45a2dabe24', '', '', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f5aec4c-3ce4-4ee9-973b-47e709361fa2', '易言', '易言', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["長風如刀剪枯葉，大河似箭浮輕舟。","投石入水豈有礙，走丸下坂安得留。","（見影印本《新編纂圖增羣書類要事林廣記》卷七。","按《全唐詩》卷一九五收韋應物《易言》一首，與此詩全異。","）。"]', '["长风如刀剪枯葉，大河似箭浮轻舟。","投石入水豈有礙，走丸下坂安得留。","（见影印本《新編纂圖增羣书類要事林廣記》卷七。","按《全唐诗》卷一九五收韋應物《易言》一首，與此诗全異。","）。"]', '诗', 'shi', '', NULL, '易言 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bc510c5-85d8-4c7f-b20f-69f3bedc1553', '句', '句', '9018bde3-4592-4e11-bf37-34bdad09c2ba', '唐', '["歲晏以爲期。","（《韋江州集》卷五有韋應物作《酬盧嵩秋夜見寄五韻》，詩末原註曰：「盧詩云歲晏以爲期之句。","」按盧詩不傳，此雖隻句，亦彌足珍。","）。"]', '["歲晏以爲期。","（《韋江州集》卷五有韋應物作《酬盧嵩秋夜见寄五韻》，诗末原註曰：「盧诗云歲晏以爲期之句。","」按盧诗不傳，此雖隻句，亦彌足珍。","）。"]', '诗', 'shi', '', NULL, '句 盧嵩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4798ce9-c3a2-400f-8c32-7128450b0409', '', '', '2a30e6f1-6127-4553-b0b8-4e04d0f59102', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 李揆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db2932d1-8a3f-4693-b68a-99f4dae77969', '句', '句', '2a30e6f1-6127-4553-b0b8-4e04d0f59102', '唐', '["免相踐蓬閣，臥痾淮海濱。","偶逢潘川守，宛是洛陽親。","（「洛陽」，《四部叢刊》影明本、中華上編本《唐詩紀事》皆作「潘陽」。","）。"]', '["免相踐蓬閣，臥痾淮海濱。","偶逢潘川守，宛是洛陽親。","（「洛陽」，《四部叢刊》影明本、中华上編本《唐诗紀事》皆作「潘陽」。","）。"]', '诗', 'shi', '', NULL, '句 李揆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('202c1e80-b368-4fd4-8a57-2069ed80d603', '又句', '又句', '2a30e6f1-6127-4553-b0b8-4e04d0f59102', '唐', '["共仰新侯伯，同瞻舊宰臣。"]', '["共仰新侯伯，同瞻旧宰臣。"]', '诗', 'shi', '', NULL, '又句 李揆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('848fd6f2-a99c-4a74-85d2-7b55ef5de88b', '又句', '又句', '2a30e6f1-6127-4553-b0b8-4e04d0f59102', '唐', '["鄉路轅思北，家林巷喜雨。","以上各句見《四部叢刊》本《唐詩紀事》卷二十八，注云：「出《江鄰幾雜志》。","」（《唐詩紀事》卷二十八《李揆》條云：「揆與饒州刺史封漸仲容叔霽連句，揆筆力遒媚。","」）。"]', '["乡路轅思北，家林巷喜雨。","以上各句见《四部叢刊》本《唐诗紀事》卷二十八，注云：「出《江鄰幾杂志》。","」（《唐诗紀事》卷二十八《李揆》條云：「揆與饒州刺史封漸仲容叔霽連句，揆笔力遒媚。","」）。"]', '诗', 'shi', '', NULL, '又句 李揆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05ecf53b-2c7f-46ec-8238-4d9a4a0a1590', '夜聽擣衣詩', '夜听擣衣诗', 'b0d880c0-1481-4d38-bac1-3405036e9284', '唐', '["霜天月照夜河明，客子思歸別有情。","厭坐長宵愁欲死，忽聞鄰女擣衣聲。","聲來繼續因風至，夜久星低無暫止。","自從別國不相聞，今在他鄉聽相似。","不知綵杵重將輕，不悉青砧（一作「碪」）平不平。","遙憐體弱多香汗，預識更深勞玉腕。","爲當欲救客衣單，爲復先愁閨閣寒。","雖忘容儀難可問，不知遙意怨無端。","寄異土兮無新識，想同心兮長歎傦。","此時獨自閨中聞，此夜誰知明眸縮。","憶憶兮心已懸，重聞（一作「閉」）兮不可穿。","既將因夢尋聲去，只爲愁多不得眠。","（詩見金毓黻撰集《渤海國志長編》卷十八引《經國集》十三。","）。"]', '["霜天月照夜河明，客子思归別有情。","厭坐长宵愁欲死，忽闻鄰女擣衣声。","声来繼續因风至，夜久星低無暫止。","自從別国不相闻，今在他乡听相似。","不知綵杵重將轻，不悉青砧（一作「碪」）平不平。","遙怜體弱多香汗，預識更深勞玉腕。","爲當欲救客衣單，爲复先愁閨閣寒。","雖忘容儀难可问，不知遙意怨無端。","寄異土兮無新識，想同心兮长歎傦。","此时独自閨中闻，此夜誰知明眸縮。","憶憶兮心已懸，重闻（一作「閉」）兮不可穿。","既將因梦尋声去，只爲愁多不得眠。","（诗见金毓黻撰集《渤海国志长編》卷十八引《經国集》十三。","）。"]', '诗', 'shi', '', NULL, '夜聽擣衣詩 楊泰師 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee5ff5a2-f7ca-4863-b345-0ebd351cdf05', '奉和紀朝臣公咏雪詩', '奉和紀朝臣公咏雪诗', 'b0d880c0-1481-4d38-bac1-3405036e9284', '唐', '["昨夜龍雲（一作「樓」）上，今朝鶴雪新。","祇（一作「怪」）看花發樹，不聽鳥驚春。","迴影疑神女，高歌似郢人。","幽蘭難可繼，更欲效而嚬。","（同前引《經國集》十三。","）（按《續日本紀》云：「寶字三年正月，大保藤原惠美朝臣押勝安蕃客於田村第，當代文士賦詩送別，副使揚泰師作詩和之。","」寶字，系日本淳仁天皇年號，即天平寶字。","天平寶字三年，當唐肅宗乾元二年，渤海文王大興二十二年。","）。"]', '["昨夜龙云（一作「楼」）上，今朝鹤雪新。","祇（一作「怪」）看花發樹，不听鸟驚春。","迴影疑神女，高歌似郢人。","幽蘭难可繼，更欲效而嚬。","（同前引《經国集》十三。","）（按《續日本紀》云：「寶字三年正月，大保藤原惠美朝臣押勝安蕃客於田村第，當代文士賦诗送別，副使揚泰師作诗和之。","」寶字，系日本淳仁天皇年號，即天平寶字。","天平寶字三年，當唐肅宗乾元二年，渤海文王大兴二十二年。","）。"]', '诗', 'shi', '', NULL, '奉和紀朝臣公咏雪詩 楊泰師 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccc853c5-2178-4126-a284-c0883f133870', '詩一首', '诗一首', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["簿領日盈機，知君傲煩囂。","飲和自忘渴，况以初筵招。","道契跡自親，誰爲列宿遙。","（誰爲，《文苑英華》卷七一○引此序作「誰謂」。","）何用結同心，綠琴復長瓢。","日月若走馬，炎涼催斗杓。","一年解頤笑，（解頤笑，《文苑英華》作「解大笑」。","）幾日如今宵。","奉君千金壽，莫使歲寒凋。","（案此詩載《全唐文》卷三百八十七獨孤及《冬夜裴員外薛侍御置酒安集序》一文中。","）。"]', '["簿領日盈機，知君傲煩囂。","饮和自忘渴，况以初筵招。","道契跡自親，誰爲列宿遙。","（誰爲，《文苑英华》卷七一○引此序作「誰謂」。","）何用結同心，綠琴复长瓢。","日月若走马，炎涼催斗杓。","一年解頤笑，（解頤笑，《文苑英华》作「解大笑」。","）幾日如今宵。","奉君千金壽，莫使歲寒凋。","（案此诗載《全唐文》卷三百八十七独孤及《冬夜裴員外薛侍御置酒安集序》一文中。","）。"]', '诗', 'shi', '', NULL, '詩一首 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9434ed5e-6e69-4b43-9fe2-175c17d21ad0', '又一首', '又一首', 'e9481761-c453-4e85-b998-73657eaad8d7', '唐', '["上天垂光兮熙予以青春，今日何日兮共此良辰。","與君觥濁酒而藉落英兮，（「觥濁酒」，《唐文粹》卷九六引此序作「觵濁醪」。","）如年華之相親。","（「如年華之相親」，《唐文粹》作「不知年華之相親」。","）蹇淹留以醉止。","孰云含意而未申。","（案此詩載《全唐文》卷三百八十七獨孤及《仲春裴胄先宅宴集聯句賦詩序》一文中。","）。"]', '["上天垂光兮熙予以青春，今日何日兮共此良辰。","與君觥濁酒而藉落英兮，（「觥濁酒」，《唐文粹》卷九六引此序作「觵濁醪」。","）如年华之相親。","（「如年华之相親」，《唐文粹》作「不知年华之相親」。","）蹇淹留以醉止。","孰云含意而未申。","（案此诗載《全唐文》卷三百八十七独孤及《仲春裴胄先宅宴集聯句賦诗序》一文中。","）。"]', '诗', 'shi', '', NULL, '又一首 獨孤及 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c2abfaf-9963-4284-8ff7-885e2ec5c478', '石門歌', '石门歌', '05fa8bff-4104-47df-b5db-d45163f3a4d0', '唐', '["左一石，右一石，石門中有□□客。","□岫□，懸崖裂，□江□□□劍闕。","□□□□□□□，石門窊尊□□□。","外□□□□，□□□□□。","（見《武昌志》及《湖北金石志》。","已殘缺不可讀，惜哉。","）（〖1〗《武昌志》〖《湖北金石志》同〗：「案馬紹基云：是刻濱臨大江，字跡漫漶，前後片存二十八字，幸題與姓名尚完好。","今又齧去數字矣。","」〖2〗《明一統志》：「石門山在武昌縣東五里，兩門對峙如門。","唐武昌令馬珦與元結遊，石刻尚存。","」〖3〗《輿地碑目》：唐令君馬珦石門石刻在石門。","郭詳正詩：『雙崖屹然起，劖蘚認題識。","』〖4〗陳詩《湖北金石存佚考》云：「無年號，在武昌縣北，濱江。","」〖5〗案清巖觀有《馬珦石門題名詩》曰：「石門開左右，一劍自中分。","何人施妙法，千載創奇聞。","良吏多幽思，詩題亦出羣。","登山尋古蹟，迭石意何殷。","江上發清嘯，厓前結翠雲。","至今樊口上，誰不愛清蒼。","我亦來訪古，心事何紛紛。","憶到窊尊石，題名定有君。","」）。"]', '["左一石，右一石，石门中有□□客。","□岫□，懸崖裂，□江□□□劍闕。","□□□□□□□，石门窊尊□□□。","外□□□□，□□□□□。","（见《武昌志》及《湖北金石志》。","已殘缺不可读，惜哉。","）（〖1〗《武昌志》〖《湖北金石志》同〗：「案马紹基云：是刻濱臨大江，字跡漫漶，前後片存二十八字，幸題與姓名尚完好。","今又齧去數字矣。","」〖2〗《明一統志》：「石门山在武昌縣东五里，兩门对峙如门。","唐武昌令马珦與元結游，石刻尚存。","」〖3〗《輿地碑目》：唐令君马珦石门石刻在石门。","郭詳正诗：『雙崖屹然起，劖蘚認題識。","』〖4〗陳诗《湖北金石存佚考》云：「無年號，在武昌縣北，濱江。","」〖5〗案清巖观有《马珦石门題名诗》曰：「石门开左右，一劍自中分。","何人施妙法，千載創奇闻。","良吏多幽思，诗題亦出羣。","登山尋古蹟，迭石意何殷。","江上發清嘯，厓前結翠云。","至今樊口上，誰不愛清蒼。","我亦来訪古，心事何紛紛。","憶到窊尊石，題名定有君。","」）。"]', '诗', 'shi', '', NULL, '石門歌 馬珦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adfe0e27-9134-4d3a-b27b-f6b0c845bb88', '送薛縣丞還家', '送薛縣丞還家', 'b3961a41-e769-47be-a3dd-1410bb78ecda', '唐', '["之子一爲別，秋霜萬里心。","野花山路冷，明月柳邊陰。","聚首情猶淺，垂鞭意更深。","望君自珍重，幽賞託瑶琴。"]', '["之子一爲別，秋霜万里心。","野花山路冷，明月柳邊陰。","聚首情猶淺，垂鞭意更深。","望君自珍重，幽賞託瑶琴。"]', '诗', 'shi', '', NULL, '送薛縣丞還家 常袞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f558ee5-d081-4656-82b3-6124886cbbdc', '赴京旅次感懷', '赴京旅次感懷', 'b3961a41-e769-47be-a3dd-1410bb78ecda', '唐', '["萬里雲煙繞畫樓，客居無事轉深愁。","秋風翠閣看初動，玉露金莖望欲流。","廿載承恩誰報主，一生僚屬且封侯。","明朝努力長安道，不爲晴川戀舊遊。","（以上二詩見沁泉山館郭柏蒼校刊本《唐制詔集》。","）。"]', '["万里云煙繞畫楼，客居無事轉深愁。","秋风翠閣看初动，玉露金莖望欲流。","廿載承恩誰報主，一生僚屬且封侯。","明朝努力长安道，不爲晴川戀旧游。","（以上二诗见沁泉山館郭柏蒼校刊本《唐制詔集》。","）。"]', '诗', 'shi', '', NULL, '赴京旅次感懷 常袞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84b0f75f-b06e-4a24-8353-e14687d6b6da', '', '', '1b411f11-f144-403d-9bd1-04249fcfff50', '唐', '["徐源字太初，高平人。","詩一首。","（《全唐詩》無徐源詩）。"]', '["徐源字太初，高平人。","诗一首。","（《全唐诗》無徐源诗）。"]', '诗', 'shi', '', NULL, ' 徐源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7992a5c-e098-4e29-a5e3-fc469f3a5127', '題靈泉寺', '題靈泉寺', '1b411f11-f144-403d-9bd1-04249fcfff50', '唐', '["竹園無外事，祕殿夕陰生。","雲起靈峯隱，風來寶鐸鳴。","焚香流玉戶，聽鳥度金楹。","静心歸正法，方此謝塵纓。","（見武虛谷《安陽縣金石錄》。","）（詩下原題「高平徐源字太初」七字。","又紀「皇唐八葉大曆六年歲次辛亥夏四月旬有五日」十九字。","）。"]', '["竹园無外事，祕殿夕陰生。","云起靈峯隐，风来寶鐸鳴。","焚香流玉戶，听鸟度金楹。","静心归正法，方此謝塵纓。","（见武虛谷《安陽縣金石錄》。","）（诗下原題「高平徐源字太初」七字。","又紀「皇唐八葉大曆六年歲次辛亥夏四月旬有五日」十九字。","）。"]', '诗', 'shi', '', NULL, '題靈泉寺 徐源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1b2cfa1-ea5b-438f-88dd-24e62ed9e32e', '題靈泉寺', '題靈泉寺', '26569687-12db-4339-94b1-84e9e64f0ef5', '唐', '["梵宇栖真所，寥寥世事稀。","老僧[披]（被）百納，童子學三歸。","寶剎臨香地，星宮隱翠微。","誰憐漂泊者，於此遂忘機。","（亦見《安陽縣金石錄》。","）（按此詩與徐源詩刻一石，詩下原題「東海徐淮字黃河」七字。","〖1〗徐淮，原作「徐涵」，從《文物》一九八六年第三期靈泉寺石刻拓片改。","四詩亦據改數字。","）。"]', '["梵宇栖真所，寥寥世事稀。","老僧[披]（被）百納，童子学三归。","寶剎臨香地，星宮隐翠微。","誰怜漂泊者，於此遂忘機。","（亦见《安陽縣金石錄》。","）（按此诗與徐源诗刻一石，诗下原題「东海徐淮字黄河」七字。","〖1〗徐淮，原作「徐涵」，從《文物》一九八六年第三期靈泉寺石刻拓片改。","四诗亦據改數字。","）。"]', '诗', 'shi', '', NULL, '題靈泉寺 徐淮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc267111-b4c6-43cf-8ce0-bedd090054cf', '題靈泉寺', '題靈泉寺', '914ad71b-5d68-4444-aa6c-3f72322a5461', '唐', '["煙景[晝]（盡）冥冥，樓臺隱翠屏。","猨攀太子樹，鳥聽《法王經》。","悟理心無著，求緣塔有靈。","迴車猶未遠，日暮數峯青。","（亦見《安陽縣金石錄》。","）（按此詩與徐源、徐淮詩刻一石，詩下原題「廣平程序字[土]〖古〗倫」七字。","）。"]', '["煙景[晝]（尽）冥冥，楼台隐翠屏。","猨攀太子樹，鸟听《法王經》。","悟理心無著，求緣塔有靈。","迴车猶未远，日暮數峯青。","（亦见《安陽縣金石錄》。","）（按此诗與徐源、徐淮诗刻一石，诗下原題「廣平程序字[土]〖古〗倫」七字。","）。"]', '诗', 'shi', '', NULL, '題靈泉寺 程序 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8a53713-7c3e-4042-b2af-01c36ae6f040', '題靈泉寺', '題靈泉寺', 'f70f01aa-2b64-460b-9107-a770840b5eaf', '唐', '["物外經行處，雲峯斷復連。","散花飛講席，輕翠澹鑪煙。","稽首求真偈，觀空[息]（悉）衆緣。","有時聞法皷，應是會諸天。","（見《安陽縣金石錄》。","）（〖1〗按此詩與徐源、徐淮、程序詩刻於一石，詩下原題「高平徐泳字太和」七字。","又以上四詩皆正書，「皇唐八{葉世=云}大歷六年歲次辛亥夏四月旬有五日」立在善應山。","〖2〗武虛谷《安陽縣金石錄》卷四：案詩共刻一石音律最詳雅，《全唐詩》未及採錄，宜以此補之。","前題『皇唐八{葉世=云}』自高祖至代宗數之，刪殤帝不書也。","葉避太宗諱，作{葉世=云}，易中世字爲云。","）。"]', '["物外經行处，云峯斷复連。","散花飞講席，轻翠澹鑪煙。","稽首求真偈，观空[息]（悉）衆緣。","有时闻法皷，應是會諸天。","（见《安陽縣金石錄》。","）（〖1〗按此诗與徐源、徐淮、程序诗刻於一石，诗下原題「高平徐泳字太和」七字。","又以上四诗皆正书，「皇唐八{葉世=云}大歷六年歲次辛亥夏四月旬有五日」立在善應山。","〖2〗武虛谷《安陽縣金石錄》卷四：案诗共刻一石音律最詳雅，《全唐诗》未及採錄，宜以此補之。","前題『皇唐八{葉世=云}』自高祖至代宗數之，刪殤帝不书也。","葉避太宗諱，作{葉世=云}，易中世字爲云。","）。"]', '诗', 'shi', '', NULL, '題靈泉寺 徐泳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('656791f5-77dc-4373-9820-560810e60b8c', '翻經臺', '翻經台', 'f0291ff9-1be0-4891-9e37-9f7b1a0c8fc6', '唐', '["野蔓高臺下，前朝記不誣。","金文翻古偈，漢字變胡書。","綵缐風飄斷，緗縑火燼餘。","破雲開白日，穿水照芙蕖。","科斗頻更改，菴園幾遍鋤。","真門兼逸韻，兩欲慕相如。","（見《永樂大典》卷二六○三「七皆」「臺」邁「翻經臺」條〖三函三十冊〗。","復見同書卷六六九九「十八陽」「江」字〖七函六十四冊〗。","）（見《吉石庵叢書》影印日本存古抄本北宋陳舜俞《廬山記》卷四。","）。"]', '["野蔓高台下，前朝記不誣。","金文翻古偈，漢字变胡书。","綵缐风飄斷，緗縑火燼餘。","破云开白日，穿水照芙蕖。","科斗頻更改，菴园幾遍鋤。","真门兼逸韻，兩欲慕相如。","（见《永乐大典》卷二六○三「七皆」「台」邁「翻經台」條〖三函三十冊〗。","复见同书卷六六九九「十八陽」「江」字〖七函六十四冊〗。","）（见《吉石庵叢书》影印日本存古抄本北宋陳舜俞《廬山記》卷四。","）。"]', '诗', 'shi', '', NULL, '翻經臺 包佶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('239006e5-0f8f-4e06-94fc-3454403affff', '金山', '金山', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["中江一柱碧崚嶒，壁立千尋我獨登。","梵唄波隨招過客，鐘聲船載送歸僧。","窗前白上浪三尺，嶺上青堆雲幾層。","六代風流衰歇盡，慿欄感喟意難勝。","（見丹徒陶紹萊輯《潤州唐人集》卷七，云：「見凈談《金山志》及繆潛《新志》。","」）。"]', '["中江一柱碧崚嶒，壁立千尋我独登。","梵唄波隨招過客，鐘声船載送归僧。","窗前白上浪三尺，嶺上青堆云幾層。","六代风流衰歇尽，慿欄感喟意难勝。","（见丹徒陶紹萊輯《潤州唐人集》卷七，云：「见凈談《金山志》及繆潛《新志》。","」）。"]', '诗', 'shi', '', NULL, '金山 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ed1abf1-bde8-49be-aa66-0c36c8583c93', '送韓司直', '送韓司直', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["（見宋趙師秀《衆妙集》，並見宋周弼《唐三體詩》卷六。","按《全唐詩》卷一百八十四作劉長卿詩，詩同，校其異文如下：首句「遊吳還適越」，「適」，《全唐詩》作「入」。","五句「山明殘雪在」，「山」，《全唐詩》作「岸」。","七句「季子留遺廟」，《全唐詩》作「季子楊柳廟」。","又《唐三體詩》本元釋圓至於此句下注曰：「皇覽《冢墓記》：季子冢在毘陵縣暨陽鄉，至今吏唐民祀事。","」〖唐姚合《極玄集》、宋計有功《唐詩紀事》卷二七均作皇甫冉詩，《文苑英華》卷二七二作皇甫曾詩，《四部叢刊》影明正德本《劉隨州文集》卷三則作劉詩。","似亦皇甫冉所作爲是。","〗）。"]', '["（见宋趙師秀《衆妙集》，並见宋周弼《唐三體诗》卷六。","按《全唐诗》卷一百八十四作劉长卿诗，诗同，校其異文如下：首句「游吳還適越」，「適」，《全唐诗》作「入」。","五句「山明殘雪在」，「山」，《全唐诗》作「岸」。","七句「季子留遺廟」，《全唐诗》作「季子楊柳廟」。","又《唐三體诗》本元釋圓至於此句下注曰：「皇覽《冢墓記》：季子冢在毘陵縣暨陽乡，至今吏唐民祀事。","」〖唐姚合《極玄集》、宋計有功《唐诗紀事》卷二七均作皇甫冉诗，《文苑英华》卷二七二作皇甫曾诗，《四部叢刊》影明正德本《劉隨州文集》卷三則作劉诗。","似亦皇甫冉所作爲是。","〗）。"]', '诗', 'shi', '', NULL, '送韓司直 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7ed2189-f1d1-4dd5-98f8-1104b7e8c4ef', '送人詩（見《學海類編》唐賈島撰《二南密旨》，題曰皇甫曾《送人詩》，亦見宋周弼《唐三體詩》卷六，題曰《途中送權曙》，皇甫曾作。按唐姚合《極玄集》卷下選此詩，作皇甫冉詩，題曰《途中送權二兄》。《全唐詩》卷二百四十九作皇甫冉詩，題曰《途中送權三兄弟》。又卷二百九十六作張南史詩，題曰《西陵懷靈一上人兼寄朱放》，詩同。校其異文如次：「淮海風濤起，江關幽」〖《極玄集》及《全唐詩》皇甫冉卷張南史卷並作「憂」。〗思長同。悲鵲遶樹，獨作〖《全唐詩》張南史卷作「坐」〗雁隨陽。山晚雲和〖《全唐詩》皇甫冉卷作「初」，張', '送人诗（见《学海類編》唐賈島撰《二南密旨》，題曰皇甫曾《送人诗》，亦见宋周弼《唐三體诗》卷六，題曰《途中送權曙》，皇甫曾作。按唐姚合《極玄集》卷下選此诗，作皇甫冉诗，題曰《途中送權二兄》。《全唐诗》卷二百四十九作皇甫冉诗，題曰《途中送權三兄弟》。又卷二百九十六作張南史诗，題曰《西陵懷靈一上人兼寄朱放》，诗同。校其異文如次：「淮海风濤起，江关幽」〖《極玄集》及《全唐诗》皇甫冉卷張南史卷並作「憂」。〗思长同。悲鵲遶樹，独作〖《全唐诗》張南史卷作「坐」〗雁隨陽。山晚云和〖《全唐诗》皇甫冉卷作「初」，張', 'd45ca94c-a2de-465d-8739-0a5f488aa217', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '送人詩（見《學海類編》唐賈島撰《二南密旨》，題曰皇甫曾《送人詩》，亦見宋周弼《唐三體詩》卷六，題曰《途中送權曙》，皇甫曾作。按唐姚合《極玄集》卷下選此詩，作皇甫冉詩，題曰《途中送權二兄》。《全唐詩》卷二百四十九作皇甫冉詩，題曰《途中送權三兄弟》。又卷二百九十六作張南史詩，題曰《西陵懷靈一上人兼寄朱放》，詩同。校其異文如次：「淮海風濤起，江關幽」〖《極玄集》及《全唐詩》皇甫冉卷張南史卷並作「憂」。〗思長同。悲鵲遶樹，獨作〖《全唐詩》張南史卷作「坐」〗雁隨陽。山晚雲和〖《全唐詩》皇甫冉卷作「初」，張 皇甫曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5627f48a-ef9a-4e6e-9148-1aecc0be921d', '暇日題草堂', '暇日題草堂', '0afc7911-b074-4331-bf0b-be0e49a2dbce', '唐', '["爲郎過壯歲，晚景對秋天。","門掩蒼苔上，池清寒竹前。","通經未拾紫，煉藥不成仙。","且醖東臯黍，愁來得醉眠。","（見宋趙師秀編选《唐衆妙集》。","）。"]', '["爲郎過壯歲，晚景对秋天。","门掩蒼苔上，池清寒竹前。","通經未拾紫，煉藥不成仙。","且醖东臯黍，愁来得醉眠。","（见宋趙師秀編选《唐衆妙集》。","）。"]', '诗', 'shi', '', NULL, '暇日題草堂 錢起 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1869336-c181-482e-922b-093660e76dcc', '雲門山投龍詩刻（並序）', '云门山投龙诗刻（並序）', '5fd82f99-7ca5-4206-bbe1-0161c64e04c5', '唐', '["（按《全唐詩》卷二百五十八收此詩，《山左金石志》石刻亦載之，惟異文較多，且序中有二十餘字，詩中有四句爲《全唐詩》所無，故重爲錄出，而以《全唐詩》校之。","）。"]', '["（按《全唐诗》卷二百五十八收此诗，《山左金石志》石刻亦載之，惟異文較多，且序中有二十餘字，诗中有四句爲《全唐诗》所無，故重爲錄出，而以《全唐诗》校之。","）。"]', '诗', 'shi', '', NULL, '雲門山投龍詩刻（並序） 赵居貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de1e74bb-31ab-454b-9142-cf5300d7ab02', '雲門山投龍詩刻（並序）', '云门山投龙诗刻（並序）', '5fd82f99-7ca5-4206-bbe1-0161c64e04c5', '唐', '["□□（《全唐詩》作「曉登」）雲門山，直上壹千尺。","絕頂彌□（《全唐詩》作「孤」。","）聳，盤途幾傾窄。","前對堅裂峯，□□（《全唐詩》作「下臨」。","）削成壁。","陽□（《全唐詩》作「巘」。","）靈芝秀，陰崖仙乳□。","（此句《全唐詩》作「陰崖半天赤」。","）□□□羣山，遠望何所隔。","太陽未出海，曠晃半天赤。","（《全唐詩》無以上四句。","）大壑静不波，渺溟無際碧。","（「碧」，《全唐詩》作「極」。","）是時雪初霽，沍寒冰（《全唐詩》作「水」。","）更積。","恭（《全唐詩》誤作「披」）展送龍儀，寧安服狐白。","□□（《全唐詩》作「沛恩」）惟聖主，祈福在方伯。","三元章醮昇，五域□□（二字《全唐詩》亦闕。","）覿。","帟幕翠微亘，機□（《全唐詩》作「茵」。","）丹洞闢。","□□（《全唐詩》作「祝起」。","）鳴天鼓，拜傳端素冊。","霞間□□□，（《全唐詩》作「朱紱縈」。","）嵐際黃裳襞。","玉□（《全唐詩》作「策」。","）□□（《全唐詩》作「奉誠」）信，□□□（《全唐詩》作「仙佩俟」。","）奔驛。","□（《全唐詩》作「香」。","）氣入岫門，瑞雲出巖石。","至誠必招感，大福旋來格。","空□□□□，（《全唐詩》作「中忽神言」。","）帝壽萬千百。","（見畢沅、阮元撰《山左金石志》卷十二。","）（〖1〗按石刻詩題下有「北海郡太守趙居貞述。","渤海吳□書。","郡人李元莊鐫」等字。","石刻係天寶十一載所立，正書，崖高四尺五寸五分，廣二尺，在益都縣雲門山洞西關帝廟後北壁。","〖2〗此詩序文中所書玄宗尊號，石刻本與《全唐詩》不同。","按《新唐書·玄宗紀》載天寶七載羣臣上尊號曰「開元天寶聖文神武應道皇帝」。","又天寶八載復上尊號曰「開元天地大寶聖文神武應禉皇帝」。","石刻所稱，顯係天寶七載所上尊號，然石刻立於天寶十一載，則當以《全唐詩》取天寶八載所上尊號爲是。","望頗疑作序刊石者緣一時疎忽，誤取七載尊號，而後之錄是刻者知其誤而糾正之，此《全唐詩》據本之所以異於石刻也。","）。"]', '["□□（《全唐诗》作「晓登」）云门山，直上壹千尺。","絕頂彌□（《全唐诗》作「孤」。","）聳，盤途幾傾窄。","前对堅裂峯，□□（《全唐诗》作「下臨」。","）削成壁。","陽□（《全唐诗》作「巘」。","）靈芝秀，陰崖仙乳□。","（此句《全唐诗》作「陰崖半天赤」。","）□□□羣山，远望何所隔。","太陽未出海，曠晃半天赤。","（《全唐诗》無以上四句。","）大壑静不波，渺溟無際碧。","（「碧」，《全唐诗》作「極」。","）是时雪初霽，沍寒冰（《全唐诗》作「水」。","）更積。","恭（《全唐诗》誤作「披」）展送龙儀，寧安服狐白。","□□（《全唐诗》作「沛恩」）惟聖主，祈福在方伯。","三元章醮昇，五域□□（二字《全唐诗》亦闕。","）覿。","帟幕翠微亘，機□（《全唐诗》作「茵」。","）丹洞闢。","□□（《全唐诗》作「祝起」。","）鳴天鼓，拜傳端素冊。","霞间□□□，（《全唐诗》作「朱紱縈」。","）嵐際黄裳襞。","玉□（《全唐诗》作「策」。","）□□（《全唐诗》作「奉誠」）信，□□□（《全唐诗》作「仙佩俟」。","）奔驛。","□（《全唐诗》作「香」。","）氣入岫门，瑞云出巖石。","至誠必招感，大福旋来格。","空□□□□，（《全唐诗》作「中忽神言」。","）帝壽万千百。","（见畢沅、阮元撰《山左金石志》卷十二。","）（〖1〗按石刻诗題下有「北海郡太守趙居貞述。","渤海吳□书。","郡人李元莊鐫」等字。","石刻係天寶十一載所立，正书，崖高四尺五寸五分，廣二尺，在益都縣云门山洞西关帝廟後北壁。","〖2〗此诗序文中所书玄宗尊號，石刻本與《全唐诗》不同。","按《新唐书·玄宗紀》載天寶七載羣臣上尊號曰「开元天寶聖文神武應道皇帝」。","又天寶八載复上尊號曰「开元天地大寶聖文神武應禉皇帝」。","石刻所稱，显係天寶七載所上尊號，然石刻立於天寶十一載，則當以《全唐诗》取天寶八載所上尊號爲是。","望頗疑作序刊石者緣一时疎忽，誤取七載尊號，而後之錄是刻者知其誤而糾正之，此《全唐诗》據本之所以異於石刻也。","）。"]', '诗', 'shi', '', NULL, '雲門山投龍詩刻（並序） 赵居貞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d38db47d-dba8-4231-b8be-1bad7bc053b7', '秋齋（題擬）', '秋斋（題擬）', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["山月皎如晝，霜風時動竹。","夜半鳥驚栖，窗間人獨宿。","（見《永樂大典》卷二五三九「七皆」「秋齋」條〖三函三十冊〗《全唐詩所未收》。","）。"]', '["山月皎如晝，霜风时动竹。","夜半鸟驚栖，窗间人独宿。","（见《永乐大典》卷二五三九「七皆」「秋斋」條〖三函三十冊〗《全唐诗所未收》。","）。"]', '诗', 'shi', '', NULL, '秋齋（題擬） 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6d3a1b8-6c21-4b79-9a91-f3c4c5ea67ac', '河上寄故人', '河上寄故人', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["河流杳靄曉天，濮水黯澹秋烟。","日暖昆吾臺上，春深顓頊城邊。","鶯聲亂鳴鴻塞，花片細點龍泉。","西望情人早至，尤應得醉芳年。","（按《全唐詩》卷二百四十五有此詩。","惟前半殘缺不可句讀。","此見《永樂大典》卷三○○五「九真」「人」字〖五函四十二冊〗。","完整可讀，故錄存之。","）。"]', '["河流杳靄晓天，濮水黯澹秋烟。","日暖昆吾台上，春深顓頊城邊。","鶯声亂鳴鴻塞，花片細点龙泉。","西望情人早至，尤應得醉芳年。","（按《全唐诗》卷二百四十五有此诗。","惟前半殘缺不可句读。","此见《永乐大典》卷三○○五「九真」「人」字〖五函四十二冊〗。","完整可读，故錄存之。","）。"]', '诗', 'shi', '', NULL, '河上寄故人 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('574afca2-f99f-4599-ba03-2c7456f3deeb', '訪邱員外丹（題擬）', '訪邱員外丹（題擬）', 'e7b88c9d-5050-4bfc-9f83-1cd5aea0b78e', '唐', '["五月五日日亭午，獨自騎驢入山隝。","來到君家不見君，下驢倚杖叩君戶。","驚起山童開山扉，黃犬摇尾銜人衣。","試問先生住何處，云入山中采紫薇，平明一去今未歸。","引我池中看釣磯，池中數箇白鷗兒，見人慣後癡不飛。","待君歸來君未歸，卻復騎驢下翠微。","（見仁和張大昌輯《臨平記補遺》卷四。","）（《全唐詩續補遺》卷六據《咸淳臨安志》卷九五《紀遺》收此詩，題作《謁丘真人不遇》，今刪彼存此，錄其異文如次：「亭午」作「卓午」，「入山」作「上山」，「歸來」作「君歸」。","）（〖1〗《臨平記補遺》：「曲園先生曰：『沈〖沈謙〗記於唐人贈邱丹詩悉錄之，而失錄此詩。","按此詩見宋陳郁《藏一話腴》，云「邱本唐人，棄官學道於此，顧況訪之」云云。","有詩無題。","姑據《話腴》題爲《訪邱員外丹》，未知原題云何也。","』」）。"]', '["五月五日日亭午，独自騎驢入山隝。","来到君家不见君，下驢倚杖叩君戶。","驚起山童开山扉，黄犬摇尾銜人衣。","試问先生住何处，云入山中采紫薇，平明一去今未归。","引我池中看釣磯，池中數箇白鷗兒，见人慣後癡不飞。","待君归来君未归，卻复騎驢下翠微。","（见仁和張大昌輯《臨平記補遺》卷四。","）（《全唐诗續補遺》卷六據《咸淳臨安志》卷九五《紀遺》收此诗，題作《謁丘真人不遇》，今刪彼存此，錄其異文如次：「亭午」作「卓午」，「入山」作「上山」，「归来」作「君归」。","）（〖1〗《臨平記補遺》：「曲园先生曰：『沈〖沈謙〗記於唐人贈邱丹诗悉錄之，而失錄此诗。","按此诗见宋陳郁《藏一話腴》，云「邱本唐人，棄官学道於此，顧況訪之」云云。","有诗無題。","姑據《話腴》題爲《訪邱員外丹》，未知原題云何也。","』」）。"]', '诗', 'shi', '', NULL, '訪邱員外丹（題擬） 顧况 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa5ecf11-5380-49d1-a2a9-0fc1d038ef7e', '句（朝天行）', '句（朝天行）', 'dcbb78e1-5cd2-4d89-984b-d785149d55d2', '唐', '["賴有雙旌在手中，鏌鎁昨夜新磨了。","（見李肇《國史補》卷上。","）（〖1〗李肇《國史補·徐州朝天行》：「張建封自徐州入覲，爲《朝天行》。","末句云：『賴有雙旌在筘，鏌鎁昨夜新磨了。","』德宗不說。","」〖2〗《新唐書》卷一百五十八《張報封傳》：「十三年來朝，帝不待日召見延英殿，方會朝赴大夫班，以示殊寵，建封賦《朝天行》以獻。","帝眷遇異等，賜名馬珍具。","」）。"]', '["賴有雙旌在手中，鏌鎁昨夜新磨了。","（见李肇《国史補》卷上。","）（〖1〗李肇《国史補·徐州朝天行》：「張建封自徐州入覲，爲《朝天行》。","末句云：『賴有雙旌在筘，鏌鎁昨夜新磨了。","』德宗不说。","」〖2〗《新唐书》卷一百五十八《張報封傳》：「十三年来朝，帝不待日召见延英殿，方會朝赴大夫班，以示殊寵，建封賦《朝天行》以獻。","帝眷遇異等，賜名马珍具。","」）。"]', '诗', 'shi', '', NULL, '句（朝天行） 張建封 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8c90034-c629-4fed-ad9d-d9100fc1e130', '廳事之西因依墉壑爲山數仞有懸水焉予理戎之暇聊以息讌此相國張公之所作也緬懷高致時濯塵纓即事寄言而賦斯什', '廳事之西因依墉壑爲山數仞有懸水焉予理戎之暇聊以息讌此相国張公之所作也緬懷高致时濯塵纓即事寄言而賦斯什', 'b882b09f-8955-4a9d-8b99-7eeb15a9a2a9', '唐', '["奇峰似天作，半倚增城隅。","何處通泉脉，潺湲竟朝晡。","挂石懸一帶，灑荷散千珠。","固宜賞高人，何爲對武夫？","鼓鼙時鏗{言訇}，吏卒亦喧呼。","愧爾來我所，顧我非爾徒。","乃是風流相，昔嘗居此都。","能移造化力，雅與山水俱。","多慙受成者，得此聊自娛。","（見《分門纂類唐歌詩》殘本第三冊《天地山川類》卷三十二。","）。"]', '["奇峰似天作，半倚增城隅。","何处通泉脉，潺湲竟朝晡。","挂石懸一带，灑荷散千珠。","固宜賞高人，何爲对武夫？","鼓鼙时鏗{言訇}，吏卒亦喧呼。","愧爾来我所，顧我非爾徒。","乃是风流相，昔嘗居此都。","能移造化力，雅與山水俱。","多慙受成者，得此聊自娛。","（见《分门纂類唐歌诗》殘本第三冊《天地山川類》卷三十二。","）。"]', '诗', 'shi', '', NULL, '廳事之西因依墉壑爲山數仞有懸水焉予理戎之暇聊以息讌此相國張公之所作也緬懷高致時濯塵纓即事寄言而賦斯什 裴度 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d46c47a-b5eb-4ebf-9856-3de1e69552ee', '月詩', '月诗', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["金波絢彩麗初筵，玉冕（友人蔣禮鴻同志謂當作「玉菟」。","菟，同兔。","）流輝滿大圓。","鏡裏山川同炯炯，樓前風露共娟娟。","（清康熙間仁和孫之騄《玉川子詩註》收此詩，云見《萬花谷後集》。","）（見《錦繡萬花谷後集》卷一《月》）。"]', '["金波絢彩丽初筵，玉冕（友人蔣禮鴻同志謂當作「玉菟」。","菟，同兔。","）流輝满大圓。","镜裏山川同炯炯，楼前风露共娟娟。","（清康熙间仁和孫之騄《玉川子诗註》收此诗，云见《万花谷後集》。","）（见《錦繡万花谷後集》卷一《月》）。"]', '诗', 'shi', '', NULL, '月詩 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be609e91-15fb-4ef7-ac6b-f6874e876d15', '紀湯泉', '紀湯泉', 'f2670833-4855-4d4e-9523-6e76091e2eee', '唐', '["維泉肇何代，開鑿同二儀。","五行分水火，厥用誰一之。","在卦得既濟，備象坎與離。","下有風輪煽，上有雷車馳。","霞掀祝融井，日爛扶桑池。","氣殊礐石厲，脉有靈砂滋。","驪山豈不好，玉環污流脂。","至今華清樹，空遺後人悲。","遐哉哲人逝，此水真吾師。","一濯三沐髪，六鑿還希夷。","伐毛返骨髓，髪白令人黟。","十年走塵土，負我汗漫期。","再來池上遊，觸熱三伏時。","古寺僧寂寞，但餘壁上詩。","不見題詩人，令我長嘆咨。","（見康熙十八年閔麟嗣撰《黃山志定本》卷六，乾隆間刊印。","此詩承儀徵吳白匋先生見告。","）。"]', '["維泉肇何代，开鑿同二儀。","五行分水火，厥用誰一之。","在卦得既濟，備象坎與離。","下有风輪煽，上有雷车驰。","霞掀祝融井，日爛扶桑池。","氣殊礐石厲，脉有靈砂滋。","驪山豈不好，玉环污流脂。","至今华清樹，空遺後人悲。","遐哉哲人逝，此水真吾師。","一濯三沐髪，六鑿還希夷。","伐毛返骨髓，髪白令人黟。","十年走塵土，負我汗漫期。","再来池上游，觸熱三伏时。","古寺僧寂寞，但餘壁上诗。","不见題诗人，令我长嘆咨。","（见康熙十八年閔麟嗣撰《黄山志定本》卷六，乾隆间刊印。","此诗承儀徵吳白匋先生见告。","）。"]', '诗', 'shi', '', NULL, '紀湯泉 賈島 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aed8507c-b048-4459-8bbf-e0e1c8923d71', '歙郡有黃山樓北瞰黃山山勢中拆若巨門狀因題一絕', '歙郡有黄山楼北瞰黄山山勢中拆若巨门狀因題一絕', 'abb11b4c-78b4-4775-a649-38b164e939ad', '唐', '["黟峰翠色自天流，直下青冥豁素秋。","閒倚朱欄頻北望，只宜名作巨門樓。","（〖1〗詩見康熙十八年閔麟嗣撰《黃山志定本》卷六，乾隆間刊刻。","此詩承儀徵吳白匋先生見告。","按原志附注曰：「程弘志云：按《一統志》：刺史有從兄棄官學道，號於方外，刺史爲築室於問政山，山始名問政。","」望按：《金石萃編》卷八十有于德晦題名，在李虞仲題名之左，曰「監察御史于德晦」，題名後紀「大中六年三月廿四日」云云。","又《長安志》務本坊有左散騎常侍于德晦宅。","〖大興徐松撰《唐兩京城坊考》卷二所記同〗）。"]', '["黟峰翠色自天流，直下青冥豁素秋。","閒倚朱欄頻北望，只宜名作巨门楼。","（〖1〗诗见康熙十八年閔麟嗣撰《黄山志定本》卷六，乾隆间刊刻。","此诗承儀徵吳白匋先生见告。","按原志附注曰：「程弘志云：按《一統志》：刺史有從兄棄官学道，號於方外，刺史爲築室於问政山，山始名问政。","」望按：《金石萃編》卷八十有于德晦題名，在李虞仲題名之左，曰「監察御史于德晦」，題名後紀「大中六年三月廿四日」云云。","又《长安志》務本坊有左散騎常侍于德晦宅。","〖大兴徐松撰《唐兩京城坊考》卷二所記同〗）。"]', '诗', 'shi', '', NULL, '歙郡有黃山樓北瞰黃山山勢中拆若巨門狀因題一絕 于德晦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cb85a63-9307-437b-aa1d-7b1b00c7769a', '寒食下第簡長安故人', '寒食下第簡长安故人', '673def2a-df72-45ac-b66b-ad84724381b7', '唐', '["寒食都人重勝遊，相如獨自閉門愁。","嘗聞婁護因名達，君試將余問五侯。","（見《永樂大典》卷三○○五「九真」「人」字（五函四十二冊）。","按詩共二首，其一五言四句，《全唐詩》卷三百十七載之，其二即此詩。","）（《古今歲時雜詠》卷十一收此詩，前爲五言四句，後爲七言四句，與《大典》同。","疑原詩應爲雜言體一首。","《全唐詩》卷三一七錄作五絕，似沿《萬首唐人絕句》卷十四，題作《寒食下第》，錄如次：「柳挂九衢絲，花飄萬家雪。","如何憔悴人，對此芳菲節。","」《古今歲時雜詠》「萬家」作「萬里」，「人」作「客」。）"]', '["寒食都人重勝游，相如独自閉门愁。","嘗闻婁護因名達，君試將余问五侯。","（见《永乐大典》卷三○○五「九真」「人」字（五函四十二冊）。","按诗共二首，其一五言四句，《全唐诗》卷三百十七載之，其二即此诗。","）（《古今歲时杂詠》卷十一收此诗，前爲五言四句，後爲七言四句，與《大典》同。","疑原诗應爲杂言體一首。","《全唐诗》卷三一七錄作五絕，似沿《万首唐人絕句》卷十四，題作《寒食下第》，錄如次：「柳挂九衢絲，花飄万家雪。","如何憔悴人，对此芳菲節。","」《古今歲时杂詠》「万家」作「万里」，「人」作「客」。）"]', '诗', 'shi', '', NULL, '寒食下第簡長安故人 武元衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c6ab476-63d8-4647-a94d-59ee3ff8d4ef', '臨平湖夜泛', '臨平湖夜泛', '6661ba41-9320-4902-b5ef-8a562758eff8', '唐', '["素彩皓通津，孤舟入清曠。","已愛隔簾看，還宜捲簾望。","隔簾當此時，（《四部叢刊》本《權載之文集》卷六收此詩，此句作「隔簾卷簾時此時」，與《臨平記》同。","）惆悵思君君不知。","（此見《永樂大典》卷二二七一「六模」「湖」字《臨平湖》條〖二函二十冊〗。","此詩亦見沈謙《臨平記》卷四，惟第五句作「隔簾捲簾當此時」爲異。","）。"]', '["素彩皓通津，孤舟入清曠。","已愛隔簾看，還宜捲簾望。","隔簾當此时，（《四部叢刊》本《權載之文集》卷六收此诗，此句作「隔簾卷簾时此时」，與《臨平記》同。","）惆悵思君君不知。","（此见《永乐大典》卷二二七一「六模」「湖」字《臨平湖》條〖二函二十冊〗。","此诗亦见沈謙《臨平記》卷四，惟第五句作「隔簾捲簾當此时」爲異。","）。"]', '诗', 'shi', '', NULL, '臨平湖夜泛 權德輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22c97c99-6a7a-407e-aa92-d15e7cf9098d', '題雲居上寺（並序）', '題云居上寺（並序）', 'a4a9ace6-1432-4eb5-95fc-1bc67e6ca382', '唐', '["到此花宮裏，觀身火宅中。","有爲皆是幻，何事不成空？","晚籟鳴寒谷，秋山響暮鐘。","欲歸林下路，新月上前峯。","（見《金石萃編》卷一百五。","）（〖1〗《金石萃編》王昶按：「雲居上寺，未詳處所。","據詩前稱范陽縣丞吉逾同躋攀于此云云，則寺當在范陽矣。","唐時范陽縣屬涿州，今撿《日下舊聞》引《名勝志》云：『涿州有智度寺，石城東北隅，剙自唐時，有舊碑刻。","其後即雲居寺，俱有石基浮圖。","』疑即此雲居上寺也。","謂之上寺者，以在智度寺之後也。","唐時舊碑刻，或即指此碑。","吉逾諸人之詩，《全唐詩》無一載者，因錄之，以見唐人詩千餘年來淪於草莽、爲人所未見者，蓋不勝紀云。","」〖2〗望按：詩題次行原有「范陽縣丞吉逾」六字，詩序辛酉歲云云。","當是唐德宗建中二年。","石刻於此詩後出「元和四年四月八是范□□」一行，疑此爲刻石年月，而「范□□」疑本是「范某刻」字樣，當是刻工題名。","果爾，則自辛酉賦詩以迄元和四年己丑刻石，其間已歷二十九年矣。","〖吉逾等人詩作於建中二年。","元和題名，陸增祥《八瓊室金石補正》卷六五錄作「元和四年八月八日范惟清呂〖以下缺〗」幷云此題名雖書於軒轅偉詩首「同前」二字之下，應別標一題，「《萃編》合爲一刻，誤矣」。","〗）。"]', '["到此花宮裏，观身火宅中。","有爲皆是幻，何事不成空？","晚籟鳴寒谷，秋山响暮鐘。","欲归林下路，新月上前峯。","（见《金石萃編》卷一百五。","）（〖1〗《金石萃編》王昶按：「云居上寺，未詳处所。","據诗前稱范陽縣丞吉逾同躋攀于此云云，則寺當在范陽矣。","唐时范陽縣屬涿州，今撿《日下旧闻》引《名勝志》云：『涿州有智度寺，石城东北隅，剙自唐时，有旧碑刻。","其後即云居寺，俱有石基浮圖。","』疑即此云居上寺也。","謂之上寺者，以在智度寺之後也。","唐时旧碑刻，或即指此碑。","吉逾諸人之诗，《全唐诗》無一載者，因錄之，以见唐人诗千餘年来淪於草莽、爲人所未见者，蓋不勝紀云。","」〖2〗望按：诗題次行原有「范陽縣丞吉逾」六字，诗序辛酉歲云云。","當是唐德宗建中二年。","石刻於此诗後出「元和四年四月八是范□□」一行，疑此爲刻石年月，而「范□□」疑本是「范某刻」字樣，當是刻工題名。","果爾，則自辛酉賦诗以迄元和四年己丑刻石，其间已歷二十九年矣。","〖吉逾等人诗作於建中二年。","元和題名，陸增祥《八瓊室金石補正》卷六五錄作「元和四年八月八日范惟清呂〖以下缺〗」幷云此題名雖书於軒轅偉诗首「同前」二字之下，應別標一題，「《萃編》合爲一刻，誤矣」。","〗）。"]', '诗', 'shi', '', NULL, '題雲居上寺（並序） 吉逾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7898a92e-8c90-4966-afda-063bcc48b18c', '題雲居上寺', '題云居上寺', '6e1ad8ef-44e1-4844-bdd6-d24e45c6ef08', '唐', '["石室最高峯，躋攀到此中。","白雲連晚翠，清磬度秋風。","未悟無生理，寧知有想空。","且歸山下寺，更欲問支公。","（見《金石萃編》卷一百五。","）（按詩次軒轅偉詩後，原題曰「同前」，下署「騊駼上」，無官銜。","）。"]', '["石室最高峯，躋攀到此中。","白云連晚翠，清磬度秋风。","未悟無生理，寧知有想空。","且归山下寺，更欲问支公。","（见《金石萃編》卷一百五。","）（按诗次軒轅偉诗後，原題曰「同前」，下署「騊駼上」，無官銜。","）。"]', '诗', 'shi', '', NULL, '題雲居上寺 吉騊駼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('515b111d-8d03-41cf-b5c9-080f822909fe', '題雲居上寺', '題云居上寺', 'e8686e88-8de3-42e9-9068-2da43fc8c2a6', '唐', '["石路多奇迹，幽巖鑿寶經。","暮煙千壑裏，新月一山明。","宿鳥知清梵，樵人慣獨行。","爲隨歡奉後，豈敢學逃[名]。","（見《金石萃編》卷一百五。","）（缺文據吉逾條下所引諸書補。","）（按詩次吉騊駼詩後，原題曰「同前」，下署「□上」，蓋名已摩滅。","據吉逾詩序，知爲其猶子吉播所賦。","詩中「暮煙」，石刻原作「暮煙」，王昶謂是筆誤，今據正。","〖1〗吉播，原作吉潛，詳前吉逾條附考。","前引諸書及《八瓊室金石補正》卷六五此詩末署名皆作「播上」。","）。"]', '["石路多奇迹，幽巖鑿寶經。","暮煙千壑裏，新月一山明。","宿鸟知清梵，樵人慣独行。","爲隨歡奉後，豈敢学逃[名]。","（见《金石萃編》卷一百五。","）（缺文據吉逾條下所引諸书補。","）（按诗次吉騊駼诗後，原題曰「同前」，下署「□上」，蓋名已摩滅。","據吉逾诗序，知爲其猶子吉播所賦。","诗中「暮煙」，石刻原作「暮煙」，王昶謂是笔誤，今據正。","〖1〗吉播，原作吉潛，詳前吉逾條附考。","前引諸书及《八瓊室金石補正》卷六五此诗末署名皆作「播上」。","）。"]', '诗', 'shi', '', NULL, '題雲居上寺 吉播 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e12a790-abd6-46d0-ba84-636f4931ccc2', '題雲居上寺', '題云居上寺', 'ce6c7e36-2f09-4d20-b716-8360a7a16ea1', '唐', '["[支]公禪誦處，絕頂共登攀。","日色千峯裏，鐘聲萬壑間。","[暮]猿吟砌近，沙鳥傍溪閑。","一逕[堪]藜杖，行行獨下山。","（見《金石萃編》卷一百五。","）（缺文據《續古文苑》卷四補。","《房山石經題記匯編》首字不缺。","）（〖1〗石刻詩次王潛詩後。","原題曰「同前」。","下署「男益上」。","與吉逾詩序所稱「息益」合。","〖2〗王益，原作吉益。","爲王潛之子，詳前吉逾條附考。","諸書錄石刻。","此詩收於王潛詩之次，署「男益上」。","）。"]', '["[支]公禪誦处，絕頂共登攀。","日色千峯裏，鐘声万壑间。","[暮]猿吟砌近，沙鸟傍溪闲。","一逕[堪]藜杖，行行独下山。","（见《金石萃編》卷一百五。","）（缺文據《續古文苑》卷四補。","《房山石經題記匯編》首字不缺。","）（〖1〗石刻诗次王潛诗後。","原題曰「同前」。","下署「男益上」。","與吉逾诗序所稱「息益」合。","〖2〗王益，原作吉益。","爲王潛之子，詳前吉逾條附考。","諸书錄石刻。","此诗收於王潛诗之次，署「男益上」。","）。"]', '诗', 'shi', '', NULL, '題雲居上寺 王益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ad24b75-635d-4538-8a15-1b3e5a2ed0ff', '', '', '9a47d95a-b2a6-468e-b018-3d3218f17414', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 軒轅偉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('558f3404-d2ed-497f-84e0-b4919631a102', '題雲居上寺', '題云居上寺', '9a47d95a-b2a6-468e-b018-3d3218f17414', '唐', '["不著登山屐，捫蘿也上躋。","石梁分鳥道，苔逕過雲霓。","梵宇千花裏，秋聲萬籟齊。","[周]遊興未盡，鐘磬度前溪。","（見《金石萃編》卷一百五。）","（缺字據吉逾條下所引諸書補。","下同。","）（〖1〗石刻詩次吉逾詩後，原題曰「同作」，下署軒轅偉，無官銜。","）。"]', '["不著登山屐，捫蘿也上躋。","石梁分鸟道，苔逕過云霓。","梵宇千花裏，秋声万籟齊。","[周]游兴未尽，鐘磬度前溪。","（见《金石萃編》卷一百五。）","（缺字據吉逾條下所引諸书補。","下同。","）（〖1〗石刻诗次吉逾诗後，原題曰「同作」，下署軒轅偉，無官銜。","）。"]', '诗', 'shi', '', NULL, '題雲居上寺 軒轅偉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47609e76-25d9-46ee-acb2-45397ecb4dfc', '題雲居上寺', '題云居上寺', 'f120f4a1-dd6a-4fc0-b36d-094c616ffdd5', '唐', '["萬木千峯空鳥喧，潺潺[溪]水下長川。","人來石室藏何處。","一逕歸時帶暮煙。","（見《金石萃編》卷一百五。","）（〖1〗石刻詩次吉潛詩後。","原題曰「同前」。","下署「節度都巡使太常卿上柱國王潛」。","第二句第三字原作「氵」，摩其右半，意者或爲「澗」字，或爲「流」字，雖然，未敢擅補也。","）。"]', '["万木千峯空鸟喧，潺潺[溪]水下长川。","人来石室藏何处。","一逕归时带暮煙。","（见《金石萃編》卷一百五。","）（〖1〗石刻诗次吉潛诗後。","原題曰「同前」。","下署「節度都巡使太常卿上柱国王潛」。","第二句第三字原作「氵」，摩其右半，意者或爲「澗」字，或爲「流」字，雖然，未敢擅補也。","）。"]', '诗', 'shi', '', NULL, '題雲居上寺 王潛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2ed84ca-107c-4d6f-a971-70e692d6e991', '汝州北樓晚望少室詩', '汝州北楼晚望少室诗', 'b37f9ee3-b8c6-4e85-b9cb-47f2c4cc103f', '唐', '["峭拔烟雲外，雄居造化工。","三山慙海上，五嶽讓天中。","翠積當華甸，騰標占太空。","周臨萬里暮，猶掛夕陽紅。","（見《槐廬叢書》《金石錄補》。","）（〖1〗葉九來《金石錄補》卷十九《唐胡証題少室詩》跋尾：「右唐檢校祠部員外郎胡証《汝州北樓晚望少室詩》，詩云〖不重錄〗。","永貞元年仲夏記。","按新舊《書·證傳》皆云貞元中登第，繇渾瑊舉爲從事，自殿中侍御史爲韶州刺史而已。","據此碑。","先爲祠部員外郎，可以補史之闕漏。","」）。"]', '["峭拔烟云外，雄居造化工。","三山慙海上，五嶽讓天中。","翠積當华甸，腾標占太空。","周臨万里暮，猶掛夕陽紅。","（见《槐廬叢书》《金石錄補》。","）（〖1〗葉九来《金石錄補》卷十九《唐胡証題少室诗》跋尾：「右唐檢校祠部員外郎胡証《汝州北楼晚望少室诗》，诗云〖不重錄〗。","永貞元年仲夏記。","按新旧《书·證傳》皆云貞元中登第，繇渾瑊舉爲從事，自殿中侍御史爲韶州刺史而已。","據此碑。","先爲祠部員外郎，可以補史之闕漏。","」）。"]', '诗', 'shi', '', NULL, '汝州北樓晚望少室詩 胡証 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('538a7b02-b5b7-4c3a-a150-7bfcf2ee3e78', '奉敕陪內宴', '奉敕陪內宴', '596c6f17-f7b7-4055-9497-34fd40271c71', '唐', '["海國來朝自遠方，百年一醉謁天裳。","日宮座外何攸見，五色雲飛萬歲光。","（見金毓黻撰集《渤海國志長編》卷十八引《文華秀麗集》上。","）。"]', '["海国来朝自远方，百年一醉謁天裳。","日宮座外何攸见，五色云飞万歲光。","（见金毓黻撰集《渤海国志长編》卷十八引《文华秀丽集》上。","）。"]', '诗', 'shi', '', NULL, '奉敕陪內宴 王孝廉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66c39208-e3a3-4254-9f3a-05305aa66764', '春日對雨得情字', '春日对雨得情字', '596c6f17-f7b7-4055-9497-34fd40271c71', '唐', '["主人開宴在邊聽，客醉如泥等上京。","疑是雨師知聖意，甘滋芳潤灑羈情。","（同前。","）。"]', '["主人开宴在邊听，客醉如泥等上京。","疑是雨師知聖意，甘滋芳潤灑羈情。","（同前。","）。"]', '诗', 'shi', '', NULL, '春日對雨得情字 王孝廉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ad0f00d-7671-490e-84db-7cc49dd14a9a', '在邊亭賦得山花戲寄兩領客使並滋三', '在邊亭賦得山花戲寄兩領客使並滋三', '596c6f17-f7b7-4055-9497-34fd40271c71', '唐', '["芳樹春色（疑應作花）色甚明，初開似笑聽無聲。","主人每日專攀盡，殘片何時贈客情？","（同前。","）。"]', '["芳樹春色（疑應作花）色甚明，初开似笑听無声。","主人每日專攀尽，殘片何时贈客情？","（同前。","）。"]', '诗', 'shi', '', NULL, '在邊亭賦得山花戲寄兩領客使並滋三 王孝廉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7faa2e2-6f32-47e4-bb18-717f07b7ccc8', '和坂領客對月思鄉之作', '和坂領客对月思乡之作', '596c6f17-f7b7-4055-9497-34fd40271c71', '唐', '["寂寂朱明夜，團團白月輪。","幾山明影徹，萬象水天新。","棄妾看生悵，羈情對動神。","誰云千里隔，能照兩鄉人。","（同前。","）。"]', '["寂寂朱明夜，團團白月輪。","幾山明影徹，万象水天新。","棄妾看生悵，羈情对动神。","誰云千里隔，能照兩乡人。","（同前。","）。"]', '诗', 'shi', '', NULL, '和坂領客對月思鄉之作 王孝廉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d6020d8-ea72-4db2-bd58-e1dfda677b92', '出雲州書情寄兩敕使', '出云州书情寄兩敕使', '596c6f17-f7b7-4055-9497-34fd40271c71', '唐', '["南風海路連歸思，北雁長天引旅情。","賴有鏘鏘雙鳯伴，莫愁多日住邊亭。","（同前。","）（〖1〗按王孝廉奉渤海國王命使日，日本嵯峨天皇設宴禮之。","孝廉返國，舟覆溺海而死。","嵯峨天皇特頒敕書，追贈榮爵，且致悼念。","嵯峨在位十四年，年號曰弘仁，於唐則爲憲宗元和五年至穆宗長慶三年也。","敕文附後。","〖2〗《日本後紀》二十四日本嵯峨天皇《贈渤海使王孝廉正三位敕書》云：「惜往飾終，事茂舊範，褒忠錄績，義存先彝。","故渤海國使從三位王孝廉，闕庭修聘，滄溟迴艫，復命未申，昊蒼不憖。","寔雖有命在天，薤露難駐，而銜恨使命，不得更歸。","朕痛於懷，加贈榮爵，死而有靈，應業泉扃。","宜可正三位。","」〖3〗又日僧空海有《傷渤海國大使王孝廉中途物故》詩句，日人阪上今繼有《和渤海大使見寄之作》，可以參閱。","詩附於次。","）（〖4〗空海《傷渤海國大使王孝廉中途物故》：一面新交不忍聽，況乎鄉國〖一作「園」〗故園〖一作「國」〗情。","〖見金毓黻撰《渤海國志長編》卷十八引《高野大師廣傳》下〗〖5〗阪上今繼《和渤海大使見寄之作》：賓亭寂寞對青溪，處處登旅念悽。","萬里雲邊辭國遠，三春煙裏望卿〖蔣禮鴻及陳九思同志並謂當是「鄉」之形誤。","〗迷。","長天去雁催歸思，函谷來鶯助客啼。","一面相逢如舊識，交情自與古人齊。","〖見金毓黻撰《渤海國志長編》卷十八引《文華秀麗集》上〗）。"]', '["南风海路連归思，北雁长天引旅情。","賴有鏘鏘雙鳯伴，莫愁多日住邊亭。","（同前。","）（〖1〗按王孝廉奉渤海国王命使日，日本嵯峨天皇設宴禮之。","孝廉返国，舟覆溺海而死。","嵯峨天皇特頒敕书，追贈榮爵，且致悼念。","嵯峨在位十四年，年號曰弘仁，於唐則爲憲宗元和五年至穆宗长慶三年也。","敕文附後。","〖2〗《日本後紀》二十四日本嵯峨天皇《贈渤海使王孝廉正三位敕书》云：「惜往飾終，事茂旧範，褒忠錄績，義存先彝。","故渤海国使從三位王孝廉，闕庭修聘，滄溟迴艫，复命未申，昊蒼不憖。","寔雖有命在天，薤露难駐，而銜恨使命，不得更归。","朕痛於懷，加贈榮爵，死而有靈，應業泉扃。","宜可正三位。","」〖3〗又日僧空海有《傷渤海国大使王孝廉中途物故》诗句，日人阪上今繼有《和渤海大使见寄之作》，可以參閱。","诗附於次。","）（〖4〗空海《傷渤海国大使王孝廉中途物故》：一面新交不忍听，況乎乡国〖一作「园」〗故园〖一作「国」〗情。","〖见金毓黻撰《渤海国志长編》卷十八引《高野大師廣傳》下〗〖5〗阪上今繼《和渤海大使见寄之作》：賓亭寂寞对青溪，处处登旅念悽。","万里云邊辞国远，三春煙裏望卿〖蔣禮鴻及陳九思同志並謂當是「乡」之形誤。","〗迷。","长天去雁催归思，函谷来鶯助客啼。","一面相逢如旧識，交情自與古人齊。","〖见金毓黻撰《渤海国志长編》卷十八引《文华秀丽集》上〗）。"]', '诗', 'shi', '', NULL, '出雲州書情寄兩敕使 王孝廉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c0d3cd4-7ee8-408d-b70e-6fe4b33fe43e', '九銷山', '九銷山', '5878e662-1f91-4e4a-8f37-082a0a73270a', '唐', '["人行之字路嶔巇，九銷青山勝九疑。","祇被但白雲生不斷，無端點破碧琉璃。","（見道士孟宗寶集虛所編《洞霄詩集》卷一。","）（〖1〗鄧牧《洞霄圖志》卷二《山水門》《九鎖山》條：「自餘杭西郭外，行十有八里，逆溪水上，左右合七峯，皆拔地數百尺。","其趾犬牙相錯，行路並溪屈折者九，故云九鎖。","好事者悉命以名。","」）。"]', '["人行之字路嶔巇，九銷青山勝九疑。","祇被但白云生不斷，無端点破碧琉璃。","（见道士孟宗寶集虛所編《洞霄诗集》卷一。","）（〖1〗鄧牧《洞霄圖志》卷二《山水门》《九鎖山》條：「自餘杭西郭外，行十有八里，逆溪水上，左右合七峯，皆拔地數百尺。","其趾犬牙相錯，行路並溪屈折者九，故云九鎖。","好事者悉命以名。","」）。"]', '诗', 'shi', '', NULL, '九銷山 徐凝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee1b1897-e793-43c7-9c7b-991a418af440', '', '', 'b84e79b6-bd64-45ff-b2a2-8596498c9971', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 周匡物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30dd6122-273c-4b28-a6c5-9150496264d2', '三橋隱居歌', '三橋隐居歌', 'b84e79b6-bd64-45ff-b2a2-8596498c9971', '唐', '["誰家作橋溪水頭，茅堂四月如清秋。","白雲已過暮山紫，黃鳥不鳴春自幽。","掀髯背向孤舟立，猶記仙源舊曾入。","（近人翁國樑《漳州史蹟》亦引此詩「曾」作「會」。","）雨打疎篷醉不知，桃花一夜新流急。","（見《漳州府志》。","末句《漳州史蹟》作「桃花一夜急新流」，誤。","）。"]', '["誰家作橋溪水头，茅堂四月如清秋。","白云已過暮山紫，黄鸟不鳴春自幽。","掀髯背向孤舟立，猶記仙源旧曾入。","（近人翁国樑《漳州史蹟》亦引此诗「曾」作「會」。","）雨打疎篷醉不知，桃花一夜新流急。","（见《漳州府志》。","末句《漳州史蹟》作「桃花一夜急新流」，誤。","）。"]', '诗', 'shi', '', NULL, '三橋隱居歌 周匡物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9724a6df-eafd-4fd8-8ef4-f2c348e690fb', '湘中紀行', '湘中紀行', '3de08808-24cc-4d85-80aa-524c0b0ac705', '唐', '["[湘江]（江水）永州路，水碧山崒兀。","古木暗[漁]（魚）潭，陰雲起龍窟。","峻屏夾澄[徹]（澈），怪石生[溪渤]（□勒）。","[巨]艦時邅迴，輕舠已超忽。","疾如奔羽翼，清可[鑑]（鑒）毛髪。","寂寞[幾]（榜）漁舟，逶迤逗[啇]（商）[筏]。","[我]行十月杪，猿嘯中夜發。","楓葉寒始丹，菊花冬未歇。","凝流綠可[染]，積[翠]（學）浮堪擷。","[峭]蒨每驚新，幽奇信誇絕。","稠[峰]（峯）疊玉嶂，淺[浪]（泿）翻殘雪。","石[燕]（鷰）雨中飛，[塞]（霜）鴻雲外別。（迴鴈峯）","泝洄已勞苦，覽[玩]（翫）還愉悅。","鶴嶺訪胎仙（[祁]陽縣白鶴[嶺]道士屈志静得仙處），𢈪（音吾）亭仰文[喆]（哲）（祁陽𢈪亭，元中丞次山所居。）。","川間[有]漁釣，山上多薇蕨。","無[以]（公）佐雍熙，何如養疵拙。","安人苟有[積]（績），撫己行將[耋]。","此路好[乘桴]，吾其謝羈紲。","（見《金石萃編》卷一百八。","第三句「暗魚」二字原缺，據《輿地紀勝》卷五十六補。","）（《金石萃編》錄此詩缺誤甚多，而清瞿中溶《古泉山館金石文編殘稿》卷三補錄此詩無缺，今據以校補。","瞿中溶跋云：李諒《湘中紀行》詩二十行，行三十字，正書左行。","述葊侍郎《金石萃編》所載闕十五字，又『溪渤』之『渤』誤作『勒』，『積翠』之『翠』誤作『學』，蓋搨本未精之故。","予遊浯溪，親督搨工椎打，所謂闕泐者一一皆可辨識，乃爲補之。","中云『痦亭仰文哲』，『亭』字並不作『廎』，此唐人手筆，可見次山當本用『亭』字也。","）（〖1〗石刻詩後至題「大和四年十月廿五日，[桂]管都防禦觀察處置等使桂州刺史兼御史大夫李諒，過此偶題，並領男穎同登覽。","」〖2〗《金石萃編》王昶按：「李諒，兩《唐書》無傳，《全唐詩》有其人，小傳稱諒字復言，三宰劇邑，再爲郡牧，終京兆尹，而不詳所牧何郡。","所載詩，便有《蘇州元日郡齊感懷寄越州元相公杭州白舍人》詩一首，題下注云：『時長慶四年也。","』而不載此詩。","詩中缺泐，無從校補。","此詩題曰《湘中紀行》，是官桂州刺史道經永州題此詩於𢈪亭者。","合而觀之，是諒先於長慶四年守蘇州，至此時相距七年而移守桂州，所謂再爲郡牧者是已。","《蘇州元日》詩句云『新知四十九年非』，是長慶四年年五十也，至此則五十六矣。","有一子，名穎。","諒之可見者祇此。","」）。"]', '["[湘江]（江水）永州路，水碧山崒兀。","古木暗[漁]（鱼）潭，陰云起龙窟。","峻屏夾澄[徹]（澈），怪石生[溪渤]（□勒）。","[巨]艦时邅迴，轻舠已超忽。","疾如奔羽翼，清可[鑑]（鑒）毛髪。","寂寞[幾]（榜）漁舟，逶迤逗[啇]（商）[筏]。","[我]行十月杪，猿嘯中夜發。","楓葉寒始丹，菊花冬未歇。","凝流綠可[染]，積[翠]（学）浮堪擷。","[峭]蒨每驚新，幽奇信誇絕。","稠[峰]（峯）叠玉嶂，淺[浪]（泿）翻殘雪。","石[燕]（鷰）雨中飞，[塞]（霜）鴻云外別。（迴鴈峯）","泝洄已勞苦，覽[玩]（翫）還愉悅。","鹤嶺訪胎仙（[祁]陽縣白鹤[嶺]道士屈志静得仙处），𢈪（音吾）亭仰文[喆]（哲）（祁陽𢈪亭，元中丞次山所居。）。","川间[有]漁釣，山上多薇蕨。","無[以]（公）佐雍熙，何如養疵拙。","安人苟有[積]（績），撫己行將[耋]。","此路好[乘桴]，吾其謝羈紲。","（见《金石萃編》卷一百八。","第三句「暗鱼」二字原缺，據《輿地紀勝》卷五十六補。","）（《金石萃編》錄此诗缺誤甚多，而清瞿中溶《古泉山館金石文編殘稿》卷三補錄此诗無缺，今據以校補。","瞿中溶跋云：李諒《湘中紀行》诗二十行，行三十字，正书左行。","述葊侍郎《金石萃編》所載闕十五字，又『溪渤』之『渤』誤作『勒』，『積翠』之『翠』誤作『学』，蓋搨本未精之故。","予游浯溪，親督搨工椎打，所謂闕泐者一一皆可辨識，乃爲補之。","中云『痦亭仰文哲』，『亭』字並不作『廎』，此唐人手笔，可见次山當本用『亭』字也。","）（〖1〗石刻诗後至題「大和四年十月廿五日，[桂]管都防禦观察处置等使桂州刺史兼御史大夫李諒，過此偶題，並領男穎同登覽。","」〖2〗《金石萃編》王昶按：「李諒，兩《唐书》無傳，《全唐诗》有其人，小傳稱諒字复言，三宰劇邑，再爲郡牧，終京兆尹，而不詳所牧何郡。","所載诗，便有《蘇州元日郡齊感懷寄越州元相公杭州白舍人》诗一首，題下注云：『时长慶四年也。","』而不載此诗。","诗中缺泐，無從校補。","此诗題曰《湘中紀行》，是官桂州刺史道經永州題此诗於𢈪亭者。","合而观之，是諒先於长慶四年守蘇州，至此时相距七年而移守桂州，所謂再爲郡牧者是已。","《蘇州元日》诗句云『新知四十九年非』，是长慶四年年五十也，至此則五十六矣。","有一子，名穎。","諒之可见者祇此。","」）。"]', '诗', 'shi', '', NULL, '湘中紀行 李諒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88dfb94e-ecc2-4a28-b281-df6a8057a6c1', '杪春再遊廬山（吳汝煜、胡可先云此詩爲涉兄李渤作，見《唐才子傳校箋》卷五。）', '杪春再游廬山（吳汝煜、胡可先云此诗爲涉兄李渤作，见《唐才子傳校箋》卷五。）', '916a18bf-0188-4719-8ba5-0727ca7d4e1f', '唐', '["二十七年別，煙雲如昨辭。","偶逢行春日，得遂歸山期。","曉駕出湓城，晚會東林師。","巡廊閱衆院，遍讀新舊詩。","蕭魏故已塵，符楊亦川馳。","拂牀歸塵壁，再覔舊遊詩。","南訪靜（應作「靖」）節居，石臺有遺基。","紅葩列澗艷，碧蔦懸林絲。","迢遞二霄峯，晴雲間出危。","壇空仙馭遠，谷斷啼猿悲。","白鹿舊洞門，五老東一枝。","當時手結茅，聚族長在玆。","孫姪皆後來，非我昔所知。","生爲前世翁，安得不涕垂？","白髪唯兩人，形骸久支離。","雖同故山會，草草如路歧。","惆悵塵中身，何由重來斯。","無令誚余者，更效《北山移》。","（見《分門纂類唐歌詩》殘本第二冊《天地山川類》卷二十二。","）。"]', '["二十七年別，煙云如昨辞。","偶逢行春日，得遂归山期。","晓駕出湓城，晚會东林師。","巡廊閱衆院，遍读新旧诗。","蕭魏故已塵，符楊亦川驰。","拂牀归塵壁，再覔旧游诗。","南訪静（應作「靖」）節居，石台有遺基。","紅葩列澗艷，碧蔦懸林絲。","迢遞二霄峯，晴云间出危。","壇空仙馭远，谷斷啼猿悲。","白鹿旧洞门，五老东一枝。","當时手結茅，聚族长在玆。","孫姪皆後来，非我昔所知。","生爲前世翁，安得不涕垂？","白髪唯兩人，形骸久支離。","雖同故山會，草草如路歧。","惆悵塵中身，何由重来斯。","無令誚余者，更效《北山移》。","（见《分门纂類唐歌诗》殘本第二冊《天地山川類》卷二十二。","）。"]', '诗', 'shi', '', NULL, '杪春再遊廬山（吳汝煜、胡可先云此詩爲涉兄李渤作，見《唐才子傳校箋》卷五。） 李涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae0cfb5e-9273-4bac-9afe-2cd2b02e740c', '范處士在育王寺書碑因以寄贈', '范处士在育王寺书碑因以寄贈', '83b3602d-8c25-4478-bc36-8af188235b80', '唐', '["墨妙復辭雄，扁舟訪遠公。","□（趙紹祖《金石文鈔》卷七作「雲」）天書梵□（《金石文鈔》作「字」，）霜月步蓮宮。","跡寄雙林下，名留刼石中。","遙知松逕望，棠（《金石文鈔》作「栗」）葉滿山紅。","（見《金石萃編》卷一百八。","）（又見《兩浙金石志》卷一，第三句不缺，文同《金石文鈔》，末句作「棠葉滿山紅」。","）（〖1〗石刻於題下原署「明州刺史于季友」。","按阿育王寺在今浙江鄞縣阿育王山中，此詩及後范的酬和詩附鐫於《阿育王里常住田碑》後。","碑末有太和七年十二月一日于季友作《碑後記》，則兩詩之作，當亦在同時。）。"]', '["墨妙复辞雄，扁舟訪远公。","□（趙紹祖《金石文鈔》卷七作「云」）天书梵□（《金石文鈔》作「字」，）霜月步蓮宮。","跡寄雙林下，名留刼石中。","遙知松逕望，棠（《金石文鈔》作「栗」）葉满山紅。","（见《金石萃編》卷一百八。","）（又见《兩浙金石志》卷一，第三句不缺，文同《金石文鈔》，末句作「棠葉满山紅」。","）（〖1〗石刻於題下原署「明州刺史于季友」。","按阿育王寺在今浙江鄞縣阿育王山中，此诗及後范的酬和诗附鐫於《阿育王里常住田碑》後。","碑末有太和七年十二月一日于季友作《碑後記》，則兩诗之作，當亦在同时。）。"]', '诗', 'shi', '', NULL, '范處士在育王寺書碑因以寄贈 于季友 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6b22a8f-b3f2-4502-b425-e55bfae52c7b', '時在育王寺書石字奉酬□丞使君寄贈四韻依次用本韻', '时在育王寺书石字奉酬□丞使君寄贈四韻依次用本韻', 'aaf87c09-7e18-4bfb-a9ef-bbffc7891494', '唐', '["（《金石文鈔》題作《時在育王寺書石中丞使君寄目前四韻奉酬本韻》）拙藝荷才雄，新詩起謝公。","開緘光佛域，望景動星宮。","風雪文章裏，書鐫琬琰中。","將誰比佳句？霞綺散成紅。","（見《金石萃編》卷一百八。）","（又見《兩浙金石志》卷一，題中「□丞」作「中丞」，「次用本韻」四字爲題注小字。）","（望按：石刻題下原署曰「處士范的上」。","于季友《育王寺碑後記》有「剡越間隱逸之士曰范的，業文功書，未遇于時，常萍泊雲水間。","一日，扁舟到明」等語。","又《育王寺常住田碑》，原爲萬齊融所撰，徐嶠之書，其後碑隳，大和七年于季友爲明州刺史時，始邀范的重書。","其碑題下署「順陽范的書並篆額」，是范的爲順陽人。","范生平可考者僅此。","又詩中琬下原是「御名」兩字，蓋避武宗諱不書，武宗名炎，則詩中此字原當作琰可知。","〖此王昶避嘉慶帝諱而注爲「御名」。","〗然則詩之作在大和間，鐫石則在武宗會昌中，其間相去固將十載矣。）。"]', '["（《金石文鈔》題作《时在育王寺书石中丞使君寄目前四韻奉酬本韻》）拙藝荷才雄，新诗起謝公。","开緘光佛域，望景动星宮。","风雪文章裏，书鐫琬琰中。","將誰比佳句？霞綺散成紅。","（见《金石萃編》卷一百八。）","（又见《兩浙金石志》卷一，題中「□丞」作「中丞」，「次用本韻」四字爲題注小字。）","（望按：石刻題下原署曰「处士范的上」。","于季友《育王寺碑後記》有「剡越间隐逸之士曰范的，業文功书，未遇于时，常萍泊云水间。","一日，扁舟到明」等語。","又《育王寺常住田碑》，原爲万齊融所撰，徐嶠之书，其後碑隳，大和七年于季友爲明州刺史时，始邀范的重书。","其碑題下署「順陽范的书並篆額」，是范的爲順陽人。","范生平可考者僅此。","又诗中琬下原是「御名」兩字，蓋避武宗諱不书，武宗名炎，則诗中此字原當作琰可知。","〖此王昶避嘉慶帝諱而注爲「御名」。","〗然則诗之作在大和间，鐫石則在武宗會昌中，其间相去固將十載矣。）。"]', '诗', 'shi', '', NULL, '時在育王寺書石字奉酬□丞使君寄贈四韻依次用本韻 范的 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9077c173-38ae-4ce5-8033-dca418921cef', '', '', '96efda6a-f9ff-4f06-91ed-73136fa4a744', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 盧元輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18e1e6e1-08a9-4458-95ef-52f097cb235a', '遊天竺寺', '游天竺寺', '96efda6a-f9ff-4f06-91ed-73136fa4a744', '唐', '["水田十里學袈裟，秋殿千金儼釋迦。","遠客偏求月桂子，老人不記石蓮花。","武林山價縣隋日，天竺經文隸漢家。","苔壁媧皇鍊來處，泐中脩竹掃雲霞。","（見《兩浙金石志》卷二。","）（〖1〗石刻詩前原題「大唐杭州刺史盧元輔」九字。","〖2〗阮元《兩浙金石志》：「右刻在下天竺神尼塔下磨崖，文九行，右行，正書，徑二寸。","此詩《全唐詩》未載。","按盧元輔於德宗時自河南縣令除杭州刺史，嘗於武林山作見山亭，見《咸淳臨安志》。","又《胥山碑銘》，元和十年盧元輔文，王遹書，見《輿地碑目》。","此疑元和時刻。","又《陜西通志》云：『盧元輔滑州人，曾爲華州刺史。』","《郎官石柱題名》有金部郎中盧元輔。","白樂天有《盧元輔除杭州刺史制》，中云：『嘗守商都，再領京縣。』","皆其歷官也。","石本『泐中脩竹掃雲霞』，『泐』字係原刻，『脩竹』二字係改鑿。","『大唐』二字亦添補。","《西湖志》作『洞中』，蓋據文理，未見石刻也。」","〖3〗《杭州府志》引《武林石刻記》：「唐盧元輔《遊天竺詩》，縱一尺八寸，橫二尺，正書，字徑二寸。」）。"]', '["水田十里学袈裟，秋殿千金儼釋迦。","远客偏求月桂子，老人不記石蓮花。","武林山價縣隋日，天竺經文隸漢家。","苔壁媧皇鍊来处，泐中脩竹掃云霞。","（见《兩浙金石志》卷二。","）（〖1〗石刻诗前原題「大唐杭州刺史盧元輔」九字。","〖2〗阮元《兩浙金石志》：「右刻在下天竺神尼塔下磨崖，文九行，右行，正书，徑二寸。","此诗《全唐诗》未載。","按盧元輔於德宗时自河南縣令除杭州刺史，嘗於武林山作见山亭，见《咸淳臨安志》。","又《胥山碑銘》，元和十年盧元輔文，王遹书，见《輿地碑目》。","此疑元和时刻。","又《陜西通志》云：『盧元輔滑州人，曾爲华州刺史。』","《郎官石柱題名》有金部郎中盧元輔。","白乐天有《盧元輔除杭州刺史制》，中云：『嘗守商都，再領京縣。』","皆其歷官也。","石本『泐中脩竹掃云霞』，『泐』字係原刻，『脩竹』二字係改鑿。","『大唐』二字亦添補。","《西湖志》作『洞中』，蓋據文理，未见石刻也。」","〖3〗《杭州府志》引《武林石刻記》：「唐盧元輔《游天竺诗》，縱一尺八寸，橫二尺，正书，字徑二寸。」）。"]', '诗', 'shi', '', NULL, '遊天竺寺 盧元輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9f50671-de23-46cc-bf6e-4d21b1afa81b', '憶錢塘', '憶錢塘', '0ac28590-334d-4d3b-9abe-9ad672e9b9cc', '唐', '["往歲東遊鬢未凋，渡江曾駐木蘭橈。","一千里色中秋月，十萬軍聲半夜潮。","桂倚玉兒吟處雪，蓬遺蘇丞舞時腰。","仍聞江上春來柳，依舊參差拂寺橋。","（見韋莊《又玄集》卷中。","）（〖1〗陶敏云。","此詩之頸聯「一千里色中秋月，十萬軍聲半夜潮。」","張爲《詩人主客圖》取爲趙嘏句，《全唐詩》卷五五○亦收趙嘏句。）。"]', '["往歲东游鬢未凋，渡江曾駐木蘭橈。","一千里色中秋月，十万軍声半夜潮。","桂倚玉兒吟处雪，蓬遺蘇丞舞时腰。","仍闻江上春来柳，依旧參差拂寺橋。","（见韋莊《又玄集》卷中。","）（〖1〗陶敏云。","此诗之頸聯「一千里色中秋月，十万軍声半夜潮。」","張爲《诗人主客圖》取爲趙嘏句，《全唐诗》卷五五○亦收趙嘏句。）。"]', '诗', 'shi', '', NULL, '憶錢塘 李廓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8cd28f3-0c3d-4cc5-96ea-ca24b7350775', '遥知（友人陳九思同志疑「知」乃「和」字之訛）元九送王行周遊越', '遥知（友人陳九思同志疑「知」乃「和」字之訛）元九送王行周游越', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["江湖隨月盈還宿，沙渚依潮斷更連。","伍相廟中多白浪，越王臺畔少晴烟。","低頭綠草羞枚乘，刺眼紅花笑杜鵑。","莫倚西施舊苔石，由來破國是神仙。","（見韋莊《又玄集》卷中。","）。"]', '["江湖隨月盈還宿，沙渚依潮斷更連。","伍相廟中多白浪，越王台畔少晴烟。","低头綠草羞枚乘，刺眼紅花笑杜鵑。","莫倚西施旧苔石，由来破国是神仙。","（见韋莊《又玄集》卷中。","）。"]', '诗', 'shi', '', NULL, '遥知（友人陳九思同志疑「知」乃「和」字之訛）元九送王行周遊越 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33b2fbcb-28b9-4794-a22d-08b8e7bd4c10', '哭微之', '哭微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["今在豈有相逢日，未死應無暫忘時。","從此三篇收淚後，終身無復更吟詩。","（見《文苑英華》。","）（按《全唐詩》載《哭微之》詩二首，其詩原附於白居易《祭微之文》，畧謂無以寄悲情，作哀詞二首云云。","《全唐文》卷六百八十一及坊刻《白香山集》均載之。","惟《文苑英華》卷九百八十九《祭微之文》則謂作哀詞三首，其第三首爲）（諸本所無。","承友人顧學頡先生函告，爰補錄於此。","或以其出處不明爲疑，則俟方家之考定於來更可耳。","）。"]', '["今在豈有相逢日，未死應無暫忘时。","從此三篇收泪後，終身無复更吟诗。","（见《文苑英华》。","）（按《全唐诗》載《哭微之》诗二首，其诗原附於白居易《祭微之文》，畧謂無以寄悲情，作哀词二首云云。","《全唐文》卷六百八十一及坊刻《白香山集》均載之。","惟《文苑英华》卷九百八十九《祭微之文》則謂作哀词三首，其第三首爲）（諸本所無。","承友人顧学頡先生函告，爰補錄於此。","或以其出处不明爲疑，則俟方家之考定於来更可耳。","）。"]', '诗', 'shi', '', NULL, '哭微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f0feffb-b00b-4fd7-a7ad-44494c1b4959', '失題', '失題', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["石榴枝上花千朵，荷葉杯中酒十分。","滿院弟兄皆痛飲，就中大戶不如君。","（見《玉照新志》。","）（〖1〗《玉照新志》〖宋王明清撰，《寶顏堂祕笈》本〗卷三：「王彦國獻臣，招信人，居縣之近郊。","建炎初，虜人將渡淮，獻臣坐於所居小樓，望見一老士大夫彷徨阡陌間，攜一小僕，負一匣，埋於空迥之所。","獻臣默識之。","事定，往掘其地，宛然尚存。","啟匣，乃白樂天手書詩一紙。","云〖詩不重錄〗。","獻臣後南渡，寓居餘姚，嘗出以示余，真奇物也。","聞後以歸劉綱公舉矣。","」〖2〗按此亦顧先生所見示，其事可信與否，未敢遽斷，期海內方家有以論定之。","）。"]', '["石榴枝上花千朵，荷葉杯中酒十分。","满院弟兄皆痛饮，就中大戶不如君。","（见《玉照新志》。","）（〖1〗《玉照新志》〖宋王明清撰，《寶顏堂祕笈》本〗卷三：「王彦国獻臣，招信人，居縣之近郊。","建炎初，虜人將渡淮，獻臣坐於所居小楼，望见一老士大夫彷徨阡陌间，携一小僕，負一匣，埋於空迥之所。","獻臣默識之。","事定，往掘其地，宛然尚存。","啟匣，乃白乐天手书诗一紙。","云〖诗不重錄〗。","獻臣後南渡，寓居餘姚，嘗出以示余，真奇物也。","闻後以归劉綱公舉矣。","」〖2〗按此亦顧先生所见示，其事可信與否，未敢遽斷，期海內方家有以論定之。","）。"]', '诗', 'shi', '', NULL, '失題 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05532703-9c9e-4cb0-9a34-d1be9655a615', '春遊（見歷史博物館藏明王氏藏《宋拓四名人法書》冊頁。承顧學頡先生函告，詩爲白居易所作，即未竹垞云後人誤以爲元稹詩者，《全唐詩》亦入元稹卷，今宜還諸樂天。詩不重錄。〖《全唐詩》卷四二三收作元稹詩。顧說見其校點本《白居易集外集》卷上，朱說見《曝書亭集》卷四九。檢南宋洪邁《容齋隨筆五集》卷二云此詩「白樂天書之，題云『元相公《春游》』，錢思公藏其真跡，穆父守越時，摹刻於蓬萊閣下，今不復存。」錢思公指錢惟演，穆父指錢勰，爲北宋前中期執行。其言似比明清人所說更可靠些。此詩是否白作，恐尚難論定。）', '春游（见歷史博物館藏明王氏藏《宋拓四名人法书》冊頁。承顧学頡先生函告，诗爲白居易所作，即未竹垞云後人誤以爲元稹诗者，《全唐诗》亦入元稹卷，今宜還諸乐天。诗不重錄。〖《全唐诗》卷四二三收作元稹诗。顧说见其校点本《白居易集外集》卷上，朱说见《曝书亭集》卷四九。檢南宋洪邁《容斋隨笔五集》卷二云此诗「白乐天书之，題云『元相公《春游》』，錢思公藏其真跡，穆父守越时，摹刻於蓬萊閣下，今不复存。」錢思公指錢惟演，穆父指錢勰，爲北宋前中期執行。其言似比明清人所说更可靠些。此诗是否白作，恐尚难論定。）', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '春遊（見歷史博物館藏明王氏藏《宋拓四名人法書》冊頁。承顧學頡先生函告，詩爲白居易所作，即未竹垞云後人誤以爲元稹詩者，《全唐詩》亦入元稹卷，今宜還諸樂天。詩不重錄。〖《全唐詩》卷四二三收作元稹詩。顧說見其校點本《白居易集外集》卷上，朱說見《曝書亭集》卷四九。檢南宋洪邁《容齋隨筆五集》卷二云此詩「白樂天書之，題云『元相公《春游》』，錢思公藏其真跡，穆父守越時，摹刻於蓬萊閣下，今不復存。」錢思公指錢惟演，穆父指錢勰，爲北宋前中期執行。其言似比明清人所說更可靠些。此詩是否白作，恐尚難論定。） 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c5a8d90-33b9-4317-81ab-41edd6a15d1e', '郡治樓望黃山', '郡治楼望黄山', '3991544b-927c-44b1-b336-bf24db2b448e', '唐', '["郡齋北望春光好，平楚無雲秋望寬。","清氣爽時塵外見，碧煙飛處静中看。","争高千仞山皆讓，並秀三峯色也寒。","莫怪寓名同嶽號，暫圖瞻眺近長安。","（見康熙十八年閔嗣撰《黃山志定本》卷六，書刻於乾隆間。","）（〖1〗詩後原附按語：「汪晉穀云：唐有兩韋綬，一德宗朝翰林學士，一穆宗朝吏部尚書。","以《石門巖志》辨之，當是德宗朝者。","」〖2〗望按：《金石萃編》卷八十有「華陰縣令韋綬」題名，次「檢校水部員外郎崔熲」題名後。","韋綬題名下刻「貞元元年二月六日記」九字。","）。"]', '["郡斋北望春光好，平楚無云秋望寬。","清氣爽时塵外见，碧煙飞处静中看。","争高千仞山皆讓，並秀三峯色也寒。","莫怪寓名同嶽號，暫圖瞻眺近长安。","（见康熙十八年閔嗣撰《黄山志定本》卷六，书刻於乾隆间。","）（〖1〗诗後原附按語：「汪晉穀云：唐有兩韋綬，一德宗朝翰林学士，一穆宗朝吏部尚书。","以《石门巖志》辨之，當是德宗朝者。","」〖2〗望按：《金石萃編》卷八十有「华陰縣令韋綬」題名，次「檢校水部員外郎崔熲」題名後。","韋綬題名下刻「貞元元年二月六日記」九字。","）。"]', '诗', 'shi', '', NULL, '郡治樓望黃山 韋綬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b575640e-ca28-437c-9c5b-dcf660a6a2d9', '勸酒行', '勸酒行', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["樂往難重得，老來豈自由。","嬋娟過三五，珠翠成仇讎。","君不聞古曲，酒能消人憂。","何人更年少，君惜秉燭遊。","莫閑金絲手，月在西南樓。","羅换歌妾袂，錦纏舞人頭。","半醉月入懷，仰空笑牽牛。","那令酒生塵，虛見紅貌秋。","（見《永樂大典》卷一二○四三「二十有」「酒」字「勸酒」條〖十三函一百二十四冊〗。","）。"]', '["乐往难重得，老来豈自由。","嬋娟過三五，珠翠成仇讎。","君不闻古曲，酒能消人憂。","何人更年少，君惜秉燭游。","莫闲金絲手，月在西南楼。","羅换歌妾袂，錦纏舞人头。","半醉月入懷，仰空笑牽牛。","那令酒生塵，虛见紅貌秋。","（见《永乐大典》卷一二○四三「二十有」「酒」字「勸酒」條〖十三函一百二十四冊〗。","）。"]', '诗', 'shi', '', NULL, '勸酒行 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e67dff8d-2d70-42c5-bc37-069447d85006', '去東林寺詩', '去东林寺诗', '7b3922a5-baa6-4f35-bbef-c1ab60449feb', '唐', '["峯頭不住起孤煙，池上相留有白蓮。","塵網分明知束縛，更須騎馬別林（「林」字，《金石錄補》作「雲」。","）泉。","（見《古刻叢鈔》。","以《槐盧叢書》本《金石錄補》參校之。","）（〖1〗詩下原署「會昌三年七月十三日祕書省正字曹汾題」十七字。","〖2〗陶宗儀《古刻叢鈔》：此詩在曇玭碑陰，塵土昏塞，無知之者。","至和三年春二月，陳國袁陟來遊山，徧抉奇跡，始發其晦。","東林詩多矣，未有如此篇之意遠而美者，因題以永之。","汾，開成四年崔蠡下進士，後爲中書舍人，戶部侍郎、忠武軍節度使，實丞相確之弟也。","）。"]', '["峯头不住起孤煙，池上相留有白蓮。","塵網分明知束縛，更須騎马別林（「林」字，《金石錄補》作「云」。","）泉。","（见《古刻叢鈔》。","以《槐盧叢书》本《金石錄補》參校之。","）（〖1〗诗下原署「會昌三年七月十三日祕书省正字曹汾題」十七字。","〖2〗陶宗儀《古刻叢鈔》：此诗在曇玭碑陰，塵土昏塞，無知之者。","至和三年春二月，陳国袁陟来游山，徧抉奇跡，始發其晦。","东林诗多矣，未有如此篇之意远而美者，因題以永之。","汾，开成四年崔蠡下進士，後爲中书舍人，戶部侍郎、忠武軍節度使，實丞相確之弟也。","）。"]', '诗', 'shi', '', NULL, '去東林寺詩 曹汾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('030398c7-4a81-4de4-8096-d5d66524d7c0', '朱槿花', '朱槿花', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["紅開露臉誤文君，□□芙蓉草綠雲。","（張篷舟《薛濤詩箋》謂北京圖書館藏宋本《分門纂類唐歌詩》，此句無缺文，作「司蒡芙蓉草綠雲」。","）造化大都排比巧，衣裳色澤總薰薰。","。"]', '["紅开露臉誤文君，□□芙蓉草綠云。","（張篷舟《薛濤诗箋》謂北京圖书館藏宋本《分门纂類唐歌诗》，此句無缺文，作「司蒡芙蓉草綠云」。","）造化大都排比巧，衣裳色澤總薰薰。","。"]', '诗', 'shi', '', NULL, '朱槿花 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9baf7e52-3d34-4ff3-b28d-04e0a1b00d09', '浣花亭陪川主王播相公暨寮同賦早菊', '浣花亭陪川主王播相公暨寮同賦早菊', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["西陸行終令，東籬始再陽。","綠英初濯露，金蘂半含霜。","自有兼材用，那同衆草芳。","獻酬樽俎外，寧有懼豺狼。","（以上二詩見《分門纂類唐歌詩》殘本第六冊《草木蟲魚類》卷五。","）。"]', '["西陸行終令，东籬始再陽。","綠英初濯露，金蘂半含霜。","自有兼材用，那同衆草芳。","獻酬樽俎外，寧有懼豺狼。","（以上二诗见《分门纂類唐歌诗》殘本第六冊《草木蟲鱼類》卷五。","）。"]', '诗', 'shi', '', NULL, '浣花亭陪川主王播相公暨寮同賦早菊 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1937a8d-db11-477d-961a-d64f834d0d20', '題小華山（原注：「目黃山爲小華」。）', '題小华山（原注：「目黄山爲小华」。）', '03f45b67-b969-4207-b418-2589aa4a62b1', '唐', '["峰簇蓮花小，分明似華山。","魚符何日罷，深處掩松關。","（見閔麟嗣撰《黃山志定本》卷六。","）。"]', '["峰簇蓮花小，分明似华山。","鱼符何日罷，深处掩松关。","（见閔麟嗣撰《黄山志定本》卷六。","）。"]', '诗', 'shi', '', NULL, '題小華山（原注：「目黃山爲小華」。） 李敬方 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30853ebd-bf9e-4874-bc58-6d36f8cd50e8', '送友人罷舉歸東海', '送友人罷舉归东海', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["滄滄天塹外，何島是新羅？","舶主辭蕃遠，碁僧入漢多。","海風吹白鶻，沙日曬紅螺。","此去知提筆，須求利劍磨。","（見韋莊《又玄集》卷下。","熊飛云《全唐詩》卷五三一收此爲許渾詩。","今檢《文苑英華》卷二八○收此爲許詩，而許渾自書之烏絲欄詩真蹟及席刻本《丁卯詩集》、《四部叢刊》影宋鈔《下卯集》中皆無此詩。","應爲誰作，尚難斷定。","）。"]', '["滄滄天塹外，何島是新羅？","舶主辞蕃远，碁僧入漢多。","海风吹白鶻，沙日曬紅螺。","此去知提笔，須求利劍磨。","（见韋莊《又玄集》卷下。","熊飞云《全唐诗》卷五三一收此爲許渾诗。","今檢《文苑英华》卷二八○收此爲許诗，而許渾自书之烏絲欄诗真蹟及席刻本《丁卯诗集》、《四部叢刊》影宋鈔《下卯集》中皆無此诗。","應爲誰作，尚难斷定。","）。"]', '诗', 'shi', '', NULL, '送友人罷舉歸東海 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('344b4e8a-dcf1-4f1f-b52f-8dd21d9eeee0', '', '', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["空（按《全唐詩》卷五百十及卷五百十一編張祜詩二卷，又卷八百七十收諧謔詩二首，其中《戲顏郎中騎中騎臘詩》一首已見正卷，蓋複出，又卷八百八十三補遺卷有詩五首。","本編所輯四卷，均所未及。","今從北京圖書館藏南宋蜀刻本《張承吉文集》、《永樂大典》、韋莊《又玄集》、《太平廣記》引唐康駢《劇談錄》、唐馮翊子《桂苑叢談》等書錄出之。","祜，諸書或有作祐者，誤。","）。"]', '["空（按《全唐诗》卷五百十及卷五百十一編張祜诗二卷，又卷八百七十收諧謔诗二首，其中《戲顏郎中騎中騎臘诗》一首已见正卷，蓋複出，又卷八百八十三補遺卷有诗五首。","本編所輯四卷，均所未及。","今從北京圖书館藏南宋蜀刻本《張承吉文集》、《永乐大典》、韋莊《又玄集》、《太平廣記》引唐康駢《劇談錄》、唐馮翊子《桂苑叢談》等书錄出之。","祜，諸书或有作祐者，誤。","）。"]', '诗', 'shi', '', NULL, ' 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2ea2f74-0297-4ae6-ae92-c36afd1bae16', '慈烏', '慈烏', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["慈烏色似漆，孔雀尾如金。","內外既相及，聖人空理心。","（此以下均見南宋蜀刻本《張承吉文集》卷六。","）。"]', '["慈烏色似漆，孔雀尾如金。","內外既相及，聖人空理心。","（此以下均见南宋蜀刻本《張承吉文集》卷六。","）。"]', '诗', 'shi', '', NULL, '慈烏 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8af2220-e975-410e-ba37-eaa3512099c5', '閑居作五首 其一', '闲居作五首 其一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["十年狂是酒，一世癖緣詩。","剩物心長厭，閑書性理不違。","補窠新鷰子，争食乳鴉兒。","幸爾隣家竹，春來又許移。"]', '["十年狂是酒，一世癖緣诗。","剩物心长厭，闲书性理不違。","補窠新鷰子，争食乳鴉兒。","幸爾隣家竹，春来又許移。"]', '诗', 'shi', '', NULL, '閑居作五首 其一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6128a8a6-4ea4-47ce-87de-e7c9caaa2da9', '閑居作五首 其三', '闲居作五首 其三', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["小院新栽柳，深窗古畫屏。","屋塼懸蜴蜥，蟲網礙蜻蜓。","啓軸憐孤進，添盃慮獨醒。","殷勤東郭外，春麥又苗青。"]', '["小院新栽柳，深窗古畫屏。","屋塼懸蜴蜥，蟲網礙蜻蜓。","啓軸怜孤進，添盃慮独醒。","殷勤东郭外，春麦又苗青。"]', '诗', 'shi', '', NULL, '閑居作五首 其三 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60aa5fb8-0040-4d53-8807-17719f2db621', '閑居作五首 其四', '闲居作五首 其四', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["悶看垂簷雨，閑尋小院芳。","壁泥根長麥，籬柱葉生楊。","旋碾新茶試，生開嫩酒嘗。","看看花漸老，無復滯春光。"]', '["悶看垂簷雨，闲尋小院芳。","壁泥根长麦，籬柱葉生楊。","旋碾新茶試，生开嫩酒嘗。","看看花漸老，無复滯春光。"]', '诗', 'shi', '', NULL, '閑居作五首 其四 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cf0976f-0ece-4670-894d-94596d5b4a32', '閑居作五首 其五', '闲居作五首 其五', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["俗人無語詔，病客少經過。","種竹憐莖少，移花喜日多。","唯精《左氏傳》，不養右軍鵝。"]', '["俗人無語詔，病客少經過。","種竹怜莖少，移花喜日多。","唯精《左氏傳》，不養右軍鵝。"]', '诗', 'shi', '', NULL, '閑居作五首 其五 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('231f5c38-16b9-4f96-acb0-8d813c80ab46', '江南雜題三十首 其一', '江南杂題三十首 其一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["遠對三茅嶺，踈開一槿籬。","人憐貧好學，自笑老吟詩。","仰腹獼猴睡，斜身蝘蜒癡。","殷勤謝莊叟，櫟社更何疑。"]', '["远对三茅嶺，踈开一槿籬。","人怜貧好学，自笑老吟诗。","仰腹獼猴睡，斜身蝘蜒癡。","殷勤謝莊叟，櫟社更何疑。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95234e29-8ed5-48ac-994a-f37065ffb90a', '江南雜題三十首 其二', '江南杂題三十首 其二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["退居三畝地，聊復謝喧卑。","盡日題書標，無風下釣絲。","蚰蜒過竹節，翡翠抱蘆枝。","惆悵是臨水，星星蓬鬢垂。","。"]', '["退居三畝地，聊复謝喧卑。","尽日題书標，無风下釣絲。","蚰蜒過竹節，翡翠抱蘆枝。","惆悵是臨水，星星蓬鬢垂。","。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c17453f5-e2bf-455c-9dae-eaafe575c41f', '江南雜題三十首 其三', '江南杂題三十首 其三', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["鳥逸溪雲静，人行野岸稀。","茅峯三點翠，練水一條輝。","晚蝶花心少，陰瑩草裏微。","何妨孟朱舍，夜飲醉歌歸。"]', '["鸟逸溪云静，人行野岸稀。","茅峯三点翠，練水一條輝。","晚蝶花心少，陰瑩草裏微。","何妨孟朱舍，夜饮醉歌归。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其三 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0edb3f8-e5ed-41c9-91ee-b0bfc68324bf', '江南雜題三十首 其四', '江南杂題三十首 其四', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["南畝山光對，西郊日影斜。","碧抽書帶草，紅節米囊花。","夜跣嘗琴室，昏岷自酒家。","何妨人不到，私酌是侯芭。"]', '["南畝山光对，西郊日影斜。","碧抽书带草，紅節米囊花。","夜跣嘗琴室，昏岷自酒家。","何妨人不到，私酌是侯芭。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其四 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b58dc65d-fb1e-497c-a55f-fefe0d7bafd5', '江南雜題三十首 其五', '江南杂題三十首 其五', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["野岸煙花好，東園自插籬。","茈姑交宛葉，喜子抱遊絲。","盡日人稀到，終年井不窺。","何當謝貞白，《真誥》是吾師。"]', '["野岸煙花好，东园自插籬。","茈姑交宛葉，喜子抱游絲。","尽日人稀到，終年井不窺。","何當謝貞白，《真誥》是吾師。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其五 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e4d77a9-311d-4ce8-accf-a54a1ff648dc', '江南雜題三十首 其六', '江南杂題三十首 其六', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["遠郭浸煙波，村橋入薜蘿。","水虵驚去疾，山鳥自來多。","夜月傾壺酒，春風就榜歌。"]', '["远郭浸煙波，村橋入薜蘿。","水虵驚去疾，山鸟自来多。","夜月傾壺酒，春风就榜歌。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其六 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12aa0c9f-a27a-4848-9b5d-a83a97ad6c10', '江南雜題三十首 其七', '江南杂題三十首 其七', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["五里波㳂郭，扁舟棹到門。","水經春雨漲，山近夕陽溫。","鸂鶆穿蘆葉，蟛蟖上竹根。","憂來欲誰話，猶賴酒盈罇。"]', '["五里波㳂郭，扁舟棹到门。","水經春雨漲，山近夕陽溫。","鸂鶆穿蘆葉，蟛蟖上竹根。","憂来欲誰話，猶賴酒盈罇。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其七 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f4564e4-ccb7-47b0-9bf9-d87dc5c022f8', '江南雜題三十首 其八', '江南杂題三十首 其八', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["村橋路不端，數里就迴湍。","積壤連涇脉，高林上笋竿。","早嘗甘蔗淡，生摘琵琶酸。","（「琵琶」，嚴壽澄校《張祜詩集》云：疑「枇杷」之誤。","）好是去塵俗，煙花長一欄。"]', '["村橋路不端，數里就迴湍。","積壤連涇脉，高林上笋竿。","早嘗甘蔗淡，生摘琵琶酸。","（「琵琶」，嚴壽澄校《張祜诗集》云：疑「枇杷」之誤。","）好是去塵俗，煙花长一欄。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其八 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a275436-ae1f-463d-ae10-2842ad4245e4', '江南雜題三十首 其九', '江南杂題三十首 其九', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["曉日明高柳，春池合細萍。","鷰巢通蜴蜥，魚網漏蜻蜒。","汩沒非兼濟，終窮是獨醒。"]', '["晓日明高柳，春池合細萍。","鷰巢通蜴蜥，鱼網漏蜻蜒。","汩沒非兼濟，終窮是独醒。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其九 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9756b80-829c-4b5d-b2f9-884aa75ff9c5', '江南雜題三十首 其十', '江南杂題三十首 其十', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["三峯前望峻，一派上遊斜。","雨過離披草，風吹顛倒查。","拂林山鵲翅，叢岸野裳（望疑「裳」爲「棠」之誤。","）花。","好是醉中舞，村橋行數家。"]', '["三峯前望峻，一派上游斜。","雨過離披草，风吹顛倒查。","拂林山鵲翅，叢岸野裳（望疑「裳」爲「棠」之誤。","）花。","好是醉中舞，村橋行數家。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其十 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e36c636d-eb74-4819-8e0c-038ac267c194', '江南雜題三十首 其十一', '江南杂題三十首 其十一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["碧草分遥岸，清池入細流。","投鋪虛飲馬，自物且垂鈎。","小鳥聞批頰，徵蟲弄印頭。","（「徵」，嚴云：疑當作「徵」。","《海錄碎事》卷二十二引此二句，正作「微」字。","）何妨一壺酒，遠遠棹扁舟。"]', '["碧草分遥岸，清池入細流。","投鋪虛饮马，自物且垂鈎。","小鸟闻批頰，徵蟲弄印头。","（「徵」，嚴云：疑當作「徵」。","《海錄碎事》卷二十二引此二句，正作「微」字。","）何妨一壺酒，远远棹扁舟。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其十一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('179a456b-eeb1-45c3-8ff8-f62c2ca32b29', '江南雜題三十首 其十二', '江南杂題三十首 其十二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["端居無外事，長日臥煙嵐。","樹影侵籬北，花香自水南。","酒腸嬰女笑，碁路老僧諳。","似此成乖嬾，嵇康七不堪。","。"]', '["端居無外事，长日臥煙嵐。","樹影侵籬北，花香自水南。","酒腸嬰女笑，碁路老僧諳。","似此成乖嬾，嵇康七不堪。","。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其十二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('683e75a5-3a53-46f8-94f5-06b0bc20f296', '江南雜題三十首 其十三', '江南杂題三十首 其十三', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["一逕遶荒陂，渟洿是小池。","紅蕉心半卷，白練尾長垂。","倒篋纏書帶，尋竿解釣絲。","聊當事山履，遠與白雲期。"]', '["一逕遶荒陂，渟洿是小池。","紅蕉心半卷，白練尾长垂。","倒篋纏书带，尋竿解釣絲。","聊當事山履，远與白云期。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其十三 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06b4dbde-d47b-40c1-924b-08d9fd236216', '江南雜題三十首 其十四', '江南杂題三十首 其十四', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["久病無行意，溪亭益到稀。","月迴秋扇影，螢落夜琴微。","滄海尚凝棹，木山誰採薇？","佳期不可俟，空羡鷰西歸。"]', '["久病無行意，溪亭益到稀。","月迴秋扇影，螢落夜琴微。","滄海尚凝棹，木山誰採薇？","佳期不可俟，空羡鷰西归。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其十四 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba4419d8-17b9-43a9-bf31-791ed80d859c', '江南雜題三十首 其十五', '江南杂題三十首 其十五', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["碧溪窮欲盡，迴棹喜山家。","曲岸深迷竹，平灘下見沙。","懸窠巧婦子，拂水剪刀花。","好是棲心地，人間路不遐。"]', '["碧溪窮欲尽，迴棹喜山家。","曲岸深迷竹，平灘下见沙。","懸窠巧婦子，拂水剪刀花。","好是棲心地，人间路不遐。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其十五 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97b42d80-f46b-4f3e-8a72-6c7ed501f0af', '江南雜題三十首 其十六', '江南杂題三十首 其十六', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["僻居成嬾病，春至強耕蠶。","後港通圍竹，前溪下檐柑。","舊巢飛巧婦，新葉長宜男。","且賴身無事，窮愁亦自甘。"]', '["僻居成嬾病，春至強耕蠶。","後港通圍竹，前溪下檐柑。","旧巢飞巧婦，新葉长宜男。","且賴身無事，窮愁亦自甘。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其十六 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01e69b6f-6246-4adc-9c26-f2b72f690d76', '江南雜題三十首 其十七', '江南杂題三十首 其十七', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["小檻雲低處，高廊雨過時。","鹿胎含笋籜，猿臂長松枝。","舊匣藏鈎軫，沉查骨釣絲。","（「骨」，嚴云：疑當作「罥」。","）平生心未遠，徒欲效鴟夷。","。"]', '["小檻云低处，高廊雨過时。","鹿胎含笋籜，猿臂长松枝。","旧匣藏鈎軫，沉查骨釣絲。","（「骨」，嚴云：疑當作「罥」。","）平生心未远，徒欲效鴟夷。","。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其十七 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c0c3c3e-2d92-4fd9-97c5-eabf1e0267dd', '江南雜題三十首 其十八', '江南杂題三十首 其十八', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["春醪盡數盃，竹逕坐深苔。","鳥道思歸樂，人呼隱去來。","溪花流作片，雨葉爛成堆。","訪戴值兹夕，何妨乘興迴。"]', '["春醪尽數盃，竹逕坐深苔。","鸟道思归乐，人呼隐去来。","溪花流作片，雨葉爛成堆。","訪戴值兹夕，何妨乘兴迴。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其十八 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ef108fd-3581-41e0-9b87-fe60d33fd0cd', '江南雜題三十首 其十九', '江南杂題三十首 其十九', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["洛下無名客，江南不繫舟。","病身黃葉晚，詩思碧雲秋。","雀語嘉賓笑，蛩鳴嬾婦愁。","幸因重醖熱，聊作醉鄉遊。"]', '["洛下無名客，江南不繫舟。","病身黄葉晚，诗思碧云秋。","雀語嘉賓笑，蛩鳴嬾婦愁。","幸因重醖熱，聊作醉乡游。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其十九 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccaf5bb1-f4ef-41d7-908e-ece6b228524f', '江南雜題三十首 其二十', '江南杂題三十首 其二十', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["余生唯愛酒，師長是山翁。","定葬槽丘下，須沉釀瓮中。","鵜鴣春作鳥，舂黍夏爲蟲。","會入醉鄉去，爲君成醉風。"]', '["余生唯愛酒，師长是山翁。","定葬槽丘下，須沉釀瓮中。","鵜鴣春作鸟，舂黍夏爲蟲。","會入醉乡去，爲君成醉风。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其二十 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5c4befd-47c5-4ffd-a9fe-21ae799a733f', '江南雜題三十首 其二十一', '江南杂題三十首 其二十一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["翠竹千竿聳，青池一面臨。","白煙生草末，黃粉露花心。","簇脚蠨蛸桂，（望疑「桂」爲「挂」之誤。","）拋身翡翠沉。"]', '["翠竹千竿聳，青池一面臨。","白煙生草末，黄粉露花心。","簇脚蠨蛸桂，（望疑「桂」爲「挂」之誤。","）拋身翡翠沉。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其二十一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('685f5d38-8324-48d5-90e6-7dd07e675eb9', '江南雜題三十首 其二十二', '江南杂題三十首 其二十二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["滄海一遺民，詩書盡老身。","不逢青眼舊，争奈白頭新。","小小調茶鼎，銖銖定藥斤。","空疎更誰問，賴與酒家隣。","。"]', '["滄海一遺民，诗书尽老身。","不逢青眼旧，争奈白头新。","小小調茶鼎，銖銖定藥斤。","空疎更誰问，賴與酒家隣。","。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其二十二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6f235f9-a246-4e2e-9e2f-6b47326ff853', '江南雜題三十首 其二十三', '江南杂題三十首 其二十三', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["南國久無悰，東郊自養蒙。","老年孤枕在，愁夜一樽空。","澇水聞歌女，枯枝見宛童。","秋來因攬鏡，強欲理衰蓬。"]', '["南国久無悰，东郊自養蒙。","老年孤枕在，愁夜一樽空。","澇水闻歌女，枯枝见宛童。","秋来因攬镜，強欲理衰蓬。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其二十三 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c246a45e-416b-4a39-bf58-ba9f85cb04ab', '江南雜題三十首 其二十五', '江南杂題三十首 其二十五', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["郊園日牢落，無意及壺飱。","大笑俯塵甑，高歌敲酒盆。","汲池澆韮壟，占石坐松根。","未免猶隨俗，長竿掛一褌。"]', '["郊园日牢落，無意及壺飱。","大笑俯塵甑，高歌敲酒盆。","汲池澆韮壟，占石坐松根。","未免猶隨俗，长竿掛一褌。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其二十五 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a601aafc-8e20-4b39-b70f-4c211f96b66e', '江南雜題三十首 其二十六', '江南杂題三十首 其二十六', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["三年江海客，長日犯埃氛。","失脚遠行地，無心空羡雲。","愚非甯武子，蔽是卓文君。","以此圖終計，深棲麋鹿羣。"]', '["三年江海客，长日犯埃氛。","失脚远行地，無心空羡云。","愚非甯武子，蔽是卓文君。","以此圖終計，深棲麋鹿羣。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其二十六 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('349eac6a-d40e-4177-b862-4c9701c19648', '江南雜題三十首 其二十七', '江南杂題三十首 其二十七', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["卜築寄雲陽，穿池面草堂。","尋常登峻嶺，丈六得奇彊。","井鮒依頹甃，隣花出敗墻。"]', '["卜築寄云陽，穿池面草堂。","尋常登峻嶺，丈六得奇彊。","井鮒依頹甃，隣花出敗墻。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其二十七 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a912b789-7543-4373-afd3-f78dba057acd', '江南雜題三十首 其二十八', '江南杂題三十首 其二十八', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["美人殊不見，惆悵望行雲。","竹翠静含粉，榴花輕曳裙。","嬋娟非月色，散漫是蘭薫。","無復荆王夢，子規空夜聞。"]', '["美人殊不见，惆悵望行云。","竹翠静含粉，榴花轻曳裙。","嬋娟非月色，散漫是蘭薫。","無复荆王梦，子規空夜闻。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其二十八 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61b71081-ea1d-47d2-8263-f5e4e14473e3', '江南雜題三十首 其二十九', '江南杂題三十首 其二十九', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["佳期楚雲外，寂寞是春華。","昔去軒車遠，今來衣帶賒。","生風貝母葉，活艷鼠姑花。","惆望碧江阻，夢𩲑雲陟遐。"]', '["佳期楚云外，寂寞是春华。","昔去軒车远，今来衣带賒。","生风貝母葉，活艷鼠姑花。","惆望碧江阻，梦𩲑云陟遐。"]', '诗', 'shi', '', NULL, '江南雜題三十首 其二十九 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62d6c3ae-c835-43d9-baa8-89e7321e12be', '寓居臨平山下三首', '寓居臨平山下三首', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["（按此第一首亦見《永樂大典》卷二二七一、七模、湖字臨平湖條〖二函二十冊〗。","又清初沈謙《臨平記》卷四亦載之。","題曰《過臨平湖》，即將兩書異字校注於下。","）。"]', '["（按此第一首亦见《永乐大典》卷二二七一、七模、湖字臨平湖條〖二函二十冊〗。","又清初沈謙《臨平記》卷四亦載之。","題曰《過臨平湖》，即將兩书異字校注於下。","）。"]', '诗', 'shi', '', NULL, '寓居臨平山下三首 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28e5fe53-7997-4d0c-b998-4d908628d46d', '寓居臨平山下三首 其一', '寓居臨平山下三首 其一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["三月平湖浪（《大典》及《臨平記》作「草」。","）欲齊，綠楊分映（《臨平記》作「影」。","）入長堤。","田家起處烏龍（《臨平記》作「猶」。","）静，（《大典》及《臨平記》作「吠」。","）酒客醒時謝豹啼。","溪（《大典》及《臨平記》作「山」）檻正當蓮葉渚，水涇新麥稻苗畦。","（《大典》作「水堘新擘稻秧畦」，《臨平記》作「水塍新築稻秧畦」。","）人間謾說多歧路，咫尺神仙洞却迷。","（《臨平記》作「路欲迷」。","）。"]', '["三月平湖浪（《大典》及《臨平記》作「草」。","）欲齊，綠楊分映（《臨平記》作「影」。","）入长堤。","田家起处烏龙（《臨平記》作「猶」。","）静，（《大典》及《臨平記》作「吠」。","）酒客醒时謝豹啼。","溪（《大典》及《臨平記》作「山」）檻正當蓮葉渚，水涇新麦稻苗畦。","（《大典》作「水堘新擘稻秧畦」，《臨平記》作「水塍新築稻秧畦」。","）人间謾说多歧路，咫尺神仙洞却迷。","（《臨平記》作「路欲迷」。","）。"]', '诗', 'shi', '', NULL, '寓居臨平山下三首 其一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8150ee7e-61e3-4b9b-82b5-6b46385af482', '寓居臨平山下三首 其二', '寓居臨平山下三首 其二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["一角橫查礙小灘，漁舟稍稍避迴湍。","鹿蹄踏葉暮山響，龜殻曝沙春水寒。","詩句近吟知律變，《易》書窮討覺才難。","風光好處自擕酌，歸去醉扶花藥欄。"]', '["一角橫查礙小灘，漁舟稍稍避迴湍。","鹿蹄踏葉暮山响，龟殻曝沙春水寒。","诗句近吟知律变，《易》书窮討覺才难。","风光好处自擕酌，归去醉扶花藥欄。"]', '诗', 'shi', '', NULL, '寓居臨平山下三首 其二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afdf02f9-0d3e-4bd2-8eb1-9c2cb8694c10', '寓居臨平山下三首 其三', '寓居臨平山下三首 其三', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["散髪垂肩久不簪，竹床推椀就藤陰。","澗傍春渡水流急，山半夜歸雲色深。","拂檻數竿爲去處，隨波一葉是浮沉。","世間年少正行樂，應笑老人無事心。"]', '["散髪垂肩久不簪，竹床推椀就藤陰。","澗傍春渡水流急，山半夜归云色深。","拂檻數竿爲去处，隨波一葉是浮沉。","世间年少正行乐，應笑老人無事心。"]', '诗', 'shi', '', NULL, '寓居臨平山下三首 其三 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('196d2422-4423-4390-b9b8-aecac59b9723', '到廣陵', '到廣陵', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["一年江海恣狂遊，夜宿倡家曉上樓。","嗜酒幾曾羣從小，爲文多是諷諸侯。","逢人說劒三攘臂，對鏡吟詩一掉頭。","今日更來憔悴意，不堪風月滿揚州。","（此以下均見南宋蜀刻本《張承吉文集》卷七。","）。"]', '["一年江海恣狂游，夜宿倡家晓上楼。","嗜酒幾曾羣從小，爲文多是諷諸侯。","逢人说劒三攘臂，对镜吟诗一掉头。","今日更来憔悴意，不堪风月满揚州。","（此以下均见南宋蜀刻本《張承吉文集》卷七。","）。"]', '诗', 'shi', '', NULL, '到廣陵 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be97408b-ceec-4a1c-aa25-d0e61d4881f3', '謝高燕公惠生衣', '謝高燕公惠生衣', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["高公寵歲賜白衣裳，驚訝災天雪滿箱。","乍展輕煙總手滑，如披薄霧覺身凉。","誰家纖素秋蟾色，何處絲抽嫩異香？","珍重六銖無可贈，空憑七字當瓊漿。"]', '["高公寵歲賜白衣裳，驚訝災天雪满箱。","乍展轻煙總手滑，如披薄霧覺身凉。","誰家纖素秋蟾色，何处絲抽嫩異香？","珍重六銖無可贈，空憑七字當瓊漿。"]', '诗', 'shi', '', NULL, '謝高燕公惠生衣 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64eb21d4-e493-460c-81e8-cf0994ed3401', '戲贈村婦', '戲贈村婦', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["二升酸醋瓦瓶盛，請得姑嫜十日程。","赤黑畫眉臨水笑，草鞋苞脚逐風行。","黃絲髪亂梳橑緊，青䘢裙高種掠輕。","想得到家相見後，父孃由唤小時名。"]', '["二升酸醋瓦瓶盛，請得姑嫜十日程。","赤黑畫眉臨水笑，草鞋苞脚逐风行。","黄絲髪亂梳橑緊，青䘢裙高種掠轻。","想得到家相见後，父孃由唤小时名。"]', '诗', 'shi', '', NULL, '戲贈村婦 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cca1a5fb-0c2c-4d93-807d-94bfc7ef1383', '偶登蘇州重玄閣', '偶登蘇州重玄閣', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["飛閣層層茂苑間，夏凉秋晚屙登攀。","萬家前後皆臨水，四檻高低盡見山。","何事越王侵敵國，不妨遼鶴唁人寰。","五湖直下須歸去，自笑身閑迹未閑。"]', '["飞閣層層茂苑间，夏凉秋晚屙登攀。","万家前後皆臨水，四檻高低尽见山。","何事越王侵敵国，不妨遼鹤唁人寰。","五湖直下須归去，自笑身闲迹未闲。"]', '诗', 'shi', '', NULL, '偶登蘇州重玄閣 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64313420-1f91-405d-a4a2-1c095a0e5496', '投蘇州盧中丞', '投蘇州盧中丞', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["金紫清門美丈夫，聖人憂地詔分符。","猶將儉德同朝客，不着尊官傲世儒。","經術在心長說體，吏材臨事必開模。","西來郡界逢鄉老，盡說而今是坦途。"]', '["金紫清门美丈夫，聖人憂地詔分符。","猶將儉德同朝客，不着尊官傲世儒。","經術在心长说體，吏材臨事必开模。","西来郡界逢乡老，尽说而今是坦途。"]', '诗', 'shi', '', NULL, '投蘇州盧中丞 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d3c571e-4fd7-4430-86f1-84498af12518', '投滑州上盧尚書', '投滑州上盧尚书', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["雨露恩重棣萼繁，一時旌旆刊雄藩。","權經兩使材尤重，位近三台道益尊。","江海豁開爲氣岸，河隍堅畫在心源。","門闌盡是雲霄客，應念於陵獨灌園。","。"]', '["雨露恩重棣萼繁，一时旌旆刊雄藩。","權經兩使材尤重，位近三台道益尊。","江海豁开爲氣岸，河隍堅畫在心源。","门闌尽是云霄客，應念於陵独灌园。","。"]', '诗', 'shi', '', NULL, '投滑州上盧尚書 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f318ed52-7c91-4458-8c52-c5a264969731', '投蘇州盧郎中', '投蘇州盧郎中', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["三地分符寵更深，兩方旌斾日駸駸。","蛟龍可是池中物，鳯鳥無非閣上音。","世重才人皆立績，客依公子盡推心。","猶思謝尚經牛渚，曾聽袁宏一夜吟。"]', '["三地分符寵更深，兩方旌斾日駸駸。","蛟龙可是池中物，鳯鸟無非閣上音。","世重才人皆立績，客依公子尽推心。","猶思謝尚經牛渚，曾听袁宏一夜吟。"]', '诗', 'shi', '', NULL, '投蘇州盧郎中 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('becc1d63-2739-4007-8d3d-2e0fadef9ba4', '送劉軺秀才江陵歸寧', '送劉軺秀才江陵归寧', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["出告遊方是素辭，喜君迴棹不逾時。","荆門暮指連山遠，郢國春歸上水遲。","罇酒惜離文舉坐，郡齋誰覆中宣碁。","（《輿地紀勝》卷六五引以上四句，「中宣」作「仲宣」，是。","）殷勤莫忘趨庭日，學禮三餘已學詩。"]', '["出告游方是素辞，喜君迴棹不逾时。","荆门暮指連山远，郢国春归上水遲。","罇酒惜離文舉坐，郡斋誰覆中宣碁。","（《輿地紀勝》卷六五引以上四句，「中宣」作「仲宣」，是。","）殷勤莫忘趨庭日，学禮三餘已学诗。"]', '诗', 'shi', '', NULL, '送劉軺秀才江陵歸寧 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03348032-d1f9-40cf-b35a-29e297a52709', '奉和池州杜員外南亭惜春', '奉和池州杜員外南亭惜春', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["草霧輝輝柳色新，前山差掩黛眉頻。","碧溪潮漲碁侵夜，紅樹花深醉度春。","幾恨今年提已過，翻悲昨日事成塵。","可知屈轉江南郡，還就封州詠白蘋。"]', '["草霧輝輝柳色新，前山差掩黛眉頻。","碧溪潮漲碁侵夜，紅樹花深醉度春。","幾恨今年提已過，翻悲昨日事成塵。","可知屈轉江南郡，還就封州詠白蘋。"]', '诗', 'shi', '', NULL, '奉和池州杜員外南亭惜春 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58fdb972-9268-4d5c-8449-b1b0051d3dc0', '題河陽新鼓角樓', '題河陽新鼓角楼', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["重樓高桍兩簷開，曉夕風雲會振雷。","中國最推鼙鼓地，大臣先選陳樑材。","馬悲塞北千羣牧，鴈到城南一半迴。","從此聖朝思將帥，上衣須脫食須推。"]', '["重楼高桍兩簷开，晓夕风云會振雷。","中国最推鼙鼓地，大臣先選陳樑材。","马悲塞北千羣牧，鴈到城南一半迴。","從此聖朝思將帥，上衣須脫食須推。"]', '诗', 'shi', '', NULL, '題河陽新鼓角樓 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46754f32-a6ab-4a3c-91d2-e7cb59511aac', '觀楚州韋舍人新築河堤怺建兩閶門（按此詩亦見《永樂大典》卷三五二七「九真」「門」字「北閶門」條〖五函四十九冊〗。《大典》引《元一統志》曰：「淮安路有北閶門，唐〖張，原脫〗祐〖應作祜〗有《陪楚州韋舍人北閶門遊燕詩》。」）', '观楚州韋舍人新築河堤怺建兩閶门（按此诗亦见《永乐大典》卷三五二七「九真」「门」字「北閶门」條〖五函四十九冊〗。《大典》引《元一統志》曰：「淮安路有北閶门，唐〖張，原脫〗祐〖應作祜〗有《陪楚州韋舍人北閶门游燕诗》。」）', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["宴賓容易小筵成，隼擊秋原助放情。","紅袖退行鞍上語，白眉迂步馬前迎。","一冬霜意先黃葉，兩路風威動翠旌。","須道孔融罇已滿，不勞臺下說餘酲。"]', '["宴賓容易小筵成，隼擊秋原助放情。","紅袖退行鞍上語，白眉迂步马前迎。","一冬霜意先黄葉，兩路风威动翠旌。","須道孔融罇已满，不勞台下说餘酲。"]', '诗', 'shi', '', NULL, '觀楚州韋舍人新築河堤怺建兩閶門（按此詩亦見《永樂大典》卷三五二七「九真」「門」字「北閶門」條〖五函四十九冊〗。《大典》引《元一統志》曰：「淮安路有北閶門，唐〖張，原脫〗祐〖應作祜〗有《陪楚州韋舍人北閶門遊燕詩》。」） 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82a0d26d-71d4-455f-87ad-428a7073af52', '題潤州李尚書北固新樓', '題潤州李尚书北固新楼', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["躡石攀雲一逕危，粉廊朱檻眺江湄。","青山半在潮來處，碧海先看月滿時。","樹色轉煙城斗峻，水光浮草岸遥卑。","西樓又起公羊意，坐對寒潮向渺瀰。"]', '["躡石攀云一逕危，粉廊朱檻眺江湄。","青山半在潮来处，碧海先看月满时。","樹色轉煙城斗峻，水光浮草岸遥卑。","西楼又起公羊意，坐对寒潮向渺瀰。"]', '诗', 'shi', '', NULL, '題潤州李尚書北固新樓 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb47b8e6-e6b0-4b84-b834-b43bdfdf3857', '酬張權宣州新橋秋夜對月見寄', '酬張權宣州新橋秋夜对月见寄', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["謝亭煙月泛清流，千載溪山一造舟。","風定遠帆依郡郭，夜深寒笛起江樓。","張憑逆旅逢新唱，王粲從軍值勝游。","長愛征南杜公意，不將餘力礙《春秋》。"]', '["謝亭煙月泛清流，千載溪山一造舟。","风定远帆依郡郭，夜深寒笛起江楼。","張憑逆旅逢新唱，王粲從軍值勝游。","长愛征南杜公意，不將餘力礙《春秋》。"]', '诗', 'shi', '', NULL, '酬張權宣州新橋秋夜對月見寄 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e22b1cfe-f30d-4820-9053-1dd4e2acdb61', '題宛陵新橋兼獻裴尚書', '題宛陵新橋兼獻裴尚书', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["富平津路遠陵開，武庫森森又姓裴。","高步已吟携手句，上聞初喜造舟才。","霜明華表塵初静，月正欄干斗乍回。","猶憶醉歌南浦夜，五更人過萬聲雷。"]', '["富平津路远陵开，武庫森森又姓裴。","高步已吟携手句，上闻初喜造舟才。","霜明华表塵初静，月正欄干斗乍回。","猶憶醉歌南浦夜，五更人過万声雷。"]', '诗', 'shi', '', NULL, '題宛陵新橋兼獻裴尚書 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbf4e269-503d-4bf9-8e21-a0958f3aa92a', '所居即事六首（原注：丹陽閑居寄鄭明府如範上人。） 其一', '所居即事六首（原注：丹陽闲居寄鄭明府如範上人。） 其一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["南下丹陽一水灣，陋居瓢飲是希顏。","來爲野鳥入春郭，去作溪雲歸夜山。","蓬鬢已衰言必賤，竹門雖立意無關。","陶潛惠遠如相愛，朝訪遺民暮却還。"]', '["南下丹陽一水灣，陋居瓢饮是希顏。","来爲野鸟入春郭，去作溪云归夜山。","蓬鬢已衰言必賤，竹门雖立意無关。","陶潛惠远如相愛，朝訪遺民暮却還。"]', '诗', 'shi', '', NULL, '所居即事六首（原注：丹陽閑居寄鄭明府如範上人。） 其一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef179582-6040-4a1b-b5f0-0647986ad061', '所居即事六首（原注：丹陽閑居寄鄭明府如範上人。） 其二（原注：溪上小齋。）', '所居即事六首（原注：丹陽闲居寄鄭明府如範上人。） 其二（原注：溪上小斋。）', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["日暮空齋對小溪，遠村歸岸醉如泥。","杜鵑花茫然杜鵑叫，烏臼葉生烏臼啼。","（嚴云：「頷聯二句見《唐詩紀事》，『花落』作『花前。","』」又見《海錄碎事》卷二十二、《全唐詩》卷五一一，「花落」作「花發」，「葉生」作「花生」。","）野食不妨菰作飯，園蔬何必稻爲虀。","辛勤最愛孟光意，除却梁鴻無急妻。"]', '["日暮空斋对小溪，远村归岸醉如泥。","杜鵑花茫然杜鵑叫，烏臼葉生烏臼啼。","（嚴云：「頷聯二句见《唐诗紀事》，『花落』作『花前。","』」又见《海錄碎事》卷二十二、《全唐诗》卷五一一，「花落」作「花發」，「葉生」作「花生」。","）野食不妨菰作飯，园蔬何必稻爲虀。","辛勤最愛孟光意，除却梁鴻無急妻。"]', '诗', 'shi', '', NULL, '所居即事六首（原注：丹陽閑居寄鄭明府如範上人。） 其二（原注：溪上小齋。） 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9a6f1c3-4395-484d-b09e-693f1ab2f3b1', '所居即事六首（原注：丹陽閑居寄鄭明府如範上人。） 其三', '所居即事六首（原注：丹陽闲居寄鄭明府如範上人。） 其三', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["牢落東溪滿鬢絲，一身扶杖二男隨。","（《全唐詩》卷五一一據《野客叢書》收此句。","）鳴鳩在處携書卷，科斗生時想墨池。","日夕愛琴憐犬子，春風詠雪喜胡兒。","我家命駕還千里，別與鱸魚爲後期。"]', '["牢落东溪满鬢絲，一身扶杖二男隨。","（《全唐诗》卷五一一據《野客叢书》收此句。","）鳴鳩在处携书卷，科斗生时想墨池。","日夕愛琴怜犬子，春风詠雪喜胡兒。","我家命駕還千里，別與鱸鱼爲後期。"]', '诗', 'shi', '', NULL, '所居即事六首（原注：丹陽閑居寄鄭明府如範上人。） 其三 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eca96d99-534b-4d9f-865a-944e3e79e8ea', '所居即事六首（原注：丹陽閑居寄鄭明府如範上人。） 其四（原注：春日寓言。）', '所居即事六首（原注：丹陽闲居寄鄭明府如範上人。） 其四（原注：春日寓言。）', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["寂寞春風意未降，酒狂詩癖舊無雙。","柳花飛處曾逢雪，桃葉開提憶渡江。","自古不堪居陋巷，從今休更犯危邦。","聖朝何用詢名姓，從放書生老北窗。"]', '["寂寞春风意未降，酒狂诗癖旧無雙。","柳花飞处曾逢雪，桃葉开提憶渡江。","自古不堪居陋巷，從今休更犯危邦。","聖朝何用詢名姓，從放书生老北窗。"]', '诗', 'shi', '', NULL, '所居即事六首（原注：丹陽閑居寄鄭明府如範上人。） 其四（原注：春日寓言。） 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b4d1ce7-dfc8-42b1-a3f0-b5d96d7b2db1', '所居即事六首（原注：丹陽閑居寄鄭明府如範上人。） 其五（原注：偶作。）', '所居即事六首（原注：丹陽闲居寄鄭明府如範上人。） 其五（原注：偶作。）', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["南窮海徼北天涯，惆悵亡羊是路歧。","眼下已隳梁武佛，耳中猶聽魏文詩。","三茅道士朝携手，五柳先生夜對棊。","自向廬山爲一社，百年生計任嬰兒。"]', '["南窮海徼北天涯，惆悵亡羊是路歧。","眼下已隳梁武佛，耳中猶听魏文诗。","三茅道士朝携手，五柳先生夜对棊。","自向廬山爲一社，百年生計任嬰兒。"]', '诗', 'shi', '', NULL, '所居即事六首（原注：丹陽閑居寄鄭明府如範上人。） 其五（原注：偶作。） 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78083627-3f1d-4dfb-9853-9aaa0ce0c889', '所居即事六首（原注：丹陽閑居寄鄭明府如範上人。） 其六', '所居即事六首（原注：丹陽闲居寄鄭明府如範上人。） 其六', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["晨起常掻兩鬢絲，小亭深坐一洿池。","墻頭鸜鵒隈花葉，水面蜻蜓寄草枝。","賴得木奴些子力，生憎魚婢苦頑癡。","扁舟遠棹尋春處，竹榼新醪喜自隨。","。"]', '["晨起常掻兩鬢絲，小亭深坐一洿池。","墻头鸜鵒隈花葉，水面蜻蜓寄草枝。","賴得木奴些子力，生憎鱼婢苦頑癡。","扁舟远棹尋春处，竹榼新醪喜自隨。","。"]', '诗', 'shi', '', NULL, '所居即事六首（原注：丹陽閑居寄鄭明府如範上人。） 其六 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e2e1eb0-f67c-4cdf-b7de-cd64d19dc951', '贈薛鼎臣侍御', '贈薛鼎臣侍御', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["君子清明致自強，大寮僉語美公方。","長才上拔孤摽日，利劒新磨一匣霜。","千里早時知逸足，片言中夜許剛腸。","已知金石終無變，應蓄歸休在智囊。"]', '["君子清明致自強，大寮僉語美公方。","长才上拔孤摽日，利劒新磨一匣霜。","千里早时知逸足，片言中夜許剛腸。","已知金石終無变，應蓄归休在智囊。"]', '诗', 'shi', '', NULL, '贈薛鼎臣侍御 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af7ca7f8-2c4d-40f3-8841-0a232c8228d2', '偶信', '偶信', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["浮生擾擾務華虛，未勝東歸重結廬。","自已忘言師靖節，聘関真隱慕玄居。","無機坐上休捫虱，失脚溪頭便釣魚。","唯恨世間些子事，兩莖衰髪爲人梳。"]', '["浮生擾擾務华虛，未勝东归重結廬。","自已忘言師靖節，聘関真隐慕玄居。","無機坐上休捫虱，失脚溪头便釣鱼。","唯恨世间些子事，兩莖衰髪爲人梳。"]', '诗', 'shi', '', NULL, '偶信 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('761ab788-511b-4278-98af-64f34b209482', '贈季峯上人', '贈季峯上人', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["時賢近喪若山崖，却賴青雲望素乖。","強似鵷鸞趍宦達，可勝藜藿伴僧齋。","一壺酒外終無事，萬卷書中死便埋。","唯是江東道門子，許詢長說是吾儕。"]', '["时賢近喪若山崖，却賴青云望素乖。","強似鵷鸾趍宦達，可勝藜藿伴僧斋。","一壺酒外終無事，万卷书中死便埋。","唯是江东道门子，許詢长说是吾儕。"]', '诗', 'shi', '', NULL, '贈季峯上人 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cf0328d-fc5c-4b83-98a2-00baca29b3bb', '送法鏡上人歸上元', '送法镜上人归上元', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["南國僧遊二十年，却因無任訪生緣。","風迴建業秋歸寺，月滿秦淮夜到舡。","故老盡成雙鬢雪，舊房深鏁一林煙。","莫言了悟爲真理，不歎興亡在眼前。"]', '["南国僧游二十年，却因無任訪生緣。","风迴建業秋归寺，月满秦淮夜到舡。","故老尽成雙鬢雪，旧房深鏁一林煙。","莫言了悟爲真理，不歎兴亡在眼前。"]', '诗', 'shi', '', NULL, '送法鏡上人歸上元 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3853c0c3-3b28-4c83-bfb3-f1720ece3b87', '鷹（按《全唐詩》卷三百六十一作劉禹錫詩，題曰《白鷹》。詩同，不重錄。校其異字如下：第一句「手羽斒斕白野裁」，「野」，《全唐詩》作「紵」，是。二句「馬前擎出不擎猜」，「不擎」，《全唐詩》作「不驚」，是。五句「綠玉觜啗雞腦破」，「啗」，《全唐詩》作「攅」。末句「所以人人道俊裁」，「裁」，《全唐詩》作「哉」，是。〖《劉賓客文集》不收此詩，應爲張祜作。〗）', '鷹（按《全唐诗》卷三百六十一作劉禹錫诗，題曰《白鷹》。诗同，不重錄。校其異字如下：第一句「手羽斒斕白野裁」，「野」，《全唐诗》作「紵」，是。二句「马前擎出不擎猜」，「不擎」，《全唐诗》作「不驚」，是。五句「綠玉觜啗雞腦破」，「啗」，《全唐诗》作「攅」。末句「所以人人道俊裁」，「裁」，《全唐诗》作「哉」，是。〖《劉賓客文集》不收此诗，應爲張祜作。〗）', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '鷹（按《全唐詩》卷三百六十一作劉禹錫詩，題曰《白鷹》。詩同，不重錄。校其異字如下：第一句「手羽斒斕白野裁」，「野」，《全唐詩》作「紵」，是。二句「馬前擎出不擎猜」，「不擎」，《全唐詩》作「不驚」，是。五句「綠玉觜啗雞腦破」，「啗」，《全唐詩》作「攅」。末句「所以人人道俊裁」，「裁」，《全唐詩》作「哉」，是。〖《劉賓客文集》不收此詩，應爲張祜作。〗） 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('807b9361-acce-4685-954a-e7b17fe599c3', '題李戡山居', '題李戡山居', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["三畝溪田竹逕通，道情交態只漁翁。","青山夜入孤帆遠，碧水秋澄一檻空。","自以蛙聲爲皷樂，聊將早色當屏風。","莫言酷學無知己，未必王音不薦雄。"]', '["三畝溪田竹逕通，道情交態只漁翁。","青山夜入孤帆远，碧水秋澄一檻空。","自以蛙声爲皷乐，聊將早色當屏风。","莫言酷学無知己，未必王音不薦雄。"]', '诗', 'shi', '', NULL, '題李戡山居 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7c19297-1d3e-4b55-a2c9-4b5af225e82b', '題李山人園林', '題李山人园林', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["幾年垂釣碧江潯，長愛嚴陵是此心。","萬壑深秋聞伐木，一溪長日看淘金。","桑生壠上螟蛉挂，竹在沙頭翡翠沉。","唯道石田堪種黍，不將衰髪羡華簪。","。"]', '["幾年垂釣碧江潯，长愛嚴陵是此心。","万壑深秋闻伐木，一溪长日看淘金。","桑生壠上螟蛉挂，竹在沙头翡翠沉。","唯道石田堪種黍，不將衰髪羡华簪。","。"]', '诗', 'shi', '', NULL, '題李山人園林 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42937589-4430-4059-a308-3d7a6727ec83', '投河陽右僕射', '投河陽右僕射', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["黠虜搆攙搶，（應作「欃槍」或「攙槍」。","）將軍首出征。","萬人旗下泣，一馬陳前行。","對敵梟心死，衝圍虎力生。","雪霜齊擐甲，風雨驟揚兵。","指點看鞭勢，喧呼認前聲。","狂胡追過磧，貴主奪還京。","黑夜星華朗，黃昏火號明。","無非刀筆吏，獨傳說時英。","（本卷均見南宋蜀刻本《張承吉文集》卷八。","）。"]', '["黠虜搆攙搶，（應作「欃槍」或「攙槍」。","）將軍首出征。","万人旗下泣，一马陳前行。","对敵梟心死，衝圍虎力生。","雪霜齊擐甲，风雨驟揚兵。","指点看鞭勢，喧呼認前声。","狂胡追過磧，貴主奪還京。","黑夜星华朗，黄昏火號明。","無非刀笔吏，独傳说时英。","（本卷均见南宋蜀刻本《張承吉文集》卷八。","）。"]', '诗', 'shi', '', NULL, '投河陽右僕射 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5083d11-7f30-4681-9c30-f98524b56778', '宋城道中逢王直方八韻', '宋城道中逢王直方八韻', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["二年離子載，發跡自江南。","馬上行尋度，途中語再三。","始因窮去魏，河北戰方酣。","後以文投許，淮西難未戡。","謫官逢李涉，狂客見劉弇。","失意憐初話，多端耻舊諳。","茶風無奈筆，酒禿不勝簪。","幾鬱胸中恨，聊當遂劇談。"]', '["二年離子載，發跡自江南。","马上行尋度，途中語再三。","始因窮去魏，河北戰方酣。","後以文投許，淮西难未戡。","謫官逢李涉，狂客见劉弇。","失意怜初話，多端耻旧諳。","茶风無奈笔，酒禿不勝簪。","幾鬱胸中恨，聊當遂劇談。"]', '诗', 'shi', '', NULL, '宋城道中逢王直方八韻 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b1b22a4-37a9-4916-a724-9cf313cda916', '題重玄寺閣八韻', '題重玄寺閣八韻', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["朱閣鱗虛搆，環瞻極水鄉。","青螺蔟山色，白練展湖光。","矗戶浮雲過，斜軒早鴈翔。","萬簷攢肆邸，千葉溢津航。","疊供儳寒碧，飛窗漏夕陽。","月輪霄輾棟，風鐸曙鏗廊。","塔聳尖層出，河縈小派長。","因還九霄上，凝步獨成章。","。"]', '["朱閣鱗虛搆，环瞻極水乡。","青螺蔟山色，白練展湖光。","矗戶浮云過，斜軒早鴈翔。","万簷攢肆邸，千葉溢津航。","叠供儳寒碧，飞窗漏夕陽。","月輪霄輾棟，风鐸曙鏗廊。","塔聳尖層出，河縈小派长。","因還九霄上，凝步独成章。","。"]', '诗', 'shi', '', NULL, '題重玄寺閣八韻 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e1b8a95-ee7c-465b-b0c0-d2e16a9242eb', '投韓員外六韻', '投韓員外六韻', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["見說韓員外，聲華溢九垓。","大川舟欲濟，荒草路初開。","聳地千潯壁，（「千潯」，疑應作「千尋」。","）森雲百丈材。","狂波心上湧，驟雨筆前來。","後學無人譽，先賢亦自媒。","還聞孔融表，曾薦禰衡才。"]', '["见说韓員外，声华溢九垓。","大川舟欲濟，荒草路初开。","聳地千潯壁，（「千潯」，疑應作「千尋」。","）森云百丈材。","狂波心上湧，驟雨笔前来。","後学無人譽，先賢亦自媒。","還闻孔融表，曾薦禰衡才。"]', '诗', 'shi', '', NULL, '投韓員外六韻 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94686acf-6110-49f2-bb09-bd49f4df32ca', '登杭州龍興寺三門樓', '登杭州龙兴寺三门楼', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["十里江城下渺漫，兩層門上倚欄干。","偏宜竹翠山長潤，早見梅花地少寒。","沙觜漸平人改路，潮痕初静鳥移灘。","高樓酒夜誰家笛，一曲《凉州》夢裏殘。"]', '["十里江城下渺漫，兩層门上倚欄干。","偏宜竹翠山长潤，早见梅花地少寒。","沙觜漸平人改路，潮痕初静鸟移灘。","高楼酒夜誰家笛，一曲《凉州》梦裏殘。"]', '诗', 'shi', '', NULL, '登杭州龍興寺三門樓 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bc20a00-130e-4ddd-b022-ba38fc772b5e', '江上旅伯呈池州杜員外', '江上旅伯呈池州杜員外', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["（按《全唐詩》卷五一一收此詩之前四句，缺其後半。","題作《江上旅伯呈杜員外》，今全錄之。","）牛渚南來沙岸長，遠吟佳句望池陽。","野人未必非毛遂，太守還須是孟嘗。","江郡風流今絶世，杜陵才子舊爲郎。","不妨酒夜因閑語，別指東山是醉鄉。"]', '["（按《全唐诗》卷五一一收此诗之前四句，缺其後半。","題作《江上旅伯呈杜員外》，今全錄之。","）牛渚南来沙岸长，远吟佳句望池陽。","野人未必非毛遂，太守還須是孟嘗。","江郡风流今絶世，杜陵才子旧爲郎。","不妨酒夜因闲語，別指东山是醉乡。"]', '诗', 'shi', '', NULL, '江上旅伯呈池州杜員外 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31b4bec5-ec7e-43fe-910e-5820353a6e0e', '題臨平驛亭', '題臨平驛亭', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["津亭一望海西壖，舊說湖開是幾年。","風起半山雲出寺，雨餘深岸水平舡。","竹林上拔高高笋，荷葉中藏小小蓮。","長愛向南些子地，兩三家近野唐邊。"]', '["津亭一望海西壖，旧说湖开是幾年。","风起半山云出寺，雨餘深岸水平舡。","竹林上拔高高笋，荷葉中藏小小蓮。","长愛向南些子地，兩三家近野唐邊。"]', '诗', 'shi', '', NULL, '題臨平驛亭 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33869a36-d15c-4cca-b242-129657d2eb8d', '窮居', '窮居', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["陋巷長聞君子窮，我生寧免因儒宮。","辛勤自灌一畦韮，鹵莽還開三徑蓬。","竹下喜逢青眼士，草中甘作白頭翁。","佳期日暮不知處，把鈎（陳九思同志謂是「釣」字之訛。","）徒吟江上風。"]', '["陋巷长闻君子窮，我生寧免因儒宮。","辛勤自灌一畦韮，鹵莽還开三徑蓬。","竹下喜逢青眼士，草中甘作白头翁。","佳期日暮不知处，把鈎（陳九思同志謂是「釣」字之訛。","）徒吟江上风。"]', '诗', 'shi', '', NULL, '窮居 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('668b42f8-4cf1-4af6-985b-e8381bcc4fa5', '題贈崔權處士', '題贈崔權处士', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["（按此詩亦見《永樂大典》卷一三四五○「二寘」「士」字「處士」條。","〖十四函一百三十七冊〗。","）讀盡儒書鬢皓然，身遊城市（《大典》作「下」）意林泉。","已因駿馬成三逕，猶恨胡麻欠一廛。","真玉比來曾不磷，直鈎從此更誰憐？","遺民莫恨無高躅，陶令而今亦甚賢。"]', '["（按此诗亦见《永乐大典》卷一三四五○「二寘」「士」字「处士」條。","〖十四函一百三十七冊〗。","）读尽儒书鬢皓然，身游城市（《大典》作「下」）意林泉。","已因駿马成三逕，猶恨胡麻欠一廛。","真玉比来曾不磷，直鈎從此更誰怜？","遺民莫恨無高躅，陶令而今亦甚賢。"]', '诗', 'shi', '', NULL, '題贈崔權處士 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2142c37-e2fc-4ed6-8f98-c790c2388fca', '酬餘姚鄭摸（《大典》作「模」）明府見贈長句四韻', '酬餘姚鄭摸（《大典》作「模」）明府见贈长句四韻', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["（按此詩亦見《永樂大典》卷一一○○○「六姥」「府」字「明府」條。","〖十一函一百十冊〗）仙令東來值勝遊，人間稀遇一扁舟。","萬重山色軍江徼，十里溪聲到縣樓。","吏隱不妨彭澤遠，公才多謝武城優。","生疎莫笑滄浪叟，白首直竿是直鈎。"]', '["（按此诗亦见《永乐大典》卷一一○○○「六姥」「府」字「明府」條。","〖十一函一百十冊〗）仙令东来值勝游，人间稀遇一扁舟。","万重山色軍江徼，十里溪声到縣楼。","吏隐不妨彭澤远，公才多謝武城優。","生疎莫笑滄浪叟，白首直竿是直鈎。"]', '诗', 'shi', '', NULL, '酬餘姚鄭摸（《大典》作「模」）明府見贈長句四韻 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e16814d-afb7-4b70-9a43-630e9b6be592', '早秋貴溪南亭晚眺', '早秋貴溪南亭晚眺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["溪流照檻肅埃氛，百里秋光草樹分。","青壁峻時山背日，碧潭空處水銷雲。","千尋下徹魚無隱，一點高飛鷺出羣。","迴首故鄉人未去，亂蟬聲噪不堪聞。"]', '["溪流照檻肅埃氛，百里秋光草樹分。","青壁峻时山背日，碧潭空处水銷云。","千尋下徹鱼無隐，一点高飞鷺出羣。","迴首故乡人未去，亂蟬声噪不堪闻。"]', '诗', 'shi', '', NULL, '早秋貴溪南亭晚眺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d799a1de-5f30-47a3-8090-d735ccc9b90d', '壽州裴中丞出柘枝', '壽州裴中丞出柘枝', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["青娥十五柘枝人，玉鳯雙翹翠帽新。","羅帶却翻柔紫袖，錦靴前踏沒紅茵。","深情記處常低眼，急拍來時旋折身。","愁見曲終如夢覺，又迷煙水漢江濱。"]', '["青娥十五柘枝人，玉鳯雙翹翠帽新。","羅带却翻柔紫袖，錦靴前踏沒紅茵。","深情記处常低眼，急拍来时旋折身。","愁见曲終如梦覺，又迷煙水漢江濱。"]', '诗', 'shi', '', NULL, '壽州裴中丞出柘枝 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19bf83aa-e89d-47f8-af3d-dad942523a0f', '池州周員外出柘枝', '池州周員外出柘枝', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["紅筵高設畫堂開，小妓粧成爲舞催。","珠帽著聽歌遍匝，錦靴行踏鼓聲來。","纖纖玉笋羅衫撮，戢戢金星鈿帶迴。","長恐周瑜一私顧，不教閑客望瑤臺。"]', '["紅筵高設畫堂开，小妓粧成爲舞催。","珠帽著听歌遍匝，錦靴行踏鼓声来。","纖纖玉笋羅衫撮，戢戢金星鈿带迴。","长恐周瑜一私顧，不教闲客望瑤台。"]', '诗', 'shi', '', NULL, '池州周員外出柘枝 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b53132b-2813-4285-9929-df9c447d4d75', '贈柘枝', '贈柘枝', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["鴛帶排方鏤綠牙，紫羅衫卷合懽花。","當筵舞汗銷胸雪，入破凝姿動臉霞。","帽側蹙腰鈴數轉，亞身招拍腕頻斜。","須臾曲罷歸何處？稱道巫山是我家。"]', '["鴛带排方鏤綠牙，紫羅衫卷合懽花。","當筵舞汗銷胸雪，入破凝姿动臉霞。","帽側蹙腰鈴數轉，亞身招拍腕頻斜。","須臾曲罷归何处？稱道巫山是我家。"]', '诗', 'shi', '', NULL, '贈柘枝 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dee316a-0c0d-42f8-93e9-3d7bc23307d4', '觀濠州田中丞出臘', '观濠州田中丞出臘', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["東城曉出静塵埃，紫畫神旗向日開。","錦袖半攘争捧轡，銀鞍不下小傳盃。","馬盤草上朱弓滿，鴈落雲中白羽迴。","晚向三通殘皷盡，北原千騎卷行來。"]', '["东城晓出静塵埃，紫畫神旗向日开。","錦袖半攘争捧轡，銀鞍不下小傳盃。","马盤草上朱弓满，鴈落云中白羽迴。","晚向三通殘皷尽，北原千騎卷行来。"]', '诗', 'shi', '', NULL, '觀濠州田中丞出臘 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cefa5eaa-afb2-4668-a894-1ca3484bd33d', '鍾陵旅泊', '鍾陵旅泊', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["城衘西面驛堤連，十里長江夜看舡。","漁市月中人静過，酒家燈下犬長眠。","龍笻迥泊灘聲下，略彴深行樹影邊。","唯是南風還小瘴，與他歸去避衰年。"]', '["城衘西面驛堤連，十里长江夜看舡。","漁市月中人静過，酒家灯下犬长眠。","龙笻迥泊灘声下，略彴深行樹影邊。","唯是南风還小瘴，與他归去避衰年。"]', '诗', 'shi', '', NULL, '鍾陵旅泊 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed120ae4-0e8b-454e-8a9b-50d79e05c5ec', '湘中行', '湘中行', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["南去長沙又幾程，二妃來死我來行。","人歸五嶺暮天碧，日下三湘寒水清。","遠地毒虵冬不蟄，深山古木夜爲精。","傷心靈跡在何處？斑竹廟前風雨聲。"]', '["南去长沙又幾程，二妃来死我来行。","人归五嶺暮天碧，日下三湘寒水清。","远地毒虵冬不蟄，深山古木夜爲精。","傷心靈跡在何处？斑竹廟前风雨声。"]', '诗', 'shi', '', NULL, '湘中行 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e9d7727-8434-42c3-9122-978eb79cf2b4', '秋日宿簡寂觀陸先生草堂', '秋日宿簡寂观陸先生草堂', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["紫霄峯下草堂仙，千載空梁石磬懸。","白氣夜生龍在水，碧雲秋斷鶴歸天。","竹廊影過中庭月，松檻聲來半壁泉。","明日又爲浮世恨，滿山行路夢依然。","（見《吉石庵叢書》本陳舜俞《廬山記》卷四，題作《簡寂觀》，「空梁」作「空遺」，「竹廊」作「空遺」，「竹廊」作「竹房」，「鑾過」作「影占」，「行路」作「徒積」。","）。"]', '["紫霄峯下草堂仙，千載空梁石磬懸。","白氣夜生龙在水，碧云秋斷鹤归天。","竹廊影過中庭月，松檻声来半壁泉。","明日又爲浮世恨，满山行路梦依然。","（见《吉石庵叢书》本陳舜俞《廬山記》卷四，題作《簡寂观》，「空梁」作「空遺」，「竹廊」作「空遺」，「竹廊」作「竹房」，「鑾過」作「影占」，「行路」作「徒積」。","）。"]', '诗', 'shi', '', NULL, '秋日宿簡寂觀陸先生草堂 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('032ad1bb-1476-4794-ade1-952b3e4d8295', '投滑州盧尚書', '投滑州盧尚书', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["海內諸侯最屈名，不妨中立自經營。","文翁莫猒分符久，韓信終須仗鉞行。","静以軍威齊虎士，別將才力誚儒生。","親筆幾話南遷客，未必無憂是早榮。"]', '["海內諸侯最屈名，不妨中立自經營。","文翁莫猒分符久，韓信終須仗鉞行。","静以軍威齊虎士，別將才力誚儒生。","親笔幾話南遷客，未必無憂是早榮。"]', '诗', 'shi', '', NULL, '投滑州盧尚書 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('978ebcc5-8f6e-4140-b55e-e6b4527779ee', '送鄭灊判官歸冬寧', '送鄭灊判官归冬寧', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["結束翩翩肯寡悰，早時强學已三冬。","鯉庭趍日通明訓，鄭曲歸時美盛宗。","摘句競推梁記室，談經今紹漢司農。","異聞不暇陳亢問，爾德無非是孝恭。"]', '["結束翩翩肯寡悰，早时强学已三冬。","鯉庭趍日通明訓，鄭曲归时美盛宗。","摘句競推梁記室，談經今紹漢司農。","異闻不暇陳亢问，爾德無非是孝恭。"]', '诗', 'shi', '', NULL, '送鄭灊判官歸冬寧 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ea049dd-1b91-44d0-bb6f-19dc44d80cf5', '經咸陽城', '經咸陽城', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["阿房宮盡客誰來，可惜連雲萬戶開。","秦地起爲千載業，楚兵焚作一場灰。","應知長者名終在，祇是生人意不迴。","何事暴成還暴廢，祖龍須死項須摧。"]', '["阿房宮尽客誰来，可惜連云万戶开。","秦地起爲千載業，楚兵焚作一場灰。","應知长者名終在，祇是生人意不迴。","何事暴成還暴廢，祖龙須死項須摧。"]', '诗', 'shi', '', NULL, '經咸陽城 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34231cba-faf4-4f7a-b513-dfee49d77392', '惠尼童子', '惠尼童子', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["慢眉童子語惺惺，實爲天主自有靈。","（「主」，嚴疑「生」之誤。","）可惜綠絲梳黛髻，枉將纖手把銅瓶。","低迴綩態傳師教，更學吳音誦梵經。","不似俗家諸姊妹，朝朝畫得兩蛾青。","。"]', '["慢眉童子語惺惺，實爲天主自有靈。","（「主」，嚴疑「生」之誤。","）可惜綠絲梳黛髻，枉將纖手把銅瓶。","低迴綩態傳師教，更学吳音誦梵經。","不似俗家諸姊妹，朝朝畫得兩蛾青。","。"]', '诗', 'shi', '', NULL, '惠尼童子 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93dcad5c-2441-4a22-a374-acda014cfede', '將之會稽先寄越中知友', '將之會稽先寄越中知友', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["三年此路卻迴頭，認得湖山是舊遊。","百里鏡中明月夜，萬重屏外碧雲秋。","竹林雨過誰家宅，楊葉風生河處樓。"]', '["三年此路卻迴头，認得湖山是旧游。","百里镜中明月夜，万重屏外碧云秋。","竹林雨過誰家宅，楊葉风生河处楼。"]', '诗', 'shi', '', NULL, '將之會稽先寄越中知友 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a439117-3395-4903-b072-f374ad69293b', '陪杭州郡使讌西湖亭', '陪杭州郡使讌西湖亭', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["小亭移宴近雲端，十里山圖馬上看。","青壁遠光凌鳥峻，碧湖深影鍳人寒。","詩成病愈生犀角，酒引嬌娃活牡丹。","歸去不須愁暮雨，高唐神女屬仙壇。"]', '["小亭移宴近云端，十里山圖马上看。","青壁远光凌鸟峻，碧湖深影鍳人寒。","诗成病愈生犀角，酒引嬌娃活牡丹。","归去不須愁暮雨，高唐神女屬仙壇。"]', '诗', 'shi', '', NULL, '陪杭州郡使讌西湖亭 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('823d933f-f5c4-40e0-9ee0-a00b5d01a8de', '杭州晚眺', '杭州晚眺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["萬仞危峯厭渺漫，碧雲梢上倚欄干。","雲橫海鴈天風夕，月照城鵶水霧寒。","行客待潮來遠渡，居人瞻火去平灘。","蕭條醉臥誰家笛，一曲《梁州》夢裏殘。"]', '["万仞危峯厭渺漫，碧云梢上倚欄干。","云橫海鴈天风夕，月照城鵶水霧寒。","行客待潮来远渡，居人瞻火去平灘。","蕭條醉臥誰家笛，一曲《梁州》梦裏殘。"]', '诗', 'shi', '', NULL, '杭州晚眺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7f728a4-49e4-4bdd-8bfc-f458f801caea', '彈琴謌', '彈琴謌', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["楚人玉琴怨聲苦，客欲聽時盡懷土。","別鶴朝辭滄海雲，悲風夜入瀟湘雨。","弄之不難聽者難，金徽冷冷流水寒。","一曲自然堪下淚，三山不忍向君彈。"]', '["楚人玉琴怨声苦，客欲听时尽懷土。","別鹤朝辞滄海云，悲风夜入瀟湘雨。","弄之不难听者难，金徽冷冷流水寒。","一曲自然堪下泪，三山不忍向君彈。"]', '诗', 'shi', '', NULL, '彈琴謌 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee111042-3c23-4324-9f94-200db76cf5cc', '射虎詞', '射虎词', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["高山路傍射虎兒，執弓走箭如星馳。","一夫中虎人所異，萬夫圍虎人不知。","崗頭少年羞弓箭，從此誓心休射虎。","更使山頭白額來，萬金懸賞如泥土。"]', '["高山路傍射虎兒，執弓走箭如星驰。","一夫中虎人所異，万夫圍虎人不知。","崗头少年羞弓箭，從此誓心休射虎。","更使山头白額来，万金懸賞如泥土。"]', '诗', 'shi', '', NULL, '射虎詞 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eeafd616-062e-4e3f-9242-cba2f69a10ba', '古鏡謌', '古镜謌', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["小兒行把街中劇，千年𥘴斗銅衣碧。","將金换得試磨看，俄見洞門深一尺。","夜深時出仰照天，二十八宿中相連。","青龍耀躍麟眼動，神鬼不敢當庭總之。","明朝擎出遊都市，一半狐狸落城死。"]', '["小兒行把街中劇，千年𥘴斗銅衣碧。","將金换得試磨看，俄见洞门深一尺。","夜深时出仰照天，二十八宿中相連。","青龙耀躍麟眼动，神鬼不敢當庭總之。","明朝擎出游都市，一半狐狸落城死。"]', '诗', 'shi', '', NULL, '古鏡謌 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d3d1cb6-94b8-401c-b450-182b2b5991b3', '開聖寺', '开聖寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["西去山門五里程，粉牌書字甚分明。","蕭帝壞陵深虎跡，廣師遺院閉松聲。","長廊畫剥僧形影，古壁塵昏客姓名。","何必更將空理遣，眼前人事已浮生。"]', '["西去山门五里程，粉牌书字甚分明。","蕭帝壞陵深虎跡，廣師遺院閉松声。","长廊畫剥僧形影，古壁塵昏客姓名。","何必更將空理遣，眼前人事已浮生。"]', '诗', 'shi', '', NULL, '開聖寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec876eb3-cb16-4e3e-8aee-053f3ebf1197', '偶題', '偶題', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["微風和暖日鮮明，草色迷人向渭城。","越客捲簾閑不語，楚娥攀樹獨含情。","紅垂菓蔕櫻珠重，黃點花鬢粉蝶輕。","（「鬢」，嚴疑「鬚」之誤。","）自是青樓無近信，莫將心事問卿卿。"]', '["微风和暖日鲜明，草色迷人向渭城。","越客捲簾闲不語，楚娥攀樹独含情。","紅垂菓蔕櫻珠重，黄点花鬢粉蝶轻。","（「鬢」，嚴疑「鬚」之誤。","）自是青楼無近信，莫將心事问卿卿。"]', '诗', 'shi', '', NULL, '偶題 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86b72a41-0eff-4077-a4f6-8d308c5e339d', '曉別', '晓別', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["翠羽朱冠碧樹雞，未鳴先下短墻啼。","窗間謝女青蛾斂，門外蕭郎白馬嘶。","斜漢繁星當燭盡，淡煙殘月映花迷。","景陽宮裏晨鍾動，不語垂鞭上柳堤。","（《全唐詩》卷五七八作溫庭筠詩，題作《贈知音》。","別《才調集》卷二、《文苑英華》卷二八八亦作溫詩。","）。"]', '["翠羽朱冠碧樹雞，未鳴先下短墻啼。","窗间謝女青蛾斂，门外蕭郎白马嘶。","斜漢繁星當燭尽，淡煙殘月映花迷。","景陽宮裏晨鍾动，不語垂鞭上柳堤。","（《全唐诗》卷五七八作溫庭筠诗，題作《贈知音》。","別《才調集》卷二、《文苑英华》卷二八八亦作溫诗。","）。"]', '诗', 'shi', '', NULL, '曉別 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a94c00e-0a0e-4b8a-86de-93ecc4e572e3', '上元懷古', '上元懷古', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["倚雲宮闕已平蕪，東望連天到海隅。","文物六朝興廢地，江山萬里帝王都。","只聞丞相夷三族，不見扁舟泛五湖。","遥想永嘉南過日，洛陽風景盡歸吳。","。"]', '["倚云宮闕已平蕪，东望連天到海隅。","文物六朝兴廢地，江山万里帝王都。","只闻丞相夷三族，不见扁舟泛五湖。","遥想永嘉南過日，洛陽风景尽归吳。","。"]', '诗', 'shi', '', NULL, '上元懷古 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9060e332-b72c-421c-879d-90a710e40076', '隋堤懷古', '隋堤懷古', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["隋季窮兵復濬川，自爲猛虎可周旋。","錦帆東去不歸日，汴水西來無盡年。","本欲山河傳百二，誰知鍾鼎已三千。","那堪重問江都事，迴望空悲綠樹煙。"]', '["隋季窮兵复濬川，自爲猛虎可周旋。","錦帆东去不归日，汴水西来無尽年。","本欲山河傳百二，誰知鍾鼎已三千。","那堪重问江都事，迴望空悲綠樹煙。"]', '诗', 'shi', '', NULL, '隋堤懷古 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4351b470-b3b7-46a2-8329-1e450bac14bb', '洛陽春望', '洛陽春望', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["世事空悲衰復榮，慿音一望更添情。","紅顏只向愛中盡，芳草先從愁處生。","佳氣藹空迷鳯闕，綠楊抵水撓宮城。","（「撓」，嚴疑當作「繞」。","）遊執行駐馬煙花外，玉笛不利何處聲。"]', '["世事空悲衰复榮，慿音一望更添情。","紅顏只向愛中尽，芳草先從愁处生。","佳氣藹空迷鳯闕，綠楊抵水撓宮城。","（「撓」，嚴疑當作「繞」。","）游執行駐马煙花外，玉笛不利何处声。"]', '诗', 'shi', '', NULL, '洛陽春望 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db0a20c7-7a54-40c6-b0b7-4a6e8987bf97', '灞上送客', '灞上送客', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["自省論心意不疑，五年風水因追隨。","憐君有玉曾三獻，顧我無才忝一枝。","煙隔灞亭人去日，雨迷秦樹鴈歸時。","那知此夏罇前別，卻遣相如歎路歧。"]', '["自省論心意不疑，五年风水因追隨。","怜君有玉曾三獻，顧我無才忝一枝。","煙隔灞亭人去日，雨迷秦樹鴈归时。","那知此夏罇前別，卻遣相如歎路歧。"]', '诗', 'shi', '', NULL, '灞上送客 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69e15ebb-d824-4be9-a191-1a2d58d6240f', '經西溩偶題（按《全唐詩》卷五百七十七作溫庭筠詩，詩同，不重錄，校其異字如下：第二句「芳草無人情自迷」，《全唐詩》作「芳草無情人自迷」，是。四句「荇花唼喋青頭雞」，「荇」，「全唐詩」作「杏」，非。五句「微紅杏蔕惹蜂粉」，「杏」，《全唐詩》作「柰」。七句「借問含嚬向何許」，「許」，《全唐詩》作「事」，非。〖《文苑英華》卷一六一作溫詩。〗）', '經西溩偶題（按《全唐诗》卷五百七十七作溫庭筠诗，诗同，不重錄，校其異字如下：第二句「芳草無人情自迷」，《全唐诗》作「芳草無情人自迷」，是。四句「荇花唼喋青头雞」，「荇」，「全唐诗」作「杏」，非。五句「微紅杏蔕惹蜂粉」，「杏」，《全唐诗》作「柰」。七句「借问含嚬向何許」，「許」，《全唐诗》作「事」，非。〖《文苑英华》卷一六一作溫诗。〗）', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '經西溩偶題（按《全唐詩》卷五百七十七作溫庭筠詩，詩同，不重錄，校其異字如下：第二句「芳草無人情自迷」，《全唐詩》作「芳草無情人自迷」，是。四句「荇花唼喋青頭雞」，「荇」，「全唐詩」作「杏」，非。五句「微紅杏蔕惹蜂粉」，「杏」，《全唐詩》作「柰」。七句「借問含嚬向何許」，「許」，《全唐詩》作「事」，非。〖《文苑英華》卷一六一作溫詩。〗） 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73d9da07-8db0-416e-a855-300d77d61ac6', '喜聞收復河隴', '喜闻收复河隴', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["詔書頻降盡論邊，將擇英雄相卜賢。","河隴已耕曾歿（陳九思同志疑當作「沒」。","）地，犬羊誰辯却朝天。","高懸日月胡沙外，遥拜旌旗漢壘前。","共感垂衣匡濟力，華夷同見太平年。"]', '["詔书頻降尽論邊，將擇英雄相卜賢。","河隴已耕曾歿（陳九思同志疑當作「沒」。","）地，犬羊誰辯却朝天。","高懸日月胡沙外，遥拜旌旗漢壘前。","共感垂衣匡濟力，华夷同见太平年。"]', '诗', 'shi', '', NULL, '喜聞收復河隴 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d456ab8d-32f2-4264-af12-6d2179ffc822', '冬日幷州道中寄荆門舍', '冬日幷州道中寄荆门舍', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["聖明神武尚營邊，我是何人不控弦。","身着貂裘隨十萬，心思白社隔三千。","雲沉古戍初寒日，鴈下平陂欲雪天。","却爲恩深歸未得，許隨車騎勒燕然。"]', '["聖明神武尚營邊，我是何人不控弦。","身着貂裘隨十万，心思白社隔三千。","云沉古戍初寒日，鴈下平陂欲雪天。","却爲恩深归未得，許隨车騎勒燕然。"]', '诗', 'shi', '', NULL, '冬日幷州道中寄荆門舍 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d1e7af7-f861-47f8-aa63-0d8417c818fe', '和李子智魯中使院前鑿池種蘆之什', '和李子智魯中使院前鑿池種蘆之什', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["鑒地栽蘆貯碧流，臨軒一望似汀洲。","䓗籠好映淮南樹，疎野偏直海上鷗。","歷歷迎風欹枕曉，蕭蕭和雨捲簾秋。","君看范蠡功成公然上道煙波無去舟。","（見《全芳備祖後集》卷十二《蘆》，缺題。","）。"]', '["鑒地栽蘆貯碧流，臨軒一望似汀洲。","䓗籠好映淮南樹，疎野偏直海上鷗。","歷歷迎风欹枕晓，蕭蕭和雨捲簾秋。","君看范蠡功成公然上道煙波無去舟。","（见《全芳備祖後集》卷十二《蘆》，缺題。","）。"]', '诗', 'shi', '', NULL, '和李子智魯中使院前鑿池種蘆之什 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c83e8a1-2ad0-4df4-8dd0-59ddea35f906', '長安感懷', '长安感懷', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["家寄東吳西入秦，三年虛度帝城春。","流光漸漸到華髪，離恨蕭蕭生白蘋。","楚夢覺來愁翠被，越吟聲盡怨芳塵。","更聞玉笛吹明月，一曲風前淚滿巾。"]', '["家寄东吳西入秦，三年虛度帝城春。","流光漸漸到华髪，離恨蕭蕭生白蘋。","楚梦覺来愁翠被，越吟声尽怨芳塵。","更闻玉笛吹明月，一曲风前泪满巾。"]', '诗', 'shi', '', NULL, '長安感懷 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d335d30c-c543-4399-96b4-78eac60a598f', '題徐州流溝寺', '題徐州流溝寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["古寺層層結構勞，土岡前面峻如濠。","露雲竹翠石橋冷，風起松聲山殿高。","日色動廊開木槿，夜陰生院結蒲桃。","西龕禪客不相得，一片舊階行幾遭。","。"]', '["古寺層層結構勞，土岡前面峻如濠。","露云竹翠石橋冷，风起松声山殿高。","日色动廊开木槿，夜陰生院結蒲桃。","西龕禪客不相得，一片旧階行幾遭。","。"]', '诗', 'shi', '', NULL, '題徐州流溝寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('642342b4-871b-441e-92eb-d34c02ae3483', '貧居遣憤', '貧居遣憤', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["築室枕隋流，貧居喜自由。","未爲齊國悲，争免魯人丘。","不畏長堪恥，無成久更羞。","家須男子繼，國合丈夫憂。","苟利他相與，誅當我自求。","輪迴飜礙直，劒折却思柔。","老虎終開眼，微蟲會叩頭。","但令吾舌在，何畏不封侯。"]', '["築室枕隋流，貧居喜自由。","未爲齊国悲，争免魯人丘。","不畏长堪恥，無成久更羞。","家須男子繼，国合丈夫憂。","苟利他相與，誅當我自求。","輪迴飜礙直，劒折却思柔。","老虎終开眼，微蟲會叩头。","但令吾舌在，何畏不封侯。"]', '诗', 'shi', '', NULL, '貧居遣憤 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('852966ee-e24a-40e8-be08-f9b7987aec6d', '題弋陽徐明府水亭', '題弋陽徐明府水亭', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["小邑不勞賢，心期勝地偏。","樹微青嶂聳，沙淺碧波旋。","盪槳投昏岸，燒燔指濕煙。","板簷傍眺寺，石路上登舡。","水檻推衣浴，風軒側枕眠。","無因長寄此，吟和酒中仙。"]', '["小邑不勞賢，心期勝地偏。","樹微青嶂聳，沙淺碧波旋。","盪槳投昏岸，燒燔指濕煙。","板簷傍眺寺，石路上登舡。","水檻推衣浴，风軒側枕眠。","無因长寄此，吟和酒中仙。"]', '诗', 'shi', '', NULL, '題弋陽徐明府水亭 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7d635b2-178e-4e6a-8bce-8a4cab75e2fa', '題靈巖寺', '題靈巖寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["北寺三年別，西湖十里程。","山門橋上轉，石路閣中行。","地入千重險，江分一面平。","引藤聞鼠亂，窺洞見龍驚。","嶂月排簷出，屏風倚檻成。","猿尋青壁過，樹遶碧崖生。","小殿靈雲影，高廊下水聲。","何當還夢謝，盡我一詩情。"]', '["北寺三年別，西湖十里程。","山门橋上轉，石路閣中行。","地入千重險，江分一面平。","引藤闻鼠亂，窺洞见龙驚。","嶂月排簷出，屏风倚檻成。","猿尋青壁過，樹遶碧崖生。","小殿靈云影，高廊下水声。","何當還梦謝，尽我一诗情。"]', '诗', 'shi', '', NULL, '題靈巖寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58c8a928-d5a2-47b1-a798-ab2dfae569f2', '題天竺寺', '題天竺寺', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["臺殿聳高摽，鐘聲下小子遥。","路分松到寺，山斷石爲橋。","引水穿廊去，呼猿繞檻眺。","海明初上月，法白正來潮。","夏雨蓮苞破，秋風桂子彫。","（「夏雨」二句，《嘉泰會稽志》卷九引。","《全唐詩》卷五一一據《海錄碎事》收入。","）亂雲行沒脚，欹樹過低腰。","嫩綠茶新焙，乾黃竹旋燒。","唯思閑事了，長此臥煙霄。","。"]', '["台殿聳高摽，鐘声下小子遥。","路分松到寺，山斷石爲橋。","引水穿廊去，呼猿繞檻眺。","海明初上月，法白正来潮。","夏雨蓮苞破，秋风桂子彫。","（「夏雨」二句，《嘉泰會稽志》卷九引。","《全唐诗》卷五一一據《海錄碎事》收入。","）亂云行沒脚，欹樹過低腰。","嫩綠茶新焙，乾黄竹旋燒。","唯思闲事了，长此臥煙霄。","。"]', '诗', 'shi', '', NULL, '題天竺寺 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c222379-ec1f-4db6-8139-3beacfee795c', '讀韓文公集十韻', '读韓文公集十韻', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["天縱韓公愈，才爲出世英。","言前風自正，筆下意先萌。","塵土曾無跡，波瀾不可名。","詞高碑益顯，疏直事終明。","片段隨冰釋，絲毫入鏡清。","文彫玉璽重，詩織錦梭輕。","別得春王旨，深㳂《大雅》情。","窮奇開蜀道，詭恠哭秦坑。","驥逸終難襲，鵰蹲力更生。","誰當死後者，別爲破規程。"]', '["天縱韓公愈，才爲出世英。","言前风自正，笔下意先萌。","塵土曾無跡，波瀾不可名。","词高碑益显，疏直事終明。","片段隨冰釋，絲毫入镜清。","文彫玉璽重，诗织錦梭轻。","別得春王旨，深㳂《大雅》情。","窮奇开蜀道，詭恠哭秦坑。","驥逸終难襲，鵰蹲力更生。","誰當死後者，別爲破規程。"]', '诗', 'shi', '', NULL, '讀韓文公集十韻 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c553821-94d7-4c7e-84b8-10cc3d8c9c2d', '題岳州徐員外雲夢新亭十韻', '題岳州徐員外云梦新亭十韻', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["古地摽圖籍，新亭建梓材。","水從三峽漲，人自九江來。","宿涵曹推遠，停驂謝喜陪。","山形連岳去，草色盡天迴。","晚檻高牆出，晴郊古戍開。","陽精動金礦，暗魄孕珠胎。","竹换經冬葉，松移帶雨栽。","夜深南浦鴈，春老北枝梅。","山峴嶺功初畢，汀洲詠幾裁。","仙遊秪斯在，何用便蓬萊。","。"]', '["古地摽圖籍，新亭建梓材。","水從三峽漲，人自九江来。","宿涵曹推远，停驂謝喜陪。","山形連岳去，草色尽天迴。","晚檻高牆出，晴郊古戍开。","陽精动金礦，暗魄孕珠胎。","竹换經冬葉，松移带雨栽。","夜深南浦鴈，春老北枝梅。","山峴嶺功初畢，汀洲詠幾裁。","仙游秪斯在，何用便蓬萊。","。"]', '诗', 'shi', '', NULL, '題岳州徐員外雲夢新亭十韻 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e25d279-b3ea-4c2e-a34d-714a42830450', '吳中懷古十六韻', '吳中懷古十六韻', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["萬里江連蜀，千山水占吳。","地形分楚塞，舟路控閩隅。","西北京華遠，東南王氣無。","未爲勾踐入，先是子胥殂。","國破重泉恨，天迷兆庶乎。","黑煙宗廟廢，紅艷美人駈。","舊戰儲宮盡，新加太宰誅。","拆言江北死，羞面角東途。","假僨屍猶泊，教懸骨未枯。","墮釵殘玉鷰，穿墓得金鳧。","苑樹深行鹿，閶門逈噪烏。","夜陰生越絕，秋色遍姑蘇。","羣邑空遺跡，山川是廢圖。","六朝人已去，三國事應殊。","欲下金陵泣，還爲建業吁。","傷心此時意，狂乞賴麻襦。","（本卷均見南宋蜀刻本《張承吉文集》卷九。","）。"]', '["万里江連蜀，千山水占吳。","地形分楚塞，舟路控閩隅。","西北京华远，东南王氣無。","未爲勾踐入，先是子胥殂。","国破重泉恨，天迷兆庶乎。","黑煙宗廟廢，紅艷美人駈。","旧戰儲宮尽，新加太宰誅。","拆言江北死，羞面角东途。","假僨屍猶泊，教懸骨未枯。","墮釵殘玉鷰，穿墓得金鳧。","苑樹深行鹿，閶门逈噪烏。","夜陰生越絕，秋色遍姑蘇。","羣邑空遺跡，山川是廢圖。","六朝人已去，三国事應殊。","欲下金陵泣，還爲建業吁。","傷心此时意，狂乞賴麻襦。","（本卷均见南宋蜀刻本《張承吉文集》卷九。","）。"]', '诗', 'shi', '', NULL, '吳中懷古十六韻 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad67dcea-a2e9-4f1b-86d8-37197b2522b3', '和岳州徐員外雲夢新亭二十韻', '和岳州徐員外云梦新亭二十韻', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["澤國連荒徼，津亭揭上游。","飛欄控乾馬，却住壓坤牛。","（「却住」，嚴疑應作「却柱」。","）滉漭吞何處，青蒼別幾州。","黑天三伏裏，紅日五更頭。","樹失湘潭髪，山明楚塞漚。","舜巡初此去，禹鑿向南休。","白氣都爲曉，清光別是秋。","雨行神女過，雲降帝妃遊。","接鑑凌星斗，褰簾就月鈎。","草煙凝夜思，花露滴春愁。","近渚延沙濕，中壖小島浮。","竹尋諸洞遍，石占一泉幽。","日復上山頂，波連歸客舟。","招𩲑宋餘恨，吊死屈何投。","臣子悲遷斥，王孫念去留。","林當藏漢道，兵昔益巴丘。","縛將高皇策，燒舡太祖羞。","星霜人自變，江漢事長流。","勝景離方絕，功符坎德優。","還因望京意，歌詠爲皇猷。"]', '["澤国連荒徼，津亭揭上游。","飞欄控乾马，却住壓坤牛。","（「却住」，嚴疑應作「却柱」。","）滉漭吞何处，青蒼別幾州。","黑天三伏裏，紅日五更头。","樹失湘潭髪，山明楚塞漚。","舜巡初此去，禹鑿向南休。","白氣都爲晓，清光別是秋。","雨行神女過，云降帝妃游。","接鑑凌星斗，褰簾就月鈎。","草煙凝夜思，花露滴春愁。","近渚延沙濕，中壖小島浮。","竹尋諸洞遍，石占一泉幽。","日复上山頂，波連归客舟。","招𩲑宋餘恨，吊死屈何投。","臣子悲遷斥，王孫念去留。","林當藏漢道，兵昔益巴丘。","縛將高皇策，燒舡太祖羞。","星霜人自变，江漢事长流。","勝景離方絕，功符坎德優。","還因望京意，歌詠爲皇猷。"]', '诗', 'shi', '', NULL, '和岳州徐員外雲夢新亭二十韻 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc87d881-d4b2-46a4-baa6-923814fddd96', '投陳許崔尚書二十韻', '投陳許崔尚书二十韻', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["重鎮壓華戎，恩威達聖聰。","泰山高不讓，滄海闊難窮。","接物懽盈貌，安民術在衷。","旱天雲出水，霜野鶚摶風。","東土承殊渥，南方著顯功。","瑞呈須是鳯，畋獲必非熊。","令下齊軍仵，詩傳入帝宮。","春行膏雨降，夜仰德星藂。","翰苑推詞敏，台庭揖道崇。","才周儒學外，禮厚笑譚中。","吏理今廉度，文章昔馬融。","行慿孤竹立，諾爲一言終。","揭檻樓臺聳，加籩海陸豐。","俯移青玉案，高掛綠沉弓。","大幕賓名瑀，長裾客姓馮。","耻爲狂狷者，強廁滑稽雄。","馬足虛行地，鞭頭漫畫空。","無能甘畫虎，失趣奈雕蟲。","死歎身何處，生嗟命不通。","聊當問詹尹，猶許訴明公。"]', '["重鎮壓华戎，恩威達聖聰。","泰山高不讓，滄海闊难窮。","接物懽盈貌，安民術在衷。","旱天云出水，霜野鶚摶风。","东土承殊渥，南方著显功。","瑞呈須是鳯，畋獲必非熊。","令下齊軍仵，诗傳入帝宮。","春行膏雨降，夜仰德星藂。","翰苑推词敏，台庭揖道崇。","才周儒学外，禮厚笑譚中。","吏理今廉度，文章昔马融。","行慿孤竹立，諾爲一言終。","揭檻楼台聳，加籩海陸豐。","俯移青玉案，高掛綠沉弓。","大幕賓名瑀，长裾客姓馮。","耻爲狂狷者，強廁滑稽雄。","马足虛行地，鞭头漫畫空。","無能甘畫虎，失趣奈雕蟲。","死歎身何处，生嗟命不通。","聊當问詹尹，猶許訴明公。"]', '诗', 'shi', '', NULL, '投陳許崔尚書二十韻 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26d4f7cb-40e0-4523-96ff-6849a1572887', '酬房子客郊居六韻', '酬房子客郊居六韻', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["三畝田東竹一墟，習家深處自安居。","每逢山簡能騎馬，長羨王弘不賣魚。","南國煙帆低晚岸，北林霜葉墮寒蔬。","郡中舊指賢哉巷，門外多來長者車。","近日稍聞池盡墨，他時誰見壁藏書。","已知每提能携酒，同倚閶門四檻虛。"]', '["三畝田东竹一墟，習家深处自安居。","每逢山簡能騎马，长羨王弘不賣鱼。","南国煙帆低晚岸，北林霜葉墮寒蔬。","郡中旧指賢哉巷，门外多来长者车。","近日稍闻池尽墨，他时誰见壁藏书。","已知每提能携酒，同倚閶门四檻虛。"]', '诗', 'shi', '', NULL, '酬房子客郊居六韻 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b7490fe-c3d2-4907-837a-0c8b5e83befd', '觀潮十韻', '观潮十韻', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["泯泯順爲迴，泙泙逆是來。","草微淹澤莽，沙漲積雲堆。","不止靈威怒，當慿恠力推。","夏天江疊雪，晴日海奔雷。","近落痕猶淺，初平勢漸開。","舟驚浮浩渺，石看打崔嵬。","鳥下愁灘沒，人行畏岸頹。","鼓風連涵澹，值洑更旋迴。","進退隨蟾魄，虛盈合蚌胎。","何妨俾巨浸，爲爾濟川才。"]', '["泯泯順爲迴，泙泙逆是来。","草微淹澤莽，沙漲積云堆。","不止靈威怒，當慿恠力推。","夏天江叠雪，晴日海奔雷。","近落痕猶淺，初平勢漸开。","舟驚浮浩渺，石看打崔嵬。","鸟下愁灘沒，人行畏岸頹。","鼓风連涵澹，值洑更旋迴。","進退隨蟾魄，虛盈合蚌胎。","何妨俾巨浸，爲爾濟川才。"]', '诗', 'shi', '', NULL, '觀潮十韻 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('886e5d0d-ae10-431e-adf8-d66636854b43', '觀《山海圖》二首 其一', '观《山海圖》二首 其一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["古色辨微茫，華夷在一堂。","雲霞開藻井，天地出雕梁。","細草生毫末，輕風拂黛光。","夜山猶帶景，秋樹不凋霜。","隱竹纔分翠，穠華欲墮香。","無風帆自起，度日鳥空翔。","舟勢鯨吞久，樓形蜃吐長。","更看臺上鏡，造化落中央。"]', '["古色辨微茫，华夷在一堂。","云霞开藻井，天地出雕梁。","細草生毫末，轻风拂黛光。","夜山猶带景，秋樹不凋霜。","隐竹纔分翠，穠华欲墮香。","無风帆自起，度日鸟空翔。","舟勢鯨吞久，楼形蜃吐长。","更看台上镜，造化落中央。"]', '诗', 'shi', '', NULL, '觀《山海圖》二首 其一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('424f9a6e-8057-408b-91be-4942133d6609', '觀《山海圖》二首 其二', '观《山海圖》二首 其二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["何人筆思狂，一壁盡滄浪。","日月明丹拱，煙雲起畫梁。","山嵐開曉色，海氣動秋光。","島踞鰲睛大，沙行鰐齒長。","粉波明百越，黛點簇三湘。","詎作無圖意，空迷造化鄉。"]', '["何人笔思狂，一壁尽滄浪。","日月明丹拱，煙云起畫梁。","山嵐开晓色，海氣动秋光。","島踞鰲睛大，沙行鰐齒长。","粉波明百越，黛点簇三湘。","詎作無圖意，空迷造化乡。"]', '诗', 'shi', '', NULL, '觀《山海圖》二首 其二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c15a3482-9915-40be-a533-ea5ad8d4381c', '題海陵監李端公後亭十韻', '題海陵監李端公後亭十韻', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["古城連廢地，規畫自初心。","眺出紅亭址，裁成綠樹林。","竹欹叢岸勢，池滿到簷陰。","暗草通溪遠，閑花落院深。","上簾新鷰入，拋葉小魚沉。","晚影移罇惜，殘芳秉燭尋。","風蘭曳衣繡，露柳柫頭簪。","屬詠聊題極，垂竿旋屈針。","短橋多凭看，高堞幾登臨。","漫廁賓階末，無因和至音。"]', '["古城連廢地，規畫自初心。","眺出紅亭址，裁成綠樹林。","竹欹叢岸勢，池满到簷陰。","暗草通溪远，闲花落院深。","上簾新鷰入，拋葉小鱼沉。","晚影移罇惜，殘芳秉燭尋。","风蘭曳衣繡，露柳柫头簪。","屬詠聊題極，垂竿旋屈針。","短橋多凭看，高堞幾登臨。","漫廁賓階末，無因和至音。"]', '诗', 'shi', '', NULL, '題海陵監李端公後亭十韻 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ae06bee-e8ad-4a7d-abbd-f22b890d2f4b', '題江陵崔兵曹林亭', '題江陵崔兵曹林亭', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["小隱蜀江邊，重巒盡一川。","山形分斷岸，水勢盡平田。","嫩碧生欄淺，輕紅落砌蔫。","短橋扶竹過，欹路把藤緣。","南巷纖埃隔，東郊遠思延。","月庭潛潤石，風渚自移舡。","滴露蒲光冷，摇波柳翠鮮。","關心每來勝，幸爾必相然。","。"]', '["小隐蜀江邊，重巒尽一川。","山形分斷岸，水勢尽平田。","嫩碧生欄淺，轻紅落砌蔫。","短橋扶竹過，欹路把藤緣。","南巷纖埃隔，东郊远思延。","月庭潛潤石，风渚自移舡。","滴露蒲光冷，摇波柳翠鲜。","关心每来勝，幸爾必相然。","。"]', '诗', 'shi', '', NULL, '題江陵崔兵曹林亭 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d140e14-2712-48ed-86ba-33f5abb15921', '題宿州城西宋徵君林亭', '題宿州城西宋徵君林亭', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["數畝四郊地，紐帶勝漸偏。","磴崖欹入竹，筒水下澆田。","黑壤霑河潤，紅葩寄樹鮮。","驛明昏岸火，檣插曉林煙。","嫩笋撑簷曲，新荷帖沼圓。","不妨成隱顯，長日步通阡。"]', '["數畝四郊地，紐带勝漸偏。","磴崖欹入竹，筒水下澆田。","黑壤霑河潤，紅葩寄樹鲜。","驛明昏岸火，檣插晓林煙。","嫩笋撑簷曲，新荷帖沼圓。","不妨成隐显，长日步通阡。"]', '诗', 'shi', '', NULL, '題宿州城西宋徵君林亭 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c98078a0-ace6-4b84-aaf9-d25914d4accd', '題泗州劉中丞郡中新樓。', '題泗州劉中丞郡中新楼。', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["一檻構庭上，臨川望益崇。","朗懷披夏日，高嘯得清風。","紫府須黃霸，青山屬謝公。","夜聲聞動草，春意覺抽叢。","野迥雲初白，天寒樹間紅。","月華深委素，淮色逈流空。","暮雨佳人到，良辰樂事同。","更憐初渡水，先詠子來工。"]', '["一檻構庭上，臨川望益崇。","朗懷披夏日，高嘯得清风。","紫府須黄霸，青山屬謝公。","夜声闻动草，春意覺抽叢。","野迥云初白，天寒樹间紅。","月华深委素，淮色逈流空。","暮雨佳人到，良辰乐事同。","更怜初渡水，先詠子来工。"]', '诗', 'shi', '', NULL, '題泗州劉中丞郡中新樓。 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afa2c29f-abc4-49f1-b054-954ce8ad73c2', '奉和湖州蘇員外題游柸池', '奉和湖州蘇員外題游柸池', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["舊勝因金剎，新遷就水堂。","何勞數爵筭，不止一龜航。","忝座非珎席，窮源喜濫觴。","酒醲開若醖，詩妙掇蘋芳。","廣檻餘清景，連山疊霽光。","徒思繼高韻，益歎謬成章。"]', '["旧勝因金剎，新遷就水堂。","何勞數爵筭，不止一龟航。","忝座非珎席，窮源喜濫觴。","酒醲开若醖，诗妙掇蘋芳。","廣檻餘清景，連山叠霽光。","徒思繼高韻，益歎謬成章。"]', '诗', 'shi', '', NULL, '奉和湖州蘇員外題游柸池 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05f9c1ae-7fb1-4d58-b558-0211feb466bb', '奉和浙西盧大夫題假山', '奉和浙西盧大夫題假山', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["入門驚秀崪，規畫自奇人。","遠不離堦砌，高寧讓隙塵。","巖成須夢說，岳就合生申。","掩映深尤妙，踈通久更新。","聊思峴嶺日，小認會稽春。","好是怡情處，西樓長景真。"]', '["入门驚秀崪，規畫自奇人。","远不離堦砌，高寧讓隙塵。","巖成須梦说，岳就合生申。","掩映深尤妙，踈通久更新。","聊思峴嶺日，小認會稽春。","好是怡情处，西楼长景真。"]', '诗', 'shi', '', NULL, '奉和浙西盧大夫題假山 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c477b22-0ef3-48ee-86d4-b9403d805cb6', '越州懷古', '越州懷古', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["振檝大江東，前林波萬頃。","高秋海天闊，色落湖山影。","行尋王謝迹，望望登絕嶺。","荒林草木瘦，古樹泉石冷。","昔游不可見，牢落餘風景。","窮愁心未死，一筆聊復秉。","。"]', '["振檝大江东，前林波万頃。","高秋海天闊，色落湖山影。","行尋王謝迹，望望登絕嶺。","荒林草木瘦，古樹泉石冷。","昔游不可见，牢落餘风景。","窮愁心未死，一笔聊复秉。","。"]', '诗', 'shi', '', NULL, '越州懷古 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6a68d36-0253-4ad1-b072-188bac2f1ca6', '晚下彭澤', '晚下彭澤', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["斜日照鳥當，（「鳥當」，嚴疑當作「馬當」。","）孤舟下彭澤。","平分江九派，斂度山一壁。","淺浦橫黑查，高林間白石。","帆收天益暝，鳥沒嵐更碧。","依依戍前鼓，稍稍村外笛。","何處上面眠人，月明西楚客。"]', '["斜日照鸟當，（「鸟當」，嚴疑當作「马當」。","）孤舟下彭澤。","平分江九派，斂度山一壁。","淺浦橫黑查，高林间白石。","帆收天益暝，鸟沒嵐更碧。","依依戍前鼓，稍稍村外笛。","何处上面眠人，月明西楚客。"]', '诗', 'shi', '', NULL, '晚下彭澤 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20048999-ed26-4905-aed8-8eaacb0f0bac', '游仙', '游仙', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["赤足一仙翁，耳毫垂兩頸。","摩娑雪毛項，騎上崑崙頂。","顧我踨鹿蹄，去遊遐寂境。","洞門出昏黑，却望如側井。","行折青桂枝，隔雲敲石屏。","空巖響深徹，臺觀凝碧冷。","風觸瓊樹花，動摇天水影。","端衣禮真貌，心目明耿耿。","願侶牧羊兒，休休在崖嶺。"]', '["赤足一仙翁，耳毫垂兩頸。","摩娑雪毛項，騎上崑崙頂。","顧我踨鹿蹄，去游遐寂境。","洞门出昏黑，却望如側井。","行折青桂枝，隔云敲石屏。","空巖响深徹，台观凝碧冷。","风觸瓊樹花，动摇天水影。","端衣禮真貌，心目明耿耿。","願侶牧羊兒，休休在崖嶺。"]', '诗', 'shi', '', NULL, '游仙 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('105e186b-9ce9-46a8-a184-7412aa966c3b', '寓言', '寓言', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["江海一遺叟，塊然窮巷居。","門前是川陸，反背臥枕袪。","興來座援琴，忽忽味《關雎》。","但願致樽酒，豈憂無斗儲。","野牧亦乘馬，家池還釣魚。","偶思榮啓期，益喜鬢白初。","日夕粗充飢，呼兒掇園蔬。","行登逸民舟，坐愧長者車。","倐值體中佳，未嘗廢三餘。","理生且自昧，安忍限衆徂。","屏迹豈無素，立誠非甚踈。","杜門草《太玄》，落草賦《子虛》。","大賈傾十萬，一名終不書。","小人苟片善，言下輙紀渠。","不然少年長，百萬看一樗。","過此任老圃，笑歌立倚鋤。","道門演空言，未必死錄除。"]', '["江海一遺叟，塊然窮巷居。","门前是川陸，反背臥枕袪。","兴来座援琴，忽忽味《关雎》。","但願致樽酒，豈憂無斗儲。","野牧亦乘马，家池還釣鱼。","偶思榮啓期，益喜鬢白初。","日夕粗充飢，呼兒掇园蔬。","行登逸民舟，坐愧长者车。","倐值體中佳，未嘗廢三餘。","理生且自昧，安忍限衆徂。","屏迹豈無素，立誠非甚踈。","杜门草《太玄》，落草賦《子虛》。","大賈傾十万，一名終不书。","小人苟片善，言下輙紀渠。","不然少年长，百万看一樗。","過此任老圃，笑歌立倚鋤。","道门演空言，未必死錄除。"]', '诗', 'shi', '', NULL, '寓言 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('119155b5-27ae-4d3a-9123-a9697b04bf06', '題池州杜員外弄水新亭', '題池州杜員外弄水新亭', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["廣廈光奇輩，恢材卓不羣。","夏天平岸水，春雨近山雲。","婉衍榱甍揭，端完柱石分。","孤帆驚乍駐，一葉動初聞。","晚檻餘清景，涼軒啓碧氛。","賓筵習主簿，詩版鮑參軍。","露灑新篁滴，風含秀落葉松薰。","何勞思峴嶺，虛望漢江濱。"]', '["廣廈光奇輩，恢材卓不羣。","夏天平岸水，春雨近山云。","婉衍榱甍揭，端完柱石分。","孤帆驚乍駐，一葉动初闻。","晚檻餘清景，涼軒啓碧氛。","賓筵習主簿，诗版鲍參軍。","露灑新篁滴，风含秀落葉松薰。","何勞思峴嶺，虛望漢江濱。"]', '诗', 'shi', '', NULL, '題池州杜員外弄水新亭 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7977676-d92c-4ff9-a9c6-254090d87cb7', '戊午年寓興二十韻', '戊午年寓兴二十韻', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["大道開王室，辛勤自賈生。","白衣逢聖主，青眼賴時英。","一路來邊海，三年別上京。","淚因南國盡，心向北辰傾。","咄咄中途事，栖栖此日行。","登封期未卜，弔汩恨空盈。","謫見天何再，勤憂詔未幷。","漢胡當重理，魏相昔權兵。","《葛藟》機尤巧，《鴟鶚》義可精。","（「鴟鶚」當作「鴟鴞」。","）舊恩移保傳，初論激公卿。","後學稽前古，先儒制未萌。","朱雲曾痛憤，劉向幾吞聲。","日月今纔朗，煙塵久未清。","詎聞高鳥盡，終俟小鮮烹。","坦坦前王道，雄雄近世名。","帝圖殷太甲，人鏡魏文貞。","逸足期千里，窮鱗渴一泓。","徵賢寧乏詔，進善豈無旌。","狡兔當寒伏，荒雞半夜鳴。","殷勤在伊呂，爲我致昇平。"]', '["大道开王室，辛勤自賈生。","白衣逢聖主，青眼賴时英。","一路来邊海，三年別上京。","泪因南国尽，心向北辰傾。","咄咄中途事，栖栖此日行。","登封期未卜，弔汩恨空盈。","謫见天何再，勤憂詔未幷。","漢胡當重理，魏相昔權兵。","《葛藟》機尤巧，《鴟鶚》義可精。","（「鴟鶚」當作「鴟鴞」。","）旧恩移保傳，初論激公卿。","後学稽前古，先儒制未萌。","朱云曾痛憤，劉向幾吞声。","日月今纔朗，煙塵久未清。","詎闻高鸟尽，終俟小鲜烹。","坦坦前王道，雄雄近世名。","帝圖殷太甲，人镜魏文貞。","逸足期千里，窮鱗渴一泓。","徵賢寧乏詔，進善豈無旌。","狡兔當寒伏，荒雞半夜鳴。","殷勤在伊呂，爲我致昇平。"]', '诗', 'shi', '', NULL, '戊午年寓興二十韻 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fee1d418-d1c1-44c1-9707-d89ab86bc120', '投陳許李司空二十韻', '投陳許李司空二十韻', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["上將出東征，驊騮得路行。","青雲仰高步，白日見精誠。","朗抱韜羣物，沉思活庶氓，田文今得士，孫武舊能兵。","曉月當樓色，秋鞞入地聲。","鬼神愁運思，姦猾恐迴情。","破敵連收柵，屯師立下城。","龍觀淮甸虎，鱣視海湄鯨。","勇冠臨危貌，勳崇定遠名。","突圍親斬首，開道看擒生。","陳變虵頭出，槍迴豹尾橫。","束衣金甲冷，揮箭鐵鞭鳴。","歷戰長諸葛，封侯小富平。","去淮初五馬，遷滑再雙旌。","道秪蕭何直。","功惟范蠡成。","感恩懷敢炙，知味渴和羹。","曙閤銅牌入，昏堂蠟燭明。","玉鈎紅袖把，銀注紫衣擎。","接坐羞人識，還家畏嫂輕。","猶希匹夫膽，一向信陵傾。"]', '["上將出东征，驊騮得路行。","青云仰高步，白日见精誠。","朗抱韜羣物，沉思活庶氓，田文今得士，孫武旧能兵。","晓月當楼色，秋鞞入地声。","鬼神愁運思，姦猾恐迴情。","破敵連收柵，屯師立下城。","龙观淮甸虎，鱣視海湄鯨。","勇冠臨危貌，勳崇定远名。","突圍親斬首，开道看擒生。","陳变虵头出，槍迴豹尾橫。","束衣金甲冷，揮箭鐵鞭鳴。","歷戰长諸葛，封侯小富平。","去淮初五马，遷滑再雙旌。","道秪蕭何直。","功惟范蠡成。","感恩懷敢炙，知味渴和羹。","曙閤銅牌入，昏堂蠟燭明。","玉鈎紅袖把，銀注紫衣擎。","接坐羞人識，還家畏嫂轻。","猶希匹夫膽，一向信陵傾。"]', '诗', 'shi', '', NULL, '投陳許李司空二十韻 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('458bc439-8f42-428b-8160-d9898d764176', '投魏博田司空二十韻', '投魏博田司空二十韻', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["聖代倚龍驤，青油鎮北方。","國除心腹病，時詠股肱良。","兆栛周畋吉，言應禹拜昌。","中台初復位，太白定揚光。","傳癖深元凱，籌謀奧子房。","率先供帝命，特地舉朝綱。","吏改新曹局，民耕舊戰場。","節旌窮海島，詩句起河梁。","幕府推賢佐，杯盤任客狂。","峯巒資秀崪，鵰鶚避軒昂。","列座花茵展，鳴鼉錦臂攘。","小旗鞍馬令，尖帽柘枝娘。","掃路麾幢出，開衙斧鉞行。","旌旗垂玳瑁，黃帕結鴛鴦。","報主親臨敵，屯師首犯彊。","裂紅偷賊號，纏褐眩戎裝。","夜柵迴千馬，昏鼙亞萬鎗。","桉聲鋪陣血。","垂淚撫刀瘡。","豹望因文變，鯤期假翅翔。","空勞千里役，何策利梁王。"]', '["聖代倚龙驤，青油鎮北方。","国除心腹病，时詠股肱良。","兆栛周畋吉，言應禹拜昌。","中台初复位，太白定揚光。","傳癖深元凱，籌謀奧子房。","率先供帝命，特地舉朝綱。","吏改新曹局，民耕旧戰場。","節旌窮海島，诗句起河梁。","幕府推賢佐，杯盤任客狂。","峯巒資秀崪，鵰鶚避軒昂。","列座花茵展，鳴鼉錦臂攘。","小旗鞍马令，尖帽柘枝娘。","掃路麾幢出，开衙斧鉞行。","旌旗垂玳瑁，黄帕結鴛鴦。","報主親臨敵，屯師首犯彊。","裂紅偷賊號，纏褐眩戎裝。","夜柵迴千马，昏鼙亞万鎗。","桉声鋪陣血。","垂泪撫刀瘡。","豹望因文变，鯤期假翅翔。","空勞千里役，何策利梁王。"]', '诗', 'shi', '', NULL, '投魏博田司空二十韻 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb69e2a6-91d2-4816-bab1-40c9fab7fa5b', '投魏博李相國三十二韻', '投魏博李相国三十二韻', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["天意兆昇平，忠良自間生。","二年移四鎮，一夜破重城。","白刃來臨敵，青油引出京。","指途諳老馬，望海哂長鯨。","國用鞭頭筭，軍機帳下萌。","王師初戮力，賊將首推誠。","鼎鼐傳家世，藩隅易弟兄。","風雲將氣合，才命與時幷。","咳唾收齊土，瘡痍肓蔡甿。","指撝從上策，談笑賴高情。","發號方迴踵，歸農務散兵。","紫微纔近侍，彤矢又專征。","曲直須繩準，幽深藉鏡明。","曉江流汗漫，秋華聳崢嶸。","士勇思陳力，兒啼畏道名。","文王開卦兆，武帝下星精。","遠寄恩彌厚，深欺敵不勍。","儉風敦制度，和氣茂逢迎。","畫障朱軒設，蠻刀粉壁橫。","木魚連錀動，金獸齒環獰。","舞席宮鬃出，賓盤海饌盈。","繡蹄紅毬臥，花領紫絛縈。","鵷鷺初移府，熊羆夜烈營。","（「烈」，嚴疑當作「列」。","）濟河無反顧，當陣必前行。","野迥朱旗卜，霜乾翠幕輕。","角吹寒日色，槍揭暑雷聲。","甯越身猶賤，馮煖膽未呈。","貴門心強迹，賢路力何爭。","閟手從拋劒，愁腸却賴觥。","寧依劉表死，不接賈充榮。","阻轍羞偏轂，蟠泥渴一泓。","應憐望塵眼，歧路拜雙旌。"]', '["天意兆昇平，忠良自间生。","二年移四鎮，一夜破重城。","白刃来臨敵，青油引出京。","指途諳老马，望海哂长鯨。","国用鞭头筭，軍機帳下萌。","王師初戮力，賊將首推誠。","鼎鼐傳家世，藩隅易弟兄。","风云將氣合，才命與时幷。","咳唾收齊土，瘡痍肓蔡甿。","指撝從上策，談笑賴高情。","發號方迴踵，归農務散兵。","紫微纔近侍，彤矢又專征。","曲直須繩準，幽深藉镜明。","晓江流汗漫，秋华聳崢嶸。","士勇思陳力，兒啼畏道名。","文王开卦兆，武帝下星精。","远寄恩彌厚，深欺敵不勍。","儉风敦制度，和氣茂逢迎。","畫障朱軒設，蠻刀粉壁橫。","木鱼連錀动，金獸齒环獰。","舞席宮鬃出，賓盤海饌盈。","繡蹄紅毬臥，花領紫絛縈。","鵷鷺初移府，熊羆夜烈營。","（「烈」，嚴疑當作「列」。","）濟河無反顧，當陣必前行。","野迥朱旗卜，霜乾翠幕轻。","角吹寒日色，槍揭暑雷声。","甯越身猶賤，馮煖膽未呈。","貴门心強迹，賢路力何爭。","閟手從拋劒，愁腸却賴觥。","寧依劉表死，不接賈充榮。","阻轍羞偏轂，蟠泥渴一泓。","應怜望塵眼，歧路拜雙旌。"]', '诗', 'shi', '', NULL, '投魏博李相國三十二韻 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0664d216-e289-4807-b27b-c5f15fbc5c19', '讀《西漢書》十四韻', '读《西漢书》十四韻', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["日月中華正，星辰上國偏，經綸今四海，討伐舊三邊。","失道非無素，乘時不偶然。","安劉機在早，誅呂計須權。","禮樂勝殘後，干戈止殺前。","未聞晁氏戮，初幸賈生緣。","善馬來何利，窮兵去甚堅。","國讎因破虜。","民耗是求仙。","忍憤中郎節，殘形太史編。","冲融當魏邴，靦衍自昭宣。","故老心徒切，先皇道益懸。","元成真漸地，哀少卒崩天。","七廟傾王莽，三公敗董賢。","興亡豈無誡，爲看借秦篇。"]', '["日月中华正，星辰上国偏，經綸今四海，討伐旧三邊。","失道非無素，乘时不偶然。","安劉機在早，誅呂計須權。","禮乐勝殘後，干戈止殺前。","未闻晁氏戮，初幸賈生緣。","善马来何利，窮兵去甚堅。","国讎因破虜。","民耗是求仙。","忍憤中郎節，殘形太史編。","冲融當魏邴，靦衍自昭宣。","故老心徒切，先皇道益懸。","元成真漸地，哀少卒崩天。","七廟傾王莽，三公敗董賢。","兴亡豈無誡，爲看借秦篇。"]', '诗', 'shi', '', NULL, '讀《西漢書》十四韻 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e8c7362-fba6-4e37-ae1a-7fd2ddc72799', '苦旱', '苦旱', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["河上勞兵地，江南酷旱天。","那知討邢日，不是尅殷年。","忽忽嗟時難，矜矜畏序愆。","雲徒蔽日月，雨合降山川。","造化爐思火，陰陽炭鼓煙。","披懷遭赤晝，濯足想清漣。","獄俟于公決，心期戴令虔。","敢忘霑霈澤，俁幸及私田。","請禱誠明矣，焚巫策昧然。","靈山罷齊景，美玉罄周宣。","石鷰曾誰舞，泥龍愈自堅。","魚窮悲涸轍，井漆奈枯泉。","五畝憂還軫，三時望益懸。","蹔欣垂滴瀝，終訝阻纏綿。","貶損心應懇，踈通稅必蠲。","乘軒嘗拯物，飲馬昔投錢。","火宅逢僧話，炎荒想客遷。","泥蟠尺蠖久，草長蒺藜先。","病體長兼慮，窮愁益自煎。","猶希畏途上，一詠凱歌旋。"]', '["河上勞兵地，江南酷旱天。","那知討邢日，不是尅殷年。","忽忽嗟时难，矜矜畏序愆。","云徒蔽日月，雨合降山川。","造化爐思火，陰陽炭鼓煙。","披懷遭赤晝，濯足想清漣。","獄俟于公決，心期戴令虔。","敢忘霑霈澤，俁幸及私田。","請禱誠明矣，焚巫策昧然。","靈山罷齊景，美玉罄周宣。","石鷰曾誰舞，泥龙愈自堅。","鱼窮悲涸轍，井漆奈枯泉。","五畝憂還軫，三时望益懸。","蹔欣垂滴瀝，終訝阻纏綿。","貶損心應懇，踈通稅必蠲。","乘軒嘗拯物，饮马昔投錢。","火宅逢僧話，炎荒想客遷。","泥蟠尺蠖久，草长蒺藜先。","病體长兼慮，窮愁益自煎。","猶希畏途上，一詠凱歌旋。"]', '诗', 'shi', '', NULL, '苦旱 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f576969d-9fb6-4fc0-9ad4-b2149b127bd4', '苦雨二十韻', '苦雨二十韻', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["積雨江城久，騰雲海嶠來。","暑當初縝絺，寒亦重然灰。","曖昧連中夏，調和仰上台。","地平天沒塹，舟利木兼材。","電影窗遙入，雷聲轍乍迴。","邊除深溢潦，枕簟去浮埃。","太陸青蘋泛，曾崖白浪豗。","初跳倒蛙黽，疾長半蒿萊。","壞壤虛爲穴，淙沙逈作堆。","未如歸結網，何憚渴操杯。","漏屋誠難葺，崩牆不易坯。","遠愁超滉瀁，高羨陟崔嵬。","俯祝陰靈遍，聊飡水物該。","病非宜長老，憂是主嬰孩。","淺淺斟茶鼎，環環盪酒罍。","濯枝憐鳥噤，流麥分人咍。","日色疑羞出，天心似惜開。","巨鱗承水使，纖介幸時災。","折角巾全委，低頭柱頓摧。","神龍曾未失，螻蟻莫相裁。"]', '["積雨江城久，腾云海嶠来。","暑當初縝絺，寒亦重然灰。","曖昧連中夏，調和仰上台。","地平天沒塹，舟利木兼材。","電影窗遙入，雷声轍乍迴。","邊除深溢潦，枕簟去浮埃。","太陸青蘋泛，曾崖白浪豗。","初跳倒蛙黽，疾长半蒿萊。","壞壤虛爲穴，淙沙逈作堆。","未如归結網，何憚渴操杯。","漏屋誠难葺，崩牆不易坯。","远愁超滉瀁，高羨陟崔嵬。","俯祝陰靈遍，聊飡水物該。","病非宜长老，憂是主嬰孩。","淺淺斟茶鼎，环环盪酒罍。","濯枝怜鸟噤，流麦分人咍。","日色疑羞出，天心似惜开。","巨鱗承水使，纖介幸时災。","折角巾全委，低头柱頓摧。","神龙曾未失，螻蟻莫相裁。"]', '诗', 'shi', '', NULL, '苦雨二十韻 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31cba378-c223-40d2-b9cf-811018999cf3', '陪楚州韋舍人北閶門遊宴', '陪楚州韋舍人北閶门游宴', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["柘岸齊空遠，通波跨檻牢。","四方人意便，兩路馬行高。","霧柳蒙疎葉，風帆掛並艘。","碧雲秋水靜，紅日暮霞韜。","苟藉公心度，稀逢敏手操。","舊恩重雨露，新命壓波濤。","挹海驚涯涘，冲霄訝羽毛。","絲綸初變體，錦袖旋揮毫。","美景尤難卜，良辰不易遭。","名華應獨步，語韻洽朋曹。","異日知司衮，閑時解夢刀。","卿材尊宦達，侯業重人豪。","拽盞憐稀飲，扶鞍哂遽逃。","香鳧深促坐，畫鷁遠迴篙。","賭氣連呼采，縻心乍漱醪。","俁妨孤憤激，肯忘一言褒。","北闕承優話，南方續廣騷。","不嘗書咄咄，誰話酒陶陶。","末路猶提筆，雄藩佇擁旄。","只愁迂蹇步，歸去又蓬蒿。"]', '["柘岸齊空远，通波跨檻牢。","四方人意便，兩路马行高。","霧柳蒙疎葉，风帆掛並艘。","碧云秋水静，紅日暮霞韜。","苟藉公心度，稀逢敏手操。","旧恩重雨露，新命壓波濤。","挹海驚涯涘，冲霄訝羽毛。","絲綸初变體，錦袖旋揮毫。","美景尤难卜，良辰不易遭。","名华應独步，語韻洽朋曹。","異日知司衮，闲时解梦刀。","卿材尊宦達，侯業重人豪。","拽盞怜稀饮，扶鞍哂遽逃。","香鳧深促坐，畫鷁远迴篙。","賭氣連呼采，縻心乍漱醪。","俁妨孤憤激，肯忘一言褒。","北闕承優話，南方續廣騷。","不嘗书咄咄，誰話酒陶陶。","末路猶提笔，雄藩佇擁旄。","只愁迂蹇步，归去又蓬蒿。"]', '诗', 'shi', '', NULL, '陪楚州韋舍人北閶門遊宴 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e078d89c-442a-496c-b12f-b69b15c815c2', '又陪楚州韋舍人閶門遊讌次韻北閶門', '又陪楚州韋舍人閶门游讌次韻北閶门', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["遠派通催急，層欄架柱牢。","中開一閤靜，外拔兩簷高。","㼘崪基崇岸，灣環隘近艘。","勁竿紅旆展，長鐙紫囊韜。","舊好千金諾，新題一筆操。","開懷侵月露，惜別話風濤。","盡納黃泥水，平分沼沚毛。","詩能拘咫寸，酒妙乏絲毫。","不止才無敵，非論運合遭。","宦情周上智，美論逸諸曹。","擬義臨戎鉞，從容宰社刀。","三千藂秀彦。","百萬舉名豪。","死士曾無悔，生民肯更逃。","下簾欣繼燭，歸路止排篙。","綵柚撩青鬢，金舡泛白醪。","韻慙高手壓。","文豈拙詞褒。","賈誼猶興歎，楊雄重返騷。","不當離急引，應獲在甄陶。","強逐騑騑駟，徒瞻孑孑旄。","何堪縱高祖，生意任庭蒿。"]', '["远派通催急，層欄架柱牢。","中开一閤静，外拔兩簷高。","㼘崪基崇岸，灣环隘近艘。","勁竿紅旆展，长鐙紫囊韜。","旧好千金諾，新題一笔操。","开懷侵月露，惜別話风濤。","尽納黄泥水，平分沼沚毛。","诗能拘咫寸，酒妙乏絲毫。","不止才無敵，非論運合遭。","宦情周上智，美論逸諸曹。","擬義臨戎鉞，從容宰社刀。","三千藂秀彦。","百万舉名豪。","死士曾無悔，生民肯更逃。","下簾欣繼燭，归路止排篙。","綵柚撩青鬢，金舡泛白醪。","韻慙高手壓。","文豈拙词褒。","賈誼猶兴歎，楊雄重返騷。","不當離急引，應獲在甄陶。","強逐騑騑駟，徒瞻孑孑旄。","何堪縱高祖，生意任庭蒿。"]', '诗', 'shi', '', NULL, '又陪楚州韋舍人閶門遊讌次韻北閶門 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3b41f79-cf5e-478d-8d4b-93bbbe994acb', '投太原李司空', '投太原李司空', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["煙塵繞北京，千里動人情。","位壓中華險，功排上將榮。","四方分萬石，三鎮擁雙旌。","大郡爲深寄，河湟仗素城。","雄才身挺拔，柱石勢映傾。","霍氏勳元重，胡家正本清。","殊恩酬義勇，積慶自忠貞。","海岱乘時出，風雲得氣生。","虎頭膺將號，龍額擅侯名。","麴蘗功歸酒，塩梅味到羹。","碧霄長日路，黃犬少年行。","號令誅旡軌，觀風審未萌。","物情周智用，賓禮盡逢迎。","促座杯心亞，開場鏡面平。","神隈旗幹動，虎占地衣獰。","紫綬分排馬，青娥亂替觥。","魚金垂重獺，羅袖拂毬輕。","暖閤朝呈簡，深簾夜按笙。","栖遑窮蔡澤，孱弱病劉楨。","試暗秦臺下，應迴照膽明。","。"]', '["煙塵繞北京，千里动人情。","位壓中华險，功排上將榮。","四方分万石，三鎮擁雙旌。","大郡爲深寄，河湟仗素城。","雄才身挺拔，柱石勢映傾。","霍氏勳元重，胡家正本清。","殊恩酬義勇，積慶自忠貞。","海岱乘时出，风云得氣生。","虎头膺將號，龙額擅侯名。","麴蘗功归酒，塩梅味到羹。","碧霄长日路，黄犬少年行。","號令誅旡軌，观风審未萌。","物情周智用，賓禮尽逢迎。","促座杯心亞，开場镜面平。","神隈旗幹动，虎占地衣獰。","紫綬分排马，青娥亂替觥。","鱼金垂重獺，羅袖拂毬轻。","暖閤朝呈簡，深簾夜按笙。","栖遑窮蔡澤，孱弱病劉楨。","試暗秦台下，應迴照膽明。","。"]', '诗', 'shi', '', NULL, '投太原李司空 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aff8eba5-568b-4bf3-acbe-d46e99b7a77c', '獻太原裴相公三十韻', '獻太原裴相公三十韻', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["萬古元和史，功名將相殊。","英明逢主斷，直道與天符。","一鏡辭西闕，雙旌鎮北都。","輪轅歸大匠，劒戟盡洪爐。","物望朝端洽，人情海內輸。","重輕毫在手，斟酌斗迴樞。","邴吉真丞相，陳蕃實丈夫。","禮賓青眼色，憂國白髭鬚。","幾賴平中土，長愁入五湖。","旱苗今雨活，妖沴共風驅。","料敵窮天象，開邊過地圖。","黃河歸博望，青塚破兇奴。","虎豹皆親射，豺狼例手誅。","坐籌千不失，持鉞四無虛。","勇義精誠感，溫良美價沽。","夔龍甘道劣，賈馬分材枯。","曙色開營柳，秋聲動塞榆。","縱橫追穴兔，直下灌城狐。","舉論當前古，推心及後儒。","風雲如借便，開眼即天衢。","（本卷均見南宋蜀刻本《張承吉文集》卷第十。","）。"]', '["万古元和史，功名將相殊。","英明逢主斷，直道與天符。","一镜辞西闕，雙旌鎮北都。","輪轅归大匠，劒戟尽洪爐。","物望朝端洽，人情海內輸。","重轻毫在手，斟酌斗迴樞。","邴吉真丞相，陳蕃實丈夫。","禮賓青眼色，憂国白髭鬚。","幾賴平中土，长愁入五湖。","旱苗今雨活，妖沴共风驱。","料敵窮天象，开邊過地圖。","黄河归博望，青塚破兇奴。","虎豹皆親射，豺狼例手誅。","坐籌千不失，持鉞四無虛。","勇義精誠感，溫良美價沽。","夔龙甘道劣，賈马分材枯。","曙色开營柳，秋声动塞榆。","縱橫追穴兔，直下灌城狐。","舉論當前古，推心及後儒。","风云如借便，开眼即天衢。","（本卷均见南宋蜀刻本《張承吉文集》卷第十。","）。"]', '诗', 'shi', '', NULL, '獻太原裴相公三十韻 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9da5d218-0cb7-47d1-bb56-77a5ec129165', '途次楊州贈崔荆二十韻', '途次楊州贈崔荆二十韻', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["逆旅楊州郭，音容幸此遭。","酒漿曾不罷，風月更何逃。","寺塔排雲直，閭門架水牢。","煙籠春樹薄，日映曙樓高。","碧草連除卷，青旗指濁醪。","粉胸斜露玉，檀臉慢迴刀。","躍馬君心勁，嗔奴我氣亭。","尾生從抱柱，顏子也酺糟。","赤柏看眉睫，生憎惜羽手。","北邙終寂寞，南國且遊𢕟。","觱篥行移束，箜篌旋轉絛。","袖因迎顐破，肩爲請挼勞。","未省求媒氏，焉能泥賊曹。","揀花偷芍藥，和葉窠櫻桃。","悶口無端語，窮頭盡興搔。","覆身唯綠葛，醫病只青蒿。","事過宜他哂，詩成苟自褒。","醉時心爛漫，別夜眼號咷。","接席觀誠忝，升堂跡貴叨。","殷勤欲離抱，爲爾一揮毫。"]', '["逆旅楊州郭，音容幸此遭。","酒漿曾不罷，风月更何逃。","寺塔排云直，閭门架水牢。","煙籠春樹薄，日映曙楼高。","碧草連除卷，青旗指濁醪。","粉胸斜露玉，檀臉慢迴刀。","躍马君心勁，嗔奴我氣亭。","尾生從抱柱，顏子也酺糟。","赤柏看眉睫，生憎惜羽手。","北邙終寂寞，南国且游𢕟。","觱篥行移束，箜篌旋轉絛。","袖因迎顐破，肩爲請挼勞。","未省求媒氏，焉能泥賊曹。","揀花偷芍藥，和葉窠櫻桃。","悶口無端語，窮头尽兴搔。","覆身唯綠葛，醫病只青蒿。","事過宜他哂，诗成苟自褒。","醉时心爛漫，別夜眼號咷。","接席观誠忝，升堂跡貴叨。","殷勤欲離抱，爲爾一揮毫。"]', '诗', 'shi', '', NULL, '途次楊州贈崔荆二十韻 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e9f74cf-3810-476d-8da7-30393b80e83a', '投宛陵裴尚書二十韻', '投宛陵裴尚书二十韻', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["憶拜明公日，青雲料果符。","徵賢披顯詔，射策冠英儒。","物論推前哲，朝綱揖大巫。","德門深茂秀，義土闢膏腴。","簡翰垂師法，文章述帝謨。","民歡車轍至，士畏履聲趨。","省闥名尤美，藩方政歷殊。","五兵森武庫，百氏祕文樞。","小謝才難比，諸荀道亦具。","幾年思樂土，長日詠生蒭，潔儉遵明訓，清通軌令圖。","馬奔爲信竹，鞭舉示刑蒲。","促座嘉賓滿，分題健筆濡。","碧江秋鳥聚，青漳瞑猿孤。","月上連城璧，星環合浦珠。","早涼生玉樹，盛暑退冰壺。","豹變真君子，龍鍾淺丈夫。","新知多巂彥，舊態只狂奴。","敢望憐哀鳥，何煩敬朽株。","已愁沾洒淚，還去海西隅。"]', '["憶拜明公日，青云料果符。","徵賢披显詔，射策冠英儒。","物論推前哲，朝綱揖大巫。","德门深茂秀，義土闢膏腴。","簡翰垂師法，文章述帝謨。","民歡车轍至，士畏履声趨。","省闥名尤美，藩方政歷殊。","五兵森武庫，百氏祕文樞。","小謝才难比，諸荀道亦具。","幾年思乐土，长日詠生蒭，潔儉遵明訓，清通軌令圖。","马奔爲信竹，鞭舉示刑蒲。","促座嘉賓满，分題健笔濡。","碧江秋鸟聚，青漳瞑猿孤。","月上連城璧，星环合浦珠。","早涼生玉樹，盛暑退冰壺。","豹变真君子，龙鍾淺丈夫。","新知多巂彥，旧態只狂奴。","敢望怜哀鸟，何煩敬朽株。","已愁沾洒泪，還去海西隅。"]', '诗', 'shi', '', NULL, '投宛陵裴尚書二十韻 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90a2e6bf-b0fe-44ff-bf43-be4843fd9914', '庚子歲寓遊楊州贈崔荆四十韻', '庚子歲寓游楊州贈崔荆四十韻', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["窮賤正相仍，逢君又廣陵。","坐愁身兀兀，行信脚騰騰。","小巷朝歌滿，高樓夜吹凝。","月明街廓路，星散市橋燈。","鈍僕常羞使，贏驂半醉乘。","酷遭狂客引，剛被俗人憎。","睚眦寧宜慣，趦趄苟未能。","坊期瑞芝宿，閣詢慶雲登。","逈眺江千里，高臨塔九層。","山嵐開碧罅，海日上紅稜。","曲岸盤回出，飛欄斗峻凭。","鷺鷥行淺草，龜殻上新菱。","野霽崗形兀，林昏地氣蒸。","春天聊共賞，夏日幾同瞢。","自給勞方寸，官沽厭窄升。","堅强心似石，險峭志如陵。","悶極行挑耳，狂來起扼肱。","腸風終作疹，肺病不爲徵。","玉樹當巡打，香毬帶柏承。","暗歸逃酒席，私語結鈎朋。","僻性從他論，幽情且自矜。","砌開紅艷槿，庭架綠陰藤。","冷滑連心簟，輕疎着體繒。","被裁新蜀錦，光砑小吳綾。","久滯終何益，長貧也未應。","莫輕垂耳驥，須看脫鱗鵬。","善惡都鈐口，存亡只撫膺。","楚才君漫倚，荆璞我虛憑。","委順容如妾，幽迂論若僧。","早知身足累，近信卜無徵。","畫虎誠堪誚，雕蟲詎可稱。","掃門蹤魏勃，開閣竚孫弘。","勿易侵苗鼠，須防止棘蠅。","足憂行夜露，心懼履春冰。","旅望孤煙起，鄉愁遠水澄。","每思人似玉，長願酒如澠。","去國程無盡，離筵思不勝。","感恩因病雀，逐物甚飢鷹。","詎憶園蔬灌，唯希社肉秤。","寃讎閑物在，知己大官薨。","郄弟終須得，蘧非誓欲懲。","看看重西去，從此又兢兢。"]', '["窮賤正相仍，逢君又廣陵。","坐愁身兀兀，行信脚腾腾。","小巷朝歌满，高楼夜吹凝。","月明街廓路，星散市橋灯。","鈍僕常羞使，贏驂半醉乘。","酷遭狂客引，剛被俗人憎。","睚眦寧宜慣，趦趄苟未能。","坊期瑞芝宿，閣詢慶云登。","逈眺江千里，高臨塔九層。","山嵐开碧罅，海日上紅稜。","曲岸盤回出，飞欄斗峻凭。","鷺鷥行淺草，龟殻上新菱。","野霽崗形兀，林昏地氣蒸。","春天聊共賞，夏日幾同瞢。","自給勞方寸，官沽厭窄升。","堅强心似石，險峭志如陵。","悶極行挑耳，狂来起扼肱。","腸风終作疹，肺病不爲徵。","玉樹當巡打，香毬带柏承。","暗归逃酒席，私語結鈎朋。","僻性從他論，幽情且自矜。","砌开紅艷槿，庭架綠陰藤。","冷滑連心簟，轻疎着體繒。","被裁新蜀錦，光砑小吳綾。","久滯終何益，长貧也未應。","莫轻垂耳驥，須看脫鱗鵬。","善惡都鈐口，存亡只撫膺。","楚才君漫倚，荆璞我虛憑。","委順容如妾，幽迂論若僧。","早知身足累，近信卜無徵。","畫虎誠堪誚，雕蟲詎可稱。","掃门蹤魏勃，开閣竚孫弘。","勿易侵苗鼠，須防止棘蠅。","足憂行夜露，心懼履春冰。","旅望孤煙起，乡愁远水澄。","每思人似玉，长願酒如澠。","去国程無尽，離筵思不勝。","感恩因病雀，逐物甚飢鷹。","詎憶园蔬灌，唯希社肉秤。","寃讎闲物在，知己大官薨。","郄弟終須得，蘧非誓欲懲。","看看重西去，從此又兢兢。"]', '诗', 'shi', '', NULL, '庚子歲寓遊楊州贈崔荆四十韻 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b37264a-d203-4cc3-b147-971b7966ffab', '遊蔚過昭陵十六韻', '游蔚過昭陵十六韻', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["天意亡隋日，人心啓聖年。","順時興義卒，撥亂起戎旃。","羣盗猶蜂蟻，妖星尚屬聯。","既教龍戰野，須見血成川。","睿筭無遺策，神功亦有權。","王尋徒百萬，光武只三千。","（原注：太宗嘗以騎兵三千破僞夏十萬於虎牢。","）海静鯨鯢死，雲開日月懸。","講兵將耀德，獵渭本搜賢。","向闕皆鏘玉，臨關罷控弦。","大鑪銷劒戟，鴻澤盪腥膻。","太祖恩堯禪，（原注：武德末，天下既平，高祖致政。","）神孫受禹傳。","（原注：貞觀既終，高宗嗣位。","）宮車悲未已，陵樹藹蒼然。","岳立青冥外，虬蟠白水邊。","乾坤資王氣，巖壑擁晴煙。","虞爮曾南狩，軒轅亦上仙。","斷髯無復見，空拜鼎湖前。"]', '["天意亡隋日，人心啓聖年。","順时兴義卒，撥亂起戎旃。","羣盗猶蜂蟻，妖星尚屬聯。","既教龙戰野，須见血成川。","睿筭無遺策，神功亦有權。","王尋徒百万，光武只三千。","（原注：太宗嘗以騎兵三千破僞夏十万於虎牢。","）海静鯨鯢死，云开日月懸。","講兵將耀德，獵渭本搜賢。","向闕皆鏘玉，臨关罷控弦。","大鑪銷劒戟，鴻澤盪腥膻。","太祖恩堯禪，（原注：武德末，天下既平，高祖致政。","）神孫受禹傳。","（原注：貞观既終，高宗嗣位。","）宮车悲未已，陵樹藹蒼然。","岳立青冥外，虬蟠白水邊。","乾坤資王氣，巖壑擁晴煙。","虞爮曾南狩，軒轅亦上仙。","斷髯無复见，空拜鼎湖前。"]', '诗', 'shi', '', NULL, '遊蔚過昭陵十六韻 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ab4bfb6-37db-4014-8487-53bfe55e15e1', '敍詩', '敍诗', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["二雅泄詩源，滂滂接漣漪。","宣尼昔道{卄/氵史}，豁豁無阻疑。","小開作涇港，大漲爲塘陂。","可令萬頃澄，可使百派支。","生民苟灌溉，九穀長蕃滋。","何意束晳徒，《補亡》輒繼之。","安知去聖遠，立旨無乖隳。","五言起李陵，其什傷遠離。","雄材耻小用，屬詠隅成規。","後時班婕妤，團扇託憂悲。","枚情既云妙，蔡韻肯容卑。","建安陳思王，龍變五不知。","劉楨骨氣真，王粲文質奇。","阮公先興亡，陸氏以才推。","雅怨止潘子，高摽存左思。","延年得殊致，靈運拔英姿。","沈侯美玉蘊，謝守文錦摛。","江詞騁奇妙，鮑趣出孤危。","飄飄喜澤翁，於在務脫遺。","陳隋後諸子，往往沙可披。","拾遺昔陳公，强立制頹萎。","英華自沈宋，律唱{牙丿=丶}相維。","其間豈無長，聲病爲深宜。","江寧王昌齢，名貴人可垂。","波瀾到李杜，碧海東瀰瀰。","曲江兼在才，善奏珠纍纍。","四面近劉復，遠與何相追。","邇來韋蘇州，氣韻甚怡怡。","伶倫管尚在，此律誰能吹。"]', '["二雅泄诗源，滂滂接漣漪。","宣尼昔道{卄/氵史}，豁豁無阻疑。","小开作涇港，大漲爲塘陂。","可令万頃澄，可使百派支。","生民苟灌溉，九穀长蕃滋。","何意束晳徒，《補亡》輒繼之。","安知去聖远，立旨無乖隳。","五言起李陵，其什傷远離。","雄材耻小用，屬詠隅成規。","後时班婕妤，團扇託憂悲。","枚情既云妙，蔡韻肯容卑。","建安陳思王，龙变五不知。","劉楨骨氣真，王粲文質奇。","阮公先兴亡，陸氏以才推。","雅怨止潘子，高摽存左思。","延年得殊致，靈運拔英姿。","沈侯美玉蘊，謝守文錦摛。","江词騁奇妙，鲍趣出孤危。","飄飄喜澤翁，於在務脫遺。","陳隋後諸子，往往沙可披。","拾遺昔陳公，强立制頹萎。","英华自沈宋，律唱{牙丿=丶}相維。","其间豈無长，声病爲深宜。","江寧王昌齢，名貴人可垂。","波瀾到李杜，碧海东瀰瀰。","曲江兼在才，善奏珠纍纍。","四面近劉复，远與何相追。","邇来韋蘇州，氣韻甚怡怡。","伶倫管尚在，此律誰能吹。"]', '诗', 'shi', '', NULL, '敍詩 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08978ad6-2097-4f42-a579-fc71623735b2', '大唐聖功詩', '大唐聖功诗', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["祜聞昔隋末。","煬帝厄圍兵。","太宗初應募，杖劎起邊征。","揚師列虛旗，首激將軍誠。","神略在一斷，解圍當未萌。","高祖守河東，權力已兼幷。","猖狂蟻結徒，舉踵乃擊平。","隋德日已衰，俯折士尊名。","羣才{牙丿=丶}相枤，諾以義爲盟。","屯軍起邊州，李密馳傳迎。","楊眉愛姿度，失口真王英。","由是太河南，千里響應聲。","降王與拘竇，親待入宮城。","乃命臣蕭瑀，府庫掌虛盈。","次命臣玄齡，圖書收付卿。","開牢釋姧枉，各更重從輕。","迴戈略僞主，太廟告明明。","殊功苟未已，徽號爲重旌。","文物一以興，賢良俱間生。","聲詩日盈聽，智論益縱橫。","何意蕭牆內，陰謀中構傾。","直詞雖可進，王法詎該情。","甲子上即位，南郊赦憲灜。","八蠻與四夷，朝貢路交争，三月后親蠶，癸亥上親耕。","侍臣虞南等，碑以紀功成。"]', '["祜闻昔隋末。","煬帝厄圍兵。","太宗初應募，杖劎起邊征。","揚師列虛旗，首激將軍誠。","神略在一斷，解圍當未萌。","高祖守河东，權力已兼幷。","猖狂蟻結徒，舉踵乃擊平。","隋德日已衰，俯折士尊名。","羣才{牙丿=丶}相枤，諾以義爲盟。","屯軍起邊州，李密驰傳迎。","楊眉愛姿度，失口真王英。","由是太河南，千里响應声。","降王與拘竇，親待入宮城。","乃命臣蕭瑀，府庫掌虛盈。","次命臣玄齡，圖书收付卿。","开牢釋姧枉，各更重從轻。","迴戈略僞主，太廟告明明。","殊功苟未已，徽號爲重旌。","文物一以兴，賢良俱间生。","声诗日盈听，智論益縱橫。","何意蕭牆內，陰謀中構傾。","直词雖可進，王法詎該情。","甲子上即位，南郊赦憲灜。","八蠻與四夷，朝貢路交争，三月后親蠶，癸亥上親耕。","侍臣虞南等，碑以紀功成。"]', '诗', 'shi', '', NULL, '大唐聖功詩 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f48917a-e5a1-4013-b538-0e6995727431', '元和直言詩', '元和直言诗', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["東野小臣祜，聖朝垂淚言。","微塵豈裨助，永負丘山恩。","箕子昔爲奴，所悲逢世昏。","明時便鉗舌，切恐負乾坤。","臣當涉黃河，心目日且煩。","分明在人世，不喻波渾渾。","願以所支流，却尋到崑崙。","但窮此生感，沒齒寧爲寃。","臣讀帝王書，粗知治亂源。","文思苟未安，詎得賓四門。","陛下欲垂衣，一與夔契論。","成湯事不盡，勿更隨波翻。","直者舉其材，曲者尋其根。","直固不可遺，曲亦不可焚。","用材苟端審，帝道即羲軒。","陛下復土階，四方敢高垣。","陛下喜雕牆，四方必重藩。","畋獵豈無娛，湯泉豈無溫。","始知堯爲心，清淨自成尊。","比干不憚死，諫道久而存。","許由不務策，志士亦所敦。","兢兢小臣祜，萬死甘詞繁。"]', '["东野小臣祜，聖朝垂泪言。","微塵豈裨助，永負丘山恩。","箕子昔爲奴，所悲逢世昏。","明时便鉗舌，切恐負乾坤。","臣當涉黄河，心目日且煩。","分明在人世，不喻波渾渾。","願以所支流，却尋到崑崙。","但窮此生感，沒齒寧爲寃。","臣读帝王书，粗知治亂源。","文思苟未安，詎得賓四门。","陛下欲垂衣，一與夔契論。","成湯事不尽，勿更隨波翻。","直者舉其材，曲者尋其根。","直固不可遺，曲亦不可焚。","用材苟端審，帝道即羲軒。","陛下复土階，四方敢高垣。","陛下喜雕牆，四方必重藩。","畋獵豈無娛，湯泉豈無溫。","始知堯爲心，清淨自成尊。","比干不憚死，諫道久而存。","許由不務策，志士亦所敦。","兢兢小臣祜，万死甘词繁。"]', '诗', 'shi', '', NULL, '元和直言詩 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55f15946-e21f-4ea8-ba0a-76a6e229f393', '旅次岳州呈徐員外', '旅次岳州呈徐員外', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["襄漢止薄遊，登舟捨羸策。","浮名乃閑事，且作山水客。","遠持屠龍伎，南訪賈誼跡。","連崗黯雲樹，斜日半赤壁。","青水去悠悠，青山來歷歷。","囊無一金備，不省爲計畫。","村旗{牙丿=丶}誇酒，咺薄升斗窄。","提筆猒班超，把詩憐阮籍。","徐公岳陽守，遇我心的的。","湖鮮爲我鱠，湖藻爲我摘。","得吟多高樓，得語多末席。","平生負微志，不獨詩酒溺。","終懷咸谷泥，定刻燕然石。","會公饒迎餞，微懇私已識。","逢時魯連輩，一局如博奕。","憂來獨求醉，兀兀臨大澤。","屈原誠褊人，自死終何益。","南湖雪晴夜，星月林摵摵。","君山洞門叟，相語鶴兩隻。","風松座翹𣍿，向月吹玉笛。","笑命詩思苦，莫信狂李白。","於狂是空疎，於仙是遐謫。","寄言徐太守，人在無金液。"]', '["襄漢止薄游，登舟捨羸策。","浮名乃闲事，且作山水客。","远持屠龙伎，南訪賈誼跡。","連崗黯云樹，斜日半赤壁。","青水去悠悠，青山来歷歷。","囊無一金備，不省爲計畫。","村旗{牙丿=丶}誇酒，咺薄升斗窄。","提笔猒班超，把诗怜阮籍。","徐公岳陽守，遇我心的的。","湖鲜爲我鱠，湖藻爲我摘。","得吟多高楼，得語多末席。","平生負微志，不独诗酒溺。","終懷咸谷泥，定刻燕然石。","會公饒迎餞，微懇私已識。","逢时魯連輩，一局如博奕。","憂来独求醉，兀兀臨大澤。","屈原誠褊人，自死終何益。","南湖雪晴夜，星月林摵摵。","君山洞门叟，相語鹤兩隻。","风松座翹𣍿，向月吹玉笛。","笑命诗思苦，莫信狂李白。","於狂是空疎，於仙是遐謫。","寄言徐太守，人在無金液。"]', '诗', 'shi', '', NULL, '旅次岳州呈徐員外 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9e79943-6773-45dc-9ad0-a9754b7821f2', '登香爐峯寄遠人', '登香爐峯寄远人', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["前登香爐峯，却指湓城郡。","大江北潮海，崇岳南作鎮。","相逢虎溪子，輕策聊一振。","水石動寒光，風松洒高韻。","憂來月成語，忽忽千里憤。","六朝空遺文，三國無尺燼。","孤禽下雲久，遠樹入煙盡。","客恨猒山重，歸心喜流順。","故執行瀟湘別，即此無音信。","憔悴十年心，誰人不緇磷。"]', '["前登香爐峯，却指湓城郡。","大江北潮海，崇岳南作鎮。","相逢虎溪子，轻策聊一振。","水石动寒光，风松洒高韻。","憂来月成語，忽忽千里憤。","六朝空遺文，三国無尺燼。","孤禽下云久，远樹入煙尽。","客恨猒山重，归心喜流順。","故執行瀟湘別，即此無音信。","憔悴十年心，誰人不緇磷。"]', '诗', 'shi', '', NULL, '登香爐峯寄遠人 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4798de2e-7340-47dc-8ad0-fe123a8e39ef', '丹陽新居四十韻', '丹陽新居四十韻', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["不出丹陽郭，茅簷寄北偏。","四隅疎積潦，萬頃控平田。","地勢金陵豁，灣形珥瀆連。","路分南畝上，山映後湖邊。","故國心殊阻，新池手強穿。","閑吟招隱詠，靜賦篤終篇。","大樹應徒爾，高門亦偶然。","孤雲出小嶼，侶鶴下遼天。","早巿歸人語，昏亭醉客眠。","五更衘月岸，一宿渡江舡。","雪旦飛瓊圃，花時麗錦川。","茅峯遙自對，練水曲相㳂。","夜出澤頭火，晴昏巷裏煙。","人情嗤散漫，鳥性樂暄妍。","夏菓垂簪上，春農起面前。","竹欄隈杳嫋，藤杖決潺湲。","不忝端居勝，何妨病者便。","水軒斜浸柳，風檻散披蓮。","接壤重崗抱，坯沙淺洞延。","外瞻羣嶺拔，中坐兩崖顛。","峻面嶙岣甃，崇臺碨礧填。","小橋深宛宛，新瀑下涓涓。","架俯薔薇立，籬因枳殻編。","何當把牙筭，祇是躡苔錢。","勃窣松栽短，尖纖石筍圓。","綠含山桂潤，紅綻海棠鮮。","枕上看羈䩡，門前見着鞭。","闌珊棊未畢，撥剌釣初牽。","塵尾曾無謂，猪肝是不緣。","坐甘塵外老，來幸酒中仙。","潘岳因成賦，楊雄便草《玄》。","散襟梳短髪，揭指上遊絃。","粗可迴車馬，聊堪駐旆旃。","藉莎慙異席，折筍俟加籩。","哭地心知矣，儒家分已焉。","窮猿半啼嘯，病鶴欲飛眠。","授籙陶貞白，留齋竺法乾。","觀心知不二，叩齒問羅千。","帝里思徒切，家山望益懸。","閶門不可上，西恨涕漣漣。"]', '["不出丹陽郭，茅簷寄北偏。","四隅疎積潦，万頃控平田。","地勢金陵豁，灣形珥瀆連。","路分南畝上，山映後湖邊。","故国心殊阻，新池手強穿。","闲吟招隐詠，静賦篤終篇。","大樹應徒爾，高门亦偶然。","孤云出小嶼，侶鹤下遼天。","早巿归人語，昏亭醉客眠。","五更衘月岸，一宿渡江舡。","雪旦飞瓊圃，花时丽錦川。","茅峯遙自对，練水曲相㳂。","夜出澤头火，晴昏巷裏煙。","人情嗤散漫，鸟性乐暄妍。","夏菓垂簪上，春農起面前。","竹欄隈杳嫋，藤杖決潺湲。","不忝端居勝，何妨病者便。","水軒斜浸柳，风檻散披蓮。","接壤重崗抱，坯沙淺洞延。","外瞻羣嶺拔，中坐兩崖顛。","峻面嶙岣甃，崇台碨礧填。","小橋深宛宛，新瀑下涓涓。","架俯薔薇立，籬因枳殻編。","何當把牙筭，祇是躡苔錢。","勃窣松栽短，尖纖石筍圓。","綠含山桂潤，紅綻海棠鲜。","枕上看羈䩡，门前见着鞭。","闌珊棊未畢，撥剌釣初牽。","塵尾曾無謂，猪肝是不緣。","坐甘塵外老，来幸酒中仙。","潘岳因成賦，楊雄便草《玄》。","散襟梳短髪，揭指上游絃。","粗可迴车马，聊堪駐旆旃。","藉莎慙異席，折筍俟加籩。","哭地心知矣，儒家分已焉。","窮猿半啼嘯，病鹤欲飞眠。","授籙陶貞白，留斋竺法乾。","观心知不二，叩齒问羅千。","帝里思徒切，家山望益懸。","閶门不可上，西恨涕漣漣。"]', '诗', 'shi', '', NULL, '丹陽新居四十韻 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d771c4a5-677d-4739-a2d3-fe315101b73d', '憶江東舊遊四十韻寄宣武李尚書', '憶江东旧游四十韻寄宣武李尚书', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["憶作江東客，猖狂事頗曾。","海隅思變化，雲路折飛騰。","小子今何述，高賢昔謬稱。","瘦體休問馬，病爪莫論鷹。","海棹扁舟泛，江開一檻憑。","岸環青莽蒼，峰峭碧崚嶒。","水國程無盡，煙郊思不勝。","金絲援嫩柳，玉片犯殘冰。","夜伯度操檝，朝行看下罾。","沙明春雨霽，野白暮雲蒸。","蒲晚帆山葉，花開鏡水菱。","亂芳叢沼沚，餘溜泄溝塍。","鷲嶺因支訪，龍門詣李登。","黃鸎春惱客，白鶴夜依僧。","粗得狂歌趣，深疑笑病癥。","地窮屯健馬，天盡抑飛鵬。","桂彩分城堞，松香在閣層。","酒徒窮不破，詩債老相仍。","伯玉年將近，宣尼《易》未弘。","歲儲雖自乏，社肉必均秤。","造化三光借，乾坤一塊凝。","才當論曲直，命可繫衰興。","鳳鳥非無歎，驊騮靡不乘。","豹文須蔚蔚，羊目漫睖睖。","范蠡嘗金鑄，吳王昔土崩。","雄圖翻自失，高噣鮮相承。","禹廟思陳藻，秦山憶杖藤。","幾時心豁豁，長日醉瞢瞢。","水室窮深討，雲門極峻登。","北歸天尚遠，東望海方澄。","鶴跂虛爲羡人言敢不應。","旅游星正孛，愁望月初絙。","詎欲由斜徑，聊思枕曲肱。","興捫頭上虱，閑祖筆鋒蠅。","鳥岸勞方寸，魚缾惜一升。","詩秋情未劇，別夜思偏增。","白首身從賤，青雲氣可淩。","當知在塵土，言直更兢兢。"]', '["憶作江东客，猖狂事頗曾。","海隅思变化，云路折飞腾。","小子今何述，高賢昔謬稱。","瘦體休问马，病爪莫論鷹。","海棹扁舟泛，江开一檻憑。","岸环青莽蒼，峰峭碧崚嶒。","水国程無尽，煙郊思不勝。","金絲援嫩柳，玉片犯殘冰。","夜伯度操檝，朝行看下罾。","沙明春雨霽，野白暮云蒸。","蒲晚帆山葉，花开镜水菱。","亂芳叢沼沚，餘溜泄溝塍。","鷲嶺因支訪，龙门詣李登。","黄鸎春惱客，白鹤夜依僧。","粗得狂歌趣，深疑笑病癥。","地窮屯健马，天尽抑飞鵬。","桂彩分城堞，松香在閣層。","酒徒窮不破，诗債老相仍。","伯玉年將近，宣尼《易》未弘。","歲儲雖自乏，社肉必均秤。","造化三光借，乾坤一塊凝。","才當論曲直，命可繫衰兴。","鳳鸟非無歎，驊騮靡不乘。","豹文須蔚蔚，羊目漫睖睖。","范蠡嘗金鑄，吳王昔土崩。","雄圖翻自失，高噣鲜相承。","禹廟思陳藻，秦山憶杖藤。","幾时心豁豁，长日醉瞢瞢。","水室窮深討，云门極峻登。","北归天尚远，东望海方澄。","鹤跂虛爲羡人言敢不應。","旅游星正孛，愁望月初絙。","詎欲由斜徑，聊思枕曲肱。","兴捫头上虱，闲祖笔鋒蠅。","鸟岸勞方寸，鱼缾惜一升。","诗秋情未劇，別夜思偏增。","白首身從賤，青云氣可淩。","當知在塵土，言直更兢兢。"]', '诗', 'shi', '', NULL, '憶江東舊遊四十韻寄宣武李尚書 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('966e155e-8eae-430f-abcc-337bcd0c9a42', '戊午年感事書懷二百韻謹寄獻太原裴令公淮南李相公漢南李僕射宣武李尚書', '戊午年感事书懷二百韻謹寄獻太原裴令公淮南李相公漢南李僕射宣武李尚书', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["塞色深河曲，江聲接海壖。","一生勞遠地，萬事誡中年。","失路爲閑物，無官入長錢。","高蹤非隱遁，下界即狂顛。","漸老稀時輩，歸休著近篇。","星明知帝座，琴妙覺商絃。","闕下非才入，江南是性牽。","山猿拾蟲豸，野鳥避鷹鸇。","戲傲東方朔，文輕司馬遷。","萬言成弃置，五字失雕鐫。","去外尋莊叟，生涯挈道詮。","新秋唯白髪，舊欠祇青氊。","志業寧常墮，窮耕豈素便。","高低徇雞日，得失付魚筌。","醉臥捫雲扃，狂歌上釣舡。","古桐收取好，壞屋薦來偏。","（原注：祜累蒙方鎮論薦。","）却猒長裙曳，寧辭短褐穿。","憤窮多自樂，不佞少人憐。","靜祝旄頭矢，閑看馬腹鞭。","長途思逐日，高閣夢凌煙。","讀《易》刪王註，通《詩》斷鄭箋。","灰心志射鵠，火性急韋編。","昔命公稱許，嘗封國是燕。","中間得道濟，內外益心虔。","始助周文理，俄隨漢武仙。","長沙歸賈誼，汗馬得張騫。","戰伐窮蕃域，英雄是將員。","幾當陳俎豆，長謂鑄戈鋋。","世故貞元末，時清天寶前。","亂離中可惋，愚俊日相肩。","憶昨聆商鞅，於今俟魯連。","陰陽初未契，造化昔何邅。","竊位崇姦力，沽榮瀆貨權。","滿堂金已散，一草命無全。","皂白金徒爾，蒼黃古亦然。","不時經廢宅，無地見荒埏。","絕塞塵猶起，窮陰候莫愆。","楊朱寧謾泣，阮籍不空眠。","上意今唯允，人心遽益悛。","洪鑪當釼戟，大匠主陶甄。","諫豸心彌果，星郎議亦先。","氣腸思藻鏡，血首待花塼。","地峻清流急，天高白日懸。","軍庭深自誡，相閤肯虛延。","金馬門徒啓，蒲輪詔未宣。","會逢嵩岳幸，應見渭濱畋。","始賀官衣叚，尋聞御食蠲。","災蝗雖犯稼，彗孛欲依躔。","楚國風殊革，夷門政已傳。","深謀南界郢，重德北臨邊。","跡戀羊公切，心依魏相專。","苦眉虛更結，窮肺勿相煎。","輪轉功何倍，藩方寄甚堅。","三千擁簪紀，十萬各旌旃。","大器能斟酌，長材少棄捐。","樂音尤在律，星象倐開乾。","子夜汾河上，陽春峴嶺顛。","鬼園濡健筆，花塔醉妖鉛。","入室風儀逈，登樓月思圓。","塞旗冬獵獵，江皷夜𪔱𪔱。","臥犬偎𩊐毯，鳴騮躍錦韉。","綠毛鸚鵡細，紅實荔支駢。","酒夕繁含管，詩秋疊彩牋。","擁鑪香旋爇，剪燭艷重然。","畫鷁交浮淺，雕盤幾飫檀。","蟹黃鹹滿筯，熊白軟加籩。","文業臻曹植，軍書到謝玄。","鷓鴣詞綺靡，鸜鵒舞蹁躚。","未坐扶狼狽，重茵睡猓然。","夜門歸妓樂，部砌拾花鈿。","揭袖從風虎，彈冠仰露蟬。","依劉身未殺，投趙踵空旋。","竊語機關少，徐行病體攣。","詎煩詹尹策，徒掛養由弦。","勃窣形骸朽，眼迴語氣嫣。","萬端饒睚眦，一笑泥嬋娟。","大網寧羅雀，深源亦聚鱣。","偏思公子館，誰問李膺舩。","筆硯今猶置，文章昔精研。","行因竹林寺，出爲柘枝筵。","物外心仍僻，塵中病已痊。","蕭疎吟草木，浩渺泝波漣。","南陌逢車馬，西陵見墓田。","傷心從楚塞，垂淚到湘川。","建業人無也，姑蘇事已焉。","翠華深沓靄，情籟響潺湲。","夢去爲蝴蝶，魂遊家杜鵑。","詩吟陳後主，傅范楚先賢。","百越憐疆境，三吳隘井鄽。","江分九派水，海石一方天。","步日松陰缺，披風石翠鮮。","朝帆入大浦，暝鞚逸長阡。","曩造西霞律，新參北固禪。","澗游提破屨，樓臥枕空拳。","□肆行聊問，僧棊坐與𡎞。","朽心降杞梓，生意慕蘭筌。","真道非無隘，空談是信緣。","侯王如重阻，歸看數峯連。"]', '["塞色深河曲，江声接海壖。","一生勞远地，万事誡中年。","失路爲闲物，無官入长錢。","高蹤非隐遁，下界即狂顛。","漸老稀时輩，归休著近篇。","星明知帝座，琴妙覺商絃。","闕下非才入，江南是性牽。","山猿拾蟲豸，野鸟避鷹鸇。","戲傲东方朔，文轻司马遷。","万言成弃置，五字失雕鐫。","去外尋莊叟，生涯挈道詮。","新秋唯白髪，旧欠祇青氊。","志業寧常墮，窮耕豈素便。","高低徇雞日，得失付鱼筌。","醉臥捫云扃，狂歌上釣舡。","古桐收取好，壞屋薦来偏。","（原注：祜累蒙方鎮論薦。","）却猒长裙曳，寧辞短褐穿。","憤窮多自乐，不佞少人怜。","静祝旄头矢，闲看马腹鞭。","长途思逐日，高閣梦凌煙。","读《易》刪王註，通《诗》斷鄭箋。","灰心志射鵠，火性急韋編。","昔命公稱許，嘗封国是燕。","中间得道濟，內外益心虔。","始助周文理，俄隨漢武仙。","长沙归賈誼，汗马得張騫。","戰伐窮蕃域，英雄是將員。","幾當陳俎豆，长謂鑄戈鋋。","世故貞元末，时清天寶前。","亂離中可惋，愚俊日相肩。","憶昨聆商鞅，於今俟魯連。","陰陽初未契，造化昔何邅。","竊位崇姦力，沽榮瀆貨權。","满堂金已散，一草命無全。","皂白金徒爾，蒼黄古亦然。","不时經廢宅，無地见荒埏。","絕塞塵猶起，窮陰候莫愆。","楊朱寧謾泣，阮籍不空眠。","上意今唯允，人心遽益悛。","洪鑪當釼戟，大匠主陶甄。","諫豸心彌果，星郎議亦先。","氣腸思藻镜，血首待花塼。","地峻清流急，天高白日懸。","軍庭深自誡，相閤肯虛延。","金马门徒啓，蒲輪詔未宣。","會逢嵩岳幸，應见渭濱畋。","始賀官衣叚，尋闻御食蠲。","災蝗雖犯稼，彗孛欲依躔。","楚国风殊革，夷门政已傳。","深謀南界郢，重德北臨邊。","跡戀羊公切，心依魏相專。","苦眉虛更結，窮肺勿相煎。","輪轉功何倍，藩方寄甚堅。","三千擁簪紀，十万各旌旃。","大器能斟酌，长材少棄捐。","乐音尤在律，星象倐开乾。","子夜汾河上，陽春峴嶺顛。","鬼园濡健笔，花塔醉妖鉛。","入室风儀逈，登楼月思圓。","塞旗冬獵獵，江皷夜𪔱𪔱。","臥犬偎𩊐毯，鳴騮躍錦韉。","綠毛鸚鵡細，紅實荔支駢。","酒夕繁含管，诗秋叠彩牋。","擁鑪香旋爇，剪燭艷重然。","畫鷁交浮淺，雕盤幾飫檀。","蟹黄鹹满筯，熊白軟加籩。","文業臻曹植，軍书到謝玄。","鷓鴣词綺靡，鸜鵒舞蹁躚。","未坐扶狼狽，重茵睡猓然。","夜门归妓乐，部砌拾花鈿。","揭袖從风虎，彈冠仰露蟬。","依劉身未殺，投趙踵空旋。","竊語機关少，徐行病體攣。","詎煩詹尹策，徒掛養由弦。","勃窣形骸朽，眼迴語氣嫣。","万端饒睚眦，一笑泥嬋娟。","大網寧羅雀，深源亦聚鱣。","偏思公子館，誰问李膺舩。","笔硯今猶置，文章昔精研。","行因竹林寺，出爲柘枝筵。","物外心仍僻，塵中病已痊。","蕭疎吟草木，浩渺泝波漣。","南陌逢车马，西陵见墓田。","傷心從楚塞，垂泪到湘川。","建業人無也，姑蘇事已焉。","翠华深沓靄，情籟响潺湲。","梦去爲蝴蝶，魂游家杜鵑。","诗吟陳後主，傅范楚先賢。","百越怜疆境，三吳隘井鄽。","江分九派水，海石一方天。","步日松陰缺，披风石翠鲜。","朝帆入大浦，暝鞚逸长阡。","曩造西霞律，新參北固禪。","澗游提破屨，楼臥枕空拳。","□肆行聊问，僧棊坐與𡎞。","朽心降杞梓，生意慕蘭筌。","真道非無隘，空談是信緣。","侯王如重阻，归看數峯連。"]', '诗', 'shi', '', NULL, '戊午年感事書懷二百韻謹寄獻太原裴令公淮南李相公漢南李僕射宣武李尚書 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('277abb5e-74fb-48f6-9014-cb86a25e44ce', '夢李白', '梦李白', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["我愛李峨嵋，夢尋尋不見。","忽聞海上騎鶴人，云白正陪王母宴。","須臾不（陳九思同志疑「大」字之訛。","）醉下碧虛，搖頭逆浪鞭赤魚。","迴眸四顧飛走類，若嗔老氣多終諸。","問余曰張祜，爾則狂者否？","朝來王母安瑤池，茅君道爾還愛酒。","祜當聽我言，我昔開元中，生時值明聖，發迹恃文雄。","一言可否由賀老，即知此老心還公。","朝廷大稱我，我亦自超羣。","嚴陵死後到李白，布衣長揖萬乘君。","玄宗開懷死（陳九思同志疑當作「樂」。","）其說，滿朝呼吸生氣雲。","中人高力士，脫驊（疑是「鞾」之誤。","「鞾」，同「靴」。","）羞欲樂。","（陳九思同志疑當作「死」。","）讒言密相構，送年千萬里。","辛苦夜夜歸，知音聊復稀。","青雲舊李白，憔悴爲酒客。","自此到人間，大蟲無肉喫。","男兒重意氣，百萬呵一擲。","董賢在前官亦崇，梁冀破家金謾積。","匡山夜醉時，吟爾古風詩。","振振二雅興，重顯此人詞。","賀老不得見，百篇徒爾爲。","李白歎爾空淚下，王喬聞爾甚相思。","爾當三萬六千日，訪我蓬萊山。","高聲叫李白，爲爾開玄關。","天明夢覺白亦去，兀兀此身天地間。","（南宋蜀刻本《張承吉文集》，承江寧唐圭璋先生見告。","）。"]', '["我愛李峨嵋，梦尋尋不见。","忽闻海上騎鹤人，云白正陪王母宴。","須臾不（陳九思同志疑「大」字之訛。","）醉下碧虛，搖头逆浪鞭赤鱼。","迴眸四顧飞走類，若嗔老氣多終諸。","问余曰張祜，爾則狂者否？","朝来王母安瑤池，茅君道爾還愛酒。","祜當听我言，我昔开元中，生时值明聖，發迹恃文雄。","一言可否由賀老，即知此老心還公。","朝廷大稱我，我亦自超羣。","嚴陵死後到李白，布衣长揖万乘君。","玄宗开懷死（陳九思同志疑當作「乐」。","）其说，满朝呼吸生氣云。","中人高力士，脫驊（疑是「鞾」之誤。","「鞾」，同「靴」。","）羞欲乐。","（陳九思同志疑當作「死」。","）讒言密相構，送年千万里。","辛苦夜夜归，知音聊复稀。","青云旧李白，憔悴爲酒客。","自此到人间，大蟲無肉喫。","男兒重意氣，百万呵一擲。","董賢在前官亦崇，梁冀破家金謾積。","匡山夜醉时，吟爾古风诗。","振振二雅兴，重显此人词。","賀老不得见，百篇徒爾爲。","李白歎爾空泪下，王喬闻爾甚相思。","爾當三万六千日，訪我蓬萊山。","高声叫李白，爲爾开玄关。","天明梦覺白亦去，兀兀此身天地间。","（南宋蜀刻本《張承吉文集》，承江寧唐圭璋先生见告。","）。"]', '诗', 'shi', '', NULL, '夢李白 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebfe4c22-dd0c-43b0-8e74-feb29fecddcf', '句', '句', '1c7aa80a-5048-440e-8587-9705420c5442', '唐', '["暮鵶不噪禁城樹，衙鼓未殘賓衛秋。","（賓衛，《唐詩紀事》卷五一作「兵衛」。","）（見唐張爲《詩人主客圖》。","）。"]', '["暮鵶不噪禁城樹，衙鼓未殘賓衛秋。","（賓衛，《唐诗紀事》卷五一作「兵衛」。","）（见唐張爲《诗人主客圖》。","）。"]', '诗', 'shi', '', NULL, '句 楊洵美 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baa5bd9c-026e-4595-97a5-e1f22562c80f', '七絕一首', '七絕一首', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["嵓□□□萬木中，□□特地一枝紅。","擬攀叢棘□寥寂，□□□香感細風。","（見陸心源《吳興金石記》卷四。","《吳興金石記》云此詩在顧渚山，詩前有序，已殘泐，錄如次：「□於□□□□爲大中五年刺史樊川杜牧奉貢訖事季春□休來□□□七言。","」詩及序又見《兩浙金石志》卷三，但殘泐更甚，詩中第二句「特地」作「時池」，似誤。","）（《吳興金石記》陸心源案畧云：「拓本高一尺三寸，廣二尺三寸，字徑二寸，……談錀《吳興志》：牧於大中四年十一月授湖州刺史。","逾年，以考功郎中知制誥，遺愛塞路。","公退之餘，登臨賦詠，碧瀾消暑，俱有留題。","蓋亦不知顧渚之有詩刻石也。","《樊川集》亦未收。","」）。"]', '["嵓□□□万木中，□□特地一枝紅。","擬攀叢棘□寥寂，□□□香感細风。","（见陸心源《吳兴金石記》卷四。","《吳兴金石記》云此诗在顧渚山，诗前有序，已殘泐，錄如次：「□於□□□□爲大中五年刺史樊川杜牧奉貢訖事季春□休来□□□七言。","」诗及序又见《兩浙金石志》卷三，但殘泐更甚，诗中第二句「特地」作「时池」，似誤。","）（《吳兴金石記》陸心源案畧云：「拓本高一尺三寸，廣二尺三寸，字徑二寸，……談錀《吳兴志》：牧於大中四年十一月授湖州刺史。","逾年，以考功郎中知制誥，遺愛塞路。","公退之餘，登臨賦詠，碧瀾消暑，俱有留題。","蓋亦不知顧渚之有诗刻石也。","《樊川集》亦未收。","」）。"]', '诗', 'shi', '', NULL, '七絕一首 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7674015-09cf-4d61-9143-16d4442637c2', '宣州開元寺贈惟直上人', '宣州开元寺贈惟直上人', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["曾與徑山爲小師，十年僧行衆人知。","夜深月色當禪處，齋後鐘聲到講時。","經雨綠苔侵古畫，過秋紅葉落新詩。","勸君莫厭江城客，雖在風塵別有期。","（見丹徒陳慶年刊《橫山草堂叢書》本《許渾詩真蹟錄》。","）（《全唐詩》卷五二六誤作杜牧詩。","）。"]', '["曾與徑山爲小師，十年僧行衆人知。","夜深月色當禪处，斋後鐘声到講时。","經雨綠苔侵古畫，過秋紅葉落新诗。","勸君莫厭江城客，雖在风塵別有期。","（见丹徒陳慶年刊《橫山草堂叢书》本《許渾诗真蹟錄》。","）（《全唐诗》卷五二六誤作杜牧诗。","）。"]', '诗', 'shi', '', NULL, '宣州開元寺贈惟直上人 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c4945f9-696c-41c3-90ca-b55b864c2e72', '茅山題徐校書隱居', '茅山題徐校书隐居', 'd14614b6-d1e2-4ceb-929f-dccd6729bbfe', '唐', '["深居四十年，語舊淚潺潺。","官滿春辭省，兵來夜出關。","思隨江鶴遠，心寄海鷗閒。","莫訝頻相訪，前峯似故山。","（同前。","）（案唐許渾烏絲欄真蹟，宋岳珂《寶真齋法書贊》著錄之，其跋畧謂「右唐郢州刺史許渾所書烏絲欄詩一百七十一篇真蹟，分上下凡二卷。","纖組閒錯，辭格華古，筆妙爛然，見爲三絕」云云。","《橫山草堂叢書》陳慶年跋謂：「用晦真蹟自敍云：『編集新舊五百篇』。","《全唐詩》編丁卯詩至五百三十餘著，逾於郢州自紀之數，丁卯之詩，宜若一無所遺。","乃《宣州開元寺贈惟直上人一首》與《茅山題徐校書隱居一首》明載於真蹟中者，即爲《全唐》摭拾所不及。","」）。"]', '["深居四十年，語旧泪潺潺。","官满春辞省，兵来夜出关。","思隨江鹤远，心寄海鷗閒。","莫訝頻相訪，前峯似故山。","（同前。","）（案唐許渾烏絲欄真蹟，宋岳珂《寶真斋法书贊》著錄之，其跋畧謂「右唐郢州刺史許渾所书烏絲欄诗一百七十一篇真蹟，分上下凡二卷。","纖組閒錯，辞格华古，笔妙爛然，见爲三絕」云云。","《橫山草堂叢书》陳慶年跋謂：「用晦真蹟自敍云：『編集新旧五百篇』。","《全唐诗》編丁卯诗至五百三十餘著，逾於郢州自紀之數，丁卯之诗，宜若一無所遺。","乃《宣州开元寺贈惟直上人一首》與《茅山題徐校书隐居一首》明載於真蹟中者，即爲《全唐》摭拾所不及。","」）。"]', '诗', 'shi', '', NULL, '茅山題徐校書隱居 許渾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b34f1e29-1c24-41c6-a372-bc2d5b6cb1de', '訪白雲山人', '訪白云山人', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["瀑近懸崖屋，陰陰草木青。","自言山底住，長向月中畊。","晚雨無多點，初蟬第一聲。","煮茶歸未去，刻竹爲題名。","（見《永樂大典》卷三○○四「九真」「人」字〖五函四十一冊〗。","）（周建國云此詩可信，義山另有《白雲夫舊居》詩可參。","）。"]', '["瀑近懸崖屋，陰陰草木青。","自言山底住，长向月中畊。","晚雨無多点，初蟬第一声。","煮茶归未去，刻竹爲題名。","（见《永乐大典》卷三○○四「九真」「人」字〖五函四十一冊〗。","）（周建国云此诗可信，義山另有《白云夫旧居》诗可參。","）。"]', '诗', 'shi', '', NULL, '訪白雲山人 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a12a7c2-34e1-4f43-8804-8b629c306494', '謁華嶽廟', '謁华嶽廟', '4d361b4d-63e3-441f-a931-061850e303fc', '唐', '["老柏寒颼颼，清祠晝寂寂。","開門華山北，嵐氣沉日夕。","國家崇明祀，五岳盡封冊。","福我西土民，報君金天籍。","惟神本貞信，以道徵損益。","無力惑聰明，訛言縱巫覡（原作「●●」）。","因循作風俗，相與成（《雍州金石記》作「舊」）溺。","疲病閭里甿，錐刀往來客。","（《雍州金石記》作「役」。","）我行歲云暮，登殿拜瑤席。","奠酒徹明靈，緒言多感激。","欝然展冠冕，凜若生矛戟。","斑駮石色重，陰深香煙碧。","虹梁無燕雀，玉座鎮虺蜴。","肸（原作「{肹八=丷}」）蠁似有聞，依俙（《雍州金石記》作「稀」，通。","）疑所覿。","髫年業文翰，弱冠薦屯厄。","天命幾微茫，神逵徒悚惕。","今來遊上國，幸遇陶唐曆。","正直不吾欺，願言從所適。","（見《金石萃編》卷一百五，以《惜陰軒叢書》《雍州金石記》校其異。","）（〖1〗石刻詩後原題《唐元和元年十月二十八日。","姪男宣義郎行華州參軍琡太和六年四月廿六日重修》。","〖2〗朱彝尊《曝書亭集》：元和元年十月，著作郎河南賈竦《謁華岳廟》賦五言詩題名。","太和六年四月，其姪男宣義郎行華州參軍事琡修之。","修之者，殆鋟之也。","詩題北周天和二年趙文淵書萬紐于瑾所撰《華岳頌》之左方，頌之陰，則開元八年劉升書咸廙所撰《精享昭應碑》也，其右勒顏真卿乾元元年題名。","工每椎拓三面而遺竦詩，以是流傳者寡。","然其詩特醇雅，顧圖經未之采焉。","〖3〗畢沅《關中金石記》卷四：「竦，賈餗兄。","據《宰相表》則竦官著作郎也，無姪琡名，可以補史之缺。","」〖4〗《金石萃編》王昶按：「賈竦，官著作郎，而此詩自題不署銜，則是未侍時作也。","竦爲餗之兄，餗居相位在文宗朝，當元和年官不過員外郎，未顯也。","玩竦詩有云：『髫年業文翰，弱冠薦屯厄。","今來遊上國，幸遇陶唐曆。","正直不吾欺，願言從所適』。","則顯然是未第而求神佑者。","此詩《全唐詩》未收，故無從詳考。","」）。"]', '["老柏寒颼颼，清祠晝寂寂。","开门华山北，嵐氣沉日夕。","国家崇明祀，五岳尽封冊。","福我西土民，報君金天籍。","惟神本貞信，以道徵損益。","無力惑聰明，訛言縱巫覡（原作「●●」）。","因循作风俗，相與成（《雍州金石記》作「旧」）溺。","疲病閭里甿，錐刀往来客。","（《雍州金石記》作「役」。","）我行歲云暮，登殿拜瑤席。","奠酒徹明靈，緒言多感激。","欝然展冠冕，凜若生矛戟。","斑駮石色重，陰深香煙碧。","虹梁無燕雀，玉座鎮虺蜴。","肸（原作「{肹八=丷}」）蠁似有闻，依俙（《雍州金石記》作「稀」，通。","）疑所覿。","髫年業文翰，弱冠薦屯厄。","天命幾微茫，神逵徒悚惕。","今来游上国，幸遇陶唐曆。","正直不吾欺，願言從所適。","（见《金石萃編》卷一百五，以《惜陰軒叢书》《雍州金石記》校其異。","）（〖1〗石刻诗後原題《唐元和元年十月二十八日。","姪男宣義郎行华州參軍琡太和六年四月廿六日重修》。","〖2〗朱彝尊《曝书亭集》：元和元年十月，著作郎河南賈竦《謁华岳廟》賦五言诗題名。","太和六年四月，其姪男宣義郎行华州參軍事琡修之。","修之者，殆鋟之也。","诗題北周天和二年趙文淵书万紐于瑾所撰《华岳頌》之左方，頌之陰，則开元八年劉升书咸廙所撰《精享昭應碑》也，其右勒顏真卿乾元元年題名。","工每椎拓三面而遺竦诗，以是流傳者寡。","然其诗特醇雅，顧圖經未之采焉。","〖3〗畢沅《关中金石記》卷四：「竦，賈餗兄。","據《宰相表》則竦官著作郎也，無姪琡名，可以補史之缺。","」〖4〗《金石萃編》王昶按：「賈竦，官著作郎，而此诗自題不署銜，則是未侍时作也。","竦爲餗之兄，餗居相位在文宗朝，當元和年官不過員外郎，未显也。","玩竦诗有云：『髫年業文翰，弱冠薦屯厄。","今来游上国，幸遇陶唐曆。","正直不吾欺，願言從所適』。","則显然是未第而求神佑者。","此诗《全唐诗》未收，故無從詳考。","」）。"]', '诗', 'shi', '', NULL, '謁華嶽廟 賈竦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca84ad38-8755-4f1e-b380-bccc999b83b7', '涇川野居晚望', '涇川野居晚望', 'bee722f1-1fa0-4244-8d62-1323d54ff2cf', '唐', '["地極接穹蒼，西維落太陽。","泉聲入深稻，山色出南崗。","風起蘆兼荻。","煙生柘與桑，歸來坐幽石，半壁冷蟾光。","（見《分門纂類唐歌詩》殘本第一冊《天地山川類》。","）。"]', '["地極接穹蒼，西維落太陽。","泉声入深稻，山色出南崗。","风起蘆兼荻。","煙生柘與桑，归来坐幽石，半壁冷蟾光。","（见《分门纂類唐歌诗》殘本第一冊《天地山川類》。","）。"]', '诗', 'shi', '', NULL, '涇川野居晚望 劉得仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f484ee42-1e04-4497-9b2c-17cee3fc3439', '白龍潭', '白龙潭', 'db013af4-821d-4c5c-84c5-a71a18c3b5ac', '唐', '["中有白龍盤，偷湫見說難。","風雲隨步起，雨雹出山寒。","鳥道懸青壁，天河瀉碧湍。","軒皇曾向此，金鼎煉還丹。"]', '["中有白龙盤，偷湫见说难。","风云隨步起，雨雹出山寒。","鸟道懸青壁，天河瀉碧湍。","軒皇曾向此，金鼎煉還丹。"]', '诗', 'shi', '', NULL, '白龍潭 繆島雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40fd3cb1-3658-4e7e-9a03-f57af83ab8aa', '遊黃山懷古', '游黄山懷古', 'db013af4-821d-4c5c-84c5-a71a18c3b5ac', '唐', '["浮丘與軒后，鶴馭杳難思。","三十六峯頂，不知何處奇。","枯杉龍腦溢，陰洞石膏垂。","莫問當時事，蒼苔鎖斷碑。"]', '["浮丘與軒后，鹤馭杳难思。","三十六峯頂，不知何处奇。","枯杉龙腦溢，陰洞石膏垂。","莫问當时事，蒼苔鎖斷碑。"]', '诗', 'shi', '', NULL, '遊黃山懷古 繆島雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02fc2f92-eb29-46cd-be7b-f57d14ab1fa1', '登天都峯', '登天都峯', 'db013af4-821d-4c5c-84c5-a71a18c3b5ac', '唐', '["盤空千萬仞，險若上丹梯。","迥入天都裏，回看鳥道低。","他山青點點，遠水白凄凄。","欲下前峯暝，巖間宿錦雞。"]', '["盤空千万仞，險若上丹梯。","迥入天都裏，回看鸟道低。","他山青点点，远水白凄凄。","欲下前峯暝，巖间宿錦雞。"]', '诗', 'shi', '', NULL, '登天都峯 繆島雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aed89c3c-defe-4b66-a44a-5f65ae8c1271', '馬跡石', '马跡石', 'db013af4-821d-4c5c-84c5-a71a18c3b5ac', '唐', '["堪信曾鸞駕，尋僊道已成。","因過盤石上，如印玉沙行。","苔逐方圓匝，泉隨深淺生。","臨迴山色暮，拂拂翠雲平。","。"]', '["堪信曾鸾駕，尋僊道已成。","因過盤石上，如印玉沙行。","苔逐方圓匝，泉隨深淺生。","臨迴山色暮，拂拂翠云平。","。"]', '诗', 'shi', '', NULL, '馬跡石 繆島雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50eb7566-0bb3-4a8f-a58f-7b0a69c1a882', '望黃山諸峯', '望黄山諸峯', 'db013af4-821d-4c5c-84c5-a71a18c3b5ac', '唐', '["峰峰寒列簇芙蕖，靜想嵩陽秀不如。","峭拔雖傳三十六，參差何啻一千餘。","浮丘處處留丹竃，黃帝層層隱玉書。","終待登臨最高頂，便隨鸞鶴五雲車。"]', '["峰峰寒列簇芙蕖，静想嵩陽秀不如。","峭拔雖傳三十六，參差何啻一千餘。","浮丘处处留丹竃，黄帝層層隐玉书。","終待登臨最高頂，便隨鸾鹤五云车。"]', '诗', 'shi', '', NULL, '望黃山諸峯 繆島雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('769bab0d-5322-431b-85ae-2a14be2c73c5', '湯泉', '湯泉', 'db013af4-821d-4c5c-84c5-a71a18c3b5ac', '唐', '["暖泛朱砂石壁幽，軒皇曾浴上丹丘。","陰陽相煮連珠浦，今古長煎瀉鏡流。","紫氣曉籠煙色澹，錦霞明照火光浮。","何方爲洗身輕後，便跨飛龍到十洲。"]', '["暖泛朱砂石壁幽，軒皇曾浴上丹丘。","陰陽相煮連珠浦，今古长煎瀉镜流。","紫氣晓籠煙色澹，錦霞明照火光浮。","何方爲洗身轻後，便跨飞龙到十洲。"]', '诗', 'shi', '', NULL, '湯泉 繆島雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f66e71ab-1ac5-4b7a-bd8b-6aead6cc415e', '朱砂石', '朱砂石', 'db013af4-821d-4c5c-84c5-a71a18c3b5ac', '唐', '["寒巖萬丈陟崔嵬，只恐朱砂勢便頹。","採蘩客聞雷擘去，臥雲僧見鳥銜來。","丹霞迥爍嵌空片，紅日斜分突兀堆。","儻得神僊惠纖粟，便能輕舉向瑤臺。"]', '["寒巖万丈陟崔嵬，只恐朱砂勢便頹。","採蘩客闻雷擘去，臥云僧见鸟銜来。","丹霞迥爍嵌空片，紅日斜分突兀堆。","儻得神僊惠纖粟，便能轻舉向瑤台。"]', '诗', 'shi', '', NULL, '朱砂石 繆島雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2826f893-d4af-4160-8cf8-86b09e3660f2', '石人峯', '石人峯', 'db013af4-821d-4c5c-84c5-a71a18c3b5ac', '唐', '["雙峯何代列巍巍，忽化僊人世所稀。","絕頂長年相對坐，九天何日却同歸。","風生松柏喧天樂，山隱雲霞挂道衣。","終願捫蘿一相訪，共君齊跨鳯鸞飛。"]', '["雙峯何代列巍巍，忽化僊人世所稀。","絕頂长年相对坐，九天何日却同归。","风生松柏喧天乐，山隐云霞挂道衣。","終願捫蘿一相訪，共君齊跨鳯鸾飞。"]', '诗', 'shi', '', NULL, '石人峯 繆島雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e1263bf-14bd-4de4-941e-9d129214e49e', '僊僧洞', '僊僧洞', 'db013af4-821d-4c5c-84c5-a71a18c3b5ac', '唐', '["先朝曾有日東僧，向此乘龍忽上昇。","石徑已迷紅樹密，蘿龕猶在紫雲凝。","鉢盂峯下留丹竃，錫杖前邊隱聖燈。","從此舊庵遺跡畔，月樓霜殿一層層。","。"]', '["先朝曾有日东僧，向此乘龙忽上昇。","石徑已迷紅樹密，蘿龕猶在紫云凝。","鉢盂峯下留丹竃，錫杖前邊隐聖灯。","從此旧庵遺跡畔，月楼霜殿一層層。","。"]', '诗', 'shi', '', NULL, '僊僧洞 繆島雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('188acf91-fb17-49d8-8d83-199775bae8f7', '僊橋', '僊橋', 'db013af4-821d-4c5c-84c5-a71a18c3b5ac', '唐', '["千丈側懸飛鳥外，雙峯橫架碧天心。","月中纔有僊人過，山下應聞笙磬音。","丹竃路穿瑤草濕，朱砂泉迸錦霞深。","軒轅去後雖然在，爭奈凡流無處尋。","（以上十首均見康熙十八年閔麟嗣撰《黃山志定本》卷六。","）（〖1〗繆島雲逸詩承儀徵吳白匋先生見告。","）。"]', '["千丈側懸飞鸟外，雙峯橫架碧天心。","月中纔有僊人過，山下應闻笙磬音。","丹竃路穿瑤草濕，朱砂泉迸錦霞深。","軒轅去後雖然在，爭奈凡流無处尋。","（以上十首均见康熙十八年閔麟嗣撰《黄山志定本》卷六。","）（〖1〗繆島云逸诗承儀徵吳白匋先生见告。","）。"]', '诗', 'shi', '', NULL, '僊橋 繆島雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e16e960d-f066-45e2-8772-a88b5fa09c2d', '覽卷贈張山人', '覽卷贈張山人', '5cd52905-b045-47c2-85ac-1ed3560eea06', '唐', '["五字誰能摘？一枝猶未攀。","始知無價玉，出自有名山。","春靜烟花秀，夜深風月閑。","如何恃高節，垂老住雲間。","（見《永樂大典》卷三○○四「九真」「人」字〖五函四十一冊〗。","）。"]', '["五字誰能摘？一枝猶未攀。","始知無價玉，出自有名山。","春静烟花秀，夜深风月闲。","如何恃高節，垂老住云间。","（见《永乐大典》卷三○○四「九真」「人」字〖五函四十一冊〗。","）。"]', '诗', 'shi', '', NULL, '覽卷贈張山人 趙嘏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d68b75ec-b677-4283-9ef5-35294e4f7316', '惠泉', '惠泉', '17e221a5-3350-4a05-8c6d-44d628060203', '唐', '["璞玉耀荆山，山根竇玉泉。","有聲清出籟，凝色碧於天。","曉靜微涵日，春晴淺浸煙。","巖花紅影密，啼鳥下沙壖。","（見《湖北金石志》。","）（〖1〗詩末原題「寶曆□年二月廿一日」九字。","〖2〗《湖北金石志》：「案石碑高二尺四寸，寬三尺一寸，首行書『惠泉』二字，次行漫漶莫辨，當是作詩人姓名。","中六行行書五律一首云〖詩不重錄〗。","末行書『寶曆□年二月廿一日』，字徑二寸許。","案鄭漁仲《金石畧》載荆門軍有宇文鼎《惠泉詩》。","新舊《唐書》無鼎傳，《全唐詩》亦未之及。","是刻雖闕其名，然以年號與鄭氏所載證之，詩爲文鼎作無疑。","唐代詩人湮沒無聞者，正復不少，今荆門象山石壁留此《惠泉》詩刻，以傳文鼎之名，不可謂非幸矣。","」）。"]', '["璞玉耀荆山，山根竇玉泉。","有声清出籟，凝色碧於天。","晓静微涵日，春晴淺浸煙。","巖花紅影密，啼鸟下沙壖。","（见《湖北金石志》。","）（〖1〗诗末原題「寶曆□年二月廿一日」九字。","〖2〗《湖北金石志》：「案石碑高二尺四寸，寬三尺一寸，首行书『惠泉』二字，次行漫漶莫辨，當是作诗人姓名。","中六行行书五律一首云〖诗不重錄〗。","末行书『寶曆□年二月廿一日』，字徑二寸許。","案鄭漁仲《金石畧》載荆门軍有宇文鼎《惠泉诗》。","新旧《唐书》無鼎傳，《全唐诗》亦未之及。","是刻雖闕其名，然以年號與鄭氏所載證之，诗爲文鼎作無疑。","唐代诗人湮沒無闻者，正复不少，今荆门象山石壁留此《惠泉》诗刻，以傳文鼎之名，不可謂非幸矣。","」）。"]', '诗', 'shi', '', NULL, '惠泉 宇文鼎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16598afb-e829-460d-8f4d-4cb6298e9a7d', '聳翠峰題石（原注：峯在袁州府城西三十里。）', '聳翠峰題石（原注：峯在袁州府城西三十里。）', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["聳翠峰高千百尺，四時常似莓藍色。","卓然萬古鎮祗園，世代鬼工驅不得。","巍巍直上插青天，遠疑似與天相連。","韎臨下視羣山小，千里平鋪在眼（一作「目」）前。","藤蔓交加生薜荔，土毛蒼蘚相蒙蔽。","風翦雲開雨歇時，飛出一山新翡翠。","日迴影倒落前溪，煙波湛湛浸琉璃。","更將何物可比類，分明一隻擎天柱。"]', '["聳翠峰高千百尺，四时常似莓藍色。","卓然万古鎮祗园，世代鬼工驱不得。","巍巍直上插青天，远疑似與天相連。","韎臨下視羣山小，千里平鋪在眼（一作「目」）前。","藤蔓交加生薜荔，土毛蒼蘚相蒙蔽。","风翦云开雨歇时，飞出一山新翡翠。","日迴影倒落前溪，煙波湛湛浸琉璃。","更將何物可比類，分明一隻擎天柱。"]', '诗', 'shi', '', NULL, '聳翠峰題石（原注：峯在袁州府城西三十里。） 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('576d0850-5a8b-4275-ab24-45f723a7330a', '綠陰亭', '綠陰亭', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["亭邊古木晝陰陰，亭下寒潭百丈深。","黃菊近連陶令宅，青山遙負（一作「償」）向平心。","人歸別浦村煙斂，魚躍澄波檻水沈。","更愛玉琴調惠政，爲君登此一開襟。","（按《全唐詩》止有前四句，今從《臨江府志》錄全。","）（《全唐詩續補遺》卷十據《隆慶臨江府志》卷十三收此詩，題下注：「在新喻縣右，俯臨袁江。","」「亭邊」作「亭間」，「百丈」作「百尺」，「近連」作「舊連」，「向平」作「子平」，「檻水」作「檻影」。","今刪彼存此。","）。"]', '["亭邊古木晝陰陰，亭下寒潭百丈深。","黄菊近連陶令宅，青山遙負（一作「償」）向平心。","人归別浦村煙斂，鱼躍澄波檻水沈。","更愛玉琴調惠政，爲君登此一开襟。","（按《全唐诗》止有前四句，今從《臨江府志》錄全。","）（《全唐诗續補遺》卷十據《隆慶臨江府志》卷十三收此诗，題下注：「在新喻縣右，俯臨袁江。","」「亭邊」作「亭间」，「百丈」作「百尺」，「近連」作「旧連」，「向平」作「子平」，「檻水」作「檻影」。","今刪彼存此。","）。"]', '诗', 'shi', '', NULL, '綠陰亭 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc0d859d-e13c-4ea7-88e8-b7735d131dc9', '弔進士楊鄴', '弔進士楊鄴', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["名未榮身親在堂，九重泉路去何忙。","夫妻鏡裏鸞分影，兄弟雲中雁斷行。","林木蕭疏花失色，池亭牢落月無光。","思君欲向靈山哭，又恐猿聞更斷腸。"]', '["名未榮身親在堂，九重泉路去何忙。","夫妻镜裏鸾分影，兄弟云中雁斷行。","林木蕭疏花失色，池亭牢落月無光。","思君欲向靈山哭，又恐猿闻更斷腸。"]', '诗', 'shi', '', NULL, '弔進士楊鄴 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4acbee46-fbf2-4b4e-b740-f98ed3ae0a1f', '戲宜春李令求廳前杜鵑', '戲宜春李令求廳前杜鵑', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["杜家有女小名鵑，生在陶公吏案前。","百里望風驚調態，千金買笑愜當筵。","預防戶外鋤蘭地，莫把籬東種菊田。","爲問河陽妖艷主，聘財卻（一作「都」）要幾多錢？","（以上四詩均見《豫章叢書》《袁州二唐人集》中《文標集》卷下。","）。"]', '["杜家有女小名鵑，生在陶公吏案前。","百里望风驚調態，千金買笑愜當筵。","預防戶外鋤蘭地，莫把籬东種菊田。","爲问河陽妖艷主，聘財卻（一作「都」）要幾多錢？","（以上四诗均见《豫章叢书》《袁州二唐人集》中《文標集》卷下。","）。"]', '诗', 'shi', '', NULL, '戲宜春李令求廳前杜鵑 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cf02b7f-f3b8-44b5-8ea0-8574d7f14b6a', '句', '句', '3c13c090-c22b-45cc-b589-0c760f59e11a', '唐', '["羣烏幸胙餘。","（見宋陸游《入蜀記》卷六。","）（〖1〗《入蜀記》卷六頁十一〖《知不足齋叢書》本〗：「祠舊有烏數百，送迎客舟。","自唐夔州刺史李貽孫詩已云羣烏幸胙餘矣。","」〖2〗李貽孫，原作李貽。","李貽孫曾官夔州刺史，《全唐文》卷五四四收其會昌五年撰《夔州都督府記》，《金石錄》卷九著錄會昌五年九月「唐李貽孫《神女廟詩》」。","陸游在述巫山神女祠中景物時引及此句，應即《神女廟詩》之殘句。","）（兩《唐書》無李貽孫傳，今參張忱石所考，補傳如次：李貽孫，字里不詳。","大和初任福建團練副使，會昌五年爲夔州刺史，大中三年任左諫議大夫充宏文館學士，大中五年任福建觀察使。","又曾任金部、司勳員外郎。","約卒于大中六年後。","原列「無考」作者，今移此。","）。"]', '["羣烏幸胙餘。","（见宋陸游《入蜀記》卷六。","）（〖1〗《入蜀記》卷六頁十一〖《知不足斋叢书》本〗：「祠旧有烏數百，送迎客舟。","自唐夔州刺史李貽孫诗已云羣烏幸胙餘矣。","」〖2〗李貽孫，原作李貽。","李貽孫曾官夔州刺史，《全唐文》卷五四四收其會昌五年撰《夔州都督府記》，《金石錄》卷九著錄會昌五年九月「唐李貽孫《神女廟诗》」。","陸游在述巫山神女祠中景物时引及此句，應即《神女廟诗》之殘句。","）（兩《唐书》無李貽孫傳，今參張忱石所考，補傳如次：李貽孫，字里不詳。","大和初任福建團練副使，會昌五年爲夔州刺史，大中三年任左諫議大夫充宏文館学士，大中五年任福建观察使。","又曾任金部、司勳員外郎。","約卒于大中六年後。","原列「無考」作者，今移此。","）。"]', '诗', 'shi', '', NULL, '句 李貽孫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d338455-830f-4a45-bfc6-0a62d26da8e0', '新安郡北百餘里即黃山西北有山峯高出頗類大華因目爲小華山前郡守才客題詠至多偶登斯樓因成一絕', '新安郡北百餘里即黄山西北有山峯高出頗類大华因目爲小华山前郡守才客題詠至多偶登斯楼因成一絕', '5e202884-afa3-4947-b8aa-6c196f5649ff', '唐', '["雪晴雨霽潼關道，僊掌分明幾度逢。","可料新安郡樓上，黃山深處見三峯。","（見康熙十八年閔麟嗣撰《黃山志定本》卷六。","）。"]', '["雪晴雨霽潼关道，僊掌分明幾度逢。","可料新安郡楼上，黄山深处见三峯。","（见康熙十八年閔麟嗣撰《黄山志定本》卷六。","）。"]', '诗', 'shi', '', NULL, '新安郡北百餘里即黃山西北有山峯高出頗類大華因目爲小華山前郡守才客題詠至多偶登斯樓因成一絕 任宇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da97fe48-3ea1-42bd-b08f-9b7f5efe5c26', '', '', '8a5cfab5-6b1d-46b4-9f43-4b04be6c51db', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 裴休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d326c8d9-75d5-4000-8888-9f0e2f222838', '太平興龍寺詩（題擬）', '太平兴龙寺诗（題擬）', '8a5cfab5-6b1d-46b4-9f43-4b04be6c51db', '唐', '["麟臺朝士辭書府，鳯闕禪宗出帝京。","當堰雙林親惠遠，行過五老訪淵明。","白衣居士輕班爵，敗衲高僧薄世情。","引得病夫無外想，一身師事竺先生。","（見《永樂大典》卷六六九九。","十八陽。","江字（七函六十四冊）。","餘參閱本書卷三崔融詩附注。","此詩又見《吉石庵叢書》本陳舜俞《廬山記》卷四，原題甚長。","岑仲勉《唐方鎮年表正補》考證應爲裴坦作，是。","另詳《全唐詩續拾》卷三十二。","）。"]', '["麟台朝士辞书府，鳯闕禪宗出帝京。","當堰雙林親惠远，行過五老訪淵明。","白衣居士轻班爵，敗衲高僧薄世情。","引得病夫無外想，一身師事竺先生。","（见《永乐大典》卷六六九九。","十八陽。","江字（七函六十四冊）。","餘參閱本书卷三崔融诗附注。","此诗又见《吉石庵叢书》本陳舜俞《廬山記》卷四，原題甚长。","岑仲勉《唐方鎮年表正補》考證應爲裴坦作，是。","另詳《全唐诗續拾》卷三十二。","）。"]', '诗', 'shi', '', NULL, '太平興龍寺詩（題擬） 裴休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c0f46bb-10f5-4850-9b20-91e24f1dff9f', '白鶴觀水閣題詩（題擬）', '白鹤观水閣題诗（題擬）', '2c3f2d04-c552-4061-bc3f-386a43dfdf2f', '唐', '["松陰如幄水如羅，秋盡山青白鳥過。","獨坐一庵心正寂，數聲何處竹枝歌。","（見《永樂大典》卷二三四三「六模」「梧」字「梧州府」引《輿地紀勝》云「白鶴觀在州西。","咸通末，鄭畋守蒼梧，建水閣，題詩」。","）（此詩見《太平寰宇記》卷一六四、《輿地紀勝》卷一○八。","）。"]', '["松陰如幄水如羅，秋尽山青白鸟過。","独坐一庵心正寂，數声何处竹枝歌。","（见《永乐大典》卷二三四三「六模」「梧」字「梧州府」引《輿地紀勝》云「白鹤观在州西。","咸通末，鄭畋守蒼梧，建水閣，題诗」。","）（此诗见《太平寰宇記》卷一六四、《輿地紀勝》卷一○八。","）。"]', '诗', 'shi', '', NULL, '白鶴觀水閣題詩（題擬） 鄭畋 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6dd09de2-74fb-404a-885b-4e9cd16af659', '', '', '39ab9ff0-9bf5-42c6-954f-dc5eb0a7d8dc', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 張濬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d34f75a-2bc1-44b2-8177-82c898b3b14a', '山居洞前得杜鵑花走筆偶成以□（八瓊室本作「簡」）桂帥僕射兼寄呈廣州僕射劉公', '山居洞前得杜鵑花走笔偶成以□（八瓊室本作「簡」）桂帥僕射兼寄呈廣州僕射劉公', '39ab9ff0-9bf5-42c6-954f-dc5eb0a7d8dc', '唐', '["桂（八瓊室本作「幄」）中籌策知無暇，洞裏□花別有珍（八瓊室本作「春」。","）獨酌高吟問山水，到頭山景屬何（八瓊室本作「閑」）人。","（見《金石續編》卷十二，又見《八瓊室金石補正》卷七十七。","）（桂林市文管會近年普查石刻，編爲《桂林石刻》三冊，第一冊收此詩較完整。","題中「以□」二字作「用別」，前二句異文均同《八瓊室金石補正》，「□花」作「觀花」，末句「何人」作「詩人」。","）（按石刻於詩題下原署曰「河間張濬」。","又此詩之後有嶺南節度使劉崇龜和詩一首，《全唐詩》卷七百十五收之。","石刻於劉詩之後有「韓寧元年三月廿七日將仕郎前守監察御史張巖書」一行。","《廣西通志·金石略》謂石刻在臨桂龍隱巖下。","）。"]', '["桂（八瓊室本作「幄」）中籌策知無暇，洞裏□花別有珍（八瓊室本作「春」。","）独酌高吟问山水，到头山景屬何（八瓊室本作「闲」）人。","（见《金石續編》卷十二，又见《八瓊室金石補正》卷七十七。","）（桂林市文管會近年普查石刻，編爲《桂林石刻》三冊，第一冊收此诗較完整。","題中「以□」二字作「用別」，前二句異文均同《八瓊室金石補正》，「□花」作「观花」，末句「何人」作「诗人」。","）（按石刻於诗題下原署曰「河间張濬」。","又此诗之後有嶺南節度使劉崇龟和诗一首，《全唐诗》卷七百十五收之。","石刻於劉诗之後有「韓寧元年三月廿七日將仕郎前守監察御史張巖书」一行。","《廣西通志·金石略》謂石刻在臨桂龙隐巖下。","）。"]', '诗', 'shi', '', NULL, '山居洞前得杜鵑花走筆偶成以□（八瓊室本作「簡」）桂帥僕射兼寄呈廣州僕射劉公 張濬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0c0f19e-3d90-4701-beb6-075b8b397074', '送凌處士赴連州邀', '送凌处士赴連州邀', 'b5d2ead8-ce44-47da-a2af-94bc6846601c', '唐', '["連山羣書至，策馬出長安。","落日對酒別，晚關衝雪寒。","霜飛湖草綠，春近嶺梅殘。","知己雲霄在，那言欲掛冠。","（見北京圖書館藏《永樂大典》卷一三四五○「二寘」「處士」條。","）（按唐有兩李濤，其一長沙人，與溫庭筠同時，《全唐詩》卷七百九十五收詩句六句。","其一字信臣，避地湖南，事馬殷，後唐天成中進士，歷仕晉、漢，至宰輔，入周，封莒國公，後歸宋，《全唐詩》卷七百三十七收詩一首，又卷八百七十《諧謔二》收詩一自，卷八百七十一《諧謔三》收歇後語兩句。","此李濤頗疑係溫庭筠同時之李濤。","）。"]', '["連山羣书至，策马出长安。","落日对酒別，晚关衝雪寒。","霜飞湖草綠，春近嶺梅殘。","知己云霄在，那言欲掛冠。","（见北京圖书館藏《永乐大典》卷一三四五○「二寘」「处士」條。","）（按唐有兩李濤，其一长沙人，與溫庭筠同时，《全唐诗》卷七百九十五收诗句六句。","其一字信臣，避地湖南，事马殷，後唐天成中進士，歷仕晉、漢，至宰輔，入周，封莒国公，後归宋，《全唐诗》卷七百三十七收诗一首，又卷八百七十《諧謔二》收诗一自，卷八百七十一《諧謔三》收歇後語兩句。","此李濤頗疑係溫庭筠同时之李濤。","）。"]', '诗', 'shi', '', NULL, '送凌處士赴連州邀 李濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c23eb99-403d-4bea-bf4d-f72a14dd9ef4', '奉和元孚大德（亦依本韵）', '奉和元孚大德（亦依本韵）', '4123c865-33fb-4921-af3d-58e532774990', '唐', '["華頂高峯接太虛，承攀琪樹賦垂珠。","當時惟有建公在，老宿如今一半無。","（見明陶宗儀《古刻叢鈔》，與元孚詩同刻一石。","）（案詩原署「中散大夫行台州司馬賜魚袋王謩幷書」。","又刻後紀「唐大中九年歲次乙亥八月丁丑朔六日壬午重題，以紀他年之事」，共廿六字。","）。"]', '["华頂高峯接太虛，承攀琪樹賦垂珠。","當时惟有建公在，老宿如今一半無。","（见明陶宗儀《古刻叢鈔》，與元孚诗同刻一石。","）（案诗原署「中散大夫行台州司马賜鱼袋王謩幷书」。","又刻後紀「唐大中九年歲次乙亥八月丁丑朔六日壬午重題，以紀他年之事」，共廿六字。","）。"]', '诗', 'shi', '', NULL, '奉和元孚大德（亦依本韵） 王謩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5321fbf7-e8e5-4458-a12d-8627f8a94d53', '句', '句', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, '句 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54f295e5-7eed-4deb-8f79-e3b77d9f4795', '句 一', '句 一', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["手栽桃李十餘春，今日經過重建勳。","（《經虢縣》。","見崔致遠《桂苑筆耕集》卷十七《磻溪》詩自注引高駢句。","）。"]', '["手栽桃李十餘春，今日經過重建勳。","（《經虢縣》。","见崔致远《桂苑笔耕集》卷十七《磻溪》诗自注引高駢句。","）。"]', '诗', 'shi', '', NULL, '句 一 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('233a42cf-c75c-4583-bbfe-f70e8dab9f70', '句 二', '句 二', '38432d51-6b73-41d2-8df1-71c52aea0667', '唐', '["水急魚難釣，風吹柳易低。","（《釣魚亭》。","見《桂苑筆耕集》卷十七崔致遠《釣魚亭》詩自注引高駢句。","參閱本書第十九卷崔致遠詩集。","）。"]', '["水急鱼难釣，风吹柳易低。","（《釣鱼亭》。","见《桂苑笔耕集》卷十七崔致远《釣鱼亭》诗自注引高駢句。","參閱本书第十九卷崔致远诗集。","）。"]', '诗', 'shi', '', NULL, '句 二 高駢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35d3759d-8cb2-41e5-bebb-012b7ada9569', '題朝陽洞', '題朝陽洞', '3f88f6d2-c039-4ee1-a032-d0ef1e4d9278', '唐', '["江上朝陽洞，無人肯暫過。","今來愜心賞，迴首戀煙蘿。","（見《八瓊室金石補正》。","）（〖1〗石刻於詩題下署「義陽守李當」五字。","餘說詳魏深詩按語。","）。"]', '["江上朝陽洞，無人肯暫過。","今来愜心賞，迴首戀煙蘿。","（见《八瓊室金石補正》。","）（〖1〗石刻於诗題下署「義陽守李當」五字。","餘说詳魏深诗按語。","）。"]', '诗', 'shi', '', NULL, '題朝陽洞 李當 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('571cb80c-5084-475c-8054-291ff776c4ea', '奉和左丞八舅題朝陽洞', '奉和左丞八舅題朝陽洞', 'a7433526-00d0-496a-84ad-f33dc1560555', '唐', '["北闕飛新詔，東山喜更過。","文星動巖夢，章句別杉蘿。","（見《八瓊室金石補正》。","）（〖1〗望按：碑刻幷有魏深《書事》，畧敍李當嘗自中書舍人問俗湖南，後除戶部侍郎，尋出尹河南。","移宣□，鎮褒斜，旋拜天官氏，歲餘，除尚書左丞。","於時奸臣竊柄，凡不附者悉遭摒斥，由是出牧道州。","道州山民起事，當以書招諭之，）（不勞尺刃而山民順之云云。","又按《書事》中謂奸臣竊柄，蓋指路巖及韋保衡諸人。","路，《新唐書》有傳，與韋皆懿宗、僖宗時人。","又石刻于詩題下署曰「從甥前□州軍事判官鄉貢進士魏深」。","〖光緒《湖南通志·金石六》云此句缺字「似高字」。","《唐文續拾》卷六小傳作「道州軍事判官」，似據文意推測。","〗〖2〗陸增祥《八瓊室金石補正》卷六十：案《金石錄目》：「李舟《朝陽岩詩》，大曆十三年九月，李當、牛嵸詩附。","」自大曆十三年至咸通十四年，相距九十餘載，此題之李當，蓋別一人也。","《唐書·宰相世系表》姑臧大房有李當，官至刑部尚書，時代亦相近，當即此題詩之人。","〖3〗望又按：牛嵸，《全唐詩》作牛叢，其題朝陽岩詩，見《全唐詩》卷五百四十二。","李舟《朝陽岩詩》未見。","）。"]', '["北闕飞新詔，东山喜更過。","文星动巖梦，章句別杉蘿。","（见《八瓊室金石補正》。","）（〖1〗望按：碑刻幷有魏深《书事》，畧敍李當嘗自中书舍人问俗湖南，後除戶部侍郎，尋出尹河南。","移宣□，鎮褒斜，旋拜天官氏，歲餘，除尚书左丞。","於时奸臣竊柄，凡不附者悉遭摒斥，由是出牧道州。","道州山民起事，當以书招諭之，）（不勞尺刃而山民順之云云。","又按《书事》中謂奸臣竊柄，蓋指路巖及韋保衡諸人。","路，《新唐书》有傳，與韋皆懿宗、僖宗时人。","又石刻于诗題下署曰「從甥前□州軍事判官乡貢進士魏深」。","〖光緒《湖南通志·金石六》云此句缺字「似高字」。","《唐文續拾》卷六小傳作「道州軍事判官」，似據文意推測。","〗〖2〗陸增祥《八瓊室金石補正》卷六十：案《金石錄目》：「李舟《朝陽岩诗》，大曆十三年九月，李當、牛嵸诗附。","」自大曆十三年至咸通十四年，相距九十餘載，此題之李當，蓋別一人也。","《唐书·宰相世系表》姑臧大房有李當，官至刑部尚书，时代亦相近，當即此題诗之人。","〖3〗望又按：牛嵸，《全唐诗》作牛叢，其題朝陽岩诗，见《全唐诗》卷五百四十二。","李舟《朝陽岩诗》未见。","）。"]', '诗', 'shi', '', NULL, '奉和左丞八舅題朝陽洞 魏深 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('180b0f3c-58bf-47b2-8eeb-1adf2055ef18', '省題詩二十一首 天驥呈才', '省題诗二十一首 天驥呈才', '1d55eb85-1c8e-41fb-96a6-cb30e0e600f7', '唐', '["馬知因聖出，才本自天生。","駔駿何煩隱，權奇願盡呈。","電從雙眼落，雲向四蹄輕。","過去王良喜，嘶來伯樂驚。","絕塵慚逸步，曳練議能名。","唯待金鞭下，春風紫陌情。"]', '["马知因聖出，才本自天生。","駔駿何煩隐，權奇願尽呈。","電從雙眼落，云向四蹄轻。","過去王良喜，嘶来伯乐驚。","絕塵慚逸步，曳練議能名。","唯待金鞭下，春风紫陌情。"]', '诗', 'shi', '', NULL, '省題詩二十一首 天驥呈才 王棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec340e6a-bf9d-45da-b657-23bc4c773464', '省題詩二十一首 上德不德', '省題诗二十一首 上德不德', '1d55eb85-1c8e-41fb-96a6-cb30e0e600f7', '唐', '["何從稱上德，捨德德方全。","聖者如非聖，賢者不自賢。","海甯言我廣，神豈謂予玄。","伐善功難立，無爲化易宣。","[道]惟聞邃古，理亦愧先天。","欲述猶龍旨，應忘得意筌。"]', '["何從稱上德，捨德德方全。","聖者如非聖，賢者不自賢。","海甯言我廣，神豈謂予玄。","伐善功难立，無爲化易宣。","[道]惟闻邃古，理亦愧先天。","欲述猶龙旨，應忘得意筌。"]', '诗', 'shi', '', NULL, '省題詩二十一首 上德不德 王棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f551b6d-17d6-4de8-8854-af24a4b24e00', '省題詩二十一首 農祥晨正', '省題诗二十一首 農祥晨正', '1d55eb85-1c8e-41fb-96a6-cb30e0e600f7', '唐', '["玉律方移候，農祥已向晨。","昭回當午地，皎潔向天津。","北陸收殘凍，東臯見早春。","影浮佳氣動，光射曙雲新。","千畝功將起，三推禮欲申。"]', '["玉律方移候，農祥已向晨。","昭回當午地，皎潔向天津。","北陸收殘凍，东臯见早春。","影浮佳氣动，光射曙云新。","千畝功將起，三推禮欲申。"]', '诗', 'shi', '', NULL, '省題詩二十一首 農祥晨正 王棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('569c3ddd-64e4-4e8d-8848-e65dd8c24078', '省題詩二十一首 詠白', '省題诗二十一首 詠白', '1d55eb85-1c8e-41fb-96a6-cb30e0e600f7', '唐', '["非青玄赤黃，正色配金方。","魚表周王德，麟呈漢帝祥。","寒來邊草遠，春至嶺梅芳。","曳練聞良馬，銜鉤見瑞狼。","張蒼肥似瓠，潘岳鬢如霜。","虛室能生後，方知守黑長。"]', '["非青玄赤黄，正色配金方。","鱼表周王德，麟呈漢帝祥。","寒来邊草远，春至嶺梅芳。","曳練闻良马，銜鉤见瑞狼。","張蒼肥似瓠，潘岳鬢如霜。","虛室能生後，方知守黑长。"]', '诗', 'shi', '', NULL, '省題詩二十一首 詠白 王棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b659cc66-8238-432b-b46c-0616e66d342d', '省題詩二十一首 詠菊', '省題诗二十一首 詠菊', '1d55eb85-1c8e-41fb-96a6-cb30e0e600f7', '唐', '["秋來多野菊，節應[有]黃花。","閒葉玉如栗，滿藂金出沙。","池邊迷瑞鵠，洞裏悟仙牙。","蘂散非紅豓，香飄異[綺]葩。","贈詩宜魏帝，泛酒稱陶家。","明日登高處，期君手不賒。"]', '["秋来多野菊，節應[有]黄花。","閒葉玉如栗，满藂金出沙。","池邊迷瑞鵠，洞裏悟仙牙。","蘂散非紅豓，香飄異[綺]葩。","贈诗宜魏帝，泛酒稱陶家。","明日登高处，期君手不賒。"]', '诗', 'shi', '', NULL, '省題詩二十一首 詠菊 王棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9021ba83-ce75-469e-993a-e16b7bfefc4a', '省題詩二十一首 詠清', '省題诗二十一首 詠清', '1d55eb85-1c8e-41fb-96a6-cb30e0e600f7', '唐', '["潔澈浮天色，鏘洋入樂聲。","露零金掌滿，冰結玉壼盈。","屏障排雲母，簾櫳動水精。","南山秋雨霽，北牖晚風生。","裴楷當年意，胡威近日名。","未知堯舜化，寰宇一時清。","。"]', '["潔澈浮天色，鏘洋入乐声。","露零金掌满，冰結玉壼盈。","屏障排云母，簾櫳动水精。","南山秋雨霽，北牖晚风生。","裴楷當年意，胡威近日名。","未知堯舜化，寰宇一时清。","。"]', '诗', 'shi', '', NULL, '省題詩二十一首 詠清 王棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abac1e3c-0a22-469d-9ab3-e3fd1ccc2134', '省題詩二十一首 月前菊', '省題诗二十一首 月前菊', '1d55eb85-1c8e-41fb-96a6-cb30e0e600f7', '唐', '["秋菊近重陽，原頭復道旁。","藂滋寒露綠，花綻晚風黃。","蘗染枝枝豔，星分處處芳。","乍疑金散野，遙誤葉經霜。","籬下何人採，罇中滿座香。","唯應未歸客，對此欲沾裳。"]', '["秋菊近重陽，原头复道旁。","藂滋寒露綠，花綻晚风黄。","蘗染枝枝豔，星分处处芳。","乍疑金散野，遙誤葉經霜。","籬下何人採，罇中满座香。","唯應未归客，对此欲沾裳。"]', '诗', 'shi', '', NULL, '省題詩二十一首 月前菊 王棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf693e4c-b030-4dcf-9db6-ccc146886660', '省題詩二十一首 上巳日曲江錫宴羣臣', '省題诗二十一首 上巳日曲江錫宴羣臣', '1d55eb85-1c8e-41fb-96a6-cb30e0e600f7', '唐', '["池散暮春景，君垂晞露恩。","妙音迴舜樂，濃味降堯罇。","詔出傾蘭省，筵開對杏園。","輕漣搖彩艦，芳草映華軒。","禊事輝朝曲，歡聲徹帝門。","常陪觀者列，低首望餘暄。"]', '["池散暮春景，君垂晞露恩。","妙音迴舜乐，濃味降堯罇。","詔出傾蘭省，筵开对杏园。","轻漣搖彩艦，芳草映华軒。","禊事輝朝曲，歡声徹帝门。","常陪观者列，低首望餘暄。"]', '诗', 'shi', '', NULL, '省題詩二十一首 上巳日曲江錫宴羣臣 王棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('255a7cbd-21a0-4702-85d2-606982dc99b5', '省題詩二十一首 甸服耆舊望籍千畝', '省題诗二十一首 甸服耆旧望籍千畝', '1d55eb85-1c8e-41fb-96a6-cb30e0e600f7', '唐', '["不展三推禮，如今已幾年。","郊畿春又至，父老頸空延。","扶杖溝塍側，傾心日月邊。","[望恩]情倍百，流目地方千。","未覩公卿從，長愁犬馬先。","幸同黃耇意，因此願聞天。"]', '["不展三推禮，如今已幾年。","郊畿春又至，父老頸空延。","扶杖溝塍側，傾心日月邊。","[望恩]情倍百，流目地方千。","未覩公卿從，长愁犬马先。","幸同黄耇意，因此願闻天。"]', '诗', 'shi', '', NULL, '省題詩二十一首 甸服耆舊望籍千畝 王棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d724b13-091d-4c81-baeb-caeac0182cca', '省題詩二十一首 曉日禁林聞清漏', '省題诗二十一首 晓日禁林闻清漏', '1d55eb85-1c8e-41fb-96a6-cb30e0e600f7', '唐', '["曉過宮垣側，猶聞漏水頻。","清音傳五夜，山影值三春。","露碎金壺滴，風和玉佩振。","依稀連鳯沼，髣髴辨雞人。","溫樹初凝霧，彤闈漸向晨。","若非鴛鷺伴，誰此繼香塵。"]', '["晓過宮垣側，猶闻漏水頻。","清音傳五夜，山影值三春。","露碎金壺滴，风和玉佩振。","依稀連鳯沼，髣髴辨雞人。","溫樹初凝霧，彤闈漸向晨。","若非鴛鷺伴，誰此繼香塵。"]', '诗', 'shi', '', NULL, '省題詩二十一首 曉日禁林聞清漏 王棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('411d292d-e202-49ff-9167-5e4946faf555', '省題詩二十一首 未明求衣', '省題诗二十一首 未明求衣', '1d55eb85-1c8e-41fb-96a6-cb30e0e600f7', '唐', '["夙夜甯無準，憂勤事萬機。","良宵猶未曙，深殿早求衣。","長樂鐘纔動，華胥夢已歸。","絲綸傳紫禁，黼黻進彤闈。","被處燭仍在，垂時星始稀。","豈（一作「恭」）惟漢文帝，因此致巍巍。","。"]', '["夙夜甯無準，憂勤事万機。","良宵猶未曙，深殿早求衣。","长乐鐘纔动，华胥梦已归。","絲綸傳紫禁，黼黻進彤闈。","被处燭仍在，垂时星始稀。","豈（一作「恭」）惟漢文帝，因此致巍巍。","。"]', '诗', 'shi', '', NULL, '省題詩二十一首 未明求衣 王棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b924327-8d39-4fe3-a3d2-ed0ec225571c', '省題詩二十一首 寒雨滴空階', '省題诗二十一首 寒雨滴空階', '1d55eb85-1c8e-41fb-96a6-cb30e0e600f7', '唐', '["霏霏飄永夜，滴滴落空階。","自有路歧恨，那堪離別懷。","簷前聲乍碎，枕畔夢全乖。","遠與巖泉雜，微將漏水諧。","天涯思舊友，法上憶閒齋。","坐到空庭曉，殘雲帶石崖。"]', '["霏霏飄永夜，滴滴落空階。","自有路歧恨，那堪離別懷。","簷前声乍碎，枕畔梦全乖。","远與巖泉杂，微將漏水諧。","天涯思旧友，法上憶閒斋。","坐到空庭晓，殘云带石崖。"]', '诗', 'shi', '', NULL, '省題詩二十一首 寒雨滴空階 王棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25385a44-05e5-476c-a05d-99d711de639c', '省題詩二十一首 山明松雪', '省題诗二十一首 山明松雪', '1d55eb85-1c8e-41fb-96a6-cb30e0e600f7', '唐', '["高樹錄軒曉，長松帶雪明。","景疑殘月在，林似野雲橫。","密葉緣多亞，脩條被壓傾。","曙空連嶂白，寒氣到簷清。","影雜青牛重，光迷皓鶴驚。","披衣凝望久，無限剡溪情。"]', '["高樹錄軒晓，长松带雪明。","景疑殘月在，林似野云橫。","密葉緣多亞，脩條被壓傾。","曙空連嶂白，寒氣到簷清。","影杂青牛重，光迷皓鹤驚。","披衣凝望久，無限剡溪情。"]', '诗', 'shi', '', NULL, '省題詩二十一首 山明松雪 王棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8839db68-623b-4b0d-ad1b-91bd362fca91', '省題詩二十一首 元日端門肆赦', '省題诗二十一首 元日端门肆赦', '1d55eb85-1c8e-41fb-96a6-cb30e0e600f7', '唐', '["史官開聖曆，天子御層樓。","壽[域]（城）南山色，恩波東海流。","繞欄生杞梓，當檻簇貔貅。","日月祥光近，山河喜氣浮。","兆人瞻鳯扆，萬里御皇猷。","欲識春生處，雞竿最上頭。"]', '["史官开聖曆，天子御層楼。","壽[域]（城）南山色，恩波东海流。","繞欄生杞梓，當檻簇貔貅。","日月祥光近，山河喜氣浮。","兆人瞻鳯扆，万里御皇猷。","欲識春生处，雞竿最上头。"]', '诗', 'shi', '', NULL, '省題詩二十一首 元日端門肆赦 王棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e51e6cd-9e51-475b-ae10-79b359446890', '省題詩二十一首 原隰荑綠柳', '省題诗二十一首 原隰荑綠柳', '1d55eb85-1c8e-41fb-96a6-cb30e0e600f7', '唐', '["晴郊浮淑氣，疎柳發柔荑。","嫩翠原頭徧，巨絲隰畔低。","和煙方鬱鬱，伴草欲萋萋。","葉少眉難短，條新帶未齊。","離人心已醉，游客步初迷。","無限遷喬意，芳菲正好棲。"]', '["晴郊浮淑氣，疎柳發柔荑。","嫩翠原头徧，巨絲隰畔低。","和煙方鬱鬱，伴草欲萋萋。","葉少眉难短，條新带未齊。","離人心已醉，游客步初迷。","無限遷喬意，芳菲正好棲。"]', '诗', 'shi', '', NULL, '省題詩二十一首 原隰荑綠柳 王棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5974bad-6e41-46b1-a46c-0be2ce8c71f3', '省題詩二十一首 風中琴', '省題诗二十一首 风中琴', '1d55eb85-1c8e-41fb-96a6-cb30e0e600f7', '唐', '["虛簷來曉吹，橫榻有瑤琴。","暗報青蘋葉，潛生綠綺音。","數聲隨籟去，餘響人堂深。","徽假大王按，弦因少女吟。","如箏飄閣上，似瑟鼓江潯。","若與鐘期會，還知天地心。"]', '["虛簷来晓吹，橫榻有瑤琴。","暗報青蘋葉，潛生綠綺音。","數声隨籟去，餘响人堂深。","徽假大王按，弦因少女吟。","如箏飄閣上，似瑟鼓江潯。","若與鐘期會，還知天地心。"]', '诗', 'shi', '', NULL, '省題詩二十一首 風中琴 王棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cbf2238-b598-482c-a83d-a6189e26622c', '省題詩二十一首 文不加點', '省題诗二十一首 文不加点', '1d55eb85-1c8e-41fb-96a6-cb30e0e600f7', '唐', '["娛賓初命賦，摛翰已堪誇。","思發才無滯，文成點不加。","筆端舒錦繡，手下走龍蛇。","罷益銀鉤勢，休添麗澤華。","誤蠅寧復見，倚馬未爲嘉。","有愧當明試，含毫到日斜。"]', '["娛賓初命賦，摛翰已堪誇。","思發才無滯，文成点不加。","笔端舒錦繡，手下走龙蛇。","罷益銀鉤勢，休添丽澤华。","誤蠅寧复见，倚马未爲嘉。","有愧當明試，含毫到日斜。"]', '诗', 'shi', '', NULL, '省題詩二十一首 文不加點 王棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de073a36-758e-4df5-b054-8c202ec397eb', '省題詩二十一首 曲江春望', '省題诗二十一首 曲江春望', '1d55eb85-1c8e-41fb-96a6-cb30e0e600f7', '唐', '["暇日來南陌，春晴望曲江。","地方駢綺席，城過拂霓幢。","寶塔搖鈴鐸，雲樓闢璅窗。","落風花片片，掠水燕雙雙。","游女紅銀䡝，王孫白玉缸。","莫論仙禁裏，祗此見雄邦。"]', '["暇日来南陌，春晴望曲江。","地方駢綺席，城過拂霓幢。","寶塔搖鈴鐸，云楼闢璅窗。","落风花片片，掠水燕雙雙。","游女紅銀䡝，王孫白玉缸。","莫論仙禁裏，祗此见雄邦。"]', '诗', 'shi', '', NULL, '省題詩二十一首 曲江春望 王棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75806ff4-71e6-4ebb-bb38-e91d2544a809', '省題詩二十一首 邊城曉角', '省題诗二十一首 邊城晓角', '1d55eb85-1c8e-41fb-96a6-cb30e0e600f7', '唐', '["十年拋故國，五夜在邊城。","月照沙千里，風吹角一聲。","清音飄遠戍，殘韻落荒營。","背雪征鴻報，眠霜[老鶴驚]。","李陵應下淚，蔡琰豈勝情。","直是吳兒聽，[鄉關夢不成]。"]', '["十年拋故国，五夜在邊城。","月照沙千里，风吹角一声。","清音飄远戍，殘韻落荒營。","背雪征鴻報，眠霜[老鹤驚]。","李陵應下泪，蔡琰豈勝情。","直是吳兒听，[乡关梦不成]。"]', '诗', 'shi', '', NULL, '省題詩二十一首 邊城曉角 王棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9186bfac-9ad4-404e-9dc0-f93af34ee4b6', '省題詩二十一首 三峽聞猿', '省題诗二十一首 三峽闻猿', '1d55eb85-1c8e-41fb-96a6-cb30e0e600f7', '唐', '["扁舟韎楚峽，孤櫂下巫雲。","正值三聲斷，仍教五夜聞。","淒淒流洞壑，杳杳透烟氛。","灩澦秋歸盡，陽臺曙欲分。","何人悲失計，幾度恨離羣。","聽後盈巾淚，家山接海濆。"]', '["扁舟韎楚峽，孤櫂下巫云。","正值三声斷，仍教五夜闻。","淒淒流洞壑，杳杳透烟氛。","灩澦秋归尽，陽台曙欲分。","何人悲失計，幾度恨離羣。","听後盈巾泪，家山接海濆。"]', '诗', 'shi', '', NULL, '省題詩二十一首 三峽聞猿 王棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('deb4fb3d-b94c-479f-9bce-0cb395ccf890', '省題詩二十一首 寒梧鳯棲', '省題诗二十一首 寒梧鳯棲', '1d55eb85-1c8e-41fb-96a6-cb30e0e600f7', '唐', '["本向高岡植，甯將衆木齊。","雖隨楊柳落，長待鳯凰棲。","井上枝微亞，窗前影乍低。","九苞和月立，六律帶霜飛。","秦女含吹管，周王罷翦珪。","既同丹穴樹，那肯宿羣雞。","（以上各詩均見《麟角集》。","）（此組長詩原有缺誤，據《天壤閣叢書》本《麟角集》校補。","）（〖1〗《麟角集》原署「唐水部郎中福唐王棨輔之著」，《省題詩》二十一首爲該集附錄。","原書云：「宋紹興乙卯，八代孫蘋任著作左郎，於館閣校讎，見先郎中省題詩，錄附之。","」）。"]', '["本向高岡植，甯將衆木齊。","雖隨楊柳落，长待鳯凰棲。","井上枝微亞，窗前影乍低。","九苞和月立，六律带霜飞。","秦女含吹管，周王罷翦珪。","既同丹穴樹，那肯宿羣雞。","（以上各诗均见《麟角集》。","）（此組长诗原有缺誤，據《天壤閣叢书》本《麟角集》校補。","）（〖1〗《麟角集》原署「唐水部郎中福唐王棨輔之著」，《省題诗》二十一首爲該集附錄。","原书云：「宋紹兴乙卯，八代孫蘋任著作左郎，於館閣校讎，见先郎中省題诗，錄附之。","」）。"]', '诗', 'shi', '', NULL, '省題詩二十一首 寒梧鳯棲 王棨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4b89bd7-3c42-432c-9b3c-f203f18d326a', '贈王郎中棨（題擬，參閱前王棨小傳）', '贈王郎中棨（題擬，參閱前王棨小傳）', '678d4907-41aa-418b-8aca-9f0856324b83', '唐', '["蓬灜上客顏如玉，手探月窟如夜燭。","笑顧姮娥玉兔言，謂折一枝情未足。","（見黃璞撰《王郎中傳》。","）。"]', '["蓬灜上客顏如玉，手探月窟如夜燭。","笑顧姮娥玉兔言，謂折一枝情未足。","（见黄璞撰《王郎中傳》。","）。"]', '诗', 'shi', '', NULL, '贈王郎中棨（題擬，參閱前王棨小傳） 李顏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('958461ca-1d08-4483-b6ee-53e7db173359', '題包山', '題包山', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["一片煙村勝畫圖，四邊波浪送清虛。","此中人若無租稅，直是蓬瀛也不如。","（見《分門籔類唐歌詩》殘本第四冊《天地山川類》。","）。"]', '["一片煙村勝畫圖，四邊波浪送清虛。","此中人若無租稅，直是蓬瀛也不如。","（见《分门籔類唐歌诗》殘本第四冊《天地山川類》。","）。"]', '诗', 'shi', '', NULL, '題包山 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('961972d9-99b3-4c7f-b4e7-b5c255f15664', '', '', '103316f1-abc2-4fab-8667-6c0837b7752b', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 魏璞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e3d34d3-16a4-4171-a722-ae8c7e3fb406', '尋鳥窠蹟', '尋鸟窠蹟', '103316f1-abc2-4fab-8667-6c0837b7752b', '唐', '["（原注：唐道林禪師入秦望山，見長松蟠曲如蓋，送棲止其上，故稱鳥窠禪師。","）爲訪名僧蹟，言尋小曲阿。","松林春日靜，石逕晚雲多。","道法傳馴鵲，（原注：有鵲巢側，自然馴狎。","）禪機顯化螺。","（原注：嘗入市，見食螺已截尾，乞放之池。","至今螺螄繁生。）","悉無尾如截，遺蹟在蘆院。"]', '["（原注：唐道林禪師入秦望山，见长松蟠曲如蓋，送棲止其上，故稱鸟窠禪師。","）爲訪名僧蹟，言尋小曲阿。","松林春日静，石逕晚云多。","道法傳馴鵲，（原注：有鵲巢側，自然馴狎。","）禪機显化螺。","（原注：嘗入市，见食螺已截尾，乞放之池。","至今螺螄繁生。）","悉無尾如截，遺蹟在蘆院。"]', '诗', 'shi', '', NULL, '尋鳥窠蹟 魏璞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27afecd5-6b24-464d-8cc6-889810c6b0e4', '陪皮襲美陸魯望重過鳥窠蹟', '陪皮襲美陸魯望重過鸟窠蹟', '103316f1-abc2-4fab-8667-6c0837b7752b', '唐', '["重探靈蹟到空山，山下茅庵幾叩關。","不爲白雲招客屐，那教清境接人寰。","螺池水色經年靜，仙嶺松聲鎮日閒。","擬約高賢同結社，好移竹室住前灣。"]', '["重探靈蹟到空山，山下茅庵幾叩关。","不爲白云招客屐，那教清境接人寰。","螺池水色經年静，仙嶺松声鎮日閒。","擬約高賢同結社，好移竹室住前灣。"]', '诗', 'shi', '', NULL, '陪皮襲美陸魯望重過鳥窠蹟 魏璞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('008e5ae1-9900-4a4d-8736-718cad511ede', '題舜山後牛跡石', '題舜山後牛跡石', '103316f1-abc2-4fab-8667-6c0837b7752b', '唐', '["耕鑿連雲磴，蹄痕見福衡。","泣天伸養志，喘月藉留名。","紀鳯儀同美，歌麟趾歧榮。","勝遺方寸地，風動後人耕。","（以上三詩均見《江上詩鈔》卷一。","）（望按：顧季慈心求輯《江上詩鈔》卷一收魏璞詩五首，其一《奉和皮襲美悼鶴》，其二《又奉和襲美一首》。","二詩《全唐詩》收之，惟「璞」作「朴」。","小傳云：「魏朴字不琢，毘陵人。","詩二首。","」又按《全唐詩》皮日休卷有《五貺詩》幷序。","序云：「毘陵處士魏不琢，氣真而志放，居毘陵凡二紀，閉門窮學」云云。","又有《寄毘陵魏處士朴》一首，他詩詩題又有「毘陵魏不琢處士」之語。","又《全唐詩》陸龜蒙卷有《奉和襲美目前魏處士五貺詩》及《和襲美寄毘陵魏處士朴》等詩，可相參閱。","）。"]', '["耕鑿連云磴，蹄痕见福衡。","泣天伸養志，喘月藉留名。","紀鳯儀同美，歌麟趾歧榮。","勝遺方寸地，风动後人耕。","（以上三诗均见《江上诗鈔》卷一。","）（望按：顧季慈心求輯《江上诗鈔》卷一收魏璞诗五首，其一《奉和皮襲美悼鹤》，其二《又奉和襲美一首》。","二诗《全唐诗》收之，惟「璞」作「朴」。","小傳云：「魏朴字不琢，毘陵人。","诗二首。","」又按《全唐诗》皮日休卷有《五貺诗》幷序。","序云：「毘陵处士魏不琢，氣真而志放，居毘陵凡二紀，閉门窮学」云云。","又有《寄毘陵魏处士朴》一首，他诗诗題又有「毘陵魏不琢处士」之語。","又《全唐诗》陸龟蒙卷有《奉和襲美目前魏处士五貺诗》及《和襲美寄毘陵魏处士朴》等诗，可相參閱。","）。"]', '诗', 'shi', '', NULL, '題舜山後牛跡石 魏璞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('662612f8-e699-44e1-83dd-4e82fc38f973', '晚思', '晚思', 'dcf9380f-c7cf-4737-8a49-6c3300bff2ee', '唐', '["蛩餘窗下月，草濕堦前露。","晚景淒我衣，秋風入何樹？","（此見《分門纂類唐歌詩》殘本第一冊《天地山川類》。","）。"]', '["蛩餘窗下月，草濕堦前露。","晚景淒我衣，秋风入何樹？","（此见《分门纂類唐歌诗》殘本第一冊《天地山川類》。","）。"]', '诗', 'shi', '', NULL, '晚思 司空圖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efb2909c-4cec-4dab-adab-9376d72a8e51', '牡丹', '牡丹', '946eb92d-0948-499b-8844-32f48584cf46', '唐', '["中國名花異國香，花開得地更芬芳。","纔呈冶態當春晝，却歛妖姿向夕陽。","雨過阿嬌慵粉黛，風□□□□□□。","□□□□□□□，□□□□□□□。","（見《分門纂類唐歌詩》殘本《草木蟲魚類》卷三。","）。"]', '["中国名花異国香，花开得地更芬芳。","纔呈冶態當春晝，却歛妖姿向夕陽。","雨過阿嬌慵粉黛，风□□□□□□。","□□□□□□□，□□□□□□□。","（见《分门纂類唐歌诗》殘本《草木蟲鱼類》卷三。","）。"]', '诗', 'shi', '', NULL, '牡丹 來鵬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9b6c7ee-ca67-4998-baab-4dd1d5ccf50f', '', '', 'b5ef68c5-c241-41aa-a1d1-b37afac70df3', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 劉蛻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68d6bce0-c0bc-40b1-999b-a25870e2d380', '覽陳拾遺文集（按題下原署名曰「東川觀察判官長沙劉蛻」。）', '覽陳拾遺文集（按題下原署名曰「东川观察判官长沙劉蛻」。）', 'b5ef68c5-c241-41aa-a1d1-b37afac70df3', '唐', '["郪中好事人，家藏君十軸。","余來多暇日，借得晝夜讀。","意氣高於頭，冰霜冷人腹。","就中《大雅》篇，日日吟不足。","生遇明皇帝，君臣竟不識。","沉湮死下位，我輩更莫卜。","射洪客來說，露碑今已踣。","剜刓存滅半，勢欲入溝瀆。","寓書託宰君，請爲試摩挃。","樹之四達地，覆碑高作屋。","憤君死後名，再依泥沙辱。","世路重富貴，婉娩好眉目。","文學如君輩，安得足衣食。","不死橫路渠，爲幸已多福。","我有平生心，推殘不局促。","揖君盛年名，萬鐘何足祿。","量長復校短，鳧脛不願續。","悲君淚垂頤，雲山空蜀國。","（見《永樂大典》卷三一三四「九真」「陳」字「陽子昂」條引《潼川志》〖五函四十四冊〗。","）。"]', '["郪中好事人，家藏君十軸。","余来多暇日，借得晝夜读。","意氣高於头，冰霜冷人腹。","就中《大雅》篇，日日吟不足。","生遇明皇帝，君臣竟不識。","沉湮死下位，我輩更莫卜。","射洪客来说，露碑今已踣。","剜刓存滅半，勢欲入溝瀆。","寓书託宰君，請爲試摩挃。","樹之四達地，覆碑高作屋。","憤君死後名，再依泥沙辱。","世路重富貴，婉娩好眉目。","文学如君輩，安得足衣食。","不死橫路渠，爲幸已多福。","我有平生心，推殘不局促。","揖君盛年名，万鐘何足祿。","量长复校短，鳧脛不願續。","悲君泪垂頤，云山空蜀国。","（见《永乐大典》卷三一三四「九真」「陳」字「陽子昂」條引《潼川志》〖五函四十四冊〗。","）。"]', '诗', 'shi', '', NULL, '覽陳拾遺文集（按題下原署名曰「東川觀察判官長沙劉蛻」。） 劉蛻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f983ae11-fe48-4c2c-9d75-2afc05246af2', '登陳拾遺書臺覽杜工部留題慨然成詠（原署：「前權知尚書刑部郎中牛嶠。」）', '登陳拾遺书台覽杜工部留題慨然成詠（原署：「前權知尚书刑部郎中牛嶠。」）', '83e25dcd-ab50-4eab-bac1-18345a45eeeb', '唐', '["步出縣西郊，攀蘿登峭壁。","行到蘂珠宮，暫喜拋火宅。","羽帔請焚脩，霜鐘扣空寂。","山影落中流，波聲吞大澤。","北廂引危檻，工部曾刻石。","辭高謝康樂，吟久驚神魄。","拾遺有書堂，荒榛堆瓦礫。","二賢間世生，垂名空烜赫。","逸足擬追風，祥鸞已𨭝翮。","伊餘誠未學，（伊餘，應作「伊余」。","）少被文章役。","興來揮兔毫，欲競雕弧力。","雖稱含香吏，猶是飄蓬客。","薄命值亂離，經年避矛戟。","今來略倚柱，不覺衝暝色。","袁安憂國心，誰憐鬢雙白？","（見《永樂大典》卷三一三四「九真」「陳」字「陳子昂」條引《潼川志》〖五函四十四冊〗。","）（按：詩後原紀年時曰「光啟三年九月二十六日」。","）。"]', '["步出縣西郊，攀蘿登峭壁。","行到蘂珠宮，暫喜拋火宅。","羽帔請焚脩，霜鐘扣空寂。","山影落中流，波声吞大澤。","北廂引危檻，工部曾刻石。","辞高謝康乐，吟久驚神魄。","拾遺有书堂，荒榛堆瓦礫。","二賢间世生，垂名空烜赫。","逸足擬追风，祥鸾已𨭝翮。","伊餘誠未学，（伊餘，應作「伊余」。","）少被文章役。","兴来揮兔毫，欲競雕弧力。","雖稱含香吏，猶是飄蓬客。","薄命值亂離，經年避矛戟。","今来略倚柱，不覺衝暝色。","袁安憂国心，誰怜鬢雙白？","（见《永乐大典》卷三一三四「九真」「陳」字「陳子昂」條引《潼川志》〖五函四十四冊〗。","）（按：诗後原紀年时曰「光啟三年九月二十六日」。","）。"]', '诗', 'shi', '', NULL, '登陳拾遺書臺覽杜工部留題慨然成詠（原署：「前權知尚書刑部郎中牛嶠。」） 牛嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30affd7d-bb88-46b3-a5c9-a035a75f25d0', '靈巖寺', '靈巖寺', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["碧峯頂上開禪坐，縱目聊窮宇宙間。","白日纔離東海底，清光先照戶窗間。","（宋李俊甫《莆陽比提》卷七收此詩，題作《靈嚴上方》，「東海」作「滄海」。","《全唐詩續補遺》卷十三據《莆風清籟集》卷五八《游蹤》收此詩，題作《靈巖廣化寺》，「戶窗間」作「戶窗前」，今刪彼存此。","）（此詩見道光甲辰年侯官嚴鴻謨校刊《周太朴詩》。","按詩集原爲明徐𤊹興公所編，嚴刊本於徐編增詩二首，此即其中一首，云據《莆風清籟集》增。","又按：此詩《全唐詩》僅存「白日纔離東海底，清光先照戶窗間」兩句，此則其全璧也。","）。"]', '["碧峯頂上开禪坐，縱目聊窮宇宙间。","白日纔離东海底，清光先照戶窗间。","（宋李俊甫《莆陽比提》卷七收此诗，題作《靈嚴上方》，「东海」作「滄海」。","《全唐诗續補遺》卷十三據《莆风清籟集》卷五八《游蹤》收此诗，題作《靈巖廣化寺》，「戶窗间」作「戶窗前」，今刪彼存此。","）（此诗见道光甲辰年侯官嚴鴻謨校刊《周太朴诗》。","按诗集原爲明徐𤊹兴公所編，嚴刊本於徐編增诗二首，此即其中一首，云據《莆风清籟集》增。","又按：此诗《全唐诗》僅存「白日纔離东海底，清光先照戶窗间」兩句，此則其全璧也。","）。"]', '诗', 'shi', '', NULL, '靈巖寺 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60094198-ccfb-4dee-98b1-948833706177', '又句', '又句', 'f8fda4ea-7888-46fc-bf0d-6cdbb9212001', '唐', '["子孫何處閒爲客，松柏被人伐作薪。","（同前見《周太朴詩》，云據《他日州志》錄存。","見《吟窗雜錄》卷二八。","）。"]', '["子孫何处閒爲客，松柏被人伐作薪。","（同前见《周太朴诗》，云據《他日州志》錄存。","见《吟窗杂錄》卷二八。","）。"]', '诗', 'shi', '', NULL, '又句 周朴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3977ecd5-147b-4a24-8624-3727372bb532', '題善權寺石壁', '題善權寺石壁', '267dfe8d-7ed2-4622-b0a8-92f31514b93c', '唐', '["四周寒暑鎮湖關，三臥漳濱帶病顏。","報國雖當存死節，解龜終得遂生還。","容華漸改心徒壯，志氣無成鬢早斑。","從此使歸林藪去，更將餘奉買南山。","（見海寧吳騫《拜經樓詩話》卷二第十七條。","同治《增修宜興縣壹》卷十《藝文志》亦載之。","）（又見《古今圖書集成·山川典》卷九九《善權洞部》。","）（〖1〗《拜經樓詩話》卷二：「唐李蠙詩世不多見。","宜興善卷二毅題石壁一首曰〖詩畧〗。","蓋蠙太和時嘗見白龍於此，其詩尚有元和遺音。","蠙本名虬，將赴舉，夢名上添一畫成虱字，及寤，曰：『虱者，蠙也。","』乃更名，果登第。","皆可補《全唐紀事》之遺。","」望按：《全唐文》卷七八八收李蠙《請自出俸錢收贖善權寺事奏文》一篇，畧謂「寺在縣南五十里離墨山，是齊時建立。","……寺內有洞府三所。","號爲乾洞者，石室通明處可坐五百餘人，稍暗處，執炬驗入，不知深淺。","……洞門直下便臨大水洞，潺湲宛轉，湍瀨實繁，於山腹內漫流入小水洞。","小水洞亦是一石室，室內水泉無底，大旱不竭。","洞門對齋堂廚庫，似非人境。","洞內常有雲氣昇騰，云是龍神所居之處。","臣大和中在此習業。","……臣懷此冤憤近三十年。","……今請自出俸錢依元買收贖，訪名僧主持，教化同力，卻造成善權寺。","……」誠如此文所云，大和中李蠙曾於此習業，三十年後始出俸錢收贖，推其時當在壹宗咸通中。","然則題此詩於寺壁，要亦咸通間事矣。","）。"]', '["四周寒暑鎮湖关，三臥漳濱带病顏。","報国雖當存死節，解龟終得遂生還。","容华漸改心徒壯，志氣無成鬢早斑。","從此使归林藪去，更將餘奉買南山。","（见海寧吳騫《拜經楼诗話》卷二第十七條。","同治《增修宜兴縣壹》卷十《藝文志》亦載之。","）（又见《古今圖书集成·山川典》卷九九《善權洞部》。","）（〖1〗《拜經楼诗話》卷二：「唐李蠙诗世不多见。","宜兴善卷二毅題石壁一首曰〖诗畧〗。","蓋蠙太和时嘗见白龙於此，其诗尚有元和遺音。","蠙本名虬，將赴舉，梦名上添一畫成虱字，及寤，曰：『虱者，蠙也。","』乃更名，果登第。","皆可補《全唐紀事》之遺。","」望按：《全唐文》卷七八八收李蠙《請自出俸錢收贖善權寺事奏文》一篇，畧謂「寺在縣南五十里離墨山，是齊时建立。","……寺內有洞府三所。","號爲乾洞者，石室通明处可坐五百餘人，稍暗处，執炬驗入，不知深淺。","……洞门直下便臨大水洞，潺湲宛轉，湍瀨實繁，於山腹內漫流入小水洞。","小水洞亦是一石室，室內水泉無底，大旱不竭。","洞门对斋堂廚庫，似非人境。","洞內常有云氣昇腾，云是龙神所居之处。","臣大和中在此習業。","……臣懷此冤憤近三十年。","……今請自出俸錢依元買收贖，訪名僧主持，教化同力，卻造成善權寺。","……」誠如此文所云，大和中李蠙曾於此習業，三十年後始出俸錢收贖，推其时當在壹宗咸通中。","然則題此诗於寺壁，要亦咸通间事矣。","）。"]', '诗', 'shi', '', NULL, '題善權寺石壁 李蠙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b5b626b-770a-40e6-b6fc-2c8a2151a297', '獻淮南崔相公', '獻淮南崔相公', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["天臨黃閤如秋淨，日照洪鈞若晝清。","虎帳坐分真宰氣，象筵吹出泰階聲。","雲霞自入淮王夢，風月誰含煬帝情。","見說蓬萊百王發，玉皇吟出廣陵城。","（此見《永樂大典》卷二七四四「八灰」「崔」字「崔某」條引《維揚志》〖四函三十四冊〗。","）。"]', '["天臨黄閤如秋淨，日照洪鈞若晝清。","虎帳坐分真宰氣，象筵吹出泰階声。","云霞自入淮王梦，风月誰含煬帝情。","见说蓬萊百王發，玉皇吟出廣陵城。","（此见《永乐大典》卷二七四四「八灰」「崔」字「崔某」條引《維揚志》〖四函三十四冊〗。","）。"]', '诗', 'shi', '', NULL, '獻淮南崔相公 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57b87fad-735b-4b76-9b2f-e640e1b89bc2', '旅夜懷故人', '旅夜懷故人', 'f00e1f75-dc09-4d86-a67e-02f9ad15c6bb', '唐', '["羸形對寒影，即此更何親。","半夜枕前淚，窮秋鄉外身。","雨餘嵐色動，風靜月華新。","故友誰相憶？年來入夢頻。","（見《永樂大典》卷三○○五「九真」「人」字〖五函四十二冊〗。","）。"]', '["羸形对寒影，即此更何親。","半夜枕前泪，窮秋乡外身。","雨餘嵐色动，风静月华新。","故友誰相憶？年来入梦頻。","（见《永乐大典》卷三○○五「九真」「人」字〖五函四十二冊〗。","）。"]', '诗', 'shi', '', NULL, '旅夜懷故人 符蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('018c9063-84aa-471b-85b1-11004cb2c14b', '贈彭蟾處士', '贈彭蟾处士', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["不阻兵散亂，穿楊已疊雙。","文深李北海，詩淨賈長江。","退隱斸山藥，醉眠憑酒缸。","年年搜草澤，未便老書窗。","（案彭蟾字東蟾，好學不仕，《全唐詩》卷五百四十六收彭蟾詩一首。","）。"]', '["不阻兵散亂，穿楊已叠雙。","文深李北海，诗淨賈长江。","退隐斸山藥，醉眠憑酒缸。","年年搜草澤，未便老书窗。","（案彭蟾字东蟾，好学不仕，《全唐诗》卷五百四十六收彭蟾诗一首。","）。"]', '诗', 'shi', '', NULL, '贈彭蟾處士 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a4ed892-8f2f-4b1f-9ed0-da08f0ad3495', '贈劉台處士', '贈劉台处士', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["擺落塵埃深處隱，欲將麋鹿混高踨。","兵機不讓韓擒虎，笑癖微方陸士龍。","月窟常留丹桂在，家山貪臥白雲重。","尋址朝有詔徵遺逸，莫掛頭冠著澗松。","（以上見《永樂大典》卷一三四五○「二寘」「處士」〖十四函一百三十七冊〗。","）。"]', '["擺落塵埃深处隐，欲將麋鹿混高踨。","兵機不讓韓擒虎，笑癖微方陸士龙。","月窟常留丹桂在，家山貪臥白云重。","尋址朝有詔徵遺逸，莫掛头冠著澗松。","（以上见《永乐大典》卷一三四五○「二寘」「处士」〖十四函一百三十七冊〗。","）。"]', '诗', 'shi', '', NULL, '贈劉台處士 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66e19a81-2e81-4de6-8686-6541998342e3', '戲贈鄉人', '戲贈乡人', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["前年內展室考文華，咫尺天顏隔絳紗。","御榜早聞傳異國，鄉人猶似薄東家。","中宵縱匣衝星劒，臨水難留上漢槎。","明日春風動行色，惟愁重別故林花。","（此見《永樂大典》卷三○○四「九真」「人」字〖五函四十一冊〗。","）。"]', '["前年內展室考文华，咫尺天顏隔絳紗。","御榜早闻傳異国，乡人猶似薄东家。","中宵縱匣衝星劒，臨水难留上漢槎。","明日春风动行色，惟愁重別故林花。","（此见《永乐大典》卷三○○四「九真」「人」字〖五函四十一冊〗。","）。"]', '诗', 'shi', '', NULL, '戲贈鄉人 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b380166-5cf7-45f5-942c-37bc4d7c8a9a', '下地日侍陸侍郎御讌賦得落花（「下地日」，疑應作「下第日」。）', '下地日侍陸侍郎御讌賦得落花（「下地日」，疑應作「下第日」。）', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["何處足落花，漂泥與藉沙。","春深上林苑，日晚五侯家。","遍地輕難掃，當風勢易斜。","無心媿蜂蝶，來歲即榮華。"]', '["何处足落花，漂泥與藉沙。","春深上林苑，日晚五侯家。","遍地轻难掃，當风勢易斜。","無心媿蜂蝶，来歲即榮华。"]', '诗', 'shi', '', NULL, '下地日侍陸侍郎御讌賦得落花（「下地日」，疑應作「下第日」。） 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d6a9bf4-550f-45b1-a34a-f47fe17c5f49', '昭陽落花', '昭陽落花', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["空樹落花時，宮嬪泣暮暉。","盡皆承雨露，爭不惜芳菲。","殘蘂猶黏草，餘香尚惹衣。","無言屬青鳥，青鳥自銜飛。","（以上見《永樂大典》卷五八三九「十六麻」「花」字「落花」條〖七函六十一冊〗。","）。"]', '["空樹落花时，宮嬪泣暮暉。","尽皆承雨露，爭不惜芳菲。","殘蘂猶黏草，餘香尚惹衣。","無言屬青鸟，青鸟自銜飞。","（以上见《永乐大典》卷五八三九「十六麻」「花」字「落花」條〖七函六十一冊〗。","）。"]', '诗', 'shi', '', NULL, '昭陽落花 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c664d8c0-54d6-452a-8ec1-7fafd04f27d5', '禮聶先生新安重圍先生能通兩軍之好及城開民皆復全也', '禮聶先生新安重圍先生能通兩軍之好及城开民皆复全也', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["李白辭翰苑，前山尋隱淪。","不遇採芝翁，滿洞惟白雲。","（原注：李白昔日曾於此山尋許宣平先生不遇。","）我來禮先生，得與龜鶴親。","學道須有緣，始逢天上人。","四皓安漢室，先生存歙民。","陰功數已滿，自合成天真。","如何未上昇，應待玉皇迎。","我願去浮名，隨師歸三清。","（此見《永樂大典》卷一○四五九「四濟」「禮」字〖十一函一百四冊〗。","）。"]', '["李白辞翰苑，前山尋隐淪。","不遇採芝翁，满洞惟白云。","（原注：李白昔日曾於此山尋許宣平先生不遇。","）我来禮先生，得與龟鹤親。","学道須有緣，始逢天上人。","四皓安漢室，先生存歙民。","陰功數已满，自合成天真。","如何未上昇，應待玉皇迎。","我願去浮名，隨師归三清。","（此见《永乐大典》卷一○四五九「四濟」「禮」字〖十一函一百四冊〗。","）。"]', '诗', 'shi', '', NULL, '禮聶先生新安重圍先生能通兩軍之好及城開民皆復全也 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f24eba13-96a1-41b8-ae09-3f113d6977b5', '送建昌馮明府', '送建昌馮明府', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["嘗聞陶彭澤，解印歸匡廬。","今見馮海昏，辭官還隱居。","賢人五百年，間生信非虛。","清風激貪冒，白雲同卷舒。","家山列畫屏，綠水環庭除。","秋清對吟尊，羲皇人不如。","祇今建昌民，方話大馮君。","何必遺愛碑，政聲人盡聞。"]', '["嘗闻陶彭澤，解印归匡廬。","今见馮海昏，辞官還隐居。","賢人五百年，间生信非虛。","清风激貪冒，白云同卷舒。","家山列畫屏，綠水环庭除。","秋清对吟尊，羲皇人不如。","祇今建昌民，方話大馮君。","何必遺愛碑，政声人尽闻。"]', '诗', 'shi', '', NULL, '送建昌馮明府 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7a55746-b5cb-4487-91d2-fcf2f60ec0bc', '贈潯陽馮明府', '贈潯陽馮明府', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["政約人知懼，訟庭荒草生。","日高諸吏散，風到七絃清。","詩味匡山色，臥諳湓浦聲。","柴桑已不遠，何苦念前程。"]', '["政約人知懼，訟庭荒草生。","日高諸吏散，风到七絃清。","诗味匡山色，臥諳湓浦声。","柴桑已不远，何苦念前程。"]', '诗', 'shi', '', NULL, '贈潯陽馮明府 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e23da36-2776-4f07-9f07-01606b728035', '宛陵早秋臥病代書寄周明府', '宛陵早秋臥病代书寄周明府', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["爲謝臨卭宰，時多闕附書。","懶非嵇叔夜，疾比馬相如。","溪雨凉生後，山亭月上初。","懷君自有句，何必遺雙魚。"]', '["爲謝臨卭宰，时多闕附书。","懶非嵇叔夜，疾比马相如。","溪雨凉生後，山亭月上初。","懷君自有句，何必遺雙鱼。"]', '诗', 'shi', '', NULL, '宛陵早秋臥病代書寄周明府 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b566540-a338-40c1-9640-b8e0c95ed7c3', '又一首', '又一首', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["吾道豈便喪，時人自不容。","白頭傷久別，青眼憶相逢。","萍迹風波急，荷衣霧露濃。","空編太平頌，天子未登封。","（以上均見《永樂大典》卷一一○○○「六姥」「府」字「明府」條〖十一函一百十冊〗。","以上諸詩，《永樂大典》皆注明出王貞白《靈溪集》。","《直齋書錄解題》卷十九著錄此集，共七卷，今不存。","）。"]', '["吾道豈便喪，时人自不容。","白头傷久別，青眼憶相逢。","萍迹风波急，荷衣霧露濃。","空編太平頌，天子未登封。","（以上均见《永乐大典》卷一一○○○「六姥」「府」字「明府」條〖十一函一百十冊〗。","以上諸诗，《永乐大典》皆注明出王貞白《靈溪集》。","《直斋书錄解題》卷十九著錄此集，共七卷，今不存。","）。"]', '诗', 'shi', '', NULL, '又一首 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0fbab60-43fa-4376-8578-b2e992540c5c', '白鹿洞二首 一', '白鹿洞二首 一', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["讀書不覺已春深，一寸光陰一寸金。","不是道人來引笑，周情孔思正追尋。"]', '["读书不覺已春深，一寸光陰一寸金。","不是道人来引笑，周情孔思正追尋。"]', '诗', 'shi', '', NULL, '白鹿洞二首 一 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8847f95a-13a2-486e-b1d1-9fc71ce52565', '白鹿洞二首 二', '白鹿洞二首 二', '18576a5b-0d4c-4266-84e8-85895155467a', '唐', '["一上西園避暑亭，芰荷香細午風輕。","眼前物物皆佳興，併作吟窩一味清。","（此二首從清餘姚邵啟賢輯、武昌陶氏刊本《王貞白詩》中補得。","邵氏序謂此二首系據家刻本續補，《全唐詩》所未收者。","）。"]', '["一上西园避暑亭，芰荷香細午风轻。","眼前物物皆佳兴，併作吟窩一味清。","（此二首從清餘姚邵啟賢輯、武昌陶氏刊本《王貞白诗》中補得。","邵氏序謂此二首系據家刻本續補，《全唐诗》所未收者。","）。"]', '诗', 'shi', '', NULL, '白鹿洞二首 二 王貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1a18c35-c7c3-46cf-b19e-180158f9ba05', '', '', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('756487a8-b4dc-40b5-9c5b-776567e57182', '重臺芙蓉', '重台芙蓉', '7e8d1535-125b-41dd-89da-45c07b2b0de5', '唐', '["衆芳凋落後，特地遇陽和。","一一開雖晚，重重得亦多。","畧無幽鳥語，時有凍蜂過。","日暮寒階畔，輕紅拂淺莎。","（見《永樂大典》卷五四○「一東」「蓉」字「重臺芙蓉」條〖一函三冊〗。","）。"]', '["衆芳凋落後，特地遇陽和。","一一开雖晚，重重得亦多。","畧無幽鸟語，时有凍蜂過。","日暮寒階畔，轻紅拂淺莎。","（见《永乐大典》卷五四○「一东」「蓉」字「重台芙蓉」條〖一函三冊〗。","）。"]', '诗', 'shi', '', NULL, '重臺芙蓉 裴說 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cd8ac9f-ae9c-42ae-90e9-d5af21a0ce40', '遊囊山', '游囊山', 'ebae6edb-03e9-4d62-812f-c2bd9db0a902', '唐', '["山有重嚢勢，門開兩徑斜。","溪聲寒走澗，海色月流沙。","庵外曾遊虎，堂中舊雨花。","不知遺讖地，一一落誰家？","（見黃鳴喬刻本《黃御史集》卷二。","）。"]', '["山有重嚢勢，门开兩徑斜。","溪声寒走澗，海色月流沙。","庵外曾游虎，堂中旧雨花。","不知遺讖地，一一落誰家？","（见黄鳴喬刻本《黄御史集》卷二。","）。"]', '诗', 'shi', '', NULL, '遊囊山 黃滔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cd8f66a-f2a9-4fd0-b959-1c868b91adae', '和從兄御史延福里居', '和從兄御史延福里居', '3c550f98-89da-4dc0-a796-d2265ea42c41', '唐', '["天賜平安水北中，滿庭荆樹醉春風。","縱覺塵世三公貴，何似吾家一脈通。","花底輕風香撲散，門前細柳綠皆同。","囘頭文館長安上，（原注：謂德溫兄。","）外際思予甯有窮。","（見《天壤閣叢書》本《莆陽黃御史集》附刻明崇禎本補附詩卷。","）（按詩題下端原署「從弟蟾」三字。","徐松《唐兩京城坊考》卷四「次南延福坊」有御史黃滔宅，即據《黃御史集》中《延福里居和林寬何紹餘酬寄》詩及黃蟾此詩爲證。","）。"]', '["天賜平安水北中，满庭荆樹醉春风。","縱覺塵世三公貴，何似吾家一脈通。","花底轻风香撲散，门前細柳綠皆同。","囘头文館长安上，（原注：謂德溫兄。","）外際思予甯有窮。","（见《天壤閣叢书》本《莆陽黄御史集》附刻明崇禎本補附诗卷。","）（按诗題下端原署「從弟蟾」三字。","徐松《唐兩京城坊考》卷四「次南延福坊」有御史黄滔宅，即據《黄御史集》中《延福里居和林寬何紹餘酬寄》诗及黄蟾此诗爲證。","）。"]', '诗', 'shi', '', NULL, '和從兄御史延福里居 黃蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71c12197-8a1f-4454-99ad-0f37ee5965ae', '賀知章官至秘書監鏡湖山水上疏明皇放歸鄉土仍賜鏡湖山河五百里曹松題鏡湖詩曰', '賀知章官至秘书監镜湖山水上疏明皇放归乡土仍賜镜湖山河五百里曹松題镜湖诗曰', '66cf80f4-db5f-475b-b42d-a4fe02c0d601', '唐', '["小因良匠寫清光，照見越州年歲長。","裹許雲山更孤峭，一時宣賜賀知章。","（見《永樂大典》卷二二六七「六模」「湖」字「鏡湖」條〖二函二十冊〗。","）。"]', '["小因良匠寫清光，照见越州年歲长。","裹許云山更孤峭，一时宣賜賀知章。","（见《永乐大典》卷二二六七「六模」「湖」字「镜湖」條〖二函二十冊〗。","）。"]', '诗', 'shi', '', NULL, '賀知章官至秘書監鏡湖山水上疏明皇放歸鄉土仍賜鏡湖山河五百里曹松題鏡湖詩曰 曹松 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6109407-3ee5-4987-a1b6-3f99ea41fc2b', '白菊（見《分門纂類唐歌詩》殘本第六冊《草本蟲魚類》卷五。按《全唐詩》卷七三四作羅紹威詩。紹威乃弘信之子。一作羅隱詩。）', '白菊（见《分门纂類唐歌诗》殘本第六冊《草本蟲鱼類》卷五。按《全唐诗》卷七三四作羅紹威诗。紹威乃弘信之子。一作羅隐诗。）', '15c2c540-dc92-4ebc-97a8-5f5168c0f893', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '白菊（見《分門纂類唐歌詩》殘本第六冊《草本蟲魚類》卷五。按《全唐詩》卷七三四作羅紹威詩。紹威乃弘信之子。一作羅隱詩。） 羅弘信 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a9a9031-34a9-4faf-a2a3-a9cef5cfc4c1', '柳（見《分門纂類唐歌詩》殘本第七冊《草本蟲魚類》卷八。按《全唐詩》卷七三四亦作羅紹威詩。）', '柳（见《分门纂類唐歌诗》殘本第七冊《草本蟲鱼類》卷八。按《全唐诗》卷七三四亦作羅紹威诗。）', '15c2c540-dc92-4ebc-97a8-5f5168c0f893', '唐', '["空。"]', '["空。"]', '诗', 'shi', '', NULL, '柳（見《分門纂類唐歌詩》殘本第七冊《草本蟲魚類》卷八。按《全唐詩》卷七三四亦作羅紹威詩。） 羅弘信 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d784b6d-ae6c-4401-8dd0-46a4ac15fbf0', '望山', '望山', '530991f4-f560-47e7-be37-b98d750da856', '唐', '["亂山難問主，相續碧嶙嶙。","何處煙霞裏，猶眠經濟人。","樓高看有意，雨過色彌新。","待取科名了，終期隱此身。","（見《分門纂類唐歌詩》殘本第二冊《天地山川類》卷二十二。","）。"]', '["亂山难问主，相續碧嶙嶙。","何处煙霞裏，猶眠經濟人。","楼高看有意，雨過色彌新。","待取科名了，終期隐此身。","（见《分门纂類唐歌诗》殘本第二冊《天地山川類》卷二十二。","）。"]', '诗', 'shi', '', NULL, '望山 盧士衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fab8ab69-3ff7-4cc9-85db-c2ffd98ea6e7', '硤石山', '硤石山', '30b17cb7-b464-439e-8d31-1478bb14b2f5', '唐', '["此山靄靄通雲煙，峭壁嵯峨勢分綿。","丹水流衍曲如帶，風皺羅紋聽管絃。","鶯啼花開入禪意，擲筆臺前梵唄宣。","遙想當年無遮會，紛紛散落雨花天。","（見《山右金石記》。","）（〖1〗《山右金石記》卷九《硤石山楊夫人摩崖詩刻》條引《鳯臺縣志》：石壁刻『唐天佑丙子歲六月十四日離府，至中旬巡祀到此，登陟硤石山，偶上先師擲筆臺，眺觀景象，爲詩上碣。","弘農郡君夫人述。","』按天佑丙子，晉稱天佑十一年〖望按：丙子，當是晉天祐十三年，公元九一六年〗。","是年，李嗣昭立鐘開元寺以七月十三日，弘農郡君夫人遊硤石山則六月十四日。","考唐制有郡君夫人、公侯伯子夫人，制同一二三四品，似屬嗣昭夫人楊氏。","但嗣昭封隴西郡公，未封弘農，或因弘農華陰以楊氏族望爲稱也。","又考楊氏善蓄財，嗣昭被梁兵圍夾城彌年，楊氏多助其軍用。","子繼韜叛後入京，楊齎銀數十萬驗賂釋其罪。","後與子繼忠家晉陽，餘貲猶鉅萬。","晉高祖起義，貸其殖以賂契丹，後以繼忠爲刺史。","楊氏平生積產，嗣昭三世皆賴。","今復見其石刻筆蹟，直奇婦人也。","）。"]', '["此山靄靄通云煙，峭壁嵯峨勢分綿。","丹水流衍曲如带，风皺羅紋听管絃。","鶯啼花开入禪意，擲笔台前梵唄宣。","遙想當年無遮會，紛紛散落雨花天。","（见《山右金石記》。","）（〖1〗《山右金石記》卷九《硤石山楊夫人摩崖诗刻》條引《鳯台縣志》：石壁刻『唐天佑丙子歲六月十四日離府，至中旬巡祀到此，登陟硤石山，偶上先師擲笔台，眺观景象，爲诗上碣。","弘農郡君夫人述。","』按天佑丙子，晉稱天佑十一年〖望按：丙子，當是晉天祐十三年，公元九一六年〗。","是年，李嗣昭立鐘开元寺以七月十三日，弘農郡君夫人游硤石山則六月十四日。","考唐制有郡君夫人、公侯伯子夫人，制同一二三四品，似屬嗣昭夫人楊氏。","但嗣昭封隴西郡公，未封弘農，或因弘農华陰以楊氏族望爲稱也。","又考楊氏善蓄財，嗣昭被梁兵圍夾城彌年，楊氏多助其軍用。","子繼韜叛後入京，楊齎銀數十万驗賂釋其罪。","後與子繼忠家晉陽，餘貲猶鉅万。","晉高祖起義，貸其殖以賂契丹，後以繼忠爲刺史。","楊氏平生積產，嗣昭三世皆賴。","今复见其石刻笔蹟，直奇婦人也。","）。"]', '诗', 'shi', '', NULL, '硤石山 楊氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93cdbdd2-c38d-4f32-aa16-2c7283a0e7ca', '獻馮李二相公（題擬）', '獻馮李二相公（題擬）', 'a98a8437-a502-46eb-901c-351c1f1e8d4a', '唐', '["雨處沙堤同日築，其如啓沃藉良謀。","民間有病誰開口，府下無人只點頭。","（見《江南餘載》卷下，云「馮延巳、李建勳拜相，張義方獻詩。","」）。"]', '["雨处沙堤同日築，其如啓沃藉良謀。","民间有病誰开口，府下無人只点头。","（见《江南餘載》卷下，云「馮延巳、李建勳拜相，張義方獻诗。","」）。"]', '诗', 'shi', '', NULL, '獻馮李二相公（題擬） 張義方 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91e4f6cb-3387-4429-bac8-8790d1b4fd58', '謝賜待詔御苑（題擬）', '謝賜待詔御苑（題擬）', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["御苑賜房令待詔，此身殊勝到蓬瀛。","禁中仙樂無時過，階下常人不敢行。","疊穎弄芳秋氣落，叢柯聳翠露華清。","天廚送食何功享，空詠康哉贊盛明。","（見《江南餘載》卷下。","）（《江南餘載》：李建勳罷相，元宗於西苑天全閣別置廳院待之，命右僕射孫晟因寓直焉。","建勳進詩動云。","）。"]', '["御苑賜房令待詔，此身殊勝到蓬瀛。","禁中仙乐無时過，階下常人不敢行。","叠穎弄芳秋氣落，叢柯聳翠露华清。","天廚送食何功享，空詠康哉贊盛明。","（见《江南餘載》卷下。","）（《江南餘載》：李建勳罷相，元宗於西苑天全閣別置廳院待之，命右僕射孫晟因寓直焉。","建勳進诗动云。","）。"]', '诗', 'shi', '', NULL, '謝賜待詔御苑（題擬） 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5e78e32-a625-4d91-8ead-86a5e6f41091', '句', '句', '80371f8e-8ccb-40d3-b6d1-62702b463fa6', '唐', '["一人看上馬，雙節引還鄉。","（同前。","）（〖1〗《江南餘載》：宋齊丘出鎮洪州，詔賜錦袍，烈祖〖李昪〗親爲衣之。","李建勳贈詩有「一人看上馬，雙節引還鄉」之句，時論榮之。","）。"]', '["一人看上马，雙節引還乡。","（同前。","）（〖1〗《江南餘載》：宋齊丘出鎮洪州，詔賜錦袍，烈祖〖李昪〗親爲衣之。","李建勳贈诗有「一人看上马，雙節引還乡」之句，时論榮之。","）。"]', '诗', 'shi', '', NULL, '句 李建勳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a757991-76ec-4b08-854d-b8ad7ba25ce0', '獻詩（題擬）', '獻诗（題擬）', '271af1ce-85a7-4ba5-859a-693a616ff240', '唐', '["偶憶昔年逢上巳，輕舟柳岸宴羣臣。","人間蹇薄時提歎，天上風光日日新。","玉帛已來諸國瑞，瑤池固有萬年春。","賦詩飲酒平生事，腸斷金門願再親。","（見《江南餘載》卷下。","）（《江南餘載》：李夷鄴者，前唐諸孫，嗜酒不羈。","保大初，以宗室賢才拜正卿，累經左降，逾年輒復舊官。","元宗上巳開宴，夷鄴不在召中，乃獻詩曰云云。","上賜御札曰：「我家有外狂宗正，快哉！」）。"]', '["偶憶昔年逢上巳，轻舟柳岸宴羣臣。","人间蹇薄时提歎，天上风光日日新。","玉帛已来諸国瑞，瑤池固有万年春。","賦诗饮酒平生事，腸斷金门願再親。","（见《江南餘載》卷下。","）（《江南餘載》：李夷鄴者，前唐諸孫，嗜酒不羈。","保大初，以宗室賢才拜正卿，累經左降，逾年輒复旧官。","元宗上巳开宴，夷鄴不在召中，乃獻诗曰云云。","上賜御札曰：「我家有外狂宗正，快哉！」）。"]', '诗', 'shi', '', NULL, '獻詩（題擬） 李夷鄴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f033536-fc5f-4970-90be-af38f17550de', '', '', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["（按《全唐詩》無呂從慶詩。","今傳世之《豐溪存稿》，即呂從慶詩集也。","此書有洪溪呂氏萃石山房本，有嘉慶癸酉歲從慶三十二世孫呂璽培重刊本，均未見。","有同治癸酉六安西鄉流波䃥鎮弗措書屋重鐫本。","此卷即自同治重鐫本錄出。","集前有雍正甲寅年任啟運撰呂從慶傳，足資參攷。","）。"]', '["（按《全唐诗》無呂從慶诗。","今傳世之《豐溪存稿》，即呂從慶诗集也。","此书有洪溪呂氏萃石山房本，有嘉慶癸酉歲從慶三十二世孫呂璽培重刊本，均未见。","有同治癸酉六安西乡流波䃥鎮弗措书屋重鐫本。","此卷即自同治重鐫本錄出。","集前有雍正甲寅年任啟運撰呂從慶傳，足資參攷。","）。"]', '诗', 'shi', '', NULL, ' 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('572dec6b-b8c3-4c87-8026-244a64c7c647', '幽居', '幽居', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["茅茨何瀟瀟，邱園復寥廓。","黃冠此中居，眷言寄高託。","理亂無聞聲，榮辱不相着。","有書聊把娛，有酒自斟酌。","侵晨課田桑，歸來日華薄。","盤桓松竹間，鳥動殘雲落。"]', '["茅茨何瀟瀟，邱园复寥廓。","黄冠此中居，眷言寄高託。","理亂無闻声，榮辱不相着。","有书聊把娛，有酒自斟酌。","侵晨課田桑，归来日华薄。","盤桓松竹间，鸟动殘云落。"]', '诗', 'shi', '', NULL, '幽居 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b846c76-6ea2-4653-8c27-4f5772a7f594', '登糾峯頂', '登糾峯頂', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["盤盤糾峯嶺，不與羣峯同。","我來值清秋，落葉飛蒼穹。","洪濤湃松柏，烟雨交空濛。","愛兹竟忘返，非關足力窮。","。"]', '["盤盤糾峯嶺，不與羣峯同。","我来值清秋，落葉飞蒼穹。","洪濤湃松柏，烟雨交空濛。","愛兹竟忘返，非关足力窮。","。"]', '诗', 'shi', '', NULL, '登糾峯頂 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('494ce632-6fbc-452b-a1f2-4bed6a0afd53', '題畫', '題畫', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["怪石倚危巒，橫烟出深谷。","其間有孤松，亭亭表蒼綠。","擕笻者伊誰？頂髪髠且禿。","請君過柴橋，臨流味幽獨。"]', '["怪石倚危巒，橫烟出深谷。","其间有孤松，亭亭表蒼綠。","擕笻者伊誰？頂髪髠且禿。","請君過柴橋，臨流味幽独。"]', '诗', 'shi', '', NULL, '題畫 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('724ac895-0523-46fa-889f-f0ae305fbd3f', '釣魚', '釣鱼', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["侵晨出門去，道遇村阿婆。","問我一竿竹，得魚日幾何？","我志不在魚，毋問寡與多。","行行至磯側，卸我青草蓑。","落花向我舞，啼鳥向我歌。","旁有垂楊枝，迎風翻阿那。","我意殊自得，翛然眠綠坡。","仰視霄漢間，還以永吟哦。"]', '["侵晨出门去，道遇村阿婆。","问我一竿竹，得鱼日幾何？","我志不在鱼，毋问寡與多。","行行至磯側，卸我青草蓑。","落花向我舞，啼鸟向我歌。","旁有垂楊枝，迎风翻阿那。","我意殊自得，翛然眠綠坡。","仰視霄漢间，還以永吟哦。"]', '诗', 'shi', '', NULL, '釣魚 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80463774-9228-48dd-8cc9-bc56bf43278a', '過金鷄石', '過金鷄石', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["金鷄自天來，桑麻列青眼。","羣耳無一聰，昂冠復飛返。","遺音此寂然，千秋意何限。","所幸一片石，猶在田中坂。","我來撫弄之，襟懷日以散。","寄語塒中禽，爾徒博飱飯。"]', '["金鷄自天来，桑麻列青眼。","羣耳無一聰，昂冠复飞返。","遺音此寂然，千秋意何限。","所幸一片石，猶在田中坂。","我来撫弄之，襟懷日以散。","寄語塒中禽，爾徒博飱飯。"]', '诗', 'shi', '', NULL, '過金鷄石 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5835ac1-b36a-49d4-96e2-8beeb8c8db45', '懷嚴子陵前輩', '懷嚴子陵前輩', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["舉世成薄俗，往往奔虛名。","一或滯草澤，其音多不平。","先生挽風化，簪組輕浮萍。","緬維富春渚，千秋有深情。"]', '["舉世成薄俗，往往奔虛名。","一或滯草澤，其音多不平。","先生挽风化，簪組轻浮萍。","緬維富春渚，千秋有深情。"]', '诗', 'shi', '', NULL, '懷嚴子陵前輩 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e782d96-e55f-4dc4-8c12-bfc52359b723', '喜晴', '喜晴', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["瞳瞳雲間日，兼旬不得明。","一朝雨勢歇，衆鳥喧新晴。","南窗有老叟，喜極推枯枰。","呼僮載樽酒，訪渠泉石盟。","出門有佳趣，清風生綠萍。","笑語途中泥，爾難濡我情。","。"]', '["瞳瞳云间日，兼旬不得明。","一朝雨勢歇，衆鸟喧新晴。","南窗有老叟，喜極推枯枰。","呼僮載樽酒，訪渠泉石盟。","出门有佳趣，清风生綠萍。","笑語途中泥，爾难濡我情。","。"]', '诗', 'shi', '', NULL, '喜晴 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d42000d1-fe4b-43dd-b6e0-90287c7b8978', '獻題金鰲山', '獻題金鰲山', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["金鰲騰騰高百丈，昔者曾遊東海浪。","女媧斷足奠坤輿，怒身化作安吳嶂。","骨肉雖變魂魄鮮，千秋萬古生雲烟。","閒花老樹滿馥郁，飛走異類爭蹁躚。","草堂熟對忽詫異，念在神僊廣遊戲。","琴高跨鯉如跨驢，初成乘龍較容易。","我今自號釣魚郎，絲綸倍比任公長。","願言活汝騎脚底，御風直造星辰傍。"]', '["金鰲腾腾高百丈，昔者曾游东海浪。","女媧斷足奠坤輿，怒身化作安吳嶂。","骨肉雖变魂魄鲜，千秋万古生云烟。","閒花老樹满馥郁，飞走異類爭蹁躚。","草堂熟对忽詫異，念在神僊廣游戲。","琴高跨鯉如跨驢，初成乘龙較容易。","我今自號釣鱼郎，絲綸倍比任公长。","願言活汝騎脚底，御风直造星辰傍。"]', '诗', 'shi', '', NULL, '獻題金鰲山 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cfd30c6-3e74-4389-9008-c3f5b8845b03', '山中作', '山中作', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["人生自古少百年，彈琴飲酒須歡然。","老子於今得此趣，縱有塵事難糾纏。","左安藥爐右茶具，失記朝來與朝去。","偶因送客出前溪，便過溪橋拾詩句。"]', '["人生自古少百年，彈琴饮酒須歡然。","老子於今得此趣，縱有塵事难糾纏。","左安藥爐右茶具，失記朝来與朝去。","偶因送客出前溪，便過溪橋拾诗句。"]', '诗', 'shi', '', NULL, '山中作 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e22dff99-7bf2-4587-a3c8-0d6849df25df', '賊警', '賊警', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["兵火逾風疾，纔西已及東。","蒼翁災海內，赤子哭途中。","城闕兼旬閉，郵書徹旦通。","不知調國者，何以慰時匆？"]', '["兵火逾风疾，纔西已及东。","蒼翁災海內，赤子哭途中。","城闕兼旬閉，郵书徹旦通。","不知調国者，何以慰时匆？"]', '诗', 'shi', '', NULL, '賊警 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfa2c224-18bf-44c8-b5a9-a7db57142feb', '行次歙州寓之', '行次歙州寓之', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["乍入新安境，溪山覺可褒。","賃房安食具，掃榻卸行絛。","明識離鄉賤，强言避世高。","君聽塗上客，多半說弓刀。"]', '["乍入新安境，溪山覺可褒。","賃房安食具，掃榻卸行絛。","明識離乡賤，强言避世高。","君听塗上客，多半说弓刀。"]', '诗', 'shi', '', NULL, '行次歙州寓之 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0819a70f-825d-42ac-bc09-018ba13ddc1c', '小園', '小园', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["小園春色麗，花發兩三株。","露笋抽泥立，風蘭狎石鋪。","教兒棋正歇，得客酒重沽。","意緒渾如此，詩腸老未枯。","。"]', '["小园春色丽，花發兩三株。","露笋抽泥立，风蘭狎石鋪。","教兒棋正歇，得客酒重沽。","意緒渾如此，诗腸老未枯。","。"]', '诗', 'shi', '', NULL, '小園 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecf2f6e5-f366-45ac-829f-10c789bcb789', '遊多寶寺', '游多寶寺', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["探幽過小澗，夕照走全陰。","倚杖娛閒睫，聞鐘寄遠心。","竹光浮古趣，松籟捲寒音。","城衲烹茶出，先供座佛歆。"]', '["探幽過小澗，夕照走全陰。","倚杖娛閒睫，闻鐘寄远心。","竹光浮古趣，松籟捲寒音。","城衲烹茶出，先供座佛歆。"]', '诗', 'shi', '', NULL, '遊多寶寺 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9b29b83-e7f3-43d9-9a61-254d9a9c380e', '村徑中即事', '村徑中即事', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["寂剪茅簷外，溪流曲似繩。","飛蜓低復仰，啼鳥斷還仍。","麥秀香聯畝，麻高影障塍。","老夫無病痛，長此樂清礽。"]', '["寂剪茅簷外，溪流曲似繩。","飞蜓低复仰，啼鸟斷還仍。","麦秀香聯畝，麻高影障塍。","老夫無病痛，长此乐清礽。"]', '诗', 'shi', '', NULL, '村徑中即事 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68212f05-3f7e-45f8-b552-7e04dcd20447', '對月有感', '对月有感', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["天開懸寶鏡，皓魄滿欄杆。","君自千秋照，人誰百歲看。","夜香金鼎燼，春酒玉壺乾。","吾意方蕭索，懷兹愈不安。"]', '["天开懸寶镜，皓魄满欄杆。","君自千秋照，人誰百歲看。","夜香金鼎燼，春酒玉壺乾。","吾意方蕭索，懷兹愈不安。"]', '诗', 'shi', '', NULL, '對月有感 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9fd5df74-84a3-4c40-b66f-60cf9f1071b7', '草堂坐雨', '草堂坐雨', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["夏來田久旱，秋雨偶然幷。","嵐影經眸幻，檐聲滴耳清。","幽花開小艷，憊黍轉餘精。","還望潢池上，蕭然洗甲兵。"]', '["夏来田久旱，秋雨偶然幷。","嵐影經眸幻，檐声滴耳清。","幽花开小艷，憊黍轉餘精。","還望潢池上，蕭然洗甲兵。"]', '诗', 'shi', '', NULL, '草堂坐雨 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22595106-56d3-4b4b-a5f4-5b1c670ca77e', '偶興', '偶兴', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["吾亦陶彭澤，從來懶折腰。","焚香懷落落，對酒意囂囂。","世態雲多幻，人情雪易消。","最佳猿共鶴，閒裏日相邀。"]', '["吾亦陶彭澤，從来懶折腰。","焚香懷落落，对酒意囂囂。","世態云多幻，人情雪易消。","最佳猿共鹤，閒裏日相邀。"]', '诗', 'shi', '', NULL, '偶興 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5125d9c-fe86-411b-a902-6a17cab209fb', '溪西村', '溪西村', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["入境聞鷄犬，悠悠古趣遐。","紅邊花落瓣，綠際茗舒芽。","深壑和烟窈，清溪避石斜。","他時須結伴，松底泛流霞。"]', '["入境闻鷄犬，悠悠古趣遐。","紅邊花落瓣，綠際茗舒芽。","深壑和烟窈，清溪避石斜。","他时須結伴，松底泛流霞。"]', '诗', 'shi', '', NULL, '溪西村 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fd5e001-3153-44a0-a1ae-c3b1da9d1b47', '冬盡', '冬尽', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["一年惟臘在，忽忽又將央。","雪重庭枝折，風輕徑蘂香。","感時空有恨，留歲竟無方。","老矣當樽客，他鄉作故鄉。"]', '["一年惟臘在，忽忽又將央。","雪重庭枝折，风轻徑蘂香。","感时空有恨，留歲竟無方。","老矣當樽客，他乡作故乡。"]', '诗', 'shi', '', NULL, '冬盡 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1041dd5-4cec-4685-950c-a0c199879dfd', '平原', '平原', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["碧天連野色，微雨濕蒿藜。","鳥影松間沒，蟬聲柳外嘶。","寺僧張遠蓋，田父把輕犁。","逸趣紛紛入，都堪作畫題。"]', '["碧天連野色，微雨濕蒿藜。","鸟影松间沒，蟬声柳外嘶。","寺僧張远蓋，田父把轻犁。","逸趣紛紛入，都堪作畫題。"]', '诗', 'shi', '', NULL, '平原 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad121c6d-c2cd-4b48-aa3d-8b9bebecf14a', '章氏幽居', '章氏幽居', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["白屋烟霞內，花期了不愆。","邱山情更好，泉石盟須堅。","綠樹當簷裏，紅藤倚壁牽。","主人閒處立，有客笑扶肩。"]', '["白屋烟霞內，花期了不愆。","邱山情更好，泉石盟須堅。","綠樹當簷裏，紅藤倚壁牽。","主人閒处立，有客笑扶肩。"]', '诗', 'shi', '', NULL, '章氏幽居 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3385d36-1092-4360-a528-924e3da98e6c', '憶弟從善', '憶弟從善', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["弟貧居歙縣，兄老住豐溪。","大被身分寢，長繩足共覊。","幅雲橫斷嶺，鈎月照斜谿。","安得源源過，陶然樂黍鷄。"]', '["弟貧居歙縣，兄老住豐溪。","大被身分寢，长繩足共覊。","幅云橫斷嶺，鈎月照斜谿。","安得源源過，陶然乐黍鷄。"]', '诗', 'shi', '', NULL, '憶弟從善 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e1e85ad-7f3c-4559-8a73-f2db17287670', '夏日即事', '夏日即事', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["結伴居山寺，超然見白雲。","境閒堪問道，客雅好論文。","坐石惟看奕，行田或課耘。","夜來塵俗語，不向夢中聞。"]', '["結伴居山寺，超然见白云。","境閒堪问道，客雅好論文。","坐石惟看奕，行田或課耘。","夜来塵俗語，不向梦中闻。"]', '诗', 'shi', '', NULL, '夏日即事 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5f9605a-ec79-437d-81d9-9f842432800d', '梅', '梅', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["最愛橫溪曲，橫流一樹梅。","藏根惟愛石，落瓣不沾埃。","臘裏孤清節，春間創闢材。","調羹還有藉，青子百千枚。"]', '["最愛橫溪曲，橫流一樹梅。","藏根惟愛石，落瓣不沾埃。","臘裏孤清節，春间創闢材。","調羹還有藉，青子百千枚。"]', '诗', 'shi', '', NULL, '梅 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59a32830-79c2-4176-b0f9-c15f449dde45', '薄暮步村徑', '薄暮步村徑', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["竹裏荆扉掩，村前萬物幽。","飛蟲摶澗舞，鳴鵲抱巢修。","川上漁歌斷，坡前牧課休。","淡烟隨杖履，吾意自悠悠。"]', '["竹裏荆扉掩，村前万物幽。","飞蟲摶澗舞，鳴鵲抱巢修。","川上漁歌斷，坡前牧課休。","淡烟隨杖履，吾意自悠悠。"]', '诗', 'shi', '', NULL, '薄暮步村徑 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6264e8b-7f5b-4c8b-996e-6e88ada392af', '避亂', '避亂', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["海內風光半血污，殺人聲過似樵蘇。","一身驅路忙如蟻，八口無家散若烏。","栗里無蹤空悵望，桃源有夢失招呼。","饑來野店供飱飯，敢怨匙前脫粟粗。"]', '["海內风光半血污，殺人声過似樵蘇。","一身驱路忙如蟻，八口無家散若烏。","栗里無蹤空悵望，桃源有梦失招呼。","饑来野店供飱飯，敢怨匙前脫粟粗。"]', '诗', 'shi', '', NULL, '避亂 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9651de83-f3bd-4bba-b746-cd206f017493', '春更書懷', '春更书懷', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["豐溪村內野人居，隱約南山對敝廬。","花下小橋春策蹇，竹中深徑夜歸漁。","無名正可驕王謝，有句還能繼庾徐。","醉罷濁醪鄰客散，一番清夢又蘧蘧。"]', '["豐溪村內野人居，隐約南山对敝廬。","花下小橋春策蹇，竹中深徑夜归漁。","無名正可驕王謝，有句還能繼庾徐。","醉罷濁醪鄰客散，一番清梦又蘧蘧。"]', '诗', 'shi', '', NULL, '春更書懷 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a95c924-a94b-46e9-aed9-8869b68b238b', '贈野僧', '贈野僧', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["有客逃禪住北岡，昔年支許意相當。","清如細竹迎風灑，潔似孤松冒雪張。","錫杖倚雪看遠岫，銅瓶汲月煑新湯。","只今石畔雙扉掩，靜閱琅函日幾章。","。"]', '["有客逃禪住北岡，昔年支許意相當。","清如細竹迎风灑，潔似孤松冒雪張。","錫杖倚雪看远岫，銅瓶汲月煑新湯。","只今石畔雙扉掩，静閱琅函日幾章。","。"]', '诗', 'shi', '', NULL, '贈野僧 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1606e976-6a04-42fe-bcb8-9cd8a26153a7', '永豐橋閒坐', '永豐橋閒坐', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["敝襪輕鞋緩足投，永豐橋上寄雙眸。","山沿東舍環西舍，水遶南疇赴北疇。","村婦坐畦挑馬齒，野童蹲澗採鷄頭。","娛閒不覺忘中飯，一點斜陽射竹樓。"]', '["敝襪轻鞋緩足投，永豐橋上寄雙眸。","山沿东舍环西舍，水遶南疇赴北疇。","村婦坐畦挑马齒，野童蹲澗採鷄头。","娛閒不覺忘中飯，一点斜陽射竹楼。"]', '诗', 'shi', '', NULL, '永豐橋閒坐 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95be15f7-5e76-4eeb-bcc5-2754b6e0d55a', '閱田禾', '閱田禾', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["村南村北稻花明，碧影清光夾望平。","節弄暑風輕拂拂，尖懸晚露澹盈盈。","道傍嫗婦呼鷄返，坡外兒童跨犢行。","獨坐小橋幽興滿，蟪蛄聲在柳梢鳴。"]', '["村南村北稻花明，碧影清光夾望平。","節弄暑风轻拂拂，尖懸晚露澹盈盈。","道傍嫗婦呼鷄返，坡外兒童跨犢行。","独坐小橋幽兴满，蟪蛄声在柳梢鳴。"]', '诗', 'shi', '', NULL, '閱田禾 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b0b585a-5ea2-4ec8-989d-ed1e52c57735', '傳婆井', '傳婆井', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["古井無淵源，千秋自涵養。","日暮汲人來，洞然發清響。"]', '["古井無淵源，千秋自涵養。","日暮汲人来，洞然發清响。"]', '诗', 'shi', '', NULL, '傳婆井 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cac559e9-f8df-4a06-b0ff-e200c69a6972', '葺豐溪橋成志喜一絕', '葺豐溪橋成志喜一絕', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["橫流架石梁，刻作永豐字。","好渡杖藜翁，逍遙謂農事。"]', '["橫流架石梁，刻作永豐字。","好渡杖藜翁，逍遙謂農事。"]', '诗', 'shi', '', NULL, '葺豐溪橋成志喜一絕 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e258fb90-7c0d-4673-9eb8-2e1a1789db9a', '醉臥田間賴里人章氏子扶歸作詩以謝之', '醉臥田间賴里人章氏子扶归作诗以謝之', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["荷鋤田澤畔，垂手引糢糊。"]', '["荷鋤田澤畔，垂手引糢糊。"]', '诗', 'shi', '', NULL, '醉臥田間賴里人章氏子扶歸作詩以謝之 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75266368-3ac0-4a15-ab5a-4c2e92f43cc3', '題英濟石', '題英濟石', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["怪石裏苔錢，高聳百餘尺。","我至輒呼名，依稀點危額。"]', '["怪石裏苔錢，高聳百餘尺。","我至輒呼名，依稀点危額。"]', '诗', 'shi', '', NULL, '題英濟石 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0df441d8-38c9-407d-9c0a-51361fca1f87', '觀野燒', '观野燒', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["烈烈西風裏，蓬蕪一掃空。","雖留生意在，已廢半年功。","。"]', '["烈烈西风裏，蓬蕪一掃空。","雖留生意在，已廢半年功。","。"]', '诗', 'shi', '', NULL, '觀野燒 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be8cf80d-9408-4ec8-aeae-76a37ec1b620', '菊', '菊', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["短籬偎曲徑，風雨困秋曦。","競惜芙蓉冷，何知更有伊。"]', '["短籬偎曲徑，风雨困秋曦。","競惜芙蓉冷，何知更有伊。"]', '诗', 'shi', '', NULL, '菊 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0edfc463-7f36-46d6-b23d-26b839973b3c', '柵山', '柵山', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["鬱鬱長林障遠鄉，茸茸細草綠於秧。","好風吹拂閒烟靄，薰得斜暉滿徑香。"]', '["鬱鬱长林障远乡，茸茸細草綠於秧。","好风吹拂閒烟靄，薰得斜暉满徑香。"]', '诗', 'shi', '', NULL, '柵山 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be6c7961-f2f0-48e1-886c-9d27550c3343', '漫興', '漫兴', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["糾嶺豐溪許避秦，一坵一壑老遺民。","妻孥莫漫悲家計，留得黃冠未算貧。"]', '["糾嶺豐溪許避秦，一坵一壑老遺民。","妻孥莫漫悲家計，留得黄冠未算貧。"]', '诗', 'shi', '', NULL, '漫興 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('385b2d6f-c793-41ff-9393-660b039af9c0', '馬蹄痕', '马蹄痕', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["一泓流水舊多情，拂塵乘驄躍淺萍。","父老競傳遺跡在，不知仙客是何名。"]', '["一泓流水旧多情，拂塵乘驄躍淺萍。","父老競傳遺跡在，不知仙客是何名。"]', '诗', 'shi', '', NULL, '馬蹄痕 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9967663-5769-4fe8-818a-8d9a5db451f1', '春日往柵山吟詩於驢子背上未即就誤入側徑爲叢莽所縛卒成之', '春日往柵山吟诗於驢子背上未即就誤入側徑爲叢莽所縛卒成之', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["風生原野翠痕充，澗曲巒隈小徑通。","覔句未成垂首索，不知身掛莽林中。"]', '["风生原野翠痕充，澗曲巒隈小徑通。","覔句未成垂首索，不知身掛莽林中。"]', '诗', 'shi', '', NULL, '春日往柵山吟詩於驢子背上未即就誤入側徑爲叢莽所縛卒成之 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3537b123-de58-4b25-8f3d-7314effbe8a2', '又', '又', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["隔絕羊腸已數旬，到來春靄正盈盈。","山神擬欲求新句，牽住衣裳不放行。"]', '["隔絕羊腸已數旬，到来春靄正盈盈。","山神擬欲求新句，牽住衣裳不放行。"]', '诗', 'shi', '', NULL, '又 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01200a90-c853-442b-9718-e331b49a883f', '寄弟', '寄弟', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["函罷家音又拆看，添書絕句報平安。","豐溪漁叟生涯定，明月清風一釣竿。"]', '["函罷家音又拆看，添书絕句報平安。","豐溪漁叟生涯定，明月清风一釣竿。"]', '诗', 'shi', '', NULL, '寄弟 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('453437ce-6f21-415f-a0fe-09958fa594c6', '糾峯別業', '糾峯別業', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["糾峯嶺半樹森然，伐竹編成翠底廛。","雜客不來塵思少，落花啼鳥自年年。","。"]', '["糾峯嶺半樹森然，伐竹編成翠底廛。","杂客不来塵思少，落花啼鸟自年年。","。"]', '诗', 'shi', '', NULL, '糾峯別業 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00cf58db-89e0-477e-b7c3-be9752977f5b', '德山老人送茶至', '德山老人送茶至', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["數株香苕產松坡，野老新分半兩多。","釣罷歸來兒說與，引瓢旋汲澗中波。"]', '["數株香苕產松坡，野老新分半兩多。","釣罷归来兒说與，引瓢旋汲澗中波。"]', '诗', 'shi', '', NULL, '德山老人送茶至 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21dacf0b-9fc7-4a11-b768-b744a35fa112', '豐溪秋社', '豐溪秋社', '6847ac51-eb82-4528-8717-c868f750b6de', '唐', '["稻熟瓜纍歲有仁，烹鷄割豕祀田神。","分腥不覺歸來晚，一幅雲煙擁醉人。","（〖1〗《四庫全書總目提要》謂：「其集歷代史志書目皆不著錄。","此本爲乾隆庚申其裔孫積祚所刊，稱其從叔高祖元進所手錄，黃之雋、邵泰、儲大文皆爲之序，稱其湮沒八百年而始顯。","然其書晚出，授受源流渺不可考，越宋、元、明至今，忽傳於世，論者頗以爲疑。","」並舉用詞數條，以爲不似晚唐五代人語。","且謂《春雪往柵山》一詩，題中有「敲詩驢子背上」語。","實賈島咏推敲二字不定，見《唐摭言》，鄭綮言『詩思在灞橋風雪中驢子背上』，見《唐詩紀事》，在今日則爲故典，在唐末猶爲近事，不應從慶用之。","且稱吟詩爲推敲，已屬割裂，至改爲敲詩，明以前人實無此語。","按南高圖書館藏同治重鐫本此詩題作《春日往柵山吟詩於驢子背上未即就誤入側徑爲叢莽所縛卒成之》。","無敲詩之語，是傳本有不同也。","其餘用詞可疑者，又安知非輾轉抄刻中所致耶？","至古籍之不顯于當世而復見於後代者，其例實繁，故仍錄存之，以俟海內方家之論定焉。","）。"]', '["稻熟瓜纍歲有仁，烹鷄割豕祀田神。","分腥不覺归来晚，一幅云煙擁醉人。","（〖1〗《四庫全书總目提要》謂：「其集歷代史志书目皆不著錄。","此本爲乾隆庚申其裔孫積祚所刊，稱其從叔高祖元進所手錄，黄之雋、邵泰、儲大文皆爲之序，稱其湮沒八百年而始显。","然其书晚出，授受源流渺不可考，越宋、元、明至今，忽傳於世，論者頗以爲疑。","」並舉用词數條，以爲不似晚唐五代人語。","且謂《春雪往柵山》一诗，題中有「敲诗驢子背上」語。","實賈島咏推敲二字不定，见《唐摭言》，鄭綮言『诗思在灞橋风雪中驢子背上』，见《唐诗紀事》，在今日則爲故典，在唐末猶爲近事，不應從慶用之。","且稱吟诗爲推敲，已屬割裂，至改爲敲诗，明以前人實無此語。","按南高圖书館藏同治重鐫本此诗題作《春日往柵山吟诗於驢子背上未即就誤入側徑爲叢莽所縛卒成之》。","無敲诗之語，是傳本有不同也。","其餘用词可疑者，又安知非輾轉抄刻中所致耶？","至古籍之不显于當世而复见於後代者，其例實繁，故仍錄存之，以俟海內方家之論定焉。","）。"]', '诗', 'shi', '', NULL, '豐溪秋社 呂從慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6b2b176-e116-4cbc-b73e-6c8996c80c88', '贈陳郎（題擬）', '贈陳郎（題擬）', '32eb2807-6231-496d-ad1c-c603369da4ff', '唐', '["陳郎不著世儒衫，也好嬉游日笑談。","幸有葛巾與藜杖，從呼宮觀老都監。","（見《江南餘載》卷上。","）（〖1〗《江南餘載》：陳致堯雍熟於《開元禮》，官太常博士，國之大禮，皆折衷焉。","與韓熙載最善。","家無儋石之儲，然妾妓至數百，暇奏《霓裳羽衣》之聲，頗以帷簿取譏於時。","二人左降者數矣，熙載詩〖詩不重錄〗云云。","其廳中置大鈴，大署其旁曰：「無錢僱僕，客至請挽之。","」）。"]', '["陳郎不著世儒衫，也好嬉游日笑談。","幸有葛巾與藜杖，從呼宮观老都監。","（见《江南餘載》卷上。","）（〖1〗《江南餘載》：陳致堯雍熟於《开元禮》，官太常博士，国之大禮，皆折衷焉。","與韓熙載最善。","家無儋石之儲，然妾妓至數百，暇奏《霓裳羽衣》之声，頗以帷簿取譏於时。","二人左降者數矣，熙載诗〖诗不重錄〗云云。","其廳中置大鈴，大署其旁曰：「無錢僱僕，客至請挽之。","」）。"]', '诗', 'shi', '', NULL, '贈陳郎（題擬） 韓熙載 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d826e40d-7ca7-443e-8d3e-1afb61a0e471', '', '', '064a506f-9df0-467a-a4fe-0e1a0e2e4c8c', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 段義宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebd1cbbd-4599-4a9a-a5fc-d8c09c115518', '題大慈寺芍藥', '題大慈寺芍藥', '064a506f-9df0-467a-a4fe-0e1a0e2e4c8c', '唐', '["浮花不與衆花同，爲感高僧護法功。","繁影夜鋪方丈月，異香朝散講筵風。","尋真自得心源靜，觀色非貪眼界空。","好是芳馨堪供養，天教生在釋門中。","（見後蜀何光遠《鑑誡錄》卷六。","）（《知不足斎叢書》二十二集第一百七十冊。","按《全唐詩》佚句卷僅存首二句。","此首句「浮花」，《全唐詩》作「此花」。","）。"]', '["浮花不與衆花同，爲感高僧護法功。","繁影夜鋪方丈月，異香朝散講筵风。","尋真自得心源静，观色非貪眼界空。","好是芳馨堪供養，天教生在釋门中。","（见後蜀何光远《鑑誡錄》卷六。","）（《知不足斎叢书》二十二集第一百七十冊。","按《全唐诗》佚句卷僅存首二句。","此首句「浮花」，《全唐诗》作「此花」。","）。"]', '诗', 'shi', '', NULL, '題大慈寺芍藥 段義宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e26e619-0333-434f-b830-ce9a366ca837', '題三學院經樓', '題三学院經楼', '064a506f-9df0-467a-a4fe-0e1a0e2e4c8c', '唐', '["鷲嶺鷄園不可儔，叨陪龍象喜登遊。","玉排複道珊瑚殿，金錯危欄翡翠樓。","尚欲歸心求四諦，敢辭旋繞滿三周。","羲和鞭撻金烏疾，欲網無由肯駐留？","（同前《鑑誡錄》卷六。","《全唐詩》佚句卷只存三、四句。","此詩第四句「危欄」，《全唐詩》作「危椆」。","）。"]', '["鷲嶺鷄园不可儔，叨陪龙象喜登游。","玉排複道珊瑚殿，金錯危欄翡翠楼。","尚欲归心求四諦，敢辞旋繞满三周。","羲和鞭撻金烏疾，欲網無由肯駐留？","（同前《鑑誡錄》卷六。","《全唐诗》佚句卷只存三、四句。","此诗第四句「危欄」，《全唐诗》作「危椆」。","）。"]', '诗', 'shi', '', NULL, '題三學院經樓 段義宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a77db47b-0cb4-4b36-9d5f-21895ec65e78', '又題', '又題', '064a506f-9df0-467a-a4fe-0e1a0e2e4c8c', '唐', '["當今積善競修崇，七寶莊嚴作梵宮。","佛日明時齊舜日，皇風清處接慈風。","一乘妙理應難測，萬刼良緣豈易窮。","共恨塵勞非法侶，掉鞭歸去夕陽中。","（同前《鑑誡錄》卷六。","《全唐詩》亦無佚句。","）（望按：《全唐詩》佚句卷共收段義宗佚詩六句，注云出《吟窗雜錄》。","其中「浮花」兩句，即今補第一首中句；「玉排」二句，即今補第二首中句。","另有「懸心秋夜月。","萬里照鄉關」兩句，實非佚句，全詩已收入《全唐詩》，署名「布燮」。","布燮，長和國人猶言宰相也，非人名，《全唐詩》與作者名等視之，失察矣。","句中「鄉關」，《鑑譖錄》作「關山」。","日本漢學家豐田穰氏所撰《全唐詩糾謬》〖見昭和二十三年即公元一九四八年養德社刊《唐詩研究》〗一文，中曾據我國後蜀何光遠《鑑誡錄》卷六《布燮朝》一條，稽之《全唐詩》，謂係《全唐詩》所未收，可以補佚云云。","此文近承日友波多）（野太郎教授函贈，即以鮑氏刻《知不足齋叢書》本《鑑誡錄》校其原詩。","畧誌顛末，深以得豐田氏論文啓迪之助爲感。","）。"]', '["當今積善競修崇，七寶莊嚴作梵宮。","佛日明时齊舜日，皇风清处接慈风。","一乘妙理應难測，万刼良緣豈易窮。","共恨塵勞非法侶，掉鞭归去夕陽中。","（同前《鑑誡錄》卷六。","《全唐诗》亦無佚句。","）（望按：《全唐诗》佚句卷共收段義宗佚诗六句，注云出《吟窗杂錄》。","其中「浮花」兩句，即今補第一首中句；「玉排」二句，即今補第二首中句。","另有「懸心秋夜月。","万里照乡关」兩句，實非佚句，全诗已收入《全唐诗》，署名「布燮」。","布燮，长和国人猶言宰相也，非人名，《全唐诗》與作者名等視之，失察矣。","句中「乡关」，《鑑譖錄》作「关山」。","日本漢学家豐田穰氏所撰《全唐诗糾謬》〖见昭和二十三年即公元一九四八年養德社刊《唐诗研究》〗一文，中曾據我国後蜀何光远《鑑誡錄》卷六《布燮朝》一條，稽之《全唐诗》，謂係《全唐诗》所未收，可以補佚云云。","此文近承日友波多）（野太郎教授函贈，即以鲍氏刻《知不足斋叢书》本《鑑誡錄》校其原诗。","畧誌顛末，深以得豐田氏論文啓迪之助爲感。","）。"]', '诗', 'shi', '', NULL, '又題 段義宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af40f526-1f39-4069-b3bb-e01d2c233e68', '', '', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["（《全唐詩》編徐鉉詩爲六卷，以下二首及句均所未收，據《宋詩紀事》卷三錄補之。","）。"]', '["（《全唐诗》編徐鉉诗爲六卷，以下二首及句均所未收，據《宋诗紀事》卷三錄補之。","）。"]', '诗', 'shi', '', NULL, ' 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a738430c-46ac-4928-abdd-ad43d22b2b62', '吳王挽辭二首 一', '吳王挽辞二首 一', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["倏忽千齡盡，冥茫萬事空。","青松洛陽陌，白草建康宮。","道德遺文在，興衰自古同。","受恩無補報，反袂泣途窮。"]', '["倏忽千齡尽，冥茫万事空。","青松洛陽陌，白草建康宮。","道德遺文在，兴衰自古同。","受恩無補報，反袂泣途窮。"]', '诗', 'shi', '', NULL, '吳王挽辭二首 一 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5faeff56-6a32-40a0-a23d-3060e471e473', '吳王挽辭二首 二', '吳王挽辞二首 二', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["土德承餘烈，江南廣舊恩。","一朝人事變，千古信書存。","哀挽周原道，銘旌鄭國門。","此生雖未死，寂寞已消魂。","（以上二首角《宋詩紀事》卷三。","）（見《東軒筆錄》卷一、《宋朝事實類苑》卷三六。","第一首第四句「白草」二字，《東軒筆錄》作「芳草」、《宋朝事實類苑》作「荒草」。","）（〖1〗宋翟耆年《籀史》：「徐鉉鼎臣從李煜歸朝，爲銀青光祿大夫、右散騎常侍。","太平興國中，李煜薨，詔侍臣撰煜神道碑。","有欲中傷鉉者，奏曰：『吳王事，莫若徐鉉爲詳。","』遂詔鉉撰。","鉉泣曰：『臣舊事李煜，陛下容臣存故主之義，乃敢奉詔。","』太宗許之。","鉉但推言歷數有盡，天命有歸而已。","其警句云：『東鄰搆禍，南箕扇疑，投杼致慈親之惑，乞火無鄰婦之詞。","始勞因壘之師，終後塗山之會。","』太宗覽之，稱歎不已。","異日復得鉉所撰《吳王挽詞》，今傳者二首云云。","鉉被詔撰《江南錄》，故有『信書』之句。","東鄰謂錢俶也。","」〖2〗望按：如《籀史》所載，知挽辭二首之作，已在入宋之後。","以所涉李煜，曾是南唐之主，而徐鉉生活於五代者亦四十餘年，且《全唐詩》徐鉉卷亦收其仕宋後篇什，故仍援例錄補，俾成完帙。","）。"]', '["土德承餘烈，江南廣旧恩。","一朝人事变，千古信书存。","哀挽周原道，銘旌鄭国门。","此生雖未死，寂寞已消魂。","（以上二首角《宋诗紀事》卷三。","）（见《东軒笔錄》卷一、《宋朝事實類苑》卷三六。","第一首第四句「白草」二字，《东軒笔錄》作「芳草」、《宋朝事實類苑》作「荒草」。","）（〖1〗宋翟耆年《籀史》：「徐鉉鼎臣從李煜归朝，爲銀青光祿大夫、右散騎常侍。","太平兴国中，李煜薨，詔侍臣撰煜神道碑。","有欲中傷鉉者，奏曰：『吳王事，莫若徐鉉爲詳。","』遂詔鉉撰。","鉉泣曰：『臣旧事李煜，陛下容臣存故主之義，乃敢奉詔。","』太宗許之。","鉉但推言歷數有尽，天命有归而已。","其警句云：『东鄰搆禍，南箕扇疑，投杼致慈親之惑，乞火無鄰婦之词。","始勞因壘之師，終後塗山之會。","』太宗覽之，稱歎不已。","異日复得鉉所撰《吳王挽词》，今傳者二首云云。","鉉被詔撰《江南錄》，故有『信书』之句。","东鄰謂錢俶也。","」〖2〗望按：如《籀史》所載，知挽辞二首之作，已在入宋之後。","以所涉李煜，曾是南唐之主，而徐鉉生活於五代者亦四十餘年，且《全唐诗》徐鉉卷亦收其仕宋後篇什，故仍援例錄補，俾成完帙。","）。"]', '诗', 'shi', '', NULL, '吳王挽辭二首 二 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99296779-2df5-4d76-b1b0-c87f0bfbd95b', '句 一', '句 一', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["落月依樓閣，歸雲擁殿廊。","（《宿山寺》，見《宋詩紀事》引宋釋文瑩《玉壺野史》。","）（見《玉壺清話》卷八。","）。"]', '["落月依楼閣，归云擁殿廊。","（《宿山寺》，见《宋诗紀事》引宋釋文瑩《玉壺野史》。","）（见《玉壺清話》卷八。","）。"]', '诗', 'shi', '', NULL, '句 一 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f70d2979-1e74-4be4-b521-d42d265c4a99', '句 二', '句 二', 'bccea2dd-8df6-4b03-98e3-79e9785fa29f', '唐', '["鐘山祠畔宿煙晴，玉澗橋邊碧樹春。","（見《景定建康志》卷十八《山川志》。）"]', '["鐘山祠畔宿煙晴，玉澗橋邊碧樹春。","（见《景定建康志》卷十八《山川志》。）"]', '诗', 'shi', '', NULL, '句 二 徐鉉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61ff052e-82c1-4f6b-99dd-c4341b985541', '', '', 'e74fd3a3-902d-4fe9-9d98-b3113de59f9f', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 范質 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37c5b00f-594e-4de1-a495-48555d8570a2', '誡兒姪八百字', '誡兒姪八百字', 'e74fd3a3-902d-4fe9-9d98-b3113de59f9f', '唐', '["（昨得謝課書，希於京秩之中更與遷轉。","余以諸兒姪輩生長以來，未諳外事，艱難損益，懵然莫知，因抒古詩一章曉之。","）去年初釋褐，一命列蓬丘。","（謂謝課。","）青袍春草色，白紵棄如仇。","適會龍飛慶，王澤天下流。","爾得六品階，無乃太爲優。","凡登進士第，四選昇校讐。","歷官十五考，敘階與爾儔。","如何志未滿，意欲陵（《紀事》「陵」作「凌」。","）雲遊。","若言品位卑，寄書來我求。","省之再三歎，不覺淚盈眸。","吾家本寒素，門地寡公侯。","先子有令德，樂道尚憂游。","生逢世多僻，委任信沉浮。","仕宦不喜達，吏隱同莊周。","積善有餘慶，清白爲貽謀。","伊余奉家訓，孜孜務進修。","夙夜事勤肅，言行思悔尤。","出門擇交友，防慎畏薰蕕。","省躬常懼玷，恐掇庭闈羞。","童年志於學，不墮（《紀事》「墮」作「惰」。","）爲箕裘。","二十中甲科，頳尾化爲虬。","（二十三進士及第，今舉全數。","）三十入翰苑（時三十三，），步武向瀛州。","四十登宰輔（年四十一），貂冠侍冕旒。","備位行一紀，將何助帝猷。","既非救旱雨，豈是濟川舟。","天子未遐棄，日益素餐憂。","黃河潤千里，草木皆浸漬。","吾宗凡九人，繼踵昇官次。","門內無白丁，森森朱綠紫。","鵷行洎內職，亞尹州從事。","府掾監省官，高低皆清美。","悉田僥倖昇，不因資考至。","朝廷懸爵秩，命之曰公器。","才者祿及身，功者賞於世。","非才及非功。","安得專（《紀事》「專」作「霑」。","）厚利。","寒衣內府帛，飢食太倉米。","不蠶復不穡，未嘗勤四體。","雖然一家榮，豈塞衆人議。","顒顒十目窺，齪齪千人指。","（曾參云：「十目所視。","」古人云：「千人所指。","」言可畏。","）借問爾與吾，如何不自媿？","戒爾學立身，莫若先孝悌。","怡怡奉親長，不敢生驕易。","戰戰復兢兢，造次必於是。","戒爾學干祿，莫若勤道藝。","嘗聞諸格言，學而優則仕。","不患人不知，惟患學不至。","戒爾遠恥辱，恭則近乎禮。","自卑而尊人，先彼而後己。","《相鼠》與《茅鴟》，宜鑒詩人剌。","（《毛詩》：「《相鼠》，刺無禮。","」《左傳》：「茅鴟」，刺不恭。","）戒爾勿放曠，放曠非端士。","周孔垂名教，齊梁尚清議。","南朝稱八達，千載穢青史。","戒爾勿嗜酒，狂藥非佳味。","能移謹厚性。","化爲凶險（《紀事》「險」作「暴」。","）類。","古今傾敗者，歷歷皆可記。","戒爾勿多言，多言者衆（《紀事》「者衆」作「衆所」。","）忌。","苟不慎樞機，災危從此始。","是非毀譽間，適足爲身累。","舉世重交遊，擬結金蘭契。","忿怨容易（《紀事》「容易」作「從是」。","）生，風波當時起。","所以公君子心，汪汪淡如水。","舉世好承奉，昂昂增意氣。","不知承奉者，以爾爲玩戲。","所以古人疾，籧篨與戚施。","舉世重任俠，（《史記》：「輕死重義曰俠。","」）呼俗（《紀事》「呼俗」作「俗呼」。","）爲氣義。","（《紀事》「氣義」作「義士」。","）爲人赴急難，往往陷刑死。","所以馬援書，殷勤戒諸子。","（馬援告兒孫書，甚非此事。","）舉世賤清素，奉身好華侈。","肥馬衣輕裘，揚揚過閭里。","雖得巿童憐，還爲識者鄙。","我本羈旅臣，遭逢堯舜理。","位重才不充，戚戚懷憂畏。","深淵與薄冰，蹈之唯恐墜。","爾曹非憫我，勿使著罪戾。","閉門斂蹤跡，縮首避名勢。","名勢不久居，畢竟何足恃。","物盛必有衰，有隆還有替。","速成不堅牢，亟走多顛躓。","灼灼園中花，早發還先萎。","遲遲澗畔松，鬱鬱含晚翠。","賦命有疾徐，青雲難力致。","寄語謝諸郎，躁進徒爲耳。","（見《宋文鑑》卷十四。","以《宋詩紀事》校之。","）（此詩疑作於入宋後。","）（〖1〗《宋史》卷二四九《范質傳》：「從子校書郎杲求奏遷秩，質作詩曉之。","時人傳誦，以爲勸戒。","」）。"]', '["（昨得謝課书，希於京秩之中更與遷轉。","余以諸兒姪輩生长以来，未諳外事，艱难損益，懵然莫知，因抒古诗一章晓之。","）去年初釋褐，一命列蓬丘。","（謂謝課。","）青袍春草色，白紵棄如仇。","適會龙飞慶，王澤天下流。","爾得六品階，無乃太爲優。","凡登進士第，四選昇校讐。","歷官十五考，敘階與爾儔。","如何志未满，意欲陵（《紀事》「陵」作「凌」。","）云游。","若言品位卑，寄书来我求。","省之再三歎，不覺泪盈眸。","吾家本寒素，门地寡公侯。","先子有令德，乐道尚憂游。","生逢世多僻，委任信沉浮。","仕宦不喜達，吏隐同莊周。","積善有餘慶，清白爲貽謀。","伊余奉家訓，孜孜務進修。","夙夜事勤肅，言行思悔尤。","出门擇交友，防慎畏薰蕕。","省躬常懼玷，恐掇庭闈羞。","童年志於学，不墮（《紀事》「墮」作「惰」。","）爲箕裘。","二十中甲科，頳尾化爲虬。","（二十三進士及第，今舉全數。","）三十入翰苑（时三十三，），步武向瀛州。","四十登宰輔（年四十一），貂冠侍冕旒。","備位行一紀，將何助帝猷。","既非救旱雨，豈是濟川舟。","天子未遐棄，日益素餐憂。","黄河潤千里，草木皆浸漬。","吾宗凡九人，繼踵昇官次。","门內無白丁，森森朱綠紫。","鵷行洎內職，亞尹州從事。","府掾監省官，高低皆清美。","悉田僥倖昇，不因資考至。","朝廷懸爵秩，命之曰公器。","才者祿及身，功者賞於世。","非才及非功。","安得專（《紀事》「專」作「霑」。","）厚利。","寒衣內府帛，飢食太倉米。","不蠶复不穡，未嘗勤四體。","雖然一家榮，豈塞衆人議。","顒顒十目窺，齪齪千人指。","（曾參云：「十目所視。","」古人云：「千人所指。","」言可畏。","）借问爾與吾，如何不自媿？","戒爾学立身，莫若先孝悌。","怡怡奉親长，不敢生驕易。","戰戰复兢兢，造次必於是。","戒爾学干祿，莫若勤道藝。","嘗闻諸格言，学而優則仕。","不患人不知，惟患学不至。","戒爾远恥辱，恭則近乎禮。","自卑而尊人，先彼而後己。","《相鼠》與《茅鴟》，宜鑒诗人剌。","（《毛诗》：「《相鼠》，刺無禮。","」《左傳》：「茅鴟」，刺不恭。","）戒爾勿放曠，放曠非端士。","周孔垂名教，齊梁尚清議。","南朝稱八達，千載穢青史。","戒爾勿嗜酒，狂藥非佳味。","能移謹厚性。","化爲凶險（《紀事》「險」作「暴」。","）類。","古今傾敗者，歷歷皆可記。","戒爾勿多言，多言者衆（《紀事》「者衆」作「衆所」。","）忌。","苟不慎樞機，災危從此始。","是非毀譽间，適足爲身累。","舉世重交游，擬結金蘭契。","忿怨容易（《紀事》「容易」作「從是」。","）生，风波當时起。","所以公君子心，汪汪淡如水。","舉世好承奉，昂昂增意氣。","不知承奉者，以爾爲玩戲。","所以古人疾，籧篨與戚施。","舉世重任俠，（《史記》：「轻死重義曰俠。","」）呼俗（《紀事》「呼俗」作「俗呼」。","）爲氣義。","（《紀事》「氣義」作「義士」。","）爲人赴急难，往往陷刑死。","所以马援书，殷勤戒諸子。","（马援告兒孫书，甚非此事。","）舉世賤清素，奉身好华侈。","肥马衣轻裘，揚揚過閭里。","雖得巿童怜，還爲識者鄙。","我本羈旅臣，遭逢堯舜理。","位重才不充，戚戚懷憂畏。","深淵與薄冰，蹈之唯恐墜。","爾曹非憫我，勿使著罪戾。","閉门斂蹤跡，縮首避名勢。","名勢不久居，畢竟何足恃。","物盛必有衰，有隆還有替。","速成不堅牢，亟走多顛躓。","灼灼园中花，早發還先萎。","遲遲澗畔松，鬱鬱含晚翠。","賦命有疾徐，青云难力致。","寄語謝諸郎，躁進徒爲耳。","（见《宋文鑑》卷十四。","以《宋诗紀事》校之。","）（此诗疑作於入宋後。","）（〖1〗《宋史》卷二四九《范質傳》：「從子校书郎杲求奏遷秩，質作诗晓之。","时人傳誦，以爲勸戒。","」）。"]', '诗', 'shi', '', NULL, '誡兒姪八百字 范質 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc9eedb6-8892-423e-b96b-92f90cc73652', '謝進士張翼投詩兩軸', '謝進士張翼投诗兩軸', '28024555-039f-423d-ae55-581c5e3a9023', '唐', '["清河詩客本賢良，惠我新吟六十章。","格調宛同羅給事，功夫深似賈司倉。","登山始覺天高廣，到海方知浪渺茫。","好去蟾宮是歸路，明年應折桂枝香。","（見《宋詩紀事》引宋張齊賢《洛陽搢紳舊聞記》。","）（見《洛陽縉紳舊聞記》卷一《陶副車求薦見忌》。","）。"]', '["清河诗客本賢良，惠我新吟六十章。","格調宛同羅給事，功夫深似賈司倉。","登山始覺天高廣，到海方知浪渺茫。","好去蟾宮是归路，明年應折桂枝香。","（见《宋诗紀事》引宋張齊賢《洛陽搢紳旧闻記》。","）（见《洛陽縉紳旧闻記》卷一《陶副车求薦见忌》。","）。"]', '诗', 'shi', '', NULL, '謝進士張翼投詩兩軸 王溥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a842ac0-88c9-4cff-b32a-052ef720c1ec', '詠牡丹', '詠牡丹', '28024555-039f-423d-ae55-581c5e3a9023', '唐', '["棗花至小能成實，桑葉雖柔解吐絲。","堪笑牡丹如斗大，不成一事又空枝。","（見《宋詩紀事》引《歷代吟譜》。","見明刻本《吟窗雜錄》卷三十三《歷代吟譜》。","）。"]', '["棗花至小能成實，桑葉雖柔解吐絲。","堪笑牡丹如斗大，不成一事又空枝。","（见《宋诗紀事》引《歷代吟譜》。","见明刻本《吟窗杂錄》卷三十三《歷代吟譜》。","）。"]', '诗', 'shi', '', NULL, '詠牡丹 王溥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd6fc024-4b18-4f7e-a4c5-d4f60aebc5b5', '', '', 'ff01fb75-c92d-4a5e-a9b8-da557c8ca673', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 李昉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a8baf1f-0a09-4aab-bf12-f15ab3a28b8a', '贈賈黃中（賈以七歲應童子舉）', '贈賈黄中（賈以七歲應童子舉）', 'ff01fb75-c92d-4a5e-a9b8-da557c8ca673', '唐', '["七歲神童古所難，賈家門戶有衣冠。","十人科第排頭上，五部經書誦舌端。","見榜不知名字貴，登筵未識管弦歡。","從今穩上青雲去，萬里誰能測羽翰。","（見《宋詩紀事》引《聞見前錄》。","）（見《邵多聞見錄》卷六。","）（望按：賈黃中字媧民，南皮人。","生後晉天福六年，卒宋太宗至道二年。","《宋史》卷二六五有傳。","詩註云「七歲應童子舉」，則時當晉天福十二年，尚未入宋也。","）。"]', '["七歲神童古所难，賈家门戶有衣冠。","十人科第排头上，五部經书誦舌端。","见榜不知名字貴，登筵未識管弦歡。","從今穩上青云去，万里誰能測羽翰。","（见《宋诗紀事》引《闻见前錄》。","）（见《邵多闻见錄》卷六。","）（望按：賈黄中字媧民，南皮人。","生後晉天福六年，卒宋太宗至道二年。","《宋史》卷二六五有傳。","诗註云「七歲應童子舉」，則时當晉天福十二年，尚未入宋也。","）。"]', '诗', 'shi', '', NULL, '贈賈黃中（賈以七歲應童子舉） 李昉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1aa86ed4-14da-4c5a-a9c6-a0872cabdb12', '仙客', '仙客', 'ff01fb75-c92d-4a5e-a9b8-da557c8ca673', '唐', '["胎化仙禽性本殊，何人攜爾到京都。","因加美號爲仙客，稱向閑庭伴野夫。","警露秋聲雲多遠，翹沙晴影月中孤。","青田萬里終歸去，暫處雞羣莫歎吁。","（見《宋詩紀事》卷二。","）（見《瀛奎律髓》卷二七。","）（〖1〗《青箱雜記》〖宋吳處厚撰〗：「昉所畜五禽，名五客，仙客鶴，雪客鷺，閑客白鷴，隴客南客孔雀，西客鸚鵡，有詩云。","」〖今本《青箱雜記》無此條。","〗）。"]', '["胎化仙禽性本殊，何人携爾到京都。","因加美號爲仙客，稱向闲庭伴野夫。","警露秋声云多远，翹沙晴影月中孤。","青田万里終归去，暫处雞羣莫歎吁。","（见《宋诗紀事》卷二。","）（见《瀛奎律髓》卷二七。","）（〖1〗《青箱杂記》〖宋吳处厚撰〗：「昉所畜五禽，名五客，仙客鹤，雪客鷺，闲客白鷴，隴客南客孔雀，西客鸚鵡，有诗云。","」〖今本《青箱杂記》無此條。","〗）。"]', '诗', 'shi', '', NULL, '仙客 李昉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eaa78063-2d62-497b-ac47-ad72ffa5f2e0', '耒陽杜工部墓（題擬）', '耒陽杜工部墓（題擬）', '2b9eb1c7-fc71-4bc0-8dde-d644975953b0', '唐', '["南遊何感思，更甚葉繽紛。","一夜耒江雨，百年工部文。","青山當日見，白酒至今聞。","惟有爲詩者，經過時弔君。","（見錢謙益《箋注杜工部集唱酬題就是》引《耒陽祠志》。","《增修詩話總龜》卷四三引劉斧《摭遺》引「一夜耒江雨，百年工部文」二句，稱爲「唐人詩」。","）。"]', '["南游何感思，更甚葉繽紛。","一夜耒江雨，百年工部文。","青山當日见，白酒至今闻。","惟有爲诗者，經過时弔君。","（见錢謙益《箋注杜工部集唱酬題就是》引《耒陽祠志》。","《增修诗話總龟》卷四三引劉斧《摭遺》引「一夜耒江雨，百年工部文」二句，稱爲「唐人诗」。","）。"]', '诗', 'shi', '', NULL, '耒陽杜工部墓（題擬） 孟賓于 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99983eda-8625-46d0-a18b-1818355e59fa', '贈徐鼎臣常侍', '贈徐鼎臣常侍', '78385c20-7d8d-47a8-99b9-5b630903f04f', '唐', '["不將才業暫時誇，人仰聲名遍海涯。","月滿朝衣聽禁漏，更闌分直掃宮花。","諫書未上先焚稾，御筆曾傳立草麻。","見說下朝無一事，小池栽葦學僧家。","（見《江南餘載》卷下。","）（〖1〗《江南餘載》畧謂：徐鉉爲人忠厚，不以位貌驕人。","有印粲者獻詩曰〖詩不重錄〗云云。","望按：徐鉉有《印秀才至舒州見尋別後寄詩依韻和》及「和印先輩及第後獻座主朱舍人郊居之作」，則印粲於時已擢進士第矣。","又按《歷代吟譜》錄印粲詩二句：「見說下朝無一事，小池栽葦學僧家。","」標其題曰《贈徐鼎臣常侍》，蓋此詩之末二句也。","）。"]', '["不將才業暫时誇，人仰声名遍海涯。","月满朝衣听禁漏，更闌分直掃宮花。","諫书未上先焚稾，御笔曾傳立草麻。","见说下朝無一事，小池栽葦学僧家。","（见《江南餘載》卷下。","）（〖1〗《江南餘載》畧謂：徐鉉爲人忠厚，不以位貌驕人。","有印粲者獻诗曰〖诗不重錄〗云云。","望按：徐鉉有《印秀才至舒州见尋別後寄诗依韻和》及「和印先輩及第後獻座主朱舍人郊居之作」，則印粲於时已擢進士第矣。","又按《歷代吟譜》錄印粲诗二句：「见说下朝無一事，小池栽葦学僧家。","」標其題曰《贈徐鼎臣常侍》，蓋此诗之末二句也。","）。"]', '诗', 'shi', '', NULL, '贈徐鼎臣常侍 印粲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5536581-b613-4387-8ec9-718bc4f5003f', '夜吟竇鞏集追思夷門題處已三稔矣悽然感興書之', '夜吟竇鞏集追思夷门題处已三稔矣悽然感兴书之', '5ea269ad-d631-4e05-b4cc-36254d0106b0', '唐', '["往歲記時梁苑夜，今宵題處洛城秋。","浮生瞥電人何在，懷舊傷心淚迸流。","三徑竹風鄰笛怨，一庭霜月井[桐]（梧）愁。","妻兒未會[余]（予）惆悵，只怪燈前不舉頭。","（見《宋詩紀事》卷二。","此詩出影宋刻《竇氏聯珠集》附錄，詩前有張昭跋：「鞏囁嚅，詩一何神妙，恨此少不見。","其集，《聯珠》之最也。","戊戌歲中元前一日夷門旅舍書，潛夫。","」潛夫爲昭字。","詩題中「夷門題處」，即指此跋。","戊戌爲天福三年〖九三八〗，知詩作於天福六年〖九四一〗。","有二處異文，今據改。","）。"]', '["往歲記时梁苑夜，今宵題处洛城秋。","浮生瞥電人何在，懷旧傷心泪迸流。","三徑竹风鄰笛怨，一庭霜月井[桐]（梧）愁。","妻兒未會[余]（予）惆悵，只怪灯前不舉头。","（见《宋诗紀事》卷二。","此诗出影宋刻《竇氏聯珠集》附錄，诗前有張昭跋：「鞏囁嚅，诗一何神妙，恨此少不见。","其集，《聯珠》之最也。","戊戌歲中元前一日夷门旅舍书，潛夫。","」潛夫爲昭字。","诗題中「夷门題处」，即指此跋。","戊戌爲天福三年〖九三八〗，知诗作於天福六年〖九四一〗。","有二处異文，今據改。","）。"]', '诗', 'shi', '', NULL, '夜吟竇鞏集追思夷門題處已三稔矣悽然感興書之 張昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08cacbb0-bbce-4675-9498-f1d68a22fb80', '贈馬道士', '贈马道士', '5de0b3b3-3ffc-4f7e-8037-46f5362bec5c', '唐', '["水共逍遙雲共孤，混時言笑只佯愚。","經年但醉宜城酒，千里唯擔《華嶽圖》。","尋野鶴來空碧洞，覔琴僧去渡重湖。","人間再見知何日，乞取先生石轆轤。","（見方回《瀛奎髓》卷四十八《仙逸類》。","）（按《瀛奎律髓》原注云：「九齡，乾德五年進士第三人。","」與《全唐詩》小傳作乾德二年者異。","）。"]', '["水共逍遙云共孤，混时言笑只佯愚。","經年但醉宜城酒，千里唯擔《华嶽圖》。","尋野鹤来空碧洞，覔琴僧去渡重湖。","人间再见知何日，乞取先生石轆轤。","（见方回《瀛奎髓》卷四十八《仙逸類》。","）（按《瀛奎律髓》原注云：「九齡，乾德五年進士第三人。","」與《全唐诗》小傳作乾德二年者異。","）。"]', '诗', 'shi', '', NULL, '贈馬道士 李九齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b82e4931-af00-4667-882f-900b181839c8', '贈譚先生', '贈譚先生', 'a1f60d22-5353-49b8-81c1-f5b0c6c54b46', '唐', '["古觀重重遶翠微，杉松深處掩雙扉。","雲生萬壑投龍去，海隔三山放鶴歸。","花洞宴游春日永，石壇朝禮曙星稀。","每聽高論長生理，擬向塵中便拂衣。","（見《瀛奎律髓》卷四十八《仙逸類》。","此詩明李蔉所輯《宋藝圃集》作李九齡詩。","按徽之又有《禁林讌會之什》一首見於《翰苑羣書》者，係入禋後所作，不收錄。","）。"]', '["古观重重遶翠微，杉松深处掩雙扉。","云生万壑投龙去，海隔三山放鹤归。","花洞宴游春日永，石壇朝禮曙星稀。","每听高論长生理，擬向塵中便拂衣。","（见《瀛奎律髓》卷四十八《仙逸類》。","此诗明李蔉所輯《宋藝圃集》作李九齡诗。","按徽之又有《禁林讌會之什》一首见於《翰苑羣书》者，係入禋後所作，不收錄。","）。"]', '诗', 'shi', '', NULL, '贈譚先生 楊徽之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df62d3fc-b5b9-458e-88e7-0a02cdc8f77a', '句 一', '句 一', 'a1f60d22-5353-49b8-81c1-f5b0c6c54b46', '唐', '["戍樓煙[自]（似）直，戰地雨長腥。","（《塞上》）。"]', '["戍楼煙[自]（似）直，戰地雨长腥。","（《塞上》）。"]', '诗', 'shi', '', NULL, '句 一 楊徽之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fd2861d-9448-4bf5-a25d-7cf3b303c3f4', '句 二', '句 二', 'a1f60d22-5353-49b8-81c1-f5b0c6c54b46', '唐', '["春歸萬年樹，月滿九重城（《元夜》）。"]', '["春归万年樹，月满九重城（《元夜》）。"]', '诗', 'shi', '', NULL, '句 二 楊徽之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1128d123-67da-4014-acb4-9033fa7d1fdf', '句 三', '句 三', 'a1f60d22-5353-49b8-81c1-f5b0c6c54b46', '唐', '["偶題嵓石雲生筆，閑遶庭松露濕衣。","（《僧舍》）。"]', '["偶題嵓石云生笔，闲遶庭松露濕衣。","（《僧舍》）。"]', '诗', 'shi', '', NULL, '句 三 楊徽之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85e015d0-cc48-4154-96fb-6d4dc7188cc2', '句 四', '句 四', 'a1f60d22-5353-49b8-81c1-f5b0c6c54b46', '唐', '["開盡菊花秋色老，落殘桐葉雨聲寒。","（《宿東林》以上八句並見《宋詩紀事》卷二。","均見《玉壺清話》卷五、《澠水燕談錄》卷七，宋太宗曾書於御屏。）"]', '["开尽菊花秋色老，落殘桐葉雨声寒。","（《宿东林》以上八句並见《宋诗紀事》卷二。","均见《玉壺清話》卷五、《澠水燕談錄》卷七，宋太宗曾书於御屏。）"]', '诗', 'shi', '', NULL, '句 四 楊徽之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a8e3553-61d2-479e-ab2a-28e76b1852a6', '句（《吟窗雜錄》卷三一《歷代吟譜》引此二句，題作《秋夕詩》。）', '句（《吟窗杂錄》卷三一《歷代吟譜》引此二句，題作《秋夕诗》。）', 'af132734-2411-4573-87b4-855f1b490562', '唐', '["空囊萬里客，斜月一床寒。","（見《宋詩紀事》引宋失名撰《歷代吟譜》。","）。"]', '["空囊万里客，斜月一床寒。","（见《宋诗紀事》引宋失名撰《歷代吟譜》。","）。"]', '诗', 'shi', '', NULL, '句（《吟窗雜錄》卷三一《歷代吟譜》引此二句，題作《秋夕詩》。） 卞震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b798467-b4ce-4553-85b5-19b2f049889f', '', '', '70843a97-fac4-4be3-92e9-63efe48dc850', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 劉吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3761e77-cfbc-4499-b6c1-392733bf4b27', '句', '句', '70843a97-fac4-4be3-92e9-63efe48dc850', '唐', '["一箭不中鵠，五湖歸釣魚。","（《贈隱者》。","見《宋詩紀事》卷三引《歷代吟譜》。","按《全唐詩》卷七百九十五作張塋詩句。","云見地志。","）（《增修詩話總龜》卷一引《叢苑》、《宋朝事實類苑》卷五五引《楊文公談苑》幷載劉吉此二句詩，並云其「有詩三百首，目爲《釣鼇集》，徐鉉爲序。","其首篇《贈隱者》，……人多誦之」。","《全唐詩》所收張塋，應張瑩，《淳熙三山志》卷二、卷三四收此二句爲其詩。","二句似驗劉作爲近是。","）。"]', '["一箭不中鵠，五湖归釣鱼。","（《贈隐者》。","见《宋诗紀事》卷三引《歷代吟譜》。","按《全唐诗》卷七百九十五作張塋诗句。","云见地志。","）（《增修诗話總龟》卷一引《叢苑》、《宋朝事實類苑》卷五五引《楊文公談苑》幷載劉吉此二句诗，並云其「有诗三百首，目爲《釣鼇集》，徐鉉爲序。","其首篇《贈隐者》，……人多誦之」。","《全唐诗》所收張塋，應張瑩，《淳熙三山志》卷二、卷三四收此二句爲其诗。","二句似驗劉作爲近是。","）。"]', '诗', 'shi', '', NULL, '句 劉吉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('896c8677-c2c4-476a-b75e-405c1d708042', '句', '句', '99ec7dbd-9dca-4f81-9ae0-f0f4a33a1b0f', '唐', '["練色有窮處，寒聲無斷（《江南野史》「斷」作「盡」。","）時。","（《瀑布》。","見宋馬令《南唐書》卷二十三《孟賓于傳》。","亦見宋龍袞《江南野史》。","）（〖1〗《南唐書》：〖孟賓于〗初歸江南，生子鱣歸唐，亦能詩。","肄業廬山國學，嘗得《瀑布詩》云：「練色有窮處，寒聲無斷時。","」隣房生亦得此聯，遂交爭之。","助教不能辯，訟于江州。","各以全篇意格定之，而歸唐爲勝。","）。"]', '["練色有窮处，寒声無斷（《江南野史》「斷」作「尽」。","）时。","（《瀑布》。","见宋马令《南唐书》卷二十三《孟賓于傳》。","亦见宋龙袞《江南野史》。","）（〖1〗《南唐书》：〖孟賓于〗初归江南，生子鱣归唐，亦能诗。","肄業廬山国学，嘗得《瀑布诗》云：「練色有窮处，寒声無斷时。","」隣房生亦得此聯，遂交爭之。","助教不能辯，訟于江州。","各以全篇意格定之，而归唐爲勝。","）。"]', '诗', 'shi', '', NULL, '句 孟歸唐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e728a021-50d1-4463-9796-255c1468a8ec', '', '', 'e16e3744-66d1-40ee-a9c8-472d530ed264', '唐', '["。"]', '["。"]', '诗', 'shi', '', NULL, ' 錢惟治 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c8d1b25-ec1c-492b-9215-6c60c13d6726', '春日登大悲閣迴文（二首） 一', '春日登大悲閣迴文（二首） 一', 'e16e3744-66d1-40ee-a9c8-472d530ed264', '唐', '["聖主欽崇教，千光顯紺容。","映雲窗綺暖，籠月箔花重。","淨剎香風遠，危闌碧霧濃。","勝因良以詠，華國一斯逢。"]', '["聖主欽崇教，千光显紺容。","映云窗綺暖，籠月箔花重。","淨剎香风远，危闌碧霧濃。","勝因良以詠，华国一斯逢。"]', '诗', 'shi', '', NULL, '春日登大悲閣迴文（二首） 一 錢惟治 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2609daa-b8c5-47bc-982f-c00eb7331d8b', '春日登大悲閣迴文（二首） 二', '春日登大悲閣迴文（二首） 二', 'e16e3744-66d1-40ee-a9c8-472d530ed264', '唐', '["碧天臨迥閣，晴雪點山屏。","夕烟侵冷箔，明月歛閑亭。","（見《宋詩紀事》卷三引《冰川詩式》。","）（均見明梁橋《冰川詩式》卷二，前首「危闌」作「危欄」，「華國」作「華閣」。","）（〖1〗《湖州府志》：「吳越《迴文綬帶連環詩碑》，在法華寺，節度使錢惟治作，九十首。","」）。"]', '["碧天臨迥閣，晴雪点山屏。","夕烟侵冷箔，明月歛闲亭。","（见《宋诗紀事》卷三引《冰川诗式》。","）（均见明梁橋《冰川诗式》卷二，前首「危闌」作「危欄」，「华国」作「华閣」。","）（〖1〗《湖州府志》：「吳越《迴文綬带連环诗碑》，在法华寺，節度使錢惟治作，九十首。","」）。"]', '诗', 'shi', '', NULL, '春日登大悲閣迴文（二首） 二 錢惟治 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2631be4e-9d41-4a60-960c-12f77c7e2454', '贈趙叟（題擬）', '贈趙叟（題擬）', '857087f9-af77-46a3-87c4-382997d66e55', '唐', '["桂枝輪卻正淒然，又被鸎聲聒晝眠。","唯有趙翁知仔細，相傳好語待來年。","（見《江南餘載》卷上。","）（〖1〗《江南餘載》：趙叟者，自保大之初至於開寶之季，嘗爲貢院門子，每歲放榜之後，或去或留，率慶慰之，若出於叟手然。","進士何蒙目前叟詩曰〖詩不重錄〗云云。","）。"]', '["桂枝輪卻正淒然，又被鸎声聒晝眠。","唯有趙翁知仔細，相傳好語待来年。","（见《江南餘載》卷上。","）（〖1〗《江南餘載》：趙叟者，自保大之初至於开寶之季，嘗爲貢院门子，每歲放榜之後，或去或留，率慶慰之，若出於叟手然。","進士何蒙目前叟诗曰〖诗不重錄〗云云。","）。"]', '诗', 'shi', '', NULL, '贈趙叟（題擬） 何蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a5dccf3-3c4f-4f6a-a03c-3be883d7b566', '寄劉乙處士', '寄劉乙处士', '66dc6ac4-3169-40c0-98d2-e76b172f894e', '唐', '["音問相忘二十秋，天者我輩到南州。","無窮風月隨宜樂，有分溪山取次收。","好語傳來如昨夢，離情欲剖帶春愁。","何時載酒從東下，細與劉君敘昔遊。","（見《永樂大典》卷一三四五○「二寘」「士」字「處士」條〖十四函一百三十七冊〗。","）（按：劉乙字子黃，泉州人。","仕閩爲鳯閣舍人，後棄祁隱安溪鳯髻山。","《全唐詩》卷七百六十三收劉乙詩一首幷殘句二，又卷八百八十六補遺二首。","《全唐詩》詹敦仁詩有《遺子訪劉乙》一首。","劉乙生涯，於此約畧可窺。","）。"]', '["音问相忘二十秋，天者我輩到南州。","無窮风月隨宜乐，有分溪山取次收。","好語傳来如昨梦，離情欲剖带春愁。","何时載酒從东下，細與劉君敘昔游。","（见《永乐大典》卷一三四五○「二寘」「士」字「处士」條〖十四函一百三十七冊〗。","）（按：劉乙字子黄，泉州人。","仕閩爲鳯閣舍人，後棄祁隐安溪鳯髻山。","《全唐诗》卷七百六十三收劉乙诗一首幷殘句二，又卷八百八十六補遺二首。","《全唐诗》詹敦仁诗有《遺子訪劉乙》一首。","劉乙生涯，於此約畧可窺。","）。"]', '诗', 'shi', '', NULL, '寄劉乙處士 詹敦仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a867366-bd79-4284-a969-1ac19b4988b4', '琲訪劉君乙時已歿故將歸王令留之不可以書來囑作此篇示', '琲訪劉君乙时已歿故將归王令留之不可以书来囑作此篇示', '66dc6ac4-3169-40c0-98d2-e76b172f894e', '唐', '["劉郎蹤跡久荒凉，卜宅何妨處士鄉。","壯志莫隨流俗變，老夫霜鬢已凝霜。","（見《永樂大典》卷一三三四四「二寘」「示」字〖十四函一百三十七冊〗引詹敦仁《清隱集》。","案：琲爲詹敦仁之子。","）。"]', '["劉郎蹤跡久荒凉，卜宅何妨处士乡。","壯志莫隨流俗变，老夫霜鬢已凝霜。","（见《永乐大典》卷一三三四四「二寘」「示」字〖十四函一百三十七冊〗引詹敦仁《清隐集》。","案：琲爲詹敦仁之子。","）。"]', '诗', 'shi', '', NULL, '琲訪劉君乙時已歿故將歸王令留之不可以書來囑作此篇示 詹敦仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a88092e3-8308-4374-bf39-872d7dfde773', '入局吟', '入局吟', '66dc6ac4-3169-40c0-98d2-e76b172f894e', '唐', '["明命初頒得美除，慚惶下拜敢寧居？","儒生不作于時計，（于時，疑當作「干時」。","）且讀人間未見書。"]', '["明命初頒得美除，慚惶下拜敢寧居？","儒生不作于时計，（于时，疑當作「干时」。","）且读人间未见书。"]', '诗', 'shi', '', NULL, '入局吟 詹敦仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c62134b6-0324-4713-8978-c5fe4d834ae2', '又一首（用前韻）', '又一首（用前韻）', '66dc6ac4-3169-40c0-98d2-e76b172f894e', '唐', '["可恨名存實已除，蘭臺芸閣復誰居？","豕魚未識應多愧，尤恐在人成蠹書。","（以上二詩見《永樂大典》卷一九七八二「一屋」。","「局」字〖十八函一百七十八冊〗。","）。"]', '["可恨名存實已除，蘭台芸閣复誰居？","豕鱼未識應多愧，尤恐在人成蠹书。","（以上二诗见《永乐大典》卷一九七八二「一屋」。","「局」字〖十八函一百七十八冊〗。","）。"]', '诗', 'shi', '', NULL, '又一首（用前韻） 詹敦仁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('257989b1-afe1-481c-a545-c4543505fccc', '答高越（題擬）', '答高越（題擬）', '4821694d-3276-4f2b-8ccf-81a770f538e8', '唐', '["罷修儒業學修真，養拙藏愚四十春。","到老不疎林裏鹿，平生未識日邊人。","澗花發處千堆錦，巖雪鋪時萬樹銀。","多謝朝賢遠相問，未聞雞得鳯爲鄰。","（見《江南餘載》卷下。","按《全唐詩》卷八百六十一作李夢符詩，題曰《答常學士》。","詩中異處較多，對勘之下，以此爲勝，故仍錄而存之。","）（〖1〗《江南餘載》：蜀人陳曙者，王氏末年避地淮南，隱於蘄州山中。","鄉人祀神，曙不召亦必至，醉飽而後去。","雖百神祀，曙能遍往也。","其所居，屋一間，道書數卷而已，與蛇虎雜處而泰突無所忌。","元宗遣中書舍人高越齎束帛徵之，三往不應。","後移居鄂州，不知所終。","越贈曙以新的。","曙次韻答之。","〖2〗按高越字仲遠，幽州人，仕吳，授秘書郎，累遷中書舍人，終勤政殿學士、戶部侍郎。","《全唐詩》收越《咏鷹》一首，《江南餘載》卷上亦載之，惟題作《鷂子詩》，字句略有異同耳。","）。"]', '["罷修儒業学修真，養拙藏愚四十春。","到老不疎林裏鹿，平生未識日邊人。","澗花發处千堆錦，巖雪鋪时万樹銀。","多謝朝賢远相问，未闻雞得鳯爲鄰。","（见《江南餘載》卷下。","按《全唐诗》卷八百六十一作李梦符诗，題曰《答常学士》。","诗中異处較多，对勘之下，以此爲勝，故仍錄而存之。","）（〖1〗《江南餘載》：蜀人陳曙者，王氏末年避地淮南，隐於蘄州山中。","乡人祀神，曙不召亦必至，醉飽而後去。","雖百神祀，曙能遍往也。","其所居，屋一间，道书數卷而已，與蛇虎杂处而泰突無所忌。","元宗遣中书舍人高越齎束帛徵之，三往不應。","後移居鄂州，不知所終。","越贈曙以新的。","曙次韻答之。","〖2〗按高越字仲远，幽州人，仕吳，授秘书郎，累遷中书舍人，終勤政殿学士、戶部侍郎。","《全唐诗》收越《咏鷹》一首，《江南餘載》卷上亦載之，惟題作《鷂子诗》，字句略有異同耳。","）。"]', '诗', 'shi', '', NULL, '答高越（題擬） 陳曙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3527a1f8-6fbe-4ea9-87f3-dbbbb46f5e53', '題失', '題失', 'e879fc35-2d86-4612-84bd-850252ad2888', '唐', '["祇應天上路，不爲下方開。","道既學不得，仙從何處來。","（〖1〗按此詩見宋鄭文寶撰《江南餘載》卷下，《知不足齋叢書》本。","《全唐詩》卷七百五十七收許堅詩五首，又卷八百六十一仙卷亦收五首幷句，其中兩句曰「道既學不得，仙從何處來」。","即此詩之後兩句，蓋《全唐詩》缺其前半。","〖2〗《江南餘載》：許堅往來句曲廬阜之間，草裝布囊，或臥於野，或和衣浴澗中，蕭然不接人事，獨笑獨吟而已〖餘畧〗。","）。"]', '["祇應天上路，不爲下方开。","道既学不得，仙從何处来。","（〖1〗按此诗见宋鄭文寶撰《江南餘載》卷下，《知不足斋叢书》本。","《全唐诗》卷七百五十七收許堅诗五首，又卷八百六十一仙卷亦收五首幷句，其中兩句曰「道既学不得，仙從何处来」。","即此诗之後兩句，蓋《全唐诗》缺其前半。","〖2〗《江南餘載》：許堅往来句曲廬阜之间，草裝布囊，或臥於野，或和衣浴澗中，蕭然不接人事，独笑独吟而已〖餘畧〗。","）。"]', '诗', 'shi', '', NULL, '題失 許堅 shi');
